// Shard
// ═══════════════════════════════════════════════════════════════════════════════

/// The replica's clock, links and disk, and what it reaches its shard
/// for. It holds nothing: the shard is moved by value after init, so a
/// pointer kept here would dangle; each call finds the shard from the
/// replica's address.
const ShardIo = struct {
    pub fn nowMs(_: *Replica) u64 {
        return Shard.nowMs();
    }

    /// A lone node has no peers: no frames go out, and no Raft clock runs.
    pub fn networked(r: *Replica) bool {
        return Host.of(r).raft_network != null;
    }

    pub fn send(r: *Replica, peer: u32, msg_type: transport.MsgType, group: u32, payload: []const u8) bool {
        const rn = Host.of(r).raft_network orelse return false;
        return rn.sendTo(peer, msg_type, group, payload);
    }

    /// An ack means "in my log, on disk" when commits are durable.
    pub fn durableCommits(r: *Replica) bool {
        return Host.of(r).durableCommits();
    }

    /// Flush the batch just taken before it is acked.
    pub fn flushForAck(r: *Replica) bool {
        return Host.of(r).flushForAck();
    }

    /// The voters the network lets dial in and votes among.
    pub fn setVoters(r: *Replica, ids: []const u32) void {
        if (Host.of(r).raft_network) |rn| rn.setVoters(ids);
    }

    pub const Host = struct {
        fn of(r: *Replica) *Shard {
            return @alignCast(@fieldParentPtr("replica", r));
        }

        pub fn raftNode(r: *Replica) *RaftNode {
            return of(r).raftNode();
        }

        pub fn isRemoved(r: *Replica) bool {
            return of(r).isRemoved();
        }

        pub fn checkRemoved(r: *Replica, now: u64) bool {
            return of(r).checkRemoved(now);
        }

        pub fn tickMembership(r: *Replica, now: u64) void {
            of(r).tickMembership(now);
        }

        pub fn applyCommitted(r: *Replica) bool {
            return of(r).applyCommitted();
        }

        /// A committed entry could not be read to apply it. The apply loop
        /// logs and surfaces this itself, so callers of `applyCommitted` do
        /// not report the same block again.
        pub fn readBlocked(r: *Replica) bool {
            return of(r).read_blocked;
        }

        pub fn clearRemovalNotices(r: *Replica) void {
            of(r).clearRemovalNotices();
        }

        pub fn strangerFrame(r: *Replica, frame: RaftFrame) void {
            of(r).strangerFrame(frame);
        }

        pub fn handleJoinRequest(r: *Replica, from: u32) void {
            of(r).handleJoinRequest(from);
        }

        pub fn takeRemovedNotice(r: *Replica, frame: RaftFrame) void {
            of(r).takeRemovedNotice(frame);
        }

        pub fn runForwardedWrite(r: *Replica, frame: RaftFrame) void {
            of(r).runForwardedWrite(frame);
        }

        pub fn takeForwardReply(r: *Replica, frame: RaftFrame) void {
            of(r).takeForwardReply(frame);
        }

        pub fn stopTakingPart(r: *Replica, message: []const u8) void {
            of(r).stopTakingPart(message);
        }

        pub fn stoppedLeading(r: *Replica, message: []const u8) void {
            of(r).stoppedLeading(message);
        }
    };
};

const Replica = replica_mod.Replica(ShardIo);

comptime {
    // A pointer held by the replica would outlive the shard's move after
    // init. ShardIo is never instantiated, so what could creep in is a
    // pointer field on the replica itself; slices into the shard's buffers
    // are fine. (A container-level `var` in ShardIo can't be seen here: don't
    // add one.)
    const fields = @typeInfo(Replica).@"struct";
    for (fields.field_names, fields.field_types) |name, F| {
        const T = switch (@typeInfo(F)) {
            .optional => |o| o.child,
            else => F,
        };
        const info = @typeInfo(T);
        if (info == .pointer and info.pointer.size == .one) @compileError("Replica." ++ name ++ " holds a pointer; the shard moves after init, so reach it through Io.Host");
    }
}

pub const Shard = struct {
    /// Shard index (0..shard_count-1).
    id: u16,

    /// Allocator for shard-owned resources.
    allocator: std.mem.Allocator,

    /// Unified event loop.
    reactor: Reactor,

    /// What other shards put in front of this one: requests, replies and
    /// wakes (heap-allocated so peers can hold its address).
    mailbox: *Mailbox,
    /// A slot per client request forwarded to another shard, until its
    /// answer comes back or `expireReplySlots` takes it back.
    reply_pool: ReplyPool,
    /// Reads under way that other shards answer in parts (a kv.mget whose
    /// keys several shards own); see `startMgetGather`.
    gathers: Gathers,
    /// Answers dropped for want of a reply slot or of room on the asker's
    /// reply ring. Both are reserved before every request, so a count means
    /// an answer came twice or long after its slot expired.
    replies_dropped: u64 = 0,
    /// The request being dispatched, which its handler answers through its
    /// connection; see `deliverDeferred`.
    dispatching: ?Dispatching = null,
    /// Requests answered as deferred without being parked; see
    /// `answeredAsDeferred`.
    answered_as_deferred: u64 = 0,
    /// Client requests refused before reaching another shard, and when that
    /// was last said; when unanswered slots are next swept.
    forwards_refused: u64 = 0,
    refuse_warn_ms: u64 = 0,
    reply_sweep_ms: u64 = 0,
    /// Unanswered requests given up on since that was last said, and when.
    slots_expired: u64 = 0,
    expire_warn_ms: u64 = 0,
    stamp_warn_ms: u64 = 0,

    /// Opcode → handler routing table.
    dispatcher: Dispatcher,

    /// Active connections: fd → Connection.
    connections: std.AutoHashMapUnmanaged(i32, *Connection),

    /// Partition router.
    router: Router,

    /// Per-shard slab allocator.
    slab: SlabAllocator,

    /// Pipe read-end fd — receives hand-offs from Acceptor.
    acceptor_pipe_rd: i32,

    /// Set once, from any thread, to stop the shard's loop; never cleared,
    /// so a stop asked for before the loop starts still stops it.
    stop_requested: std.atomic.Value(bool),
    /// Shared by the node's shards while they stop; null for a shard run
    /// alone.
    stopping: ?*Stopping,

    /// Next connection ID.
    next_conn_id: u32,

    /// Total requests dispatched (stats).
    requests_dispatched: u64,

    /// Clients refused for being built from another protocol version or
    /// table, and when the last was logged: they are logged at most once
    /// every 10 s, with a count of the ones in between.
    foreign_refused: u64 = 0,
    foreign_logged_ms: u64 = 0,
    foreign_unlogged: u64 = 0,

    /// Total inbox messages processed (stats).
    inbox_messages_processed: u64,

    /// Partitions owned by this shard (heap-allocated, stable pointers).
    /// Each Partition owns a UAL, ProjectionRouter, and all four projections.
    /// Currently 1 partition per shard; will scale to N later.
    partitions: []*Partition,
    num_partitions: u32,

    /// KV handler instance (heap-allocated, stable pointer).
    kv_handler: *KVHandler,

    /// Stream handler instance.
    stream_handler: *StreamHandler,

    /// Queue handler instance.
    queue_handler: *QueueHandler,

    /// TS handler instance.
    ts_handler: *TSHandler,

    /// Namespace handler instance.
    namespace_handler: *NamespaceHandler,

    /// Actions handler instance.
    actions_handler: *ActionsHandler,

    /// Worker registry — tracks physical worker health.
    worker_handler: *WorkerHandler,

    /// Workflow handler instance.
    workflow_handler: *WorkflowHandler,

    // Processing handler instance.
    processing_handler: *ProcessingHandler,

    /// Segment writer — accumulates entries for persistence to .flseg files.
    segment_writer: *SegmentWriter,

    /// The writer's buffer plus the sealed segments, as one log the Raft
    /// node can read below its ring and truncate through (null if ephemeral).
    durable_log: ?*DurableLog,
    /// Reads below the ring, a leader's for its peers made off this thread
    /// once the node's bulk I/O thread is attached (null if ephemeral).
    catch_up: ?*CatchUp = null,
    /// Stream payloads read back from sealed segments.
    stream_disk: ?*DiskReads = null,
    /// The damage `answerDamaged` tells the reads it expires.
    damage_for_waiters: ?silent_loss.Damage = null,

    /// Cumulative count of segment flush failures — failed attempts, not
    /// distinct incidents: in sync mode a flush is attempted per request, so
    /// while a disk is down this rises with request traffic. Surfaced (metric
    /// and /status) instead of being silently swallowed, so a disk-full or IO
    /// fault is observable. `flushes_failing_for_ms` is the better incident
    /// signal: how long the current run has lasted.
    persist_failures: u64,

    /// Storage durability — controls segment flush timing.
    durability: Durability,

    /// Per-shard data directory path (owned, null if ephemeral).
    shard_data_dir: ?[]const u8,

    /// Whether the acceptor pipe has been registered with the reactor.
    pipe_registered: bool,

    /// Raft network reference (set by runtime for shard 0, null otherwise).
    raft_network: ?*RaftNetwork,

    /// Frames from authenticated peers, filled by the network thread (set
    /// by the runtime for shard 0). Its wake pipe is a reactor source.
    raft_queue: ?*RaftQueue,
    raft_queue_registered: bool,

    /// Per-shard counters, mirroring the global server ones for attribution.
    shard_metrics: ?*ShardMetrics,

    /// This node's cluster-wide node ID, set by the runtime at start. Distinct
    /// from `raft_node.id`, which identifies the per-shard Raft group.
    cluster_node_id: u32,

    /// Raft consensus node — every shard has one. Writes go through
    /// propose() → commit → apply to projections.
    raft_node: *RaftNode,
    /// This node's side of the Raft protocol: the frames, the clock and
    /// what the leader sends each peer.
    replica: Replica,
    /// When a node with no membership last asked the peers it can reach
    /// to be added.
    join_asked_ms: u64,
    /// Proposals whose client waits for commit, by index. In steady state a
    /// slot is never contended: the Raft node refuses proposals past
    /// MAX_OUTSTANDING and the table is twice that. One case can still fill it
    /// — a lone node (which has no such cap) whose reads are blocked, so
    /// committed entries park unapplied; `parkHolding` backstops that by
    /// refusing a contended slot rather than overwriting it.
    pending: []Pending,
    pending_count: u32,
    /// The connection a parked write is answered on when the client's is not on
    /// this thread or no longer known: carries (owner, fd, id) and collects
    /// the bytes, which go out through `deliverDeferred`.
    respond_proxy: *Connection,
    /// Writes this node received while not leading, sent on to the leader
    /// and waiting for its answer; and answers held until this node has
    /// applied what the leader committed, so the client reads its write.
    forwards: []Forward,
    forward_count: u32,
    /// Reads of a namespace this follower's table doesn't have yet, held
    /// while it asks the leader (`edgeMiss`).
    edge: edge_mod.Edge = .{},
    /// Of those, blocking reads, which may wait there for minutes: they hold
    /// at most FORWARD_SLOTS - FORWARD_WRITE_RESERVE slots, so writes always
    /// find one.
    blocking_forwards: u32,
    replies_held: u32,
    next_forward_id: u32,
    /// On a lone node, damage this shard's data holds. The shard answers
    /// every request with it and applies nothing; the other shards serve.
    offline: ?silent_loss.Damage,
    /// `offline != null`, for other shards' threads. Set after `offline`,
    /// which never changes once set, so a reader that sees it true may read
    /// `offline`.
    offline_published: std.atomic.Value(bool),
    /// The entry this shard halted at, on every replica alike: it applies
    /// nothing from it on and takes no writes until a repair.
    halted: ?Halt = null,
    /// Where a crash in apply is recorded, and the entry the last one, on
    /// this build, crashed on: it halts there rather than crash again.
    marker: apply_marker.Marker = .{},
    /// The entries the log's committed repair skips name: each applies
    /// nothing here, as on every replica.
    skips: repair.Skips = .{},
    /// A halted shard looks for the skip naming its halt among committed
    /// entries from here on; each looks only at what committed since.
    skip_scan_from: u64 = 0,
    /// A repair skip applied since the last seal. Its segment is sealed at
    /// once, with the watermark at or past it, so boot collects it before
    /// replay: left above the watermark, a later build that can apply the
    /// skipped entry would apply it on boot, then meet the skip.
    seal_skip: bool = false,
    /// The shard's own writes (checkpoints, acks, run steps) refused since
    /// the last line saying so, and when the next line may go out.
    halted_refusals: u64 = 0,
    halted_line_ms: u64 = 0,
    /// In a cluster, the damage that made this member diverged, for
    /// `/status`.
    diverged_damage: ?silent_loss.Damage = null,
    /// Entries and segments lost without anyone being told, by path.
    losses: silent_loss.Counts,
    /// Where this shard publishes its state for `/ready` and `/status`.
    health: ?*health_mod.ShardSlot = null,
    /// Every shard's slot on this node, this one's among them: how a duty
    /// here knows the shard it writes to is halted.
    node_health: []health_mod.ShardSlot = &.{},
    /// The leader duties held back, and since when.
    duties: duties_mod.Duties = .{},
    join_first_asked_ms: u64,
    join_warned_ms: u64,
    join_refused_warn_ms: u64,
    stranger_warn_ms: u64,
    /// The group removed this node, at this time on the removing leader's
    /// clock: it takes no part and answers clients that it is gone.
    removed_at_ms: ?u64 = null,
    removed_warn_ms: u64 = 0,
    /// What clients are told once removed, with the time in it.
    removed_message_buf: [128]u8 = undefined,
    removed_message: []const u8 = REMOVED_MESSAGE,
    /// Last "you were removed" told to a removed node.
    removed_notice_ms: u64 = 0,
    /// Removal notices held toward a quorum of this node's committed
    /// voters, and the last line about one not counted.
    removal: RemovalNotices = .{},
    removal_warn_ms: u64 = 0,
    late_apply_warn_ms: u64,
    forward_reply_warn_ms: u64 = 0,
    /// When a failed sync flush was last logged; it repeats on every request.
    flush_fail_warn_ms: u64,
    /// The monotonic clock reading when the current run of flush failures began,
    /// or 0 while flushes are succeeding. Kept internally; `/status` and metrics
    /// publish the elapsed duration computed from it, not this raw reading, so a
    /// reader and Prometheus see a plain "failing for N ms".
    flushes_failing_since_ms: u64 = 0,

    /// Where the Raft node persists its term and vote (null if ephemeral).
    hard_state_store: ?*HardStateStore,

    /// Unified waiter pool — handles blocking GET, blocking dequeue,
    /// stream long-poll, and action_await across all subsystems.
    waiter_pool: WaiterPool,

    /// Cooperative periodic background tasks (hot_flush, TTL sweep, etc.).
    task_scheduler: TaskScheduler,

    /// Maximum age of entries in the hot ring (seconds). 0 = disabled.
    hot_flush_seconds: u64,

    /// Cross-shard shard pointer array (null until wired by runtime).
    /// Enables direct dispatch on another shard's handlers for pre-routed requests.
    peer_shards: ?[]*Shard,

    /// Every shard's mailbox, this one's included (null until wired by
    /// runtime).
    peer_mailboxes: ?[]*Mailbox,

    /// Per-shard proxy Connection used to drive forwarded requests on this
    /// shard's reactor thread. The real Connection lives on the owner shard;
    /// this proxy carries the requester's address (`Connection.proxy_for`) so
    /// handlers register waiters with the correct routing target, and accumulates direct
    /// responses in its `write_buf` for delivery on the asker's reply ring.
    /// Reused sequentially — safe because each shard's reactor is single-
    /// threaded and `drainInbox` processes one message at a time.
    forward_proxy: *Connection,

    /// Replay registry — maps EntryType → handler apply callback for the
    /// entry types no projection owns. Used by the one applier, whether the
    /// entry comes from this node's Raft log, a peer, or a segment at boot.
    replay_registry: ReplayRegistry,

    /// Copy buffer for committed entries, sized for the largest entry any
    /// handler proposes. Allocated at boot so an out-of-memory is a boot
    /// failure, not a committed write that never reaches the projection.
    apply_buf: []u8,
    /// The per-request buffers, owned here rather than declared on the
    /// stack: a safe build fills a stack buffer declared `undefined` on
    /// every call, which for these sizes cost more than the request. Each
    /// is used by one function, which no handler re-enters.
    /// Socket bytes on their way into a connection's read ring.
    read_buf: []u8,
    /// A whole request, copied out of the ring to parse.
    parse_buf: []u8,
    /// The entry `persistence.proposeEntry` builds.
    entry_buf: []u8,
    /// One buffer for a handler's answer or payload; see `Scratch`.
    scratch: Scratch,
    /// True while `applyCommitted` is draining, so a waiter woken by an
    /// apply that proposes in turn cannot start a nested drain.
    applying: bool,
    /// The last apply pass stopped at its budget with committed entries
    /// left; the next poll does not wait, and the tick applies on.
    apply_behind: bool,
    /// Apply is suspended at a snapshot bar while the state at it is
    /// serialized. Raft runs on, and commit advances; writes committed
    /// meanwhile wait in the pending table and are answered on resume.
    snapshot_window: ?SnapshotWindow = null,
    /// Set while a request's own apply runs: under sync durability its flush
    /// waits for the tick's apply pass, shared by every request read.
    hold_sync_flush: bool = false,
    /// Tests only: the next bar. Bars proper come with snapshots; until then
    /// a window opens only here, or at a test fault's entry.
    test_bar: u64 = 0,
    /// Bars a leader still applying earlier terms passed without a snapshot
    /// (cumulative): followers at the same bar take theirs, and this leader's
    /// next is at the next bar.
    snapshot_skips_leader_not_ready: u64 = 0,
    /// Processing KV sink writes other shards sent here that the log was
    /// too full to take, in arrival order, retried each tick: encoded
    /// `SinkPut`s, owned. While any wait, newer ones queue behind them, so a
    /// key's writes still land in the order they were sent.
    kv_sink_retries: std.ArrayListUnmanaged([]u8) = .empty,
    /// The bytes `kv_sink_retries` holds.
    kv_sink_retry_bytes: usize = 0,
    /// Such writes dropped because the list was full (cumulative): what is
    /// still lost until channels give sinks durable delivery.
    kv_sink_retry_overflow: u64 = 0,
    /// A committed entry could not be read to apply it — a resource or IO
    /// failure reading below the ring, not a hole. The shard holds it unapplied
    /// and retries, but not on every call: `read_retry_at_ms` paces the retry,
    /// `apply_behind` is deliberately not set (so the reactor keeps its normal
    /// poll wait and does not spin), and the state is visible (`/ready` goes
    /// 503, `/status` names it). A leader blocked this way steps down.
    read_blocked: bool = false,
    read_blocked_since_ms: u64 = 0,
    /// Whether the current block's cause may be the disk failing (an IO error),
    /// rather than a resource shortage. Shapes the reason `/status` shows.
    read_block_disk_failing: bool = false,
    /// The disk-class block is a permission the operator may fix.
    read_block_permission: bool = false,
    /// The clock reading at which a disk-class block becomes damage, or null
    /// while the block is not disk-class. Set when the cause first looks like
    /// the disk and left alone after, so a long resource shortage that later
    /// turns into a disk error does not shorten the disk's grace: the countdown
    /// starts at the change. An absolute deadline, not an elapsed time, so it
    /// never underflows a monotonic uptime clock.
    read_block_disk_deadline_ms: ?u64 = null,
    /// The next tick that may re-attempt a blocked read. Between these, apply
    /// returns at once without touching the disk, so a blocked read is not
    /// retried per request.
    read_retry_at_ms: u64 = 0,
    /// Rate-limits the one line said while blocked; null until it is first said,
    /// so a block within the first interval of uptime is not held silent.
    read_block_log_ms: ?u64 = null,
    /// A repair skip whose named entry could not be read to check it (by the
    /// skip's own index), 0 when none. The skip entry itself applied; only its
    /// check is held, and the apply loop does not go past it until the check
    /// runs. Paced by `read_retry_at_ms` like any blocked read.
    skip_check_pending: u64 = 0,
    /// What this tick's apply passes have spent, in `applyCost` units: the
    /// budget is the tick's, since every request and frame applies after it.
    /// A call outside a tick (boot, a test) has a budget of its own.
    apply_tick_spent: u64,
    in_tick: bool,
    /// Ticks that ran the producers (pipelines, triggers, schedules).
    producer_ticks: u64,
    /// Set by a cold boot (`cold_boot` in `init`) until this node's
    /// projections hold what its group committed; see `coldCaughtUp`.
    cold_gate: bool,
    /// Whether the last entry the apply loop took applied, and what its
    /// applier recorded: `park` answers from it, not from the whole pass's
    /// result.
    last_entry_applied: bool,
    last_result: persistence_mod.Result,
    /// An invoke applied on this leader in the current pass: its workers
    /// are woken once, after the pass.
    wake_workers: bool,
    /// The next poll does not wait: the tick's step passes stopped at their
    /// cap with work left, or resumed connections proposed writes the next
    /// pump sends. Only a leader sets it; nothing clears it on a follower.
    more_work: bool,
    /// Connections marked closing (`markClosing`), closed at the end of the
    /// tick. Room for one entry per connection is reserved as each is
    /// added, so marking never fails.
    closing_fds: std.ArrayListUnmanaged(i32) = .empty,
    /// Paused or waiting connections to read again (`flushToClient`, the
    /// stall check, `resumeWaiting`);
    /// their buffered requests run at the end of the tick. The end of the
    /// tick runs a swapped-out snapshot (`resume_running`), so what is
    /// queued while it runs waits for the next tick: one entry per
    /// connection at most, and both lists are reserved as above.
    resume_fds: std.ArrayListUnmanaged(i32) = .empty,
    /// Reads one connection gets per event before the others' turn; the
    /// rest is read at the end of the tick. A field so tests can shrink it.
    reads_per_event: u32 = 8,
    resume_running: std.ArrayListUnmanaged(i32) = .empty,
    /// The line of connections whose next request waits for room to go to
    /// another shard (`waitForward`), in the order they began waiting,
    /// checked at the end of every tick. An entry is live while its
    /// connection's `wait_seq` matches; a connection has at most one live
    /// and one stale entry, so two per connection are reserved as above.
    waiting_fds: std.ArrayListUnmanaged(WaitEntry) = .empty,
    /// Cancels of closed clients' blocking reads still to be sent
    /// (`releaseForwardsFor`).
    pending_cancels: std.ArrayListUnmanaged(struct { target: u16, seq: u64 }) = .empty,
    /// The last `WaitEntry.seq` given out; never 0.
    wait_seq: u32 = 0,
    /// Connections waiting for each target's room, by class
    /// (`Connection.in_queue`): a new request for that target queues behind
    /// them.
    queued: [2][@import("../config/server.zig").MAX_SHARDS]u32 = .{ @splat(0), @splat(0) },
    /// When a refusal after waiting was last logged, per wait reason.
    wait_warn_ms: [@typeInfo(Connection.WaitReason).@"enum".field_names.len]u64 = @splat(0),
    /// Connections paused now, and when the stall check next runs.
    paused_count: u32 = 0,
    stall_check_ms: u64 = 0,
    overflow_warn_ms: u64 = 0,
    overflow_unsaid: u64 = 0,

    /// Self-routing run ID generator (per-shard, single-threaded).
    run_id_gen: run_id_mod.Generator,

    /// Global metrics registry (optional, set by runtime when dashboard is enabled).
    metrics_registry: ?*MetricsRegistry,

    /// The node's live count of held client connections, for the acceptor's
    /// connection cap. A shard releases a slot here when it closes a client
    /// connection (not an admin one, which the cap never reserved). The runtime
    /// wires it; null in tests and when there is no cap.
    active_connections: ?*std.atomic.Value(u32) = null,

    /// What booting a shard needs from the runtime. Both are optional: a
    /// shard built in a test has neither.
    pub const Boot = struct {
        /// Where replay progress is published while the shard boots.
        health: ?*health_mod.ShardSlot = null,
        /// Every shard's slot on the node.
        node_health: []health_mod.ShardSlot = &.{},
        /// Set when another shard's boot failed: replay stops early, so the
        /// failure is reported without waiting for every replay to finish.
        cancel: ?*const std.atomic.Value(bool) = null,
        /// The node's namespace table, shared by its shards; a shard built
        /// without one makes its own.
        namespaces: ?*@import("../namespace/table.zig").Table = null,

        fn cancelled(self: Boot) bool {
            const cancel = self.cancel orelse return false;
            return cancel.load(.monotonic);
        }
    };

    pub fn init(
        allocator: std.mem.Allocator,
        shard_id: u16,
        shard_count: u16,
        partition_count: u32,
        acceptor_pipe_rd: i32,
        data_dir: ?[]const u8,
        ual_capacity: usize,
        max_hot_entries: u64,
        hot_flush_seconds: u64,
        durability: Durability,
        node_id: u32,
        cluster_role: ClusterRole,
        raft_config: raft_node_mod.Config,
        boot: Boot,
    ) !Shard {
        var reactor = try Reactor.init(allocator);
        errdefer reactor.deinit();

        var slab = try SlabAllocator.init(allocator);
        errdefer slab.deinit();

        // Without its wake a shard sees another's message only at its poll
        // timeout; a shard that cannot have one does not start.
        var reply_pool = try ReplyPool.init(allocator, ReplyPool.slotsFor(shard_count), shard_count);
        errdefer reply_pool.deinit(allocator);
        var gathers = try Gathers.init(allocator);
        errdefer gathers.deinit(allocator);
        var waiter_pool = try WaiterPool.init(allocator);
        errdefer waiter_pool.deinit(allocator);
        waiter_pool.owner = shard_id;
        waiter_pool.split = shard_count > 1 or cluster_role != .single;
        const mailbox = try Mailbox.create(allocator, 1024, reply_pool.ringCapacity(), shard_count);
        errdefer mailbox.destroy(allocator);
        try reactor.addSource(.{ .fd = mailbox.wake.rd, .tag = .inbox_ready, .interests = .{ .readable = true } });

        // Forward-proxy Connection: drives requests forwarded from peer
        // shards. fd=-1 means "no kernel socket" — handlers only touch
        // write_buf / response_deferred / metadata, never the fd.
        const forward_proxy = try allocator.create(Connection);
        errdefer allocator.destroy(forward_proxy);
        forward_proxy.* = try Connection.init(allocator, -1, 0, @as(u16, @intCast(shard_id)));
        forward_proxy.protocol = .binary;
        errdefer forward_proxy.deinit();

        // Create the default partition (1 per shard for now).
        // The partition owns UAL + ProjectionRouter + all four projections.
        const partitions = try allocator.alloc(*Partition, 1);
        errdefer allocator.free(partitions);

        const partition = try allocator.create(Partition);
        errdefer allocator.destroy(partition);
        partition.* = try Partition.init(allocator, @as(u32, shard_id), ual_capacity, max_hot_entries);
        errdefer partition.deinit();
        partition.wireProjections();
        partitions[0] = partition;

        // Create handlers pointing at the default partition's projections
        const kv_handler = try allocator.create(KVHandler);
        errdefer allocator.destroy(kv_handler);
        kv_handler.* = KVHandler.init(allocator, &partition.kv);
        kv_handler.txn_table.shard_id = @intCast(shard_id);
        errdefer kv_handler.deinit();

        const stream_handler = try allocator.create(StreamHandler);
        errdefer allocator.destroy(stream_handler);
        stream_handler.* = StreamHandler.init(allocator, partition);

        const queue_handler = try allocator.create(QueueHandler);
        errdefer allocator.destroy(queue_handler);
        queue_handler.* = QueueHandler.init(allocator);

        const ts_handler = try allocator.create(TSHandler);
        errdefer allocator.destroy(ts_handler);
        ts_handler.* = TSHandler.init(allocator, &partition.ts);

        // Create Namespace handler (no projection needed)
        const namespace_handler = try allocator.create(NamespaceHandler);
        errdefer allocator.destroy(namespace_handler);
        namespace_handler.* = try NamespaceHandler.initFor(allocator, shard_id, boot.namespaces);
        errdefer namespace_handler.deinit();

        // Create Actions handler
        const actions_handler = try allocator.create(ActionsHandler);
        errdefer allocator.destroy(actions_handler);
        actions_handler.* = ActionsHandler.init(allocator);

        // Create Worker handler (worker registry)
        const worker_handler = try allocator.create(WorkerHandler);
        errdefer allocator.destroy(worker_handler);
        worker_handler.* = WorkerHandler.init(allocator);

        // Create Workflow handler
        const workflow_handler = try allocator.create(WorkflowHandler);
        errdefer allocator.destroy(workflow_handler);
        workflow_handler.* = WorkflowHandler.init(allocator);
        workflow_handler.namespaces = namespace_handler;

        // Create Processing handler
        const processing_handler = try allocator.create(ProcessingHandler);
        errdefer allocator.destroy(processing_handler);
        processing_handler.* = ProcessingHandler.init(allocator);
        // Set before the log replays: whether a stored job starts depends on
        // them (a kv_lookup, a sink on another shard).
        processing_handler.peer_shard_count = shard_count;
        processing_handler.peer_partition_count = Router.init(partition_count, shard_count, shard_id).partition_count;
        processing_handler.own_shard = shard_id;
        processing_handler.ns_table = namespace_handler.table;

        // Create SegmentWriter (persistence — per-shard, not per-partition)
        const seg_writer = try allocator.create(SegmentWriter);
        errdefer allocator.destroy(seg_writer);
        seg_writer.* = SegmentWriter.init(allocator, @as(u32, shard_id));
        errdefer seg_writer.deinit();

        // Create Raft consensus node, identified by this node's cluster id
        // (the group id tells shards apart). Bootstrapped below, after replay
        // and the segment-writer hook.
        const raft_node = try allocator.create(RaftNode);
        errdefer allocator.destroy(raft_node);
        raft_node.* = try RaftNode.init(allocator, node_id, @as(u32, shard_id), raftRingCapacity(ual_capacity), raft_config);
        errdefer raft_node.deinit();
        raft_node.build = apply_marker.build_hash;
        // KV reads judge expiry by the time line the stamps follow.
        partition.kv.read_clock = .{ .ctx = raft_node, .now_ns = RaftNode.nowOpaque };
        const rpc_entries = try allocator.alloc(entry_mod.Entry, RPC_MAX_ENTRIES);
        errdefer allocator.free(rpc_entries);
        // Mapped, not filled: a group with no peers never touches them.
        const rpc_arena = try large_buffer.alloc(allocator, u8, RPC_BATCH_BYTES);
        errdefer large_buffer.free(allocator, u8, rpc_arena);
        const rpc_out = try large_buffer.alloc(allocator, u8, transport.APPEND_REQ_PREFIX + RPC_MAX_ENTRIES * entry_mod.HEADER_SIZE + RPC_BATCH_BYTES);
        errdefer large_buffer.free(allocator, u8, rpc_out);
        const pending = try allocator.alloc(Pending, PENDING_SLOTS);
        errdefer allocator.free(pending);
        @memset(pending, .{});
        const respond_proxy = try allocator.create(Connection);
        errdefer allocator.destroy(respond_proxy);
        respond_proxy.* = try Connection.init(allocator, -1, 0, @as(u16, @intCast(shard_id)));
        respond_proxy.protocol = .binary;
        errdefer respond_proxy.deinit();
        const forwards = try allocator.alloc(Forward, FORWARD_SLOTS);
        errdefer allocator.free(forwards);
        @memset(forwards, .{});

        var shard_data_dir: ?[]const u8 = null;
        var hard_state_store: ?*HardStateStore = null;
        // A node with no data dir has no hard state to lose.
        var had_hard_state = true;
        // Under async flush a crashed quorum can lose committed entries
        // this node kept on disk, and a leader then rewrites them. An entry
        // applied can't be taken back, so a member's boot applies nothing
        // before a leader commits it; the configs its segments were sealed
        // under still commit (`bringUpGroup`). Alone, nothing can rewrite
        // what this node flushed.
        const cold_boot = durability == .async_flush and cluster_role != .single;
        var config_mark: u64 = 0;
        // What boot found: losses counted along the way, and damage that
        // stopped replay (that shard then serves nothing on a lone node, or
        // takes no part in its group).
        var losses: silent_loss.Counts = .{};
        var boot_damage: ?silent_loss.Damage = null;
        var boot_halt: ?Halt = null;
        var marker: apply_marker.Marker = .{};
        errdefer marker.close();
        var skips: repair.Skips = .{};
        errdefer skips.deinit(allocator);
        errdefer if (hard_state_store) |store| allocator.destroy(store);
        var durable_log: ?*DurableLog = null;
        errdefer if (durable_log) |dl| {
            dl.deinit();
            allocator.destroy(dl);
        };

        // Build replay registry — handlers register their entry types
        // so replaySegments and handleInboxMessage can dispatch without
        // hardcoded type checks. Created before data_dir block so it's
        // always available for the Shard struct.
        var replay_registry: ReplayRegistry = .{};
        // A committed config is the membership a truncation falls back to;
        // the Raft node is on the heap, so it is the applier's context.
        replay_registry.register(.raft_config, @ptrCast(raft_node), applyRaftConfig);
        workflow_handler.registerReplay(&replay_registry);
        namespace_handler.registerReplay(&replay_registry);
        processing_handler.registerReplay(&replay_registry);
        stream_handler.registerReplay(&replay_registry);
        try checkAppliers(shard_id, &replay_registry);

        const apply_buf = try large_buffer.alloc(allocator, u8, limits.MAX_LOG_ENTRY_PAYLOAD);
        errdefer large_buffer.free(allocator, u8, apply_buf);
        // Mapped, not filled: a shard with no client never writes them.
        const read_buf = try large_buffer.mapped(u8, READ_CHUNK);
        errdefer large_buffer.unmap(u8, read_buf);
        const parse_buf = try large_buffer.mapped(u8, MAX_REQUEST_SIZE);
        errdefer large_buffer.unmap(u8, parse_buf);
        const entry_buf = try large_buffer.mapped(u8, persistence_mod.MAX_PERSIST_PAYLOAD);
        errdefer large_buffer.unmap(u8, entry_buf);
        var scratch = try Scratch.init(allocator, SCRATCH_SIZE);
        errdefer scratch.deinit(allocator);

        if (data_dir) |dir| {
            // Build shard-specific data directory: data_dir/00000/
            const shard_dir = try std.fmt.allocPrint(allocator, "{s}/{d:0>5}", .{ dir, shard_id });
            errdefer allocator.free(shard_dir);

            // Each synced into its parent: a lost directory takes HARDSTATE
            // and every segment inside it with it.
            @import("stdx").fs.makePathDurable(shard_dir) catch |err| {
                log.err("shard {d}: cannot create or sync {s}: {s}", .{ shard_id, shard_dir, @errorName(err) });
                return err;
            };

            marker = apply_marker.Marker.open(shard_dir, shard_id) catch |err| m: {
                // Opened empty, a crash it records would be lost: a resource
                // failure refuses the boot instead, as a segment's does.
                if (bootRefuses(err)) return refuseBlockedRead(shard_id, apply_marker.FILENAME, err);
                log.warn("shard {d}: cannot open {s}/{s} ({s}); a crash in apply will not be recorded", .{ shard_id, shard_dir, apply_marker.FILENAME, @errorName(err) });
                break :m .{};
            };

            const segs_dir_path = try std.fmt.allocPrint(allocator, "{s}/segs", .{shard_dir});
            defer allocator.free(segs_dir_path);
            @import("stdx").fs.makePathDurable(segs_dir_path) catch |err| {
                log.err("shard {d}: cannot create or sync {s}: {s}", .{ shard_id, segs_dir_path, @errorName(err) });
                return err;
            };
            const dl = try allocator.create(DurableLog);
            dl.* = DurableLog.init(allocator, seg_writer, segs_dir_path) catch |err| {
                allocator.destroy(dl);
                return err;
            };
            durable_log = dl;

            // ── Hard state ──────────────────────────────────────────────
            // The term and vote this shard's Raft node must not forget.
            const loaded = hard_state_mod.load(shard_dir) catch |err| {
                log.err("shard {d}: cannot read {s}/{s}: {s}", .{ shard_id, shard_dir, hard_state_mod.FILENAME, @errorName(err) });
                return err;
            };
            had_hard_state = loaded != null;
            if (loaded) |hs| {
                if (hs.node_id != node_id) {
                    log.err("shard {d}: {s}/HARDSTATE belongs to node {d}, this node is {d}; the shard directories come from different nodes", .{ shard_id, shard_dir, hs.node_id, node_id });
                    return error.NodeIdMismatch;
                }
                // Only corruption gets one past the ceiling (the file is
                // checksummed); a node there could never campaign again.
                if (hs.term > raft_node_mod.MAX_TERM) {
                    log.err("shard {d}: {s}/HARDSTATE holds term {d}, past the highest term a node takes ({d}); refusing to start on it", .{ shard_id, shard_dir, hs.term, raft_node_mod.MAX_TERM });
                    return error.TermSpaceExhausted;
                }
                raft_node.current_term = hs.term;
                raft_node.voted_for = hs.voted_for;
                if (hs.lost_log) raft_node.resumeLostLog();
            }
            const store = try allocator.create(HardStateStore);
            store.* = .{ .dir = shard_dir, .node_id = node_id, .shard_id = shard_id };
            hard_state_store = store;
            raft_node.hard_state_sink = .{ .ctx = @ptrCast(store), .persist = HardStateStore.persist };

            // Replay existing segment files from segs/ into partition.
            // Replay also rebuilds the Raft log (last index, term index and
            // the hot-ring tail) from the same pass over the segments.
            //
            // Only entries at or below the segments' commit watermark reach
            // the projections; the rest is loaded into the log and drained
            // by `applyDeferredTail` (see `SegmentHeader.commit_index_at_seal`).
            // A cold boot replays the log and applies none of it.
            //
            // A `.flseg.tmp` is a rewrite a crash cut short, never part of
            // the log; the active segment's torn tail is a flush cut short,
            // cut back to its last whole entry. A `.flseg` that will not read
            // is damage, and replay stops there, unless the read failed for
            // want of resources: then boot refuses, and a restart may read it.
            _ = durable_log.?.removeTornTail() catch |err| log.warn("shard {d}: could not remove a torn segment flush: {s}", .{ shard_id, @errorName(err) });
            // Before anything lists the log: a mark behind its entries would
            // hide written ones from replay.
            _ = durable_log.?.recoverActive() catch |err| {
                // A header that won't read is the listing's to report, below,
                // as the damage it is.
                if (durable_log.?.badHeaderSegment().len == 0) {
                    log.err("shard {d}: could not recover the newest segment's tail: {s}; not starting, since what it holds is unknown until it is", .{ shard_id, @errorName(err) });
                    return err;
                }
            };
            var watermark: u64 = 0;
            var replayed_stamp: u64 = 0;
            if (boot_damage == null) {
                const log_files = durable_log.?;
                if (listDurable(log_files)) |files| replay: {
                    for (files) |f| watermark = @max(watermark, f.commit_index_at_seal);
                    // Before anything applies: a skipped entry must not run,
                    // whatever this build would make of it. The skip set
                    // wins over a crash marker too.
                    boot_damage = try collectSkips(allocator, files, watermark, &skips, shard_id);
                    if (boot_damage != null) break :replay;
                    if (marker.crashed) |*c| if (skips.holds(&.{ .index = c.index, .term = c.term, .crc = c.entry_crc })) marker.skipped();
                    const replayed = replaySegments(allocator, files, partition, &replay_registry, if (cold_boot) 0 else watermark, &raft_node.log, shard_id, &losses, &marker, &skips, boot);
                    if (replayed.cancelled) return error.BootCancelled;
                    if (replayed.blocked) |b| return refuseBlockedRead(shard_id, b.name, b.err);
                    boot_damage = replayed.damage;
                    boot_halt = replayed.halt;
                    raft_node.last_applied = replayed.applied_through;
                    replayed_stamp = replayed.last_stamp;
                } else |err| {
                    if (log_files.badHeaderSegment().len == 0) return err;
                    boot_damage = if (DurableLog.isPermission(err))
                        silent_loss.Damage.init(.segment_header_unreadable, "segment {s}: permission denied; fix the file's permissions and restart", .{log_files.badHeaderSegment()})
                    else
                        silent_loss.Damage.init(.segment_header_unreadable, "segment {s} has a header that will not read ({s})", .{ log_files.badHeaderSegment(), @errorName(err) });
                }
            }
            // Replay clears a crash on an entry it found replaced; one past
            // what it applied is still ahead.
            marker.dropBelow(raft_node.log.start());
            if (marker.crashed) |*c| log.err("shard {d}: applying entry {d} crashed this node before the restart; it halts there instead of applying it again", .{ shard_id, c.index });
            if (cold_boot) {
                config_mark = watermark;
                if (!raft_node.log.isEmpty()) log.info("shard {d}: async durability: the {d} entries replayed apply once a leader commits them", .{ shard_id, raft_node.log.lastIndex() });
            } else if (watermark == 0 and !raft_node.log.isEmpty()) {
                log.warn("shard {d}: no segment carries a commit watermark; everything is applied at boot through the log instead of replay", .{shard_id});
            }

            // Replay's own, not the router's: an entry replay halted at
            // moved the router's past it, and a shard that halted live
            // keeps the stamp of the entry before.
            raft_node.noteApplied(replayed_stamp);
            if (boot_halt) |*h| {
                raft_node.halt_at = .{ .index = h.index, .term = h.term, .crc = h.crc };
                marker.halted(h.index, h.term, h.crc);
                log.err("shard {d} comes up halted at {s}, as it was before the restart. It applies nothing past it and takes no writes until a repair", .{ shard_id, h.reason() });
            }

            shard_data_dir = shard_dir;
        }
        // The block's own errdefer for the path ended with the block.
        errdefer if (shard_data_dir) |d| allocator.free(d);

        // Feed every Raft log append to the segment writer from here on.
        // Attached after replay (a hook active during replay would re-buffer
        // every entry just read) and before bootstrap, so the noop that
        // opens each leadership term is durable like any other entry and
        // the on-disk log has no holes at the next boot.
        // Only the Raft log UAL persists — partition.ual is a read cache
        // whose entries are already covered by the Raft log's persistence.
        raft_node.log.ual.on_append_ctx = @ptrCast(seg_writer);
        raft_node.log.ual.on_append = segmentBufferCallback;
        seg_writer.stop_at_gap = durability == .sync;
        var catch_up: ?*CatchUp = null;
        errdefer if (catch_up) |cu| {
            cu.deinit();
            allocator.destroy(cu);
        };
        var stream_disk: ?*DiskReads = null;
        errdefer if (stream_disk) |d| {
            d.deinit();
            allocator.destroy(d);
        };
        if (durable_log) |dl| {
            const d = try allocator.create(DiskReads);
            d.* = DiskReads.init(allocator, dl, &raft_node.log);
            d.commit = &raft_node.commit_index;
            dl.on_cut = .{ .ctx = d, .after = DiskReads.cutHook };
            stream_disk = d;
        }
        if (durable_log) |dl| {
            const cu = try allocator.create(CatchUp);
            cu.* = CatchUp.init(allocator, dl, RPC_MAX_ENTRIES, RPC_BATCH_BYTES);
            catch_up = cu;
            raft_node.log.catch_up = cu.source();
            raft_node.log.on_truncate_ctx = @ptrCast(dl);
            raft_node.log.on_truncate = durableTruncate;
        }
        if (boot_damage) |*damage| {
            losses.note(damage.path, nowMs(), shard_id, "{s}", .{damage.reason()});
            if (cluster_role == .single) {
                log.err("shard {d} is offline on this node: {s}. Its requests are refused; the other shards serve. A restart may help if the cause was memory; otherwise the data directory needs repair", .{ shard_id, damage.reason() });
            } else {
                log.err("shard {d}: {s}. This node's copy can no longer be trusted and it takes no part in the group. Stop it, move its data directory aside, and start it again with --join <a live member>", .{ shard_id, damage.reason() });
            }
        } else {
            try bringUpGroup(raft_node, cluster_role, apply_buf, shard_id, node_id, had_hard_state, config_mark);
        }

        // Build dispatcher and register all handlers
        var dispatcher = Dispatcher.init();
        dispatcher.setErrorHandler(answerUnknownOp);
        KVHandler.register(&dispatcher);
        StreamHandler.register(&dispatcher);
        QueueHandler.register(&dispatcher);
        TSHandler.register(&dispatcher);
        NamespaceHandler.register(&dispatcher);
        ActionsHandler.register(&dispatcher);
        WorkerHandler.register(&dispatcher);
        WorkflowHandler.register(&dispatcher);
        dispatcher.register(.system_walk_page, walk_mod.handlePage);
        dispatcher.register(.system_holds_run, handleHoldsRun);
        dispatcher.register(.system_runs_page, @import("../workflow/list_runs.zig").handlePage);
        ProcessingHandler.register(&dispatcher);
        dispatcher.register(.cluster_status, dispatchClusterStatus);
        dispatcher.register(.cluster_members, dispatchClusterMembers);
        dispatcher.register(.cluster_promote, dispatchClusterPromote);
        dispatcher.register(.cluster_remove, dispatchClusterRemove);
        dispatcher.register(.cluster_repair_skip, dispatchClusterRepairSkip);

        // Register ping handler
        dispatcher.register(.ping, handlePing);

        log.debug("Shard {d} initializing: shard_count={d} partition_count={d} handlers={d} data_dir={s}", .{
            shard_id,
            shard_count,
            partition_count,
            dispatcher.handler_count,
            data_dir orelse "(ephemeral)",
        });

        return .{
            .id = shard_id,
            .allocator = allocator,
            .reactor = reactor,
            .mailbox = mailbox,
            .reply_pool = reply_pool,
            .gathers = gathers,
            .dispatcher = dispatcher,
            .connections = .{},
            .router = Router.init(partition_count, shard_count, shard_id),
            .slab = slab,
            .acceptor_pipe_rd = acceptor_pipe_rd,
            .stop_requested = .init(false),
            .stopping = null,
            .next_conn_id = 1,
            .requests_dispatched = 0,
            .inbox_messages_processed = 0,
            .partitions = partitions,
            .num_partitions = 1,
            .kv_handler = kv_handler,
            .stream_handler = stream_handler,
            .queue_handler = queue_handler,
            .ts_handler = ts_handler,
            .namespace_handler = namespace_handler,
            .actions_handler = actions_handler,
            .worker_handler = worker_handler,
            .workflow_handler = workflow_handler,
            .processing_handler = processing_handler,
            .raft_node = raft_node,
            .replica = .{
                .id = shard_id,
                .rpc_entries = rpc_entries,
                .rpc_arena = rpc_arena,
                .rpc_out = rpc_out,
                .diverged = boot_damage != null and cluster_role != .single,
            },
            .join_asked_ms = 0,
            .pending = pending,
            .pending_count = 0,
            .respond_proxy = respond_proxy,
            .forwards = forwards,
            .forward_count = 0,
            .blocking_forwards = 0,
            .replies_held = 0,
            .next_forward_id = FORWARD_ID_FIRST,
            .offline = if (cluster_role == .single) boot_damage else null,
            .diverged_damage = if (cluster_role != .single) boot_damage else null,
            .halted = boot_halt,
            .marker = marker,
            .skips = skips,
            .offline_published = .init(cluster_role == .single and boot_damage != null),
            .losses = losses,
            .health = boot.health,
            .node_health = boot.node_health,
            .join_first_asked_ms = 0,
            .join_warned_ms = 0,
            .join_refused_warn_ms = 0,
            .stranger_warn_ms = 0,
            .late_apply_warn_ms = 0,
            .flush_fail_warn_ms = 0,
            .hard_state_store = hard_state_store,
            .segment_writer = seg_writer,
            .durable_log = durable_log,
            .catch_up = catch_up,
            .stream_disk = stream_disk,
            .persist_failures = 0,
            .durability = durability,
            .shard_data_dir = shard_data_dir,
            .pipe_registered = false,
            .raft_network = null,
            .raft_queue = null,
            .raft_queue_registered = false,
            .shard_metrics = null,
            .cluster_node_id = node_id,
            .waiter_pool = waiter_pool,
            .task_scheduler = TaskScheduler.init(),
            .hot_flush_seconds = hot_flush_seconds,
            .peer_shards = null,
            .peer_mailboxes = null,
            .forward_proxy = forward_proxy,
            .replay_registry = replay_registry,
            .apply_buf = apply_buf,
            .read_buf = read_buf,
            .parse_buf = parse_buf,
            .entry_buf = entry_buf,
            .scratch = scratch,
            .applying = false,
            .apply_behind = false,
            .apply_tick_spent = 0,
            .in_tick = false,
            .producer_ticks = 0,
            // An empty log holds nothing it could serve wrongly.
            .cold_gate = cold_boot and !raft_node.log.isEmpty(),
            .last_entry_applied = true,
            .last_result = .{},
            .wake_workers = false,
            .more_work = false,
            .run_id_gen = .{ .shard = @intCast(shard_id) },
            .metrics_registry = null,
        };
    }

    /// Namespace resolver wired into the queue and stream projections: id →
    /// name via the shard's namespace registry. `ctx` is the (stable, heap-allocated)
    /// `*NamespaceHandler`, so this is safe to call during replay — before the
    /// shard's back-pointers are wired.
    /// Wire shard back-pointers into handlers that need Raft access.
    /// Must be called after shards are at their final heap addresses.
    pub fn wireHandlerShardPtrs(self: *Shard) void {
        self.raft_node.log_flush_sink = .{ .ctx = @ptrCast(self), .flush = flushForConfig };
        self.raft_node.repaired = .{ .ctx = @ptrCast(self), .check = repairedOpaque };
        self.stream_handler.shard_ptr = @ptrCast(self);
        self.stream_handler.disk = self.stream_disk;
        if (self.stream_disk) |d| d.on_damage = .{ .ctx = @ptrCast(self), .report = streamDiskDamage };
        self.queue_handler.shard_ptr = @ptrCast(self);
        self.ts_handler.shard_ptr = @ptrCast(self);
    }

    /// A config entry is about to take effect: the log goes to disk first,
    /// whatever the durability mode.
    fn flushForConfig(ctx: *anyopaque) bool {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        self.flushSegmentToDisk() catch |err| {
            self.noteFlushFailed();
            log.err("shard {d}: flushing a membership change failed: {s}; it does not take effect (persist_failures={d})", .{ self.id, @errorName(err), self.persist_failures });
            return false;
        };
        return true;
    }

    /// Flush buffered Raft log entries to a .flseg file under `shard_data_dir/segs/`,
    /// sealed under the current commit index.
    pub fn flushSegmentToDisk(self: *Shard) !void {
        const dl = self.durable_log orelse return;
        try self.rebufferGap(dl.writer);
        try dl.flush(self.raft_node.commit_index);
        // Flushes are reaching disk again: end the failing run.
        self.flushes_failing_since_ms = 0;
    }

    /// A flush to disk failed: count it (cumulative) and, if this is the first
    /// of a run, record when it began. Every flush path funnels its failure
    /// here; a success clears the run in `flushSegmentToDisk`.
    fn noteFlushFailed(self: *Shard) void {
        self.persist_failures += 1;
        if (self.flushes_failing_since_ms == 0) self.flushes_failing_since_ms = nowMs();
    }

    /// Buffer again what the append hook could not, from the log, so the
    /// flush writes a run without a gap. The log evicts by size, so the
    /// entry may be gone; then nothing after it can reach disk, and the
    /// shard takes no more writes until a restart.
    fn rebufferGap(self: *Shard, writer: *SegmentWriter) !void {
        const raft = self.raft_node;
        const from = writer.first_unbuffered orelse {
            // A truncation cut the missing entry away: nothing is owed.
            if (raft.writes_stopped) {
                raft.writes_stopped = false;
                log.info("shard {d}: the entry that never reached disk was cut from the log; taking writes again", .{self.id});
            }
            return;
        };
        var idx = from;
        while (idx <= raft.log.lastIndex()) : (idx += 1) {
            const e = raft.log.getEntryCopy(idx, self.apply_buf) orelse {
                if (!raft.writes_stopped) {
                    raft.writes_stopped = true;
                    log.err("shard {d}: entry index={d} left memory before it reached disk, so nothing after it can be flushed; this shard takes no more writes until it restarts", .{ self.id, idx });
                }
                return error.EntryUnavailable;
            };
            writer.addEntry(&e) catch |err| {
                writer.first_unbuffered = idx;
                return err;
            };
        }
        writer.first_unbuffered = null;
        // Buffering has caught up: end any failing run. Behind a sync gap the
        // append hook returns early, so this is the only place a sync-mode run
        // ends; the cumulative count stays.
        writer.buffer_failing_since_ms = 0;
    }

    /// Start applying what replay loaded into the log above the commit
    /// watermark, once the shard is at its final address. A shard that
    /// bootstrapped re-established commit at the tip and takes one pass of
    /// the tail here; ticks apply the rest, and its reads are refused until
    /// they have (`refusedRead`). One that follows has nothing to apply until
    /// a leader speaks.
    pub fn applyDeferredTail(self: *Shard) void {
        const raft = self.raft_node;
        const pending = raft.commit_index -| raft.last_applied;
        // Bootstrapping commits the term's noop with the tail, unless
        // commits wait for the disk: then it isn't committed yet.
        const noop: u64 = if (self.durability == .sync) 0 else 1;
        if (pending > noop) {
            log.info("shard {d}: applying {d} durable entries above the commit watermark (indices {d}..{d})", .{ self.id, pending, raft.last_applied + 1, raft.commit_index });
        }
        // A shard halted at boot has said so: nothing past its halt applies.
        // A blocked read at boot is not missing writes either — it is held and
        // retried — so it says that instead of crying data loss.
        if (!self.applyCommitted() and self.halted == null and self.offline == null) {
            if (self.read_blocked) {
                log.warn("shard {d}: a committed entry could not be read to apply at boot ({s}); holding and retrying", .{ self.id, self.blockCause() });
            } else {
                log.err("shard {d}: not every durable entry above the commit watermark could be applied at boot; projections are missing writes", .{self.id});
            }
        }
    }

    /// With sync durability, flush what the log holds and tell the Raft
    /// node it's on disk: a leader's own copy counts toward commit only then.
    pub fn syncFlushIfNeeded(self: *Shard) void {
        if (self.durability != .sync or self.hold_sync_flush) return;
        const raft = self.raft_node;
        const through = raft.log.lastIndex();
        self.flushSegmentToDisk() catch |err| {
            self.noteFlushFailed();
            const now = nowMs();
            if (now -| self.flush_fail_warn_ms >= WARN_INTERVAL_MS) {
                self.flush_fail_warn_ms = now;
                log.err("shard {d}: sync flush failed: {s}; writes not on disk are not acked (persist_failures={d})", .{ self.id, @errorName(err), self.persist_failures });
            }
            // Alone, nothing else can make these writes durable: tell their
            // clients now rather than leave them waiting on the disk.
            if (raft.role == .leader and raft.voterPeers() == 0) {
                self.failPendingAbove(raft.durable_index, if (raft.writes_stopped) LOST_AT_RESTART else NOT_ON_DISK);
            }
            return;
        };
        raft.markDurable(through);
    }

    /// What a client is told when its write is in the log but its flush
    /// failed: it may still commit once the disk recovers.
    pub const NOT_ON_DISK = "unavailable: write not on disk (flush failed); it may still apply once the disk recovers — check before resending";

    /// The same, once the shard has stopped taking writes: nothing more
    /// reaches disk, so the write is gone when the node restarts.
    pub const LOST_AT_RESTART = "unavailable: write not on disk, and this shard stopped taking writes; it is lost when the node restarts — resend after the restart";

    fn failPendingAbove(self: *Shard, index: u64, message: []const u8) void {
        if (self.pending_count == 0) return;
        for (self.pending) |*slot| {
            if (!slot.active or slot.index <= index) continue;
            self.deliverDeferredError(slot.reply_to, slot.request_id, .unavailable, message);
            self.endPending(slot);
        }
    }

    fn inboxPending(ctx: *const anyopaque) u64 {
        const mailbox: *const Mailbox = @ptrCast(@alignCast(ctx));
        return mailbox.inbox.pending();
    }

    /// Wire the global MetricsRegistry into this shard and its handlers.
    /// Called by runtime after the registry is created.
    pub fn setMetricsRegistry(self: *Shard, registry: *MetricsRegistry) void {
        self.metrics_registry = registry;
        // Resolved once: the shard table is sized by `initShards` before this
        // runs, and the pointer is stable for the registry's lifetime. Without
        // it every `flo_shard_*` series exports 0 while the global `flo_*`
        // equivalents move, which reads as "this shard is idle".
        self.shard_metrics = registry.shardMetrics(self.id);
        if (self.shard_metrics) |sm| sm.live_pending = .{ .ctx = self.mailbox, .read = inboxPending };
        self.stream_handler.metrics_registry = registry;
        // Tier-hit counters are per log; resolve once so the read path avoids a
        // registry lookup per record. Also the only caller of registerTieredLog,
        // without which the flo_tiered_log_* family never appears at all.
        self.stream_handler.tiered_metrics = registry.registerTieredLog(self.id) catch null;
        self.queue_handler.metrics_registry = registry;
        self.kv_handler.metrics_registry = registry;
    }

    pub fn deinit(self: *Shard) void {
        self.marker.close();
        for (self.kv_sink_retries.items) |b| self.allocator.free(b);
        self.kv_sink_retries.deinit(self.allocator);
        self.skips.deinit(self.allocator);
        self.closing_fds.deinit(self.allocator);
        self.resume_fds.deinit(self.allocator);
        self.waiting_fds.deinit(self.allocator);
        self.pending_cancels.deinit(self.allocator);
        self.resume_running.deinit(self.allocator);
        // Close all connections (close fds + free buffers)
        var it = self.connections.iterator();
        while (it.next()) |entry| {
            const fd = entry.key_ptr.*;
            entry.value_ptr.*.deinit();
            self.allocator.destroy(entry.value_ptr.*);
            _ = std.c.close(fd);
        }
        self.connections.deinit(self.allocator);

        // Flush pending entries to segment file on shutdown
        self.flushSegmentToDisk() catch |err| {
            log.err("shard {d}: final flush on shutdown failed: {s} (buffered entries may be lost)", .{ self.id, @errorName(err) });
        };

        // The runtime stops the bulk thread before it frees any shard, so no
        // read still writes here.
        if (self.catch_up) |cu| {
            cu.deinit();
            self.allocator.destroy(cu);
        }
        if (self.stream_disk) |d| {
            d.deinit();
            self.allocator.destroy(d);
        }
        if (self.durable_log) |dl| {
            dl.deinit();
            self.allocator.destroy(dl);
        }
        // Clean up SegmentWriter
        self.segment_writer.deinit();
        self.allocator.destroy(self.segment_writer);

        // The store borrows shard_data_dir, so it goes first.
        if (self.hard_state_store) |store| self.allocator.destroy(store);
        if (self.shard_data_dir) |dir| {
            self.allocator.free(dir);
        }

        // Clean up handlers (they don't own projections — partitions do)
        self.kv_handler.deinit();
        self.allocator.destroy(self.kv_handler);
        self.stream_handler.deinit();
        self.allocator.destroy(self.stream_handler);
        self.queue_handler.deinit();
        self.allocator.destroy(self.queue_handler);
        self.allocator.destroy(self.ts_handler);

        // Clean up Raft consensus node
        self.raft_node.deinit();
        self.allocator.destroy(self.raft_node);
        for (self.forwards) |*f| if (f.active) {
            self.allocator.free(f.bytes);
            if (f.reply) |r| self.allocator.free(r);
            if (f.ask) |a| self.allocator.free(a);
        };
        self.edge.deinit(self.allocator);
        self.allocator.free(self.forwards);
        self.allocator.free(self.pending);
        self.respond_proxy.deinit();
        self.allocator.destroy(self.respond_proxy);
        self.allocator.free(self.replica.rpc_entries);
        large_buffer.free(self.allocator, u8, self.replica.rpc_arena);
        large_buffer.free(self.allocator, u8, self.replica.rpc_out);
        large_buffer.free(self.allocator, u8, self.apply_buf);
        large_buffer.unmap(u8, self.read_buf);
        large_buffer.unmap(u8, self.parse_buf);
        large_buffer.unmap(u8, self.entry_buf);
        self.scratch.deinit(self.allocator);

        // Clean up partitions (each owns UAL + all projections)
        for (self.partitions) |p| {
            p.deinit();
            self.allocator.destroy(p);
        }
        self.allocator.free(self.partitions);

        // Clean up Namespace and Actions handlers
        self.namespace_handler.deinit();
        self.allocator.destroy(self.namespace_handler);
        self.actions_handler.deinit();
        self.allocator.destroy(self.actions_handler);
        self.worker_handler.deinit();
        self.allocator.destroy(self.worker_handler);
        self.workflow_handler.deinit();
        self.allocator.destroy(self.workflow_handler);
        self.processing_handler.deinit();
        self.allocator.destroy(self.processing_handler);

        self.forward_proxy.deinit();
        self.allocator.destroy(self.forward_proxy);

        self.freeUndelivered();
        self.mailbox.destroy(self.allocator);
        self.gathers.deinit(self.allocator);
        self.reply_pool.deinit(self.allocator);
        self.waiter_pool.deinit(self.allocator);
        self.slab.deinit();
        self.reactor.deinit();
    }

    // ─── Partition access ────────────────────────────────────────────────

    /// Get the default (first) partition.
    /// Currently each shard has exactly 1 partition.
    pub fn defaultPartition(self: *Shard) *Partition {
        return self.partitions[0];
    }

    /// Get a partition by partition_id.
    /// For now, all partition_ids map to the single default partition.
    /// When multi-partition is enabled, this will index into the array.
    pub fn getPartition(self: *Shard, partition_id: u32) *Partition {
        _ = partition_id;
        return self.partitions[0];
    }

    // ─── Connection management ───────────────────────────────────────────

    const WaitEntry = struct { fd: i32, seq: u32 };

    /// Add a new connection from an accepted fd.
    pub fn addConnection(self: *Shard, fd: i32) !*Connection {
        const conn = try self.allocator.create(Connection);
        conn.* = try Connection.init(self.allocator, fd, self.next_conn_id, @intCast(self.id));
        log.debug("Shard {d} new connection: fd={d} conn_id={d}", .{ self.id, fd, self.next_conn_id });
        self.next_conn_id += 1;

        errdefer {
            conn.deinit();
            self.allocator.destroy(conn);
        }
        // Stale entries for closed fds stay until the tick ends, so reserve
        // past them.
        try self.closing_fds.ensureTotalCapacity(self.allocator, self.connections.count() + 1 + self.closing_fds.items.len);
        const resume_room = self.connections.count() + 1 + self.resume_fds.items.len;
        try self.resume_fds.ensureTotalCapacity(self.allocator, resume_room);
        try self.resume_running.ensureTotalCapacity(self.allocator, resume_room);
        try self.waiting_fds.ensureTotalCapacity(self.allocator, 2 * (self.connections.count() + 1) + self.waiting_fds.items.len);
        try self.connections.put(self.allocator, fd, conn);
        if (self.metrics_registry) |m| m.server.connectionOpened();
        if (self.shard_metrics) |sm| sm.connectionOpened();
        return conn;
    }

    /// Remove and clean up a connection (does NOT close the fd).
    pub fn removeConnection(self: *Shard, fd: i32) void {
        if (self.connections.fetchRemove(fd)) |kv| {
            if (kv.value.reads_paused) self.paused_count -= 1;
            self.endWait(kv.value);
            // Release the cap slot the acceptor reserved for a client connection
            // (an admin one was never counted). Read before deinit.
            if (!kv.value.admin) if (self.active_connections) |active| {
                _ = active.fetchSub(1, .monotonic);
            };
            kv.value.deinit();
            self.allocator.destroy(kv.value);
            if (self.metrics_registry) |m| m.server.connectionClosed();
            if (self.shard_metrics) |sm| sm.connectionClosed();
        }
    }

    /// Remove connection, unregister from reactor, and close the fd.
    pub fn closeConnection(self: *Shard, fd: i32) void {
        log.debug("Shard {d} closing connection: fd={d}", .{ self.id, fd });
        if (self.connections.get(fd)) |conn| self.waiter_pool.removeByConnection(@intCast(self.id), fd, conn.id, null, @ptrCast(self));
        if (self.forward_count > 0) {
            if (self.connections.get(fd)) |conn| self.dropForwardsFor(fd, conn.id);
        }
        if (self.edge.count > 0) {
            if (self.connections.get(fd)) |conn| self.dropEdgeFor(fd, conn.id);
        }
        if (self.connections.get(fd)) |conn| {
            if (conn.blocking_in_flight > 0) self.releaseForwardsFor(conn);
        }
        self.reactor.removeSource(fd);
        self.removeConnection(fd);
        _ = std.c.close(fd);
    }

    /// A client closed with blocking reads out on other shards: each shard
    /// holding some is asked, once, to drop them and answer each, empty, so
    /// their slots come back within its next tick rather than at their
    /// block time — a client cannot hold another shard's waiters, or this
    /// shard's share of them, by connecting and leaving. The ask goes on
    /// this shard's share of that inbox, like the reads it cancels, so it
    /// never overtakes them; with none left it waits its turn
    /// (`sendPendingCancels`). The slots stay held until answered, so they
    /// never count for less than what is parked.
    fn releaseForwardsFor(self: *Shard, conn: *Connection) void {
        var told = std.bit_set.Static(@import("../config/server.zig").MAX_SHARDS).empty;
        const seq: u64 = (@as(u64, conn.id) << 32) | @as(u32, @bitCast(conn.fd));
        for (conn.blocking_slots[0..conn.blocking_in_flight]) |t| {
            const target = self.reply_pool.orphan(t) orelse continue;
            if (told.isSet(target)) continue;
            told.set(target);
            if (self.sendCancel(target, seq)) continue;
            // At most one ask per slot that is still to be answered; past
            // that, or without memory, the reads end at their block time.
            if (self.pending_cancels.items.len < self.reply_pool.classes[@backingInt(reply_pool_mod.Class.blocking)].free.len) {
                self.pending_cancels.append(self.allocator, .{ .target = target, .seq = seq }) catch {};
            }
        }
        conn.blocking_in_flight = 0;
    }

    fn sendCancel(self: *Shard, target: u16, seq: u64) bool {
        const mailboxes = self.peer_mailboxes orelse return true;
        return mailboxes[target].sendOnShare(.{ .tag = .cancel_reads, .src_shard = @intCast(self.id), .sequence = seq });
    }

    /// Send the cancels that found no room in their target's inbox, now
    /// that some may have drained.
    fn sendPendingCancels(self: *Shard) void {
        var kept: usize = 0;
        for (self.pending_cancels.items) |c| {
            if (self.sendCancel(c.target, c.seq)) continue;
            self.pending_cancels.items[kept] = c;
            kept += 1;
        }
        self.pending_cancels.shrinkRetainingCapacity(kept);
    }

    /// Get a connection by fd.
    pub fn getConnection(self: *Shard, fd: i32) ?*Connection {
        return self.connections.get(fd);
    }

    // ─── Dispatch ────────────────────────────────────────────────────────

    /// Every request runs through here, wherever it came from: authorized,
    /// checked, then routed if it is a client's, or run here if another
    /// shard or node routed it already.
    pub fn runRequest(self: *Shard, conn: *Connection, req_in: proto.Request, origin: run_mod.Origin) void {
        var req = req_in;
        req.ns_id = self.namespaceIdOf(req);
        const auth = switch (run_mod.authorize(conn.principal, origin, req)) {
            .ok => |a| a,
            .refused => |r| return self.sendRefusal(conn, req.header.request_id, r.status, r.refusal),
        };

        // A wait longer than the server keeps a waiter is refused here, once
        // for every kind, not shortened where it is registered.
        if (req.findOption(.block_ms)) |opt| {
            if ((opt.asU32() orelse 0) > waiter_pool_mod.MAX_BLOCK_MS) {
                self.sendRefusal(conn, req.header.request_id, .bad_request, .{ .reason = .out_of_range, .ran = .no, .message = "bad request: a blocking wait (block_ms, --block) is at most 300000 ms (5 minutes)" });
                return;
            }
        }

        // Every namespace a request names meets the one rule here, before
        // anything runs: a write to an unknown namespace creates it.
        if (req.namespace.len > 0) {
            if (handler_mod.nameRefusal(req.namespace)) |why| {
                self.sendRefusal(conn, req.header.request_id, .bad_request, proto.notRun(why));
                return;
            }
        }
        // A read of a namespace no one created finds none; a client's read
        // is resolved here, once, before it goes anywhere.
        if ((origin == .client or origin == .admin) and self.edgeMiss(conn, req, origin)) return;

        switch (origin) {
            .client, .admin => self.route(conn, req, auth),
            .shard, .held => self.dispatchLocal(conn, req, auth),
            // A node forwards only writes to its leader.
            .peer => if (!self.dispatcher.serves(req.header.op_code))
                answerUnknownOp(@ptrCast(self), @ptrCast(conn), req.header.request_id, req.header.op_code)
            else if (requestToLeader(req) or req.header.op_code == @backingInt(proto.OpCode.namespace_published))
                self.dispatchLocal(conn, req, auth)
            else
                self.sendRefusal(conn, req.header.request_id, .bad_request, proto.notRun("bad request: only writes, reads the leader answers, and a follower's ask about the namespaces, are forwarded to a leader")),
        }
    }

    /// The id this shard (not 0) bound `req`'s namespace to, when the
    /// node's table now has the name under another. Only a shard 0 that
    /// lost a create's tail, and created the name again, gets here: a write
    /// stamped with the table's id would find no binding at apply and halt
    /// there, and its data under the old id is out of reach either way.
    fn boundElsewhere(self: *const Shard, req: proto.Request) ?ns_table.Id {
        if (self.id == 0 or req.ns_id == .invalid) return null;
        const bound = self.namespace_handler.idOf(req.namespace) orelse return null;
        return if (bound == req.ns_id) null else bound;
    }

    /// The id of the namespace `req` names, as the node's table has it.
    fn namespaceIdOf(self: *const Shard, req: proto.Request) ns_table.Id {
        return self.namespaceId(req.namespace);
    }

    /// The id of namespace `name` (empty is "default"), as the node's
    /// table or this shard has it; `.invalid` for one neither does.
    pub fn namespaceId(self: *const Shard, name: []const u8) ns_table.Id {
        const effective = if (name.len == 0) "default" else name;
        // Shard 0 knows a create it proposed before the table does.
        return self.namespace_handler.table.lookup(effective) orelse self.namespace_handler.idOf(effective) orelse .invalid;
    }

    /// The id a forward to the leader carries: only one this node's table
    /// has published. The leader holds an unknown id until its own table
    /// reaches this one's published index, so an id applied here and not
    /// yet published could be one that index doesn't cover.
    fn forwardedNamespaceId(self: *const Shard, name: []const u8) ns_table.Id {
        return self.namespace_handler.table.lookup(if (name.len == 0) "default" else name) orelse .invalid;
    }

    /// A client's request: walked across shards, sent to the shard that
    /// owns it, or run here. Walk opcodes (list/scan) aggregate across
    /// shards unless the pre-route narrows to a single partition.
    fn route(self: *Shard, conn: *Connection, req: proto.Request, auth: run_mod.Authorized) void {
        conn.recordRequest();
        self.requests_dispatched += 1;
        // Count every dispatched request for the cluster command counter (drives
        // Overview's commands_total + rps). Other server counters (connections,
        // bytes) are not yet wired — see the metrics gap log.
        if (self.metrics_registry) |m| m.server.recordCommand();
        if (self.shard_metrics) |sm| sm.recordCommand();

        const op = req.header.op_code;

        // Walk opcodes: multi-shard aggregation unless pre-route picks one target.
        if (op < proto.MAX_OPCODES and self.dispatcher.isWalkOp(op) and self.dispatcher.walk_context[op] != null) {
            const has_single_target = if (self.dispatcher.pre_route[op]) |f| f(req) != null else false;
            if (!has_single_target) {
                // This shard's part is read here, not through `dispatchLocal`;
                // the others' parts are gated where they run.
                if (self.refusedRead(conn, req)) return;
                self.executeWalk(conn, req, auth);
                return;
            }
        }

        // An internal op from a client runs where an unknown op would: here.
        if (run_mod.internalFromClient(op, auth.origin)) return self.dispatchLocal(conn, req, auth);

        // A workflow run id the client chose names no shard: ask each which
        // holds the run (`RunFind`), and for a start that chooses one,
        // whether another workflow's run has it already.
        if (self.runIdUnplaced(req)) {
            if (self.refusedRead(conn, req)) return;
            return self.findRun(conn, req, auth, req.key, null);
        }

        // A write routes by its namespace's id, so on a node of several
        // shards one into a namespace the node doesn't have yet waits for
        // shard 0 to create and publish it, then comes back here. Paid once
        // per namespace. One shard routes nothing: its write waits the same
        // way where it runs (`prepareWrite`), after a follower has
        // forwarded it to its leader.
        if (self.shardCount() > 1 and req.ns_id == .invalid and req.key.len > 0 and op < proto.MAX_OPCODES and dispatcher_mod.opCreates(@fromBackingInt(@intCast(op)))) {
            if (self.id != 0) return self.ensureThenRun(conn, req, auth.origin);
            // Shard 0 proposes the create and routes by the id it gave.
            switch (self.namespace_handler.prepareWrite(self, req.namespace)) {
                .go => {},
                .refused => |r| return self.sendRefusal(conn, req.header.request_id, r.status, proto.notRun(r.message)),
                .ensure => unreachable, // shard 0 creates
            }
            var routed = req;
            routed.ns_id = self.namespaceIdOf(req);
            return self.route(conn, routed, auth);
        }

        // A start that chooses its run id is decided on its workflow's
        // shard, found by the namespace's id: only past the wait above.
        if (self.startChoosesRunId(req)) |rid| {
            if (self.refusedRead(conn, req)) return;
            return self.findRun(conn, req, auth, rid, self.startHome(req));
        }

        // Route to the correct shard/node, or dispatch locally.
        switch (self.resolveTarget(op, req)) {
            .local => self.dispatchLocal(conn, req, auth),
            .shard => |s| self.forwardToShard(s.shard_id, conn, req, auth),
        }
        // Apply what committed during the request: on a single node, what
        // its handler proposed on its own account (a dequeue's ack, an
        // implicit namespace create) and anything past the entry `park`
        // answered at. In a cluster these wait for a peer's ack. Under sync
        // durability nothing commits unflushed, and the flush waits for the
        // tick's apply pass: every request read this tick shares it.
        self.hold_sync_flush = true;
        defer self.hold_sync_flush = false;
        _ = self.applyCommitted();
    }

    // ─── A run by an id the client chose ─────────────────────────────────

    /// Whether `req` names a workflow run by an id the client chose at its
    /// start. A generated id carries its run's partition, so its op routes
    /// straight there; a chosen one carries none, and the run is on the
    /// shard of its workflow's name, which the op doesn't name.
    fn runIdUnplaced(self: *const Shard, req: proto.Request) bool {
        const by_run_id = switch (req.header.op_code) {
            @backingInt(proto.OpCode.workflow_status),
            @backingInt(proto.OpCode.workflow_history),
            @backingInt(proto.OpCode.workflow_signal),
            @backingInt(proto.OpCode.workflow_cancel),
            => true,
            else => false,
        };
        // Only the server mints ids of the generated form (a start refuses a
        // chosen one), so this splits them exactly; a chosen id can decode as
        // a partition (`order-123`), and that partition is no run's.
        return by_run_id and req.key.len > 0 and self.shardCount() > 1 and !run_id_mod.looksGenerated(.workflow, req.key);
    }

    /// The run id a workflow start chooses, on a node of several shards.
    fn startChoosesRunId(self: *const Shard, req: proto.Request) ?[]const u8 {
        if (req.header.op_code != @backingInt(proto.OpCode.workflow_start) or self.shardCount() <= 1) return null;
        const rid = WorkflowHandler.startChosenRunId(req.value) orelse return null;
        // The start refuses an id of the server's form itself.
        return if (run_id_mod.looksGenerated(.workflow, rid)) null else rid;
    }

    /// The shard a start runs on: its workflow's.
    fn startHome(self: *Shard, req: proto.Request) u16 {
        return switch (self.resolveTarget(req.header.op_code, req)) {
            .local => self.id,
            .shard => |t| t.shard_id,
        };
    }

    /// A run-id request held while every shard says whether it holds the run;
    /// then sent, once, to the one that does. For a start that chooses an id,
    /// `start_home` is its workflow's shard: another shard holding the id
    /// refuses it, and its own shard decides as for any start there (a
    /// retried start with its idempotency key answers its run).
    const RunFind = struct {
        /// The request, serialized, and who may run it.
        bytes: []u8,
        auth: run_mod.Authorized,
        start_home: ?u16,

        const op: gather_mod.Op = .{ .merge = merge, .deinit = free };

        fn free(state: *anyopaque, allocator: std.mem.Allocator) void {
            const self: *RunFind = @ptrCast(@alignCast(state));
            allocator.free(self.bytes);
            allocator.destroy(self);
        }

        fn merge(shard: *Shard, conn: *Connection, request_id: u64, state: *anyopaque, bodies: []const []const u8) anyerror!void {
            const self: *RunFind = @ptrCast(@alignCast(state));
            const Holds = table_run.op("system.holds_run").response;
            if (self.start_home) |home| {
                for (bodies, 0..) |body, i| {
                    var diag: @import("../protocol/schema.zig").Diagnostic = .{};
                    if ((try Holds.decodeAll(body, &diag)).holds and i != home)
                        return shard.sendRefusal(conn, request_id, .conflict, proto.notRun(RUN_ID_TAKEN));
                }
                const req = try proto.Request.parse(self.bytes);
                return if (home == shard.id) shard.dispatchLocal(conn, req, self.auth) else shard.forwardToShard(home, conn, req, self.auth);
            }
            var owner: ?u16 = null;
            for (bodies, 0..) |body, i| {
                var diag: @import("../protocol/schema.zig").Diagnostic = .{};
                if (!(try Holds.decodeAll(body, &diag)).holds) continue;
                // Nothing makes a chosen id unique across workflows, so two
                // can hold it: neither is the one asked for.
                if (owner != null) return shard.sendRefusal(conn, request_id, .conflict, proto.notRun(RUN_ID_AMBIGUOUS));
                owner = @intCast(i);
            }
            const req = try proto.Request.parse(self.bytes);
            const to = owner orelse return shard.sendErrorResponse(conn, request_id, .not_found, "");
            if (to == shard.id) shard.dispatchLocal(conn, req, self.auth) else shard.forwardToShard(to, conn, req, self.auth);
        }
    };

    const RUN_ID_TAKEN = "conflict: a run of another workflow has this id in this namespace; choose another";
    const RUN_ID_AMBIGUOUS = "conflict: runs of more than one workflow hold this id in this namespace, so it names none of them; choose run ids unique in a namespace";

    fn findRun(self: *Shard, conn: *Connection, req: proto.Request, auth: run_mod.Authorized, run_id: []const u8, start_home: ?u16) void {
        const id = req.header.request_id;
        const n = self.shardCount();
        const state = self.allocator.create(RunFind) catch return self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory"));
        const bytes = serializeRequest(self.allocator, req) catch {
            self.allocator.destroy(state);
            return self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory"));
        };
        state.* = .{ .bytes = bytes, .auth = auth, .start_home = start_home };
        var gather_owns = false;
        defer if (!gather_owns) RunFind.free(state, self.allocator);
        const parts = self.allocator.alloc(gather_mod.Part, n) catch return self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory"));
        defer self.allocator.free(parts);
        const Holds = table_run.op("system.holds_run").response;
        var own_buf: [Holds.max_size]u8 = undefined;
        const own_body = Holds.encodeInto(&own_buf, .{ .holds = self.workflow_handler.holdsRun(req.ns_id, run_id) }) catch unreachable;
        const own = self.allocator.dupe(u8, own_body) catch return self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory"));
        var own_owned = false;
        defer if (!own_owned) self.allocator.free(own);
        for (parts, 0..) |*p, i| {
            const s: u16 = @intCast(i);
            p.* = if (s == self.id) .{ .owner = s, .body = own } else .{ .owner = s, .body = "", .op = @backingInt(proto.OpCode.system_holds_run), .key = run_id };
        }
        gather_owns = true;
        own_owned = true;
        self.startGather(conn, req, parts, &RunFind.op, state) catch |err| return switch (err) {
            error.GatherBusy => self.sendRefusal(conn, id, .overloaded, .{ .reason = .shard_busy, .ran = .no, .message = "overloaded: too many requests across shards are under way; this request was not run — retry" }),
            error.OutOfMemory => self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory")),
        };
        conn.response_deferred = true;
    }

    /// `system.holds_run`, on the shard asked: whether it holds the run.
    fn handleHoldsRun(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const shard: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        table_run.answer(table_run.op("system.holds_run").response, shard, conn, req.header.request_id, .{ .holds = shard.workflow_handler.holdsRun(req.ns_id, req.key) });
    }

    /// Where a request goes when it goes to another shard, and whether it
    /// is a read that may wait there on purpose.
    const ForwardTo = struct { target: u16, blocking: bool };

    /// The shard `req` would be sent to, if not this one: `route`'s
    /// routing, decided before anything runs.
    fn forwardTarget(self: *Shard, req: proto.Request) ?ForwardTo {
        const op = req.header.op_code;
        if (op >= proto.MAX_OPCODES or table.isInternal(op)) return null;
        if (self.dispatcher.isWalkOp(op) and self.dispatcher.walk_context[op] != null) {
            const single = if (self.dispatcher.pre_route[op]) |f| f(req) != null else false;
            if (!single) return null;
        }
        return switch (self.resolveTarget(op, req)) {
            .local => null,
            .shard => |s| blk: {
                const mailboxes = self.peer_mailboxes orelse break :blk null;
                if (self.peer_shards == null or s.shard_id == self.id or s.shard_id >= mailboxes.len) break :blk null;
                break :blk .{ .target = s.shard_id, .blocking = blockingWait(req) != null };
            },
        };
    }

    /// Requests whose answer carries what they took: a dequeued message, a
    /// group read's records, a claimed or awaited task.
    fn takesItems(op: u16) bool {
        return switch (op) {
            @backingInt(proto.OpCode.queue_dequeue),
            @backingInt(proto.OpCode.stream_group_read),
            @backingInt(proto.OpCode.action_await),
            => true,
            else => false,
        };
    }

    /// Whether `req` goes to the leader: a write, or a read only the leader
    /// can answer.
    fn requestToLeader(req: proto.Request) bool {
        return requestWrites(req) or requestAtLeader(req);
    }

    /// A read whose state lives only in the leader's memory. On a halted
    /// leader it is answered, marked stale, as other reads are: a halt
    /// stops applying, and clears none of that memory.
    fn requestAtLeader(req: proto.Request) bool {
        if (table.isOp(req.header.op_code)) return table_run.atLeader(req);
        return req.header.op_code < proto.MAX_OPCODES and dispatcher_mod.opReadsAtLeader(@fromBackingInt(@intCast(req.header.op_code)));
    }

    /// Whether `req` is a write: a write, or a table op inside a
    /// transaction.
    fn requestWrites(req: proto.Request) bool {
        if (table.isOp(req.header.op_code)) return table_run.writes(req);
        return req.header.op_code < proto.MAX_OPCODES and dispatcher_mod.opWrites(@fromBackingInt(@intCast(req.header.op_code)));
    }

    /// Whether a request can't run without its namespace's id, so one in
    /// a namespace never created is refused: a wait names what it waits for
    /// by the id, and nothing could wake it without one; a group read makes
    /// its group under the id, waiting or not, and creates no namespace.
    fn needsNamespaceId(req: proto.Request) bool {
        return blockingWait(req) != null or req.header.op_code == @backingInt(proto.OpCode.stream_group_read);
    }

    /// How long a read may wait on purpose for its data, or null for any
    /// other request. Such a read holds a slot of its own class, and is not
    /// a slow answer while it waits.
    fn blockingWait(req: proto.Request) ?u64 {
        if (table.isOp(req.header.op_code)) return table_run.waitMs(req);
        if (req.getBlockMs()) |ms| return ms;
        return null;
    }

    /// Why `conn`'s request cannot go to `to.target` now, or null when it
    /// can.
    fn forwardWait(self: *Shard, conn: *Connection, to: ForwardTo) ?Connection.WaitReason {
        if (to.target == self.id) return if (self.blockingOut(conn) >= Connection.MAX_BLOCKING_IN_FLIGHT) .blocking_reads else null;
        if (conn.forwards_in_flight >= Connection.MAX_FORWARDS_IN_FLIGHT) return .in_flight;
        if (to.blocking and self.blockingOut(conn) >= Connection.MAX_BLOCKING_IN_FLIGHT) return .blocking_reads;
        if (!self.reply_pool.canTake(if (to.blocking) .blocking else .ordinary, to.target)) return .slots;
        if (!self.peer_mailboxes.?[to.target].hasShare(@intCast(self.id))) return .inbox;
        return null;
    }

    /// `conn`'s blocking reads held for the leader: parked there, not here,
    /// but still `conn`'s.
    fn blockingForwardsFor(self: *Shard, conn: *Connection) u16 {
        if (self.blocking_forwards == 0) return 0;
        var n: u16 = 0;
        for (self.forwards) |*f| {
            if (f.active and f.wait_ms > 0 and f.reply_to.isSocket(@intCast(self.id), conn.fd, conn.id)) n += 1;
        }
        return n;
    }

    /// The blocking reads `conn` has out: on other shards, parked here, and
    /// held for the leader.
    /// `local_reads` only ever overcounts — raised as each parks, not
    /// lowered as each returns — so the waiters are counted only when it
    /// says the cap may be reached.
    fn blockingOut(self: *Shard, conn: *Connection) u16 {
        if (conn.blocking_in_flight + conn.local_reads >= Connection.MAX_BLOCKING_IN_FLIGHT) {
            conn.local_reads = self.waiter_pool.countFor(@intCast(self.id), conn.fd, conn.id) + self.blockingForwardsFor(conn);
        }
        return conn.blocking_in_flight + conn.local_reads;
    }

    /// What a client's request must wait for before it can go — to another
    /// shard, or, for a blocking read here, past this connection's cap — or
    /// null when it can go now, or is refused by `runRequest`. A
    /// waiting request is left unread: nothing about it has run or been
    /// counted.
    fn holdForward(self: *Shard, conn: *Connection, req_in: proto.Request) ?Connection.Waiting {
        // Read straight off the socket: its route needs the id `runRequest`
        // would give it.
        var req = req_in;
        req.ns_id = self.namespaceIdOf(req);
        // A body that doesn't decode is refused when it runs; it waits for
        // nothing first.
        if (table.isOp(req.header.op_code) and !table_run.decodes(req)) return null;
        if ((req.getBlockMs() orelse 0) > waiter_pool_mod.MAX_BLOCK_MS) return null;
        const to: ForwardTo = self.forwardTarget(req) orelse if (blockingWait(req) != null) .{ .target = @intCast(self.id), .blocking = true } else return null;
        var why = self.stillWaits(conn, to, null);
        // Behind connections already waiting for this target, unless this
        // is the one request `resumeWaiting` let this connection send: room
        // goes round, a request at a time.
        if (why == null and !conn.has_turn and self.queued[@intFromBool(to.blocking)][to.target] > 0) why = .slots;
        return .{ .target = to.target, .blocking = to.blocking, .reason = why orelse return null };
    }

    /// `forwardWait`; but when the answer is, or last was (`was`), the inbox
    /// share, ask to be told of a drain before looking, so a drain in
    /// between is not missed (`Mailbox.wantShare`).
    fn stillWaits(self: *Shard, conn: *Connection, to: ForwardTo, was: ?Connection.WaitReason) ?Connection.WaitReason {
        if (to.target == self.id) return self.forwardWait(conn, to);
        const mailbox = self.peer_mailboxes.?[to.target];
        if (was == .inbox) mailbox.wantShare(@intCast(self.id));
        const why = self.forwardWait(conn, to);
        if (why != .inbox or was == .inbox) return why;
        mailbox.wantShare(@intCast(self.id));
        return self.forwardWait(conn, to);
    }

    pub const Dispatching = struct { reply_to: ReplyTo, request_id: u64, answered_deferred: bool = false };

    /// Run `req` on `conn`, noting it as the request being dispatched while
    /// it runs. Returns whether it was answered through `deliverDeferred`
    /// meanwhile; see `answeredAsDeferred`.
    fn dispatchNoted(self: *Shard, conn: *Connection, req: proto.Request, origin: run_mod.Origin) bool {
        const prev = self.dispatching;
        self.dispatching = .{ .reply_to = conn.replyTo(), .request_id = req.header.request_id };
        defer self.dispatching = prev;
        self.runRequest(conn, req, origin);
        return self.dispatching.?.answered_deferred;
    }

    /// A request that left nothing on its connection and wasn't parked, yet
    /// was answered through `deliverDeferred` while it ran: its handler
    /// answered it as deferred without saying so. It has its answer, so the
    /// no-answer fallback is skipped rather than sending a second under the
    /// same id, which would put the client's reads a frame behind.
    fn answeredAsDeferred(self: *Shard, request_id: u64, op_code: u16) void {
        self.answered_as_deferred += 1;
        log.err("shard {d}: request {d} (op 0x{x}) was answered as deferred without being parked. This is a bug", .{ self.id, request_id, op_code });
        if (builtin.mode == .debug and !builtin.is_test) @panic("a request was answered as deferred without being parked");
    }

    /// Run a request on this shard — unless it writes and this shard's
    /// group is led elsewhere, when it goes to the leader over the peer
    /// link and the answer comes back the same way.
    fn dispatchLocal(self: *Shard, conn: *Connection, req_in: proto.Request, auth: run_mod.Authorized) void {
        var req = req_in;
        if (req.ns_id == .invalid) req.ns_id = self.namespaceIdOf(req);
        if (self.boundElsewhere(req)) |bound| {
            var msg: [256]u8 = undefined;
            const name = if (req.namespace.len == 0) "default" else req.namespace;
            const text = std.fmt.bufPrint(&msg, "internal error: namespace '{s}' is bound on this shard as id {d}, but the node's namespace table has it as {d}: shard 0 lost the create this shard bound (its log was damaged or salvaged). This shard refuses the namespace; wipe the node and rebuild it", .{ name, bound.int(), req.ns_id.int() }) catch "internal error: this shard binds the namespace under another id than the node's table";
            return self.sendRefusal(conn, req.header.request_id, .internal_error, proto.notRun(text));
        }
        // Taken through every check below as an unknown op is, then answered
        // as one, so nothing tells the two apart.
        const internal_from_client = run_mod.internalFromClient(req.header.op_code, auth.origin);
        const writes = !internal_from_client and requestWrites(req);
        const at_leader = !internal_from_client and !writes and requestAtLeader(req);
        const status_op = req.header.op_code == @backingInt(proto.OpCode.cluster_status) or req.header.op_code == @backingInt(proto.OpCode.cluster_members);
        if (self.removed_at_ms != null and !status_op) {
            self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(self.removed_message));
            return;
        }
        if (self.offline != null and !status_op) {
            var buf: [320]u8 = undefined;
            self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(self.offlineMessage(&buf)));
            return;
        }
        // Halted: writes, a client's or another shard's ask, are refused;
        // reads are served from the state just before the halt, marked
        // stale.
        // Membership changes are exempt: a halted group must still be able
        // to replace a dead node.
        const membership_op = req.header.op_code == @backingInt(proto.OpCode.cluster_promote) or req.header.op_code == @backingInt(proto.OpCode.cluster_remove);
        // And so is the repair that ends the halt.
        const repair_op = req.header.op_code == @backingInt(proto.OpCode.cluster_repair_skip);
        if (self.halted != null and !status_op and !membership_op and !repair_op and writes) {
            var buf: [400]u8 = undefined;
            self.sendRefusal(conn, req.header.request_id, .unavailable, .{ .reason = .shard_halted, .ran = .no, .message = self.haltedMessage(&buf) });
            return;
        }
        // A read runs here, on the shard whose group holds its state, from
        // whichever shard or node it came. Status and membership read Raft
        // and config, not projections.
        const exempt = status_op or req.header.op_code == @backingInt(proto.OpCode.ping);
        if (!writes and !at_leader and !exempt and !internal_from_client and auth.origin != .peer and self.refusedRead(conn, req)) return;
        const was_stale = proto.answering_stale;
        // A read is stale when this node can't apply what the group committed:
        // halted, diverged, or blocked reading a committed entry — the
        // projections sit behind the commit either way.
        proto.answering_stale = was_stale or ((self.halted != null or self.replica.diverged or self.read_blocked) and !writes);
        defer proto.answering_stale = was_stale;
        if (self.raft_network != null and (writes or at_leader) and (self.replica.diverged or self.raft_node.role != .leader)) {
            if (self.replica.diverged) {
                const oom = if (self.diverged_damage) |d| d.out_of_memory else false;
                self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(if (oom) OUT_OF_MEMORY_MESSAGE else DIVERGED_MESSAGE));
                return;
            }
            // A replica serves reads and sends writers to the leader
            // rather than carrying their writes. A repair or a membership
            // change came over the admin socket, which the leader's client
            // port would refuse, so it is carried like a voter's.
            if (!self.raft_node.timer_enabled and self.raft_node.self_named and !repair_op and !membership_op) return self.redirectToLeader(conn, req);
            if (conn.replyTo() == .remote) {
                // Already forwarded once; a second hop during an election
                // could bounce between nodes. The client retries instead.
                self.sendRefusal(conn, req.header.request_id, .unavailable, .{ .reason = .leader_unknown, .ran = .no, .message = "unavailable: electing a leader — retry" });
                return;
            }
            self.forwardToLeader(conn, req);
            return;
        }
        // A read the leader answers from its memory, or one inside a
        // transaction, which falls through to the leader's state: a leader
        // still applying what earlier terms committed would answer from part
        // of it. A halted one answers the former, marked stale, as other reads
        // are. So too a write whose handler reads state to decide what to
        // propose: it could finish a run again, or drop a stream that isn't
        // empty. Rather than judge each, all are refused but those that read
        // nothing the backlog could change. A membership change answers for
        // itself: it waits for the leader's first commit, and past that,
        // needn't wait for the apply. A repair reads only the log. A worker's
        // registration lives in the leader's memory alone.
        const in_txn_read = table_run.readsInTxn(req);
        const worker_op = req.header.op_code == @backingInt(proto.OpCode.worker_register) or req.header.op_code == @backingInt(proto.OpCode.worker_heartbeat) or
            req.header.op_code == @backingInt(proto.OpCode.worker_deregister) or req.header.op_code == @backingInt(proto.OpCode.worker_drain);
        const refuses_write = writes and !in_txn_read and !membership_op and !repair_op and !worker_op and !table_run.runsOnApplyingLeader(req);
        if ((at_leader or in_txn_read or refuses_write) and self.leaderApplying()) {
            self.sendRefusal(conn, req.header.request_id, .unavailable, .{ .reason = .leader_unknown, .ran = .no, .message = LEADER_NOT_READY_REFUSAL });
            return;
        }
        // A write that brings data into a namespace this shard has not seen
        // creates it. Checked after forwarding because only the leader knows
        // the creates in flight; the create is proposed here, ahead of the
        // write, so it holds the room before the next request is admitted.
        // Other writes (a delete, an ack, a wait for what is not there yet)
        // create nothing, wherever they are sent, and nor does a request
        // that names nothing to write to. A job submit names its targets in
        // its definition: its handler reserves once the definition passes.
        if (req.key.len > 0 and req.header.op_code < proto.MAX_OPCODES and dispatcher_mod.opCreates(@fromBackingInt(@intCast(req.header.op_code)))) {
            switch (self.namespace_handler.prepareWrite(self, req.namespace)) {
                .go => {},
                // Refused before anything was proposed, so a retry is safe.
                .refused => |r| return self.sendRefusal(conn, req.header.request_id, r.status, proto.notRun(r.message)),
                .ensure => return self.ensureThenRun(conn, req, auth.origin),
            }
            if (req.ns_id == .invalid) req.ns_id = self.namespaceIdOf(req);
        }
        if (req.ns_id == .invalid and namespaced(req.header.op_code) and needsNamespaceId(req))
            return self.sendRefusal(conn, req.header.request_id, .no_namespace, NO_NAMESPACE);
        if (internal_from_client) return answerUnknownOp(@ptrCast(self), @ptrCast(conn), req.header.request_id, req.header.op_code);
        self.dispatcher.dispatch(auth, @ptrCast(self), @ptrCast(conn), req);
    }

    /// A write whose namespace this node doesn't know: shard 0 creates it,
    /// or finds it, and publishes it (`namespace.ensure`, a gather of one
    /// part). Then a client's write is routed again, now by the id; one
    /// already routed here binds the name and runs as held, already
    /// authorized. The write is copied first and has not run.
    fn ensureThenRun(self: *Shard, conn: *Connection, req: proto.Request, origin: run_mod.Origin) void {
        const bytes = serializeRequest(self.allocator, req) catch
            return self.sendRefusal(conn, req.header.request_id, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: out of memory" });
        const st = self.allocator.create(EnsureThenRun) catch {
            self.allocator.free(bytes);
            return self.sendRefusal(conn, req.header.request_id, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: out of memory" });
        };
        st.* = .{ .bytes = bytes, .origin = origin };
        const name = if (req.namespace.len == 0) "default" else req.namespace;
        const parts = [_]gather_mod.Part{.{ .owner = 0, .body = "", .op = @backingInt(proto.OpCode.namespace_ensure), .key = name }};
        self.startGather(conn, req, &parts, &EnsureThenRun.gather_op, st) catch |err| return switch (err) {
            error.GatherBusy => self.sendRefusal(conn, req.header.request_id, .overloaded, .{ .reason = .shard_busy, .ran = .no, .message = "overloaded: too many requests across shards are under way; this request was not run — retry" }),
            error.OutOfMemory => self.sendRefusal(conn, req.header.request_id, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: out of memory" }),
        };
        conn.response_deferred = true;
    }

    const EnsureThenRun = struct {
        /// The write, as its client sent it; owned.
        bytes: []u8,
        origin: run_mod.Origin,

        const gather_op: gather_mod.Op = .{ .merge = bindAndRun, .deinit = free };

        /// Shard 0 published the namespace before it answered, so the
        /// node's table has it: bind it and run the write. If the table
        /// still lacks it, the write is refused, never sent to shard 0 again.
        fn bindAndRun(shard: *Shard, conn: *Connection, request_id: u64, state: *anyopaque, bodies: []const []const u8) anyerror!void {
            const self: *EnsureThenRun = @ptrCast(@alignCast(state));
            const req = proto.Request.parse(self.bytes) catch return error.HeldRequestUnreadable;
            const name = if (req.namespace.len == 0) "default" else req.namespace;
            var diag: schema.Diagnostic = .{};
            const ensured = table_run.op("namespace.ensure").response.decodeAll(bodies[0], &diag) catch return error.MalformedPart;
            const nh = shard.namespace_handler;
            const known = nh.table.lookup(name) orelse .invalid;
            if (known == .invalid or known.int() != ensured.id) {
                return shard.sendRefusal(conn, request_id, .unavailable, proto.notRun("unavailable: the namespace was created but this node doesn't show it yet; the write was not run — retry"));
            }
            if (self.origin == .client or self.origin == .admin) return shard.runRequest(conn, req, self.origin);
            switch (nh.prepareWrite(shard, name)) {
                .go => {},
                .refused => |r| return shard.sendRefusal(conn, request_id, r.status, proto.notRun(r.message)),
                .ensure => unreachable, // the table has it
            }
            shard.runRequest(conn, req, .held);
        }

        fn free(state: *anyopaque, allocator: std.mem.Allocator) void {
            const self: *EnsureThenRun = @ptrCast(@alignCast(state));
            allocator.free(self.bytes);
            allocator.destroy(self);
        }
    };

    /// Pure routing decision: pre-route → the shard that owns the key. No
    /// side effects.
    fn resolveTarget(self: *Shard, op: u16, req: proto.Request) node_router.RouteTarget {
        if (op >= proto.MAX_OPCODES) return .{ .local = .{ .partition_id = 0 } };
        if (self.dispatcher.shard_route[op]) |f| if (f(req)) |shard_id| {
            // A shard that doesn't exist holds no transaction: the request
            // runs here and is refused as one.
            const shards = if (self.peer_shards) |p| p.len else 1;
            if (shard_id == self.id or shard_id >= shards) return .{ .local = .{ .partition_id = 0 } };
            return .{ .shard = .{ .partition_id = 0, .shard_id = shard_id } };
        };
        const hash = if (self.dispatcher.pre_route[op]) |f| f(req) orelse return .{ .local = .{ .partition_id = 0 } } else return .{ .local = .{ .partition_id = 0 } };
        return self.router.route(hash);
    }

    /// The request as wire bytes on the heap, for a copy that outlives the
    /// connection's buffer: a forward to another shard or to the leader, or a
    /// write held until commit. Length and CRC are recomputed.
    pub fn serializeRequest(allocator: std.mem.Allocator, req: proto.Request) ![]u8 {
        // Sized from the parts, not header.payload_length: a client may omit
        // the options trailer, which serialize always writes.
        const size = req.wireSize();
        const buf = try allocator.alloc(u8, size);
        errdefer allocator.free(buf);
        _ = try req.serialize(buf);
        return buf;
    }

    /// Forward a request to a different shard in single-node mode.
    ///
    /// Marshals the request to the target shard's inbox as a `forward_request`.
    /// The target shard re-parses and dispatches the request on its own
    /// reactor thread (its handlers' state is therefore only ever touched by
    /// one thread). The response — direct bytes or a deferred blocking-read
    /// completion — comes back on this shard's reply ring naming the reply
    /// slot taken here first, and is written to the client. See
    /// `runForwardedRequest` and `deliverReply`.
    ///
    /// A client's request has already waited for room (`holdForward`); if
    /// there is none even so, it is answered `overloaded` — it did not run —
    /// and the client retries instead of hanging.
    fn forwardToShard(self: *Shard, target_shard_id: u16, conn: *Connection, req: proto.Request, auth: run_mod.Authorized) void {
        const peers = self.peer_shards orelse {
            // No peer shards wired — fall back to local dispatch
            self.dispatchLocal(conn, req, auth);
            return;
        };
        if (target_shard_id >= peers.len) {
            self.dispatchLocal(conn, req, auth);
            return;
        }
        if (target_shard_id == @as(u16, @intCast(self.id))) {
            // Already on the right shard — dispatch locally.
            self.dispatchLocal(conn, req, auth);
            return;
        }
        const target = (self.peer_mailboxes orelse return self.dispatchLocal(conn, req, auth))[target_shard_id];
        // A cluster member runs one shard (`Runtime` refuses more), so what
        // goes to another shard never waits there for a leader first; the
        // deadlines below count on it.
        std.debug.assert(self.raft_network == null);

        // Room for the answer first: nothing is copied for a request that
        // cannot be sent.
        const block = blockingWait(req);
        const blocking = block != null;
        const op = req.header.op_code;
        const claims = takesItems(op);
        const writes = claims or requestWrites(req);
        // An answer carrying what its request took is not dropped for a
        // deadline: it would reach no one until its lease ran out. Such a
        // request waits for it as long as the slot is held.
        const class: reply_pool_mod.Class = if (blocking) .blocking else .ordinary;
        const now = nowMs();
        const since = if (claims) now else conn.head_since_ms orelse now;
        const allowance = if (claims) reply_pool_mod.SLOT_DEADLINE_MS else reply_pool_mod.DEADLINE_MS;
        const ticket = self.reply_pool.take(class, target_shard_id, conn.fd, conn.id, req.header.request_id, writes, since, now, allowance, if (claims) 0 else block orelse 0) catch
            return self.refuseForward(conn, req, target_shard_id, .target_busy);
        self.reply_pool.tagOp(ticket, req.header.op_code);

        // Serialize request (header + recomposed payload) onto the heap so the
        // target shard can re-parse it after the source buffer is gone.
        const buf = serializeRequest(self.allocator, req) catch {
            _ = self.reply_pool.release(ticket, target_shard_id);
            self.sendErrorResponse(conn, req.header.request_id, .internal_error, "internal error: out of memory forwarding the request — retry");
            return;
        };

        // Pack (conn_id << 32) | fd into sequence: the target shard runs the
        // request on a proxy with this identity (`loadProxy`).
        const fd_bits: u64 = @as(u32, @bitCast(conn.fd));
        const seq: u64 = (@as(u64, conn.id) << 32) | fd_bits;
        var msg: InboxMessage = .{
            .tag = .forward_request,
            .src_shard = @intCast(self.id),
            .payload_len = @intCast(buf.len),
            .sequence = seq,
            .payload_ptr = buf.ptr,
        };
        msg.setReplySlot(ticket.slot, ticket.gen);
        if (!target.sendOnShare(msg)) {
            self.allocator.free(buf);
            _ = self.reply_pool.release(ticket, target_shard_id);
            return self.refuseForward(conn, req, target_shard_id, .inbox_full);
        }
        conn.forwards_in_flight += 1;
        if (blocking) {
            // `holdForward` kept it under the cap, or it would have waited.
            std.debug.assert(conn.blocking_in_flight < Connection.MAX_BLOCKING_IN_FLIGHT);
            conn.blocking_slots[conn.blocking_in_flight] = ticket;
            conn.blocking_in_flight += 1;
        }
        if (self.shard_metrics) |sm| sm.setCrossShardInFlight(self.reply_pool.taken());

        // The answer arrives on this shard's reply ring; marked deferred so
        // the no-answer fallback leaves the connection waiting for it.
        conn.recordForward();
        conn.response_deferred = true;
    }

    const ForwardRefusal = enum { target_busy, inbox_full };

    const NOT_KEEPING_UP = "overloaded: shard {d} is not keeping up; this request was not run — back off and retry";

    /// A client's request refused before it was sent to `target`: answered
    /// `overloaded` (it did not run, so resending is safe), counted, and
    /// said once per interval.
    fn refuseForward(self: *Shard, conn: *Connection, req: proto.Request, target: u16, why: ForwardRefusal) void {
        if (self.shard_metrics) |sm| sm.recordCrossShardOverloaded(.client_forward);
        var msg_buf: [128]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, NOT_KEEPING_UP, .{target}) catch "overloaded: this request was not run — back off and retry";
        self.sendErrorResponse(conn, req.header.request_id, .overloaded, message);
        self.forwards_refused += 1;
        const now = nowMs();
        if (now -| self.refuse_warn_ms < WARN_INTERVAL_MS) return;
        self.refuse_warn_ms = now;
        const reason = switch (why) {
            .target_busy => "it holds its full share of this shard's requests",
            .inbox_full => "its inbox is full of messages sent on no share",
        };
        log.warn("shard {d}: refusing client requests for shard {d}: {s} ({d} refused so far; {d} in flight to other shards, {d} ordinary and {d} blocking to shard {d})", .{ self.id, target, reason, self.forwards_refused, self.reply_pool.taken(), self.reply_pool.heldBy(.ordinary, target), self.reply_pool.heldBy(.blocking, target), target });
    }

    // ─── Gathers: one read, answered in parts by other shards ─────────────

    pub const Gathers = gather_mod.GatherTable(gather_mod.OpContext);

    pub fn shardCount(self: *const Shard) usize {
        return if (self.peer_shards) |p| p.len else 1;
    }

    /// Send each part another shard owns to it, as the client's op with
    /// the part's body, and answer the client once every part has answered:
    /// `op.merge` with their bodies, in part order. This shard's parts carry
    /// their answers already, owned from here on, as `state` is (freed by
    /// `op.deinit` exactly once). The client's request counts once against
    /// its in-flight limit, however many parts it has; each part another
    /// shard answers holds a reply slot from that shard's share.
    ///
    /// `GatherBusy` when there is no room for every part, before anything
    /// is sent: the request did not run. Past here the client is answered
    /// exactly once: merged, a part's refusal, or `unavailable` at the
    /// first part's deadline.
    pub fn startGather(self: *Shard, conn: *Connection, req: proto.Request, parts: []const gather_mod.Part, op: *const gather_mod.Op, state: *anyopaque) error{ GatherBusy, OutOfMemory }!void {
        var owned_state: ?*anyopaque = state;
        var owned_locals = true;
        defer {
            if (owned_state) |st| op.deinit(st, self.allocator);
            if (owned_locals) for (parts) |p| if (p.owner == self.id) self.allocator.free(@constCast(p.body));
        }
        std.debug.assert(parts.len > 0 and parts.len <= gather_mod.MAX_PARTS);
        for (parts, 0..) |p, i| for (parts[0..i]) |q| std.debug.assert(p.owner != q.owner);
        // Room for every part before any is sent: a slot each (they share
        // one pool), each owner's share of slots, and this shard's share of
        // each owner's inbox. Only this shard raises its share's count, so
        // room seen here is still there at the send.
        var remote: usize = 0;
        for (parts) |p| remote += @intFromBool(p.owner != self.id);
        // Only parts for other shards need them; every part this shard's
        // gathers on a node of one.
        const mailboxes: []const *Mailbox = if (remote == 0) &.{} else self.peer_mailboxes orelse return error.GatherBusy;
        if (remote > 0) std.debug.assert(self.raft_network == null); // a cluster member runs one shard
        const busy = !self.gathers.hasRoom() or conn.forwards_in_flight >= Connection.MAX_FORWARDS_IN_FLIGHT or
            self.reply_pool.freeCount(.ordinary) < remote or for (parts) |p|
        {
            if (p.owner == self.id) continue;
            if (!self.reply_pool.canTake(.ordinary, p.owner) or !mailboxes[p.owner].hasShare(@intCast(self.id))) break true;
        } else false;
        if (busy) {
            if (self.shard_metrics) |sm| sm.recordCrossShardOverloaded(.gather);
            return error.GatherBusy;
        }

        owned_state = null; // the entry has it now, also when start fails
        const ticket = self.gathers.start(self.allocator, conn.fd, conn.id, req.header.request_id, @intCast(parts.len), .{ .op = op, .state = state }) catch |err| switch (err) {
            error.Full => unreachable, // room checked above
            error.OutOfMemory => return error.OutOfMemory,
        };
        owned_locals = false;
        // A forwarded request is answered where it came from, and counts
        // against that shard's client, not the proxy running it.
        self.gathers.get(ticket).?.reply_to = conn.proxy_for;
        self.gathers.get(ticket).?.op_code = req.header.op_code;
        if (conn.proxy_for == null) conn.forwards_in_flight += 1;
        // This shard's own part was read while it is halted.
        if (self.halted != null) for (parts) |p| {
            if (p.owner == self.id) self.gathers.get(ticket).?.stale = true;
        };
        var done: ?*Gathers.Entry = null;
        for (parts, 0..) |p, i| {
            if (p.owner != self.id) continue;
            done = self.gathers.arrive(self.allocator, .{ .index = ticket.index, .gen = ticket.gen, .part = @intCast(i) }, @constCast(p.body));
        }
        if (done) |e| return self.completeGather(e); // every part was this shard's

        const now = nowMs();
        const since = conn.head_since_ms orelse now;
        const seq: u64 = (@as(u64, conn.id) << 32) | @as(u32, @bitCast(conn.fd));
        for (parts, 0..) |p, i| {
            if (p.owner == self.id) continue;
            var piece = req;
            piece.value = p.body;
            if (p.op) |o| piece.header.op_code = o;
            if (p.key) |k| piece.key = k;
            const sent = self.sendGatherPart(mailboxes[p.owner], p.owner, conn, piece, seq, since, now, .{ .index = ticket.index, .gen = ticket.gen, .part = @intCast(i) });
            if (!sent) {
                // Only a full inbox ring, or no memory for the request, gets
                // here past the checks above. The parts already sent answer
                // into an ended gather and are dropped there; their slots
                // come back as they do.
                if (conn.proxy_for == null) conn.forwards_in_flight -|= 1;
                self.gathers.finish(self.allocator, self.gathers.get(ticket).?);
                if (self.shard_metrics) |sm| sm.recordCrossShardOverloaded(.gather);
                return error.GatherBusy;
            }
        }
        conn.recordForward();
        if (self.shard_metrics) |sm| sm.setCrossShardInFlight(self.reply_pool.taken());
    }

    fn sendGatherPart(self: *Shard, target: *Mailbox, owner: u16, conn: *Connection, piece: proto.Request, seq: u64, since: u64, now: u64, part: ReplyPool.GatherPart) bool {
        const ticket = self.reply_pool.take(.ordinary, owner, conn.fd, conn.id, piece.header.request_id, false, since, now, reply_pool_mod.DEADLINE_MS, 0) catch return false;
        self.reply_pool.tagGather(ticket, part);
        self.reply_pool.tagOp(ticket, piece.header.op_code);
        const buf = serializeRequest(self.allocator, piece) catch {
            _ = self.reply_pool.release(ticket, owner);
            return false;
        };
        var msg: InboxMessage = .{ .tag = .forward_request, .src_shard = @intCast(self.id), .payload_len = @intCast(buf.len), .sequence = seq, .payload_ptr = buf.ptr };
        msg.setReplySlot(ticket.slot, ticket.gen);
        if (!target.sendOnShare(msg)) {
            self.allocator.free(buf);
            _ = self.reply_pool.release(ticket, owner);
            return false;
        }
        return true;
    }

    /// A gather's part answered, its slot already freed. A refusal ends the
    /// gather and goes to the client as it came; the last answer merges.
    fn gatherPartAnswered(self: *Shard, slot: ReplyPool.Slot, part: ReplyPool.GatherPart, bytes: []const u8) void {
        // Ended: an answer that took something is handed back.
        const e = self.gathers.get(.{ .index = part.index, .gen = part.gen }) orelse return ActionsHandler.orphanedAnswer(self, slot.op, bytes);
        if (bytes.len == 0) {
            var buf: [128]u8 = undefined;
            const message = std.fmt.bufPrint(&buf, "internal error: shard {d} lost its answer — retry", .{slot.target}) catch "internal error: an answer was lost — retry";
            return self.failGather(e, .internal_error, .{ .reason = .answer_lost, .ran = .no, .message = message });
        }
        const resp = proto.Response.parse(bytes) catch
            return self.failGather(e, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: another shard's answer did not read — retry" });
        if (resp.header.status != @backingInt(proto.StatusCode.ok)) {
            if (e.reply_to) |rt| {
                self.deliverDeferred(rt, bytes);
            } else if (self.gatherClient(e)) |conn| {
                _ = conn.queueWrite(bytes);
                self.flushToClient(conn.fd);
            }
            return self.endGather(e);
        }
        // One part read a halted shard: the whole answer is stale.
        if (resp.header.flags & proto.RESPONSE_STALE != 0) e.stale = true;
        const body = self.allocator.dupe(u8, resp.data) catch
            return self.failGather(e, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: out of memory for an answer — retry" });
        const done = self.gathers.arrive(self.allocator, part, body) orelse return;
        self.completeGather(done);
    }

    /// Every part answered ok: the op writes the client's answer.
    fn completeGather(self: *Shard, e: *Gathers.Entry) void {
        if (e.reply_to) |rt| return self.completeForwardedGather(e, rt);
        var bodies: [gather_mod.MAX_PARTS][]const u8 = undefined;
        for (e.answers, 0..) |a, i| bodies[i] = a.?;
        const conn = self.gatherClient(e) orelse {
            if (e.context.op.orphaned) |o| o(self, e.context.state, bodies[0..e.answers.len]);
            return self.endGather(e);
        };
        const was_stale = proto.answering_stale;
        proto.answering_stale = was_stale or e.stale;
        defer proto.answering_stale = was_stale;
        e.context.op.merge(self, conn, e.request_id, e.context.state, bodies[0..e.answers.len]) catch
            return self.failGather(e, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: the parts' answers did not merge — retry" });
        self.flushToClient(conn.fd);
        self.endGather(e);
    }

    /// A forwarded request's gather: the op answers on a proxy, as the
    /// request first ran, and the answer goes back where it came from.
    fn completeForwardedGather(self: *Shard, e: *Gathers.Entry, reply_to: ReplyTo) void {
        var bodies: [gather_mod.MAX_PARTS][]const u8 = undefined;
        for (e.answers, 0..) |a, i| bodies[i] = a.?;
        const was_stale = proto.answering_stale;
        proto.answering_stale = was_stale or e.stale;
        defer proto.answering_stale = was_stale;
        const proxy = self.forward_proxy;
        loadProxy(proxy, reply_to);
        proxy.protocol = .binary;
        // Noted as a dispatch is, so a handler that answers as deferred
        // without parking is caught here too.
        const prev = self.dispatching;
        self.dispatching = .{ .reply_to = reply_to, .request_id = e.request_id };
        const merged = e.context.op.merge(self, proxy, e.request_id, e.context.state, bodies[0..e.answers.len]);
        const answered_deferred = self.dispatching.?.answered_deferred;
        self.dispatching = prev;
        merged catch
            return self.failGather(e, .internal_error, .{ .reason = .internal, .ran = .no, .message = "internal error: the parts' answers did not merge — retry" });
        var err_buf: [256]u8 = undefined;
        if (self.takeProxyAnswer(proxy, e.request_id, &err_buf)) |answer| {
            defer answer.free(self.allocator);
            self.deliverDeferred(reply_to, answer.bytes());
        } else if (!proxy.response_deferred and answered_deferred) {
            self.answeredAsDeferred(e.request_id, e.op_code);
        } else if (!proxy.response_deferred) {
            self.deliverDeferredRefusal(reply_to, e.request_id, .internal_error, persistence_mod.ANSWER_LOST_REFUSAL);
        }
        self.endGather(e);
    }

    /// A gather's part not answered by its deadline: the gather ends, and
    /// its client is told once. A part of a gather already ended is let go.
    fn gatherPartLate(self: *Shard, slot: ReplyPool.Slot, part: ReplyPool.GatherPart) void {
        const e = self.gathers.get(.{ .index = part.index, .gen = part.gen }) orelse return;
        if (self.shard_metrics) |sm| sm.recordGatherTimeout();
        var buf: [128]u8 = undefined;
        const message = std.fmt.bufPrint(&buf, "unavailable: shard {d} did not answer in {d} s — retry", .{ slot.target, slot.answer_after_ms / 1000 }) catch "unavailable: no answer — retry";
        self.failGather(e, .unavailable, .{ .reason = .unclassified, .ran = .no, .message = message });
    }

    fn failGather(self: *Shard, e: *Gathers.Entry, status: proto.StatusCode, r: proto.Refusal) void {
        if (e.reply_to) |rt| {
            self.deliverDeferredRefusal(rt, e.request_id, status, r);
        } else if (self.gatherClient(e)) |conn| {
            self.sendRefusal(conn, e.request_id, status, r);
            self.flushToClient(conn.fd);
        }
        self.endGather(e);
    }

    /// The client a gather answers, if still connected.
    fn gatherClient(self: *Shard, e: *const Gathers.Entry) ?*Connection {
        if (e.reply_to != null) return null;
        const conn = self.getConnection(e.fd) orelse return null;
        return if (conn.id == e.conn_id) conn else null;
    }

    /// The gather is done: its client has one fewer request in flight, and
    /// any part still out is dropped when it comes.
    fn endGather(self: *Shard, e: *Gathers.Entry) void {
        if (self.gatherClient(e)) |conn| conn.forwards_in_flight -|= 1;
        self.gathers.finish(self.allocator, e);
    }

    // ─── Cross-Shard Walk ────────────────────────────────────────────────

    /// Execute a cross-shard walk (list/scan) for the given request.
    ///
    /// Uses ShardWalker([]const u8) to sequentially scan all shards'
    /// projections via the registered LocalScanFn, with cursor-based
    /// pagination.  Results are deduplicated (defensive — routing should
    /// prevent duplicates) and serialized in the standard list wire format.
    ///
    /// Wire format: [count:u32] ([name_len:u16][name])* [has_more:u8] [cursor_len:u16][cursor]
    fn executeWalk(self: *Shard, conn: *Connection, req: proto.Request, auth: run_mod.Authorized) void {
        const NameWalker = @import("dispatcher.zig").NameWalker;
        const op_idx = req.header.op_code;

        _ = self.dispatcher.walk_fn[op_idx] orelse {
            self.dispatcher.dispatch(auth, @ptrCast(self), @ptrCast(conn), req);
            return;
        };
        if (self.dispatcher.walk_context[op_idx] == null) {
            self.dispatcher.dispatch(auth, @ptrCast(self), @ptrCast(conn), req);
            return;
        }
        // A walk asks every shard: one offline would leave its part missing
        // in an answer that looks whole.
        if (self.offlineShard()) |down| {
            var buf: [320]u8 = undefined;
            self.sendErrorResponse(conn, req.header.request_id, .unavailable, down.offlineMessage(&buf));
            return;
        }
        // A table op decodes its own page request and walks from its handler.
        if (table.isOp(op_idx)) return self.dispatcher.dispatch(auth, @ptrCast(self), @ptrCast(conn), req);

        // [limit:u32][cursor...], the same for every walk op; a limit of 0
        // is the server's default.
        var limit: u32 = NameWalker.MAX_BATCH;
        var cursor: ?[]const u8 = null;
        if (req.value.len >= 4) {
            const parsed_limit = std.mem.readInt(u32, req.value[0..4], .little);
            if (parsed_limit > 0) limit = @min(parsed_limit, NameWalker.MAX_BATCH);
            if (req.value.len > 4) cursor = req.value[4..];
        }
        switch (walk_mod.start(self, conn, req, @intCast(self.shardCount()), limit, cursor)) {
            .asked => conn.response_deferred = true,
            .past_end => walk_mod.answerEmpty(self, conn, req.header.request_id),
            .refused => |r| self.sendRefusal(conn, req.header.request_id, r.status, r.refusal),
        }
    }

    // ─── Inbox draining ──────────────────────────────────────────────────

    /// Take the mailbox (called each reactor tick): the wakes, every reply,
    /// then at most one inbox's worth of requests — a flood of requests must
    /// not starve the shard's I/O and Raft heartbeats. What is left keeps the
    /// next tick from sleeping (`Mailbox.prepareSleep`). Replies go first and
    /// in full: each was reserved before its request was sent, so the ring
    /// holds no more than this shard asked for.
    pub fn drainInbox(self: *Shard) usize {
        const flags = self.mailbox.wake.take();
        if (flags & mailbox_mod.Flag.stream_appended.bit() != 0) self.workflow_handler.triggers_dirty = true;
        if (flags & mailbox_mod.Flag.action_invoked.bit() != 0) ActionsHandler.wakeFromPeer(self);
        if (flags & mailbox_mod.Flag.stream_disk_read.bit() != 0) self.streamDiskReadsBack();

        var buf: [64]InboxMessage = undefined;
        while (true) {
            const count = self.mailbox.replies.drain(&buf);
            if (count == 0) break;
            for (buf[0..count]) |msg| self.handleInboxMessage(msg);
        }

        const inbox = &self.mailbox.inbox;
        var total: usize = 0;
        while (total < inbox.capacity) {
            const count = inbox.drain(buf[0..@min(buf.len, inbox.capacity - total)]);
            if (count == 0) break;
            for (buf[0..count]) |msg| {
                if (self.mailbox.returnShare(msg)) {
                    if (self.peer_mailboxes) |peers| peers[msg.src_shard].wake.set(.share_returned);
                }
                self.handleInboxMessage(msg);
                total += 1;
            }
        }
        const left = inbox.pending();

        self.inbox_messages_processed += total;
        if (self.shard_metrics) |sm| {
            sm.recordInboxProcessed(total);
            sm.setInboxPending(left);
        }
        return total;
    }

    fn handleInboxMessage(self: *Shard, msg: InboxMessage) void {
        switch (msg.tag) {
            .shutdown => self.shutdown(),
            .action_start => self.startActionRun(msg),
            .action_finished, .action_result_ask, .action_abandon, .worker_report, .action_held, .action_unhold => self.actionMessage(msg),
            .kv_sink_put => self.runKvSinkPut(msg),
            .reply => self.deliverReply(msg),
            .forward_request => self.runForwardedRequest(msg),
            .cancel_reads => {
                const fd: i32 = @bitCast(@as(u32, @truncate(msg.sequence)));
                const conn_id: u32 = @truncate(msg.sequence >> 32);
                // Each dropped read is answered, empty: the asker holds its
                // slot until an answer comes.
                self.waiter_pool.removeByConnection(msg.src_shard, fd, conn_id, answerCancelled, @ptrCast(self));
            },
        }
    }

    /// Push-wake stream triggers after a stream append. The trigger for a stream
    /// lives on the workflow-definition's shard, which is usually NOT the shard
    /// that owns the stream's data — so we mark the local handler dirty (covers
    /// the co-located case) and set every peer's `stream_appended` flag, whose
    /// next tick force-polls its triggers. A flag, not a message: a burst of
    /// appends is one wake, and it can never fill an inbox. No-op when no
    /// trigger exists on the node, so streams that nobody watches incur zero
    /// cross-shard chatter.
    pub fn notifyStreamTriggers(self: *Shard) void {
        if (!WorkflowHandler.anyStreamTriggers()) return;

        self.workflow_handler.triggers_dirty = true;

        if (self.peer_mailboxes) |mailboxes| {
            for (mailboxes, 0..) |mb, i| {
                if (i == self.id) continue;
                mb.wake.set(.stream_appended);
            }
        }
    }

    /// A processing KV sink on another shard wrote a key this shard owns.
    fn runKvSinkPut(self: *Shard, msg: InboxMessage) void {
        const bytes = inboxPayload(msg);
        // Behind writes already waiting, so a key's writes keep their order.
        if (self.kv_sink_retries.items.len > 0) return self.holdKvSinkPut(bytes);
        if (!self.proposeKvSinkPut(bytes)) return self.holdKvSinkPut(bytes);
        if (bytes.len > 0) self.allocator.free(bytes);
    }

    /// Proposes one encoded sink write; false when the log is too full to
    /// take it now. A write refused for good, or that doesn't decode, is
    /// counted as dropped.
    fn proposeKvSinkPut(self: *Shard, bytes: []const u8) bool {
        const put = KVHandler.SinkPut.decode(bytes) orelse {
            self.processing_handler.noteSinkDrop(self.metrics_registry, "kv", "?", "the sink's message didn't decode");
            return true;
        };
        switch (KVHandler.sinkPropose(self, put.namespace, put.key, put.value, put.ttl_ms)) {
            .proposed => {},
            .held => return false,
            .dropped => |why| self.processing_handler.noteSinkDrop(self.metrics_registry, "kv", put.key, why),
        }
        return true;
    }

    /// Most sink writes waiting for room on one shard, and most bytes: a
    /// write can be 64 KiB, so the count alone would let 256 MiB wait.
    pub const KV_SINK_RETRY_MAX = 4096;
    pub const KV_SINK_RETRY_MAX_BYTES = 16 * 1024 * 1024;

    fn holdKvSinkPut(self: *Shard, bytes: []u8) void {
        if (self.kv_sink_retries.items.len >= KV_SINK_RETRY_MAX or self.kv_sink_retry_bytes + bytes.len > KV_SINK_RETRY_MAX_BYTES) {
            self.kv_sink_retry_overflow += 1;
            self.processing_handler.noteSinkDrop(self.metrics_registry, "kv", "?", "too many sink writes wait for room on the owning shard");
            if (bytes.len > 0) self.allocator.free(bytes);
            return;
        }
        self.kv_sink_retries.append(self.allocator, bytes) catch {
            self.kv_sink_retry_overflow += 1;
            self.processing_handler.noteSinkDrop(self.metrics_registry, "kv", "?", "out of memory holding a sink write for room");
            if (bytes.len > 0) self.allocator.free(bytes);
            return;
        };
        self.kv_sink_retry_bytes += bytes.len;
    }

    /// Proposes the sink writes waiting for room, oldest first, until the
    /// log is full again.
    fn retryKvSinkPuts(self: *Shard) void {
        const items = self.kv_sink_retries.items;
        var done: usize = 0;
        while (done < items.len) : (done += 1) {
            if (!self.proposeKvSinkPut(items[done])) break;
            self.kv_sink_retry_bytes -= items[done].len;
            if (items[done].len > 0) self.allocator.free(items[done]);
        }
        if (done == 0) return;
        std.mem.copyForwards([]u8, items[0 .. items.len - done], items[done..]);
        self.kv_sink_retries.shrinkRetainingCapacity(items.len - done);
    }

    /// How a run a workflow here waits on ended, or a workflow's shard
    /// asking how one here ended; the bytes are ours to free.
    fn actionMessage(self: *Shard, msg: InboxMessage) void {
        const ptr = msg.payload_ptr orelse return;
        const data: [*]u8 = @ptrCast(ptr);
        defer if (msg.payload_len > 0) self.allocator.free(data[0..msg.payload_len]);
        const bytes = data[0..msg.payload_len];
        switch (msg.tag) {
            .action_finished => self.actions_handler.finishedFromInbox(bytes),
            .action_result_ask => self.actions_handler.resultAskFromInbox(self, msg.src_shard, bytes),
            .action_abandon => self.actions_handler.abandonFromInbox(self, bytes),
            .worker_report => ActionsHandler.reportFromInbox(self, bytes),
            .action_held => self.actions_handler.heldFromInbox(bytes),
            .action_unhold => self.actions_handler.cancelHeld(self, self.id, bytes),
            else => unreachable,
        }
    }

    /// A workflow on another shard needs a run created here; its bytes are
    /// ours to free.
    fn startActionRun(self: *Shard, msg: InboxMessage) void {
        const ptr = msg.payload_ptr orelse return;
        const data: [*]u8 = @ptrCast(ptr);
        defer if (msg.payload_len > 0) self.allocator.free(data[0..msg.payload_len]);
        if (msg.payload_len == 0) return;
        self.actions_handler.startRunFromInbox(self, msg.src_shard, data[0..msg.payload_len]);
    }

    /// Drive a request that another shard forwarded to us. The request bytes
    /// were marshalled into `msg.payload`; the connection's identity is packed
    /// into `msg.sequence` as `(conn_id << 32) | fd`. `msg.src_shard` is the
    /// shard that owns the connection.
    ///
    /// We re-parse the wire bytes, populate the per-shard `forward_proxy`
    /// Connection with the owner's metadata, and dispatch on this shard's
    /// reactor thread — so per-shard handler state is only ever touched by
    /// the owning thread. Direct responses queued onto the proxy's write_buf
    /// are then shipped back to the owner via `deliverDeferred`. Waiter-based
    /// (blocking) responses use the address captured at registration time
    /// and round-trip through `deliverDeferred`.
    fn runForwardedRequest(self: *Shard, msg: InboxMessage) void {
        const ptr = msg.payload_ptr orelse return;
        const data: [*]u8 = @ptrCast(ptr);
        defer if (msg.payload_len > 0) self.allocator.free(data[0..msg.payload_len]);
        if (msg.payload_len == 0) return;

        const bytes = data[0..msg.payload_len];
        const fd: i32 = @bitCast(@as(u32, @truncate(msg.sequence)));
        const conn_id: u32 = @truncate(msg.sequence >> 32);
        const held = msg.replySlot();
        const reply_to: ReplyTo = .{ .socket = .{ .shard = msg.src_shard, .fd = fd, .conn_id = conn_id, .slot = held.slot, .gen = held.gen } };

        // A forwarded request that fails to parse is still answered: its
        // client is waiting on it.
        const req = proto.Request.parse(bytes) catch {
            const request_id: u64 = if (bytes.len >= 16) std.mem.readInt(u64, bytes[8..16], .little) else 0;
            var err_buf: [256]u8 = undefined;
            // The owning shard parsed it before forwarding, so the fault is
            // the server's, not the client's.
            const serialized = proto.Response.serializeRefusal(.internal_error, request_id, proto.notRun("internal error: another shard could not read this request"), &err_buf);
            self.deliverDeferred(reply_to, serialized);
            return;
        };

        const proxy = self.forward_proxy;
        loadProxy(proxy, reply_to);
        proxy.protocol = .binary;

        proxy.recordRequest();
        const answered_deferred = self.dispatchNoted(proxy, req, .shard);
        // As after a client's own request: what it proposed on its own
        // account applies before the next.
        _ = self.applyCommitted();

        // Pull any queued direct response off the proxy and ship the bytes
        // back to the owner. If the handler deferred the response (e.g. a
        // blocking group_read registered a waiter), the waiter's later
        // resolution will deliver via the same cross-shard inbox path.
        var err_buf: [256]u8 = undefined;
        if (self.takeProxyAnswer(proxy, req.header.request_id, &err_buf)) |answer| {
            defer answer.free(self.allocator);
            self.deliverDeferred(reply_to, answer.bytes());
        } else if (!proxy.response_deferred and answered_deferred) {
            self.answeredAsDeferred(req.header.request_id, req.header.op_code);
        } else if (!proxy.response_deferred) {
            const serialized = proto.Response.serializeRefusal(.internal_error, req.header.request_id, proto.unclassified(.internal_error, self.noAnswer(req)), &err_buf);
            self.deliverDeferred(reply_to, serialized);
        }
    }

    /// Ready a proxy to run a request whose answer goes to `reply_to`. The
    /// proxy also takes the requester's fd and generation as its own, so
    /// per-connection state kept by id (a KV transaction's owner) belongs to
    /// that requester.
    fn loadProxy(proxy: *Connection, reply_to: ReplyTo) void {
        proxy.proxy_for = reply_to;
        switch (reply_to) {
            .socket => |s| {
                proxy.fd = s.fd;
                proxy.id = s.conn_id;
            },
            .remote => |r| {
                proxy.fd = @bitCast(r.forward_id);
                proxy.id = r.node;
            },
        }
        proxy.state = .active;
        proxy.response_deferred = false;
        proxy.write_buf.read_pos = 0;
        proxy.write_buf.write_pos = 0;
        proxy.write_overflow = false;
    }

    /// An answer a handler queued on a proxy connection, taken whole — a cut
    /// answer desynchronises its client — or an error answer in its place.
    const ProxyAnswer = union(enum) {
        owned: []u8,
        err: []const u8,

        fn bytes(self: ProxyAnswer) []const u8 {
            return switch (self) {
                .owned => |b| b,
                .err => |b| b,
            };
        }

        fn free(self: ProxyAnswer, allocator: std.mem.Allocator) void {
            if (self == .owned) allocator.free(self.owned);
        }
    };

    /// Null when the handler queued nothing. An answer the proxy refused as
    /// too large, or that could not be copied, is replaced by an error
    /// answer written into `err_buf`.
    fn takeProxyAnswer(self: *Shard, proxy: *Connection, request_id: u64, err_buf: *[256]u8) ?ProxyAnswer {
        const pending = proxy.write_buf.readable();
        if (proxy.write_overflow) {
            proxy.write_overflow = false;
            proxy.write_buf.consume(pending);
            return .{ .err = proto.Response.serializeRefusal(.internal_error, request_id, .{ .reason = .answer_lost, .ran = .unknown, .message = "internal error: answer too large to send — ask for less" }, err_buf) };
        }
        if (pending == 0) return null;
        const answer = self.allocator.alloc(u8, pending) catch {
            proxy.write_buf.consume(pending);
            return .{ .err = proto.Response.serializeRefusal(.internal_error, request_id, .{ .reason = .answer_lost, .ran = .unknown, .message = "internal error: out of memory for the answer" }, err_buf) };
        };
        _ = proxy.write_buf.read(answer);
        proxy.shrinkWriteBuffer();
        return .{ .owned = answer };
    }

    /// The answer to a request this shard's client sent another shard. It
    /// frees the slot it names; one that is not the slot's current answer (a
    /// second answer, one for a slot reused since, or one from a shard it was
    /// not asked of) is dropped, so a client never hears twice about one
    /// request. An answer with no bytes is the other shard saying it could
    /// not send one. The connection's generation guards fd reuse: a client
    /// gone since hears nothing.
    fn deliverReply(self: *Shard, msg: InboxMessage) void {
        const bytes: []u8 = if (msg.payload_ptr) |p| @as([*]u8, @ptrCast(p))[0..msg.payload_len] else &.{};
        defer if (bytes.len > 0) self.allocator.free(bytes);
        const held = msg.replySlot();
        const slot = self.reply_pool.release(.{ .slot = held.slot, .gen = held.gen }, msg.src_shard) orelse return;
        if (self.shard_metrics) |sm| sm.setCrossShardInFlight(self.reply_pool.taken());
        // Its client was told at the deadline, or is gone: an answer that
        // took something is handed back.
        if (slot.answered) return ActionsHandler.orphanedAnswer(self, slot.op, bytes);
        if (slot.gather) |part| return self.gatherPartAnswered(slot, part, bytes);
        const conn = self.forwardAnswered(slot) orelse return ActionsHandler.orphanedAnswer(self, slot.op, bytes);
        if (bytes.len == 0) {
            var buf: [128]u8 = undefined;
            const message = std.fmt.bufPrint(&buf, "internal error: shard {d} lost its answer — the request may still apply", .{msg.src_shard}) catch "internal error: the answer was lost — the request may still apply";
            return self.sendErrorResponse(conn, slot.request_id, .internal_error, message);
        }
        _ = conn.queueWrite(bytes);
        self.flushToClient(slot.fd);
    }

    /// A forwarded request's client is answered, by the other shard or at
    /// its deadline: the client, if still connected, has one fewer request
    /// in flight.
    fn forwardAnswered(self: *Shard, slot: ReplyPool.Slot) ?*Connection {
        const conn = self.getConnection(slot.fd) orelse return null; // connection gone
        if (conn.id != slot.conn_id) return null; // fd reused for a new connection
        conn.forwards_in_flight -|= 1;
        if (slot.class == .blocking) {
            const held = conn.blocking_slots[0..conn.blocking_in_flight];
            for (held, 0..) |t, i| {
                if (t.slot != slot.index) continue;
                held[i] = held[held.len - 1];
                conn.blocking_in_flight -= 1;
                break;
            }
        }
        return conn;
    }

    /// Answer the clients whose requests another shard has not answered by
    /// their deadline, and take back slots held past `SLOT_DEADLINE_MS`:
    /// whatever lost the answer, neither the client nor the slot waits for
    /// ever. Swept every quarter second, so a client is told at most about
    /// that long after its deadline.
    fn expireReplySlots(self: *Shard) void {
        const now = nowMs();
        if (now < self.reply_sweep_ms) return;
        self.reply_sweep_ms = now + 250;
        const Expired = struct {
            shard: *Shard,
            count: u64 = 0,
            /// Expired per target, to name the one with the most.
            per_target: [@import("../config/server.zig").MAX_SHARDS]u32 = @splat(0),
            pub fn late(ctx: *@This(), slot: ReplyPool.Slot) void {
                if (slot.gather) |part| return ctx.shard.gatherPartLate(slot, part);
                ctx.count += 1;
                ctx.per_target[slot.target] += 1;
                if (ctx.shard.shard_metrics) |sm| sm.recordCrossShardTimeout();
                const conn = ctx.shard.forwardAnswered(slot) orelse return;
                const after = slot.answer_after_ms / 1000;
                var buf: [128]u8 = undefined;
                const message = if (slot.writes)
                    std.fmt.bufPrint(&buf, "unavailable: shard {d} did not answer in {d} s — the request may still apply", .{ slot.target, after }) catch "unavailable: no answer — the request may still apply"
                else
                    std.fmt.bufPrint(&buf, "unavailable: shard {d} did not answer in {d} s — retry", .{ slot.target, after }) catch "unavailable: no answer — retry";
                ctx.shard.sendRefusal(conn, slot.request_id, .unavailable, .{ .reason = .unclassified, .ran = if (slot.writes) .unknown else .no, .message = message });
                // Nothing else may touch an idle client's connection soon.
                ctx.shard.flushToClient(slot.fd);
            }
        };
        var gone = Expired{ .shard = self };
        const oldest = self.reply_pool.expire(now, &gone);
        if (self.shard_metrics) |sm| {
            sm.setCrossShardInFlight(self.reply_pool.taken());
            sm.setOldestCrossShardWait(if (oldest) |t| (now -| t) / 1000 else 0);
        }
        if (gone.count == 0) return;
        self.slots_expired += gone.count;
        if (now -| self.expire_warn_ms < WARN_INTERVAL_MS) return;
        self.expire_warn_ms = now;
        const worst = std.mem.indexOfMax(u32, &gone.per_target);
        log.warn("shard {d}: since the last report, {d} client requests to other shards went unanswered past their deadline (most in this sweep: {d}, to shard {d}); their clients were told", .{ self.id, self.slots_expired, gone.per_target[worst], worst });
        self.slots_expired = 0;
    }

    /// A leader whose clock and stamps disagree by more than a clock should
    /// says so, naming the node on each side, and gauges it either way.
    fn reportStampSkew(self: *Shard) void {
        const raft = self.raft_node;
        if (raft.role != .leader) {
            if (self.shard_metrics) |sm| sm.setStampSkew(0);
            return;
        }
        const skew_ms: i64 = @intCast(raft.stamp_skew_ns / std.time.ns_per_ms);
        if (self.shard_metrics) |sm| sm.setStampSkew(if (raft.stamp_clock_behind) -skew_ms else skew_ms);
        if (raft.stamp_skew_ns < raft_node_mod.STAMP_SKEW_WARN_NS) return;
        const now = nowMs();
        if (now -| self.stamp_warn_ms < WARN_INTERVAL_MS) return;
        self.stamp_warn_ms = now;
        const me = self.cluster_node_id;
        if (!raft.stamp_clock_behind) {
            log.warn("shard {d}: node {d}'s clock is at least {d} ms ahead of node {d}'s, the clock a majority of the voters keep; entries are stamped at the voters' time: check the clocks on nodes {d} and {d}", .{ self.id, me, skew_ms, raft.stamp_held_by, me, raft.stamp_held_by });
        } else if (raft.voterPeers() == 0) {
            log.warn("shard {d}: node {d}'s clock is {d} ms behind the last stamp in the log (was it set back?); entries are stamped 1 ns apart until it catches up", .{ self.id, me, skew_ms });
        } else {
            log.warn("shard {d}: node {d}'s clock is {d} ms behind the last stamp in the log, which an earlier leader gave; entries are stamped 1 ns apart until it catches up: check the clock on node {d} against node {d}'s, the voters' clock", .{ self.id, me, skew_ms, me, raft.stamp_held_by });
        }
    }

    /// Every frame the network queued since the last drain.
    fn drainRaftQueue(self: *Shard) void {
        const q = self.raft_queue orelse return;
        while (q.pop()) |frame| {
            defer self.allocator.free(frame.payload);
            self.replica.handleRaftFrame(frame);
        }
    }

    // ─── Writes waiting for commit ───────────────────────────────────────

    /// Answers a parked write from what its entry's applier recorded. Runs
    /// only for an entry that applied and was not refused; it reads nothing
    /// but `result`.
    pub const AnswerFn = *const fn (shard: *Shard, conn: *Connection, request_id: u64, result: *const persistence_mod.Result) void;

    /// Frees what a parked write holds (`ctx`, as `parkHolding` was given
    /// it), however its wait ends.
    pub const ReleaseFn = *const fn (shard: *Shard, ctx: u64) void;

    /// What a write handler does once its entry is proposed: nothing more
    /// now. `answer` runs once the entry is applied, on this thread, with a
    /// connection standing for the client's. When the entry is already
    /// committed (a group of one) that is right away, on the client's own
    /// connection.
    pub fn park(self: *Shard, conn: *Connection, req: proto.Request, proposed: raft_node_mod.ProposeResult, answer: AnswerFn) void {
        self.parkHolding(conn, req, proposed, answer, null, 0);
    }

    /// `park`, for a write that holds something until it is answered.
    pub fn parkHolding(self: *Shard, conn: *Connection, req: proto.Request, proposed: raft_node_mod.ProposeResult, answer: AnswerFn, release: ?ReleaseFn, ctx: u64) void {
        // Inside the apply loop `applyCommitted` returns without draining:
        // a single node's write would be answered before its entry applied.
        std.debug.assert(!self.applying);
        // Up to this write's entry and no further: its answer is that
        // entry's result, which the next entry's replaces. The dispatch
        // that parked this applies the rest. A pass that ends short of it,
        // on a backlog, leaves it to wait in the table like any other.
        const answered_here = self.raft_node.commit_index >= proposed.index and here: {
            std.debug.assert(self.raft_node.last_applied < proposed.index);
            _ = self.applyThrough(proposed.index);
            // Reached its entry, or the pass drained fully (not stopped by the
            // budget, and not held by a blocked read): otherwise it parks and
            // is answered when the rest applies.
            break :here self.raft_node.last_applied >= proposed.index or (!self.apply_behind and !self.read_blocked and self.snapshot_window == null);
        };
        if (answered_here) {
            defer if (release) |r| r(self, ctx);
            if (self.halted) |*h| if (proposed.index >= h.index) {
                // A membership change takes effect at commit, halted or not.
                const around = self.appliesAroundHalt(proposed.index);
                if (around orelse false) {
                    var done = persistence_mod.Result{ .index = proposed.index };
                    return answer(self, conn, req.header.request_id, &done);
                }
                var buf: [320]u8 = undefined;
                const message = if (around == null) "shard is halted, and your write's entry can't be read back right now to say whether it took effect; do not resend" else self.pendingMessage(&buf, proposed.index);
                return self.sendRefusal(conn, req.header.request_id, .outcome_pending, .{ .reason = .shard_halted, .ran = .unknown, .message = message });
            };
            if (self.raft_node.last_applied != proposed.index or !self.last_entry_applied) {
                self.sendRefusal(conn, req.header.request_id, .internal_error, persistence_mod.COMMITTED_REFUSAL);
                return;
            }
            if (self.last_result.refused()) |r| return self.sendRefusal(conn, req.header.request_id, r.status, r.refusal);
            if (self.last_result.overflowed) return self.sendRefusal(conn, req.header.request_id, .internal_error, persistence_mod.ANSWER_LOST_REFUSAL);
            answer(self, conn, req.header.request_id, &self.last_result);
            return;
        }
        const slot = &self.pending[proposed.index % PENDING_SLOTS];
        if (slot.active) {
            // In steady state the Raft node's outstanding cap keeps this below
            // the table size. It can still happen on a lone node (no such cap)
            // whose reads are blocked, holding committed entries unapplied: the
            // write is refused rather than a parked one overwritten.
            log.err("shard {d}: pending slot for index {d} still holds index {d}", .{ self.id, proposed.index, slot.index });
            if (release) |r| r(self, ctx);
            // Proposed already: it may still apply.
            self.sendRefusal(conn, req.header.request_id, .overloaded, .{ .reason = .unclassified, .ran = .unknown, .message = persistence_mod.failureMessage(error.Overloaded, "") });
            return;
        }
        slot.* = .{ .active = true, .index = proposed.index, .term = proposed.term, .reply_to = conn.replyTo(), .request_id = req.header.request_id, .answer = answer, .release = release, .ctx = ctx };
        self.pending_count += 1;
        conn.response_deferred = true;
        // Under sync durability its own copy is flushed with the rest of
        // this tick's writes, by the apply pass that follows (one fdatasync
        // for all of them), before anything is answered.
        self.replica.pump(nowMs());
    }

    /// The entry at `index` applied (or could not): answer whoever waits,
    /// from `result`.
    fn answerPending(self: *Shard, index: u64, term: u64, applied: bool, result: *const persistence_mod.Result) void {
        const table_slot = &self.pending[index % PENDING_SLOTS];
        if (!table_slot.active or table_slot.index != index) return;
        // Out of the table before it is answered, so a sweep of the table
        // (`resolvePending`) meanwhile cannot answer it a second time.
        const slot = table_slot.*;
        table_slot.active = false;
        self.pending_count -= 1;
        defer if (slot.release) |r| r(self, slot.ctx);
        // A different term at this index is a new leader's entry: this
        // write never committed, whatever became of that one.
        if (term != 0 and slot.term != term)
            return self.deliverDeferredRefusal(slot.reply_to, slot.request_id, .unavailable, proto.notRun("unavailable: leader changed, write not applied — retry"));
        if (!applied) return self.deliverDeferredRefusal(slot.reply_to, slot.request_id, .internal_error, persistence_mod.COMMITTED_REFUSAL);
        if (result.refused()) |r| return self.deliverDeferredRefusal(slot.reply_to, slot.request_id, r.status, r.refusal);
        if (result.overflowed) return self.deliverDeferredRefusal(slot.reply_to, slot.request_id, .internal_error, persistence_mod.ANSWER_LOST_REFUSAL);
        const proxy = self.respond_proxy;
        loadProxy(proxy, slot.reply_to);
        slot.answer(self, proxy, slot.request_id, result);
        var err_buf: [256]u8 = undefined;
        if (self.takeProxyAnswer(proxy, slot.request_id, &err_buf)) |answer| {
            defer answer.free(self.allocator);
            self.deliverDeferred(slot.reply_to, answer.bytes());
        } else {
            self.deliverDeferredRefusal(slot.reply_to, slot.request_id, .internal_error, persistence_mod.ANSWER_LOST_REFUSAL);
        }
    }

    /// Take a slot out of the table, answered already, and release what it held.
    fn endPending(self: *Shard, slot: *Pending) void {
        slot.active = false;
        self.pending_count -= 1;
        if (slot.release) |r| r(self, slot.ctx);
    }

    /// A write that committed but hadn't applied, under a backlog applied
    /// in passes, is told so rather than `message`, which speaks of commit.
    fn resolvePending(self: *Shard, message: []const u8) void {
        if (self.pending_count == 0) return;
        log.warn("shard {d}: {d} write(s) were waiting for commit; answering each: {s}", .{ self.id, self.pending_count, message });
        for (self.pending) |*slot| {
            if (!slot.active) continue;
            const committed = slot.index <= self.raft_node.commit_index;
            self.deliverDeferredError(slot.reply_to, slot.request_id, .unavailable, if (committed) COMMITTED_NOT_ANSWERED else message);
            self.endPending(slot);
        }
    }

    pub const COMMITTED_NOT_ANSWERED = "unavailable: the write committed, but this node stopped before it could answer from it; it may have applied — check before resending";

    // ─── Writes on a node that does not lead ─────────────────────────────

    fn redirectToLeader(self: *Shard, conn: *Connection, req: proto.Request) void {
        const leader = self.raft_node.leader_id;
        var buf: [160]u8 = undefined;
        const addr = if (leader != 0) if (self.raft_network) |rn| rn.clientAddress(leader) else null else null;
        const msg = if (addr) |a|
            std.fmt.bufPrint(&buf, "unavailable: this node is a replica; send writes to the leader, node {d} at {d}.{d}.{d}.{d}:{d}", .{ leader, a.ip4[0], a.ip4[1], a.ip4[2], a.ip4[3], a.port }) catch REPLICA_MESSAGE
        else if (leader != 0)
            std.fmt.bufPrint(&buf, "unavailable: this node is a replica; send writes to the leader, node {d}", .{leader}) catch REPLICA_MESSAGE
        else
            REPLICA_MESSAGE;
        self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(msg));
    }

    const REPLICA_MESSAGE = "unavailable: this node is a replica and knows no leader yet; send writes to a voter — retry";

    /// Send a client's write to the leader, and
    /// hold the client until the leader answers. With no leader known the
    /// write waits for one, up to FORWARD_TIMEOUT_MS.
    fn forwardToLeader(self: *Shard, conn: *Connection, req: proto.Request) void {
        const wait_ms = blockingWait(req) orelse 0;
        if (wait_ms > 0 and self.blocking_forwards >= FORWARD_SLOTS - FORWARD_WRITE_RESERVE) {
            self.sendRefusal(conn, req.header.request_id, .overloaded, .{ .reason = .too_many_waiters, .ran = .no, .message = "overloaded: too many reads waiting for the leader — retry" });
            return;
        }
        const slot = blk: {
            for (self.forwards) |*f| if (!f.active) break :blk f;
            self.sendErrorResponse(conn, req.header.request_id, .overloaded, "too many writes waiting for the leader");
            return;
        };
        const bytes = serializeRequest(self.allocator, req) catch {
            self.sendErrorResponse(conn, req.header.request_id, .internal_error, "could not hold the request for the leader");
            return;
        };
        slot.* = .{ .active = true, .id = self.next_forward_id, .reply_to = conn.replyTo(), .request_id = req.header.request_id, .bytes = bytes, .wait_ms = wait_ms, .deadline_ms = nowMs() + FORWARD_TIMEOUT_MS, .read = !requestWrites(req) };
        self.next_forward_id +%= 1;
        if (self.next_forward_id == 0) self.next_forward_id = FORWARD_ID_FIRST;
        self.forward_count += 1;
        if (wait_ms > 0) self.blocking_forwards += 1;
        conn.recordForward();
        conn.response_deferred = true;
        self.sendForward(slot);
    }

    /// Sent only over a link that is up, and marked with that link's
    /// session: an answer that has not come when the session changes went
    /// over a link that is gone. A full forward queue to the leader answers
    /// the client now: nothing was sent, so nothing ran.
    fn sendForward(self: *Shard, f: *Forward) void {
        const raft = self.raft_node;
        const leader = raft.leader_id;
        if (leader == 0 or leader == self.cluster_node_id) return;
        const rn = self.raft_network orelse return;
        const session = rn.linkSession(leader) orelse return;
        // A forward is the request re-encoded, which can outgrow what the
        // client sent by the namespace an empty one decodes as and the
        // options trailer a client may omit.
        var buf: [FORWARD_PREFIX + FORWARD_FIELDS + MAX_REQUEST_SIZE + proto.DEFAULT_NAMESPACE.len + 2]u8 = undefined;
        const body_at = FORWARD_PREFIX + FORWARD_FIELDS;
        if (body_at + f.bytes.len > buf.len) {
            self.finishForward(f, .internal_error, .internal, "request too large to forward");
            return;
        }
        std.mem.writeInt(u32, buf[0..4], f.id, .little);
        // Fields carried beside the client's bytes, never inside them: the
        // namespace's id as this node resolved it (0 if it doesn't know it
        // yet, and the leader resolves it), and its table's published index.
        std.mem.writeInt(u16, buf[4..6], FORWARD_FIELDS, .little);
        const req_ns = if (proto.Request.parse(f.bytes)) |r| r.namespace else |_| "";
        // An ask names no namespace of its own.
        const ns_id: ns_table.Id = if (f.ask != null) .invalid else self.forwardedNamespaceId(req_ns);
        std.mem.writeInt(u32, buf[FORWARD_PREFIX..][0..4], ns_id.int(), .little);
        std.mem.writeInt(u64, buf[FORWARD_PREFIX + 4 ..][0..8], self.namespace_handler.table.publishedIndex(), .little);
        @memcpy(buf[body_at..][0..f.bytes.len], f.bytes);
        switch (rn.sendForward(leader, .forward_write, self.id, buf[0 .. body_at + f.bytes.len], session)) {
            .queued => {},
            .full => return self.finishForward(f, .overloaded, .shard_busy, "overloaded: the link to the leader is full; this request was not run — retry"),
            .not_sent => return,
        }
        f.sent_to = leader;
        f.sent_term = raft.current_term;
        f.sent_session = session;
        f.sent_ms = nowMs();
    }

    /// Writes waiting for a leader go out once one is known, or run here
    /// once this node is it (never under a handler that is itself
    /// waiting); one that waited too long is answered. A write already
    /// sent waits for its leader's answer however long the operation
    /// takes; once the term has moved on, or the link it went over is
    /// down, that answer will never come, and the client is told what is
    /// known. A reply held for read-your-writes
    /// is released at the deadline rather than forever: the write is
    /// committed, only this node's copy is late.
    fn sweepForwards(self: *Shard, now: u64) void {
        const raft = self.raft_node;
        const leader = raft.leader_id;
        for (self.forwards) |*f| {
            if (!f.active) continue;
            if (f.reply) |reply| {
                if (now < f.deadline_ms) continue;
                if (now -| self.late_apply_warn_ms >= WARN_INTERVAL_MS) {
                    self.late_apply_warn_ms = now;
                    log.warn("shard {d}: answering a write the leader committed at index {d} before this node applied it (applied {d}); this node is behind", .{ self.id, f.applied_by, self.raft_node.last_applied });
                }
                self.deliverDeferred(f.reply_to, reply);
                self.dropForward(f);
                continue;
            }
            if (f.sent_to != 0) {
                if (raft.current_term != f.sent_term or (leader != 0 and leader != f.sent_to)) {
                    self.lostLeader(f, "unavailable: lost leadership before commit — write may still apply");
                } else if (self.raft_network != null and self.raft_network.?.linkSession(f.sent_to) != f.sent_session) {
                    // Gone, or gone and back between two ticks: either way the
                    // link it went over is not the one up now.
                    self.lostLeader(f, "unavailable: lost the link to the leader — write may still apply");
                } else if (now -| f.sent_ms >= SENT_FORWARD_BACKSTOP_MS + f.wait_ms) {
                    self.lostLeader(f, "unavailable: no answer from the leader — write may still apply");
                }
                continue;
            }
            if (leader == self.cluster_node_id) {
                // This node leads now: its own table is the one to wait for.
                if (f.ask) |name| {
                    // Not before it has applied every earlier leader's creates.
                    if (!raft.leaderReady()) continue;
                    self.edge.answered(name, self.namespace_handler.table.publishedIndex(), now);
                    self.dropForward(f);
                } else self.runHeldLocally(f);
                continue;
            }
            if (leader != 0) {
                self.sendForward(f);
                if (f.sent_to != 0) continue;
            }
            // Never sent: it can't have run.
            if (now >= f.deadline_ms) {
                const why: proto.Refusal = .{ .reason = .leader_unknown, .ran = .no, .message = if (leader != 0) "unavailable: the leader is not reachable from this node — retry" else "unavailable: electing a leader — retry" };
                if (f.ask) |name| self.failAsk(name, .unavailable, why) else self.deliverDeferredRefusal(f.reply_to, f.request_id, .unavailable, why);
                self.dropForward(f);
            }
        }
    }

    /// A write held while a leader was being chosen, on the node that
    /// became it: run it as the client's own request. The slot is freed
    /// first so nothing that runs under the handler can see it.
    fn runHeldLocally(self: *Shard, f: *Forward) void {
        const bytes = f.bytes;
        f.bytes = &.{};
        const reply_to = f.reply_to;
        const request_id = f.request_id;
        self.dropForward(f);
        defer self.allocator.free(bytes);
        self.runHeld(bytes, reply_to, request_id);
    }

    /// A held request, run here as the client's own.
    pub fn runHeld(self: *Shard, bytes: []const u8, reply_to: ReplyTo, request_id: u64) void {
        const req = proto.Request.parse(bytes) catch {
            self.deliverDeferredRefusal(reply_to, request_id, .internal_error, proto.notRun("internal error: the held request did not parse and was not run — retry"));
            return;
        };
        const proxy = self.respond_proxy;
        loadProxy(proxy, reply_to);
        const answered_deferred = self.dispatchNoted(proxy, req, .held);
        var err_buf: [256]u8 = undefined;
        if (self.takeProxyAnswer(proxy, request_id, &err_buf)) |answer| {
            defer answer.free(self.allocator);
            self.deliverDeferred(reply_to, answer.bytes());
        } else if (!proxy.response_deferred and answered_deferred) {
            self.answeredAsDeferred(req.header.request_id, req.header.op_code);
        } else if (!proxy.response_deferred) {
            self.deliverDeferredError(reply_to, request_id, .internal_error, self.noAnswer(req));
        }
    }

    // ─── The edge: a namespace this node doesn't know ────────────────────

    const NO_NAMESPACE: proto.Refusal = .{ .reason = .not_found, .ran = .no, .message = "namespace not found" };
    const NO_NAMESPACE_YET: proto.Refusal = .{ .reason = .not_found, .ran = .no, .message = "namespace not found; one created a moment ago through another node can take up to 100 ms to be seen here — retry" };
    /// The node never looked, so this isn't no_namespace: a client may take
    /// that as final for a namespace that exists.
    pub const EDGE_FULL: proto.Refusal = .{ .reason = .shard_busy, .ran = .no, .message = "overloaded: this node doesn't know the namespace yet and is already asking the leader about 64 others; the request was not run — retry" };
    const ASK_FAILED = "unavailable: this node could not ask the leader about this namespace; the request was not run — retry";

    /// Whether `op` runs within a namespace: every op but the node's own
    /// (system, namespace, cluster) and those another shard sends.
    fn namespaced(op: u16) bool {
        return op > ops.Family.range(.cluster).hi and !table.isInternal(op) and !table.serverScoped(op);
    }

    /// A read in a namespace this node's table doesn't have. The table
    /// shows a create once shard 0 has published it, which is after a write
    /// that created it implicitly may have been answered; so:
    /// - shard 0 knows its own creates, applied or under way;
    /// - another shard asks shard 0 (`namespace.published`, a gather), which
    ///   answers once a create of the name it holds is published, and then
    ///   looks again (`EdgeAsk`);
    /// - on one node, or the leader, shard 0 has every create there is, so a
    ///   name it doesn't hold is none;
    /// - a follower's shard 0 may be behind: it holds the read and asks the
    ///   leader how far its table is published, waits for its own to get
    ///   there, and looks again.
    /// A write creates its namespace, so it goes on. True when the request is
    /// answered or held.
    ///
    /// A shard other than 0 never asks the leader: a cluster member runs one
    /// shard, so it has none, and on one node shard 0 holds every create.
    fn edgeMiss(self: *Shard, conn: *Connection, req: proto.Request, origin: run_mod.Origin) bool {
        if (!namespaced(req.header.op_code) or requestWrites(req)) return false;
        const name = if (req.namespace.len == 0) "default" else req.namespace;
        const nh = self.namespace_handler;
        if (nh.table.lookup(name) != null) return false;
        if (self.id != 0) {
            self.askShard0(conn, req, name, origin);
            return true;
        }
        if (nh.creating(name)) return false;
        if (self.raft_network == null or self.raft_node.role == .leader) {
            // A new leader may not have applied its predecessor's creates.
            if (!self.raft_node.leaderReady()) self.sendRefusal(conn, req.header.request_id, .unavailable, .{ .reason = .leader_unknown, .ran = .no, .message = handler_mod.NamespaceHandler.PUBLISHED_NOT_READY }) else self.sendRefusal(conn, req.header.request_id, .no_namespace, NO_NAMESPACE);
            return true;
        }
        const now = nowMs();
        if (self.edge.missed(name, now)) {
            self.sendRefusal(conn, req.header.request_id, .no_namespace, NO_NAMESPACE_YET);
            return true;
        }
        self.holdAtEdge(conn, req, name, origin, now);
        return true;
    }

    /// A read held on a shard other than 0 while shard 0 answers whether
    /// its namespace is created: one gather each, so however it ends the
    /// client is answered once.
    const EdgeAsk = struct {
        /// The request, serialized, and where it came from.
        bytes: []u8,
        origin: run_mod.Origin,

        const op: gather_mod.Op = .{ .merge = merge, .deinit = free };

        fn free(state: *anyopaque, allocator: std.mem.Allocator) void {
            const self: *EdgeAsk = @ptrCast(@alignCast(state));
            allocator.free(self.bytes);
            allocator.destroy(self);
        }

        /// Shard 0 answered after any create of the name it held was
        /// published, so the table now has the namespace if it exists.
        fn merge(shard: *Shard, conn: *Connection, request_id: u64, state: *anyopaque, bodies: []const []const u8) anyerror!void {
            const self: *EdgeAsk = @ptrCast(@alignCast(state));
            var diag: @import("../protocol/schema.zig").Diagnostic = .{};
            _ = try table_run.op("namespace.published").response.decodeAll(bodies[0], &diag);
            const req = try proto.Request.parse(self.bytes);
            const name = if (req.namespace.len == 0) "default" else req.namespace;
            if (shard.namespace_handler.table.lookup(name) == null)
                return shard.sendRefusal(conn, request_id, .no_namespace, NO_NAMESPACE);
            shard.runRequest(conn, req, self.origin);
        }
    };

    fn askShard0(self: *Shard, conn: *Connection, req: proto.Request, name: []const u8, origin: run_mod.Origin) void {
        const id = req.header.request_id;
        const state = self.allocator.create(EdgeAsk) catch return self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory"));
        const bytes = serializeRequest(self.allocator, req) catch {
            self.allocator.destroy(state);
            return self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory"));
        };
        state.* = .{ .bytes = bytes, .origin = origin };
        const parts = [_]gather_mod.Part{.{ .owner = 0, .op = @backingInt(proto.OpCode.namespace_published), .key = name, .body = "" }};
        self.startGather(conn, req, &parts, &EdgeAsk.op, state) catch |err| return switch (err) {
            error.GatherBusy => self.sendRefusal(conn, id, .overloaded, .{ .reason = .shard_busy, .ran = .no, .message = "overloaded: too many requests across shards are under way; this request was not run — retry" }),
            error.OutOfMemory => self.sendRefusal(conn, id, .internal_error, proto.notRun("internal error: out of memory")),
        };
        conn.response_deferred = true;
    }

    fn holdAtEdge(self: *Shard, conn: *Connection, req: proto.Request, name: []const u8, origin: run_mod.Origin, now: u64) void {
        if (conn.forwards_in_flight >= Connection.MAX_FORWARDS_IN_FLIGHT) return self.sendRefusal(conn, req.header.request_id, .overloaded, .{ .reason = .shard_busy, .ran = .no, .message = "overloaded: too many requests on this connection are waiting; this request was not run — back off and retry" });
        const w = self.edge.free() orelse return self.sendRefusal(conn, req.header.request_id, .overloaded, EDGE_FULL);
        const bytes = serializeRequest(self.allocator, req) catch return self.sendRefusal(conn, req.header.request_id, .internal_error, proto.notRun("internal error: out of memory"));
        const owned = self.allocator.dupe(u8, name) catch {
            self.allocator.free(bytes);
            return self.sendRefusal(conn, req.header.request_id, .internal_error, proto.notRun("internal error: out of memory"));
        };
        const index = self.edge.knownIndex(name);
        const asked = index != null or self.askingAbout(name);
        w.* = .{ .active = true, .reply_to = conn.replyTo(), .origin = origin, .request_id = req.header.request_id, .bytes = bytes, .name = owned, .index = index, .deadline_ms = now + edge_mod.WAIT_MS };
        self.edge.count += 1;
        // One of the connection's requests waiting elsewhere, as a gather's.
        conn.forwards_in_flight += 1;
        // Held, the read lets the connection's later requests run first, as a
        // blocking read does: a write sent after it may apply before it runs,
        // and it then sees that write.
        conn.response_deferred = true;
        if (!asked) self.askLeader(owned);
    }

    fn askingAbout(self: *const Shard, name: []const u8) bool {
        for (self.forwards) |*f| if (f.active) if (f.ask) |a| if (std.mem.eql(u8, a, name)) return true;
        return false;
    }

    /// Ask the leader how far its namespaces are published, over the
    /// forward path as a write would go: one ask a name, whatever reads of
    /// it are held. Asks are at most edge_mod.WAITS (one a held name) of
    /// FORWARD_SLOTS, so they never reach the slots kept for writes.
    fn askLeader(self: *Shard, name: []const u8) void {
        const slot = for (self.forwards) |*f| {
            if (!f.active) break f;
        } else return self.failAsk(name, .overloaded, proto.notRun("overloaded: too many requests waiting for the leader; this one was not run — retry"));
        const ask = self.allocator.dupe(u8, name) catch return self.failAsk(name, .internal_error, proto.notRun("internal error: out of memory"));
        const id = self.next_forward_id;
        const req: proto.Request = .{ .header = proto.RequestHeader.init(.namespace_published, id), .namespace = "", .key = name, .value = "", .options = "" };
        const bytes = serializeRequest(self.allocator, req) catch {
            self.allocator.free(ask);
            return self.failAsk(name, .internal_error, proto.notRun("internal error: out of memory"));
        };
        // Its answer goes to the reads held for the name, never to a socket.
        slot.* = .{ .active = true, .id = id, .reply_to = .{ .remote = .{ .node = 0, .forward_id = 0 } }, .request_id = id, .bytes = bytes, .deadline_ms = nowMs() + FORWARD_TIMEOUT_MS, .ask = ask };
        self.next_forward_id +%= 1;
        if (self.next_forward_id == 0) self.next_forward_id = FORWARD_ID_FIRST;
        self.forward_count += 1;
        self.sendForward(slot);
    }

    fn takeAskAnswer(self: *Shard, name: []const u8, resp: proto.Response) void {
        if (resp.header.status != @backingInt(proto.StatusCode.ok)) return self.failAsk(name, .unavailable, proto.notRun(ASK_FAILED));
        const Published = table_run.op("namespace.published").response;
        var diag: @import("../protocol/schema.zig").Diagnostic = .{};
        const v = Published.decodeAll(resp.data, &diag) catch return self.failAsk(name, .unavailable, proto.notRun(ASK_FAILED));
        self.edge.answered(name, v.published_index, nowMs());
    }

    /// Every read of `name` still waiting for the leader is answered so.
    fn failAsk(self: *Shard, name: []const u8, status: proto.StatusCode, why: proto.Refusal) void {
        for (&self.edge.waits) |*w| if (w.active and w.index == null and std.mem.eql(u8, w.name, name)) {
            self.deliverDeferredRefusal(w.reply_to, w.request_id, status, why);
            self.endEdgeWait(w);
        };
    }

    /// Held reads whose wait is over: this node's table reached the
    /// leader's index, so the name is resolved here, or the wait ran out.
    fn sweepEdge(self: *Shard, now: u64) void {
        const t = self.namespace_handler.table;
        for (&self.edge.waits) |*w| {
            if (!w.active) continue;
            if (w.index) |index| if (t.publishedIndex() >= index) {
                self.resolveAtEdge(w, now);
                continue;
            };
            if (now >= w.deadline_ms) {
                self.deliverDeferredRefusal(w.reply_to, w.request_id, .unavailable, proto.notRun("unavailable: this node hasn't caught up with the leader's namespaces yet; the request was not run — retry"));
                self.endEdgeWait(w);
            }
        }
    }

    fn resolveAtEdge(self: *Shard, w: *edge_mod.Wait, now: u64) void {
        if (self.namespace_handler.table.lookup(w.name) == null) {
            self.edge.noteMissing(self.allocator, w.name, now);
            self.deliverDeferredRefusal(w.reply_to, w.request_id, .no_namespace, NO_NAMESPACE_YET);
            self.endEdgeWait(w);
            return;
        }
        const bytes = w.bytes;
        w.bytes = &.{};
        const reply_to = w.reply_to;
        const origin = w.origin;
        self.endEdgeWait(w);
        defer self.allocator.free(bytes);
        // Run as the client's own request, now that its namespace resolves.
        // Only a client's or the admin socket's request is held here.
        const s = switch (reply_to) {
            .socket => |sock| sock,
            .remote => return,
        };
        const conn = self.getConnection(s.fd) orelse return;
        if (conn.id != s.conn_id) return;
        const req = proto.Request.parse(bytes) catch unreachable; // serialized here
        self.runRequest(conn, req, origin);
        // Run from the tick, not from reading the client: nothing else
        // sends what it answered.
        self.flushToClient(conn.fd);
    }

    /// A held read is over: its connection has one fewer request waiting.
    fn endEdgeWait(self: *Shard, w: *edge_mod.Wait) void {
        switch (w.reply_to) {
            .socket => |sock| if (self.getConnection(sock.fd)) |conn| {
                if (conn.id == sock.conn_id) conn.forwards_in_flight -|= 1;
            },
            .remote => {},
        }
        self.edge.drop(self.allocator, w);
    }

    fn dropEdgeFor(self: *Shard, fd: i32, conn_id: u32) void {
        for (&self.edge.waits) |*w| {
            if (w.active and w.reply_to.isSocket(@intCast(self.id), fd, conn_id)) self.endEdgeWait(w);
        }
    }

    /// The client is gone: nothing it was waiting for needs a slot.
    fn dropForwardsFor(self: *Shard, fd: i32, conn_id: u32) void {
        for (self.forwards) |*f| {
            if (f.active and f.reply_to.isSocket(@intCast(self.id), fd, conn_id)) self.dropForward(f);
        }
    }

    /// A forward that went to a leader and won't be answered by it: a write
    /// may still apply there; a read ran nowhere that matters, and is retried.
    fn lostLeader(self: *Shard, f: *Forward, write_message: []const u8) void {
        self.finishForward(f, .unavailable, .leader_unknown, if (f.read) "unavailable: lost the leader before it answered — retry" else write_message);
    }

    /// End a forward unanswered. A read's refusal says it didn't run, with
    /// `reason`; a write's says what `message` does.
    fn finishForward(self: *Shard, f: *Forward, status: proto.StatusCode, reason: proto.Reason, message: []const u8) void {
        // An ask is a read: whatever ended it, nothing ran.
        if (f.ask) |name| self.failAsk(name, status, proto.notRun(ASK_FAILED)) else if (f.read)
            self.deliverDeferredRefusal(f.reply_to, f.request_id, status, .{ .reason = reason, .ran = .no, .message = message })
        else
            self.deliverDeferredError(f.reply_to, f.request_id, status, message);
        self.dropForward(f);
    }

    fn dropForward(self: *Shard, f: *Forward) void {
        self.allocator.free(f.bytes);
        if (f.ask) |a| self.allocator.free(a);
        if (f.reply) |r| {
            self.allocator.free(r);
            self.replies_held -= 1;
        }
        if (f.wait_ms > 0) self.blocking_forwards -= 1;
        f.* = .{};
        self.forward_count -= 1;
    }

    /// A write a peer received while this node leads: run it here as if
    /// the client had connected here, answering over the link.
    fn runForwardedWrite(self: *Shard, frame: RaftFrame) void {
        if (frame.payload.len < FORWARD_PREFIX) return self.replica.badFrame(frame);
        const id = std.mem.readInt(u32, frame.payload[0..4], .little);
        const fields_len = std.mem.readInt(u16, frame.payload[4..6], .little);
        // Fields this node does not know how to honour: running the request
        // without them would ignore what the forwarder meant.
        if (fields_len != FORWARD_FIELDS or frame.payload.len < FORWARD_PREFIX + FORWARD_FIELDS) {
            self.replica.badFrame(frame);
            const body = frame.payload[@min(frame.payload.len, FORWARD_PREFIX + @as(usize, fields_len))..];
            const request_id: u64 = if (body.len >= 16) std.mem.readInt(u64, body[8..16], .little) else 0;
            var err_buf: [256]u8 = undefined;
            const serialized = proto.Response.serializeRefusal(.internal_error, request_id, proto.notRun("internal error: the leader cannot read this forwarded request — are all nodes on the same version?"), &err_buf);
            return self.sendForwardReply(frame.source_node, id, serialized);
        }
        const ns_id: ns_table.Id = .of(std.mem.readInt(u32, frame.payload[FORWARD_PREFIX..][0..4], .little));
        const published = std.mem.readInt(u64, frame.payload[FORWARD_PREFIX + 4 ..][0..8], .little);
        const body_at = FORWARD_PREFIX + FORWARD_FIELDS;
        const req = proto.Request.parse(frame.payload[body_at..]) catch {
            // The forwarder holds its client until this is answered.
            self.replica.badFrame(frame);
            const body = frame.payload[body_at..];
            const request_id: u64 = if (body.len >= 16) std.mem.readInt(u64, body[8..16], .little) else 0;
            var err_buf: [256]u8 = undefined;
            // The forwarder parsed it first, so the likely cause is two
            // nodes running different versions.
            const serialized = proto.Response.serializeRefusal(.internal_error, request_id, proto.notRun("internal error: the leader could not read this request — are all nodes on the same version?"), &err_buf);
            return self.sendForwardReply(frame.source_node, id, serialized);
        };
        // A namespace the forwarder resolved is admitted only as this node's
        // table has it, under the same name: an id it doesn't know yet, or
        // one that names another namespace, never reaches the handler. The
        // table only grows, so an id it has under this name is admitted
        // however far behind the forwarder's it is; only an unknown id
        // waits for it to catch up. The forwarder's table published it, so
        // the create is committed and this node's table gets there as it
        // applies: a moment's wait, not a retry the client has to make.
        if (ns_id != .invalid) {
            var err_buf: [256]u8 = undefined;
            const t = self.namespace_handler.table;
            const want = if (req.namespace.len == 0) "default" else req.namespace;
            const name = t.nameOf(ns_id) orelse if (t.publishedIndex() < published)
                return self.holdForwardForTable(frame, id, req.header.request_id, published)
            else
                null;
            // This node's table vouches for no namespace by that id under
            // that name, but can't say there is none: the client retries,
            // and the forwarder resolves the name again.
            if (name == null or !std.mem.eql(u8, name.?, want))
                return self.sendForwardReply(frame.source_node, id, proto.Response.serializeRefusal(.unavailable, req.header.request_id, FORWARD_ID_UNKNOWN, &err_buf));
        }
        const proxy = self.forward_proxy;
        loadProxy(proxy, .{ .remote = .{ .node = frame.source_node, .forward_id = id } });
        proxy.protocol = .binary;
        proxy.recordRequest();
        const answered_deferred = self.dispatchNoted(proxy, req, .peer);
        var err_buf: [256]u8 = undefined;
        if (self.takeProxyAnswer(proxy, req.header.request_id, &err_buf)) |answer| {
            defer answer.free(self.allocator);
            self.sendForwardReply(frame.source_node, id, answer.bytes());
        } else if (!proxy.response_deferred and answered_deferred) {
            self.answeredAsDeferred(req.header.request_id, req.header.op_code);
        } else if (!proxy.response_deferred) {
            const serialized = proto.Response.serializeRefusal(.internal_error, req.header.request_id, proto.unclassified(.internal_error, self.noAnswer(req)), &err_buf);
            self.sendForwardReply(frame.source_node, id, serialized);
        }
    }

    pub const HELD_FORWARDS_FULL: proto.Refusal = .{ .reason = .shard_busy, .ran = .no, .message = "overloaded: too many forwarded writes are waiting for this leader to catch up with their namespaces; the write was not run — retry" };
    pub const FORWARD_ID_UNKNOWN: proto.Refusal = proto.notRun("unavailable: the leader's namespaces don't name this request's namespace by the id it was sent with; the write was not run — retry");
    pub const FORWARD_NOT_CAUGHT_UP: proto.Refusal = proto.notRun("unavailable: the leader hasn't caught up with this namespace yet; the write was not run — retry");

    /// Hold a forwarded write until this node's table reaches the
    /// forwarder's published index (`sweepHeldForwards`).
    fn holdForwardForTable(self: *Shard, frame: RaftFrame, id: u32, request_id: u64, published: u64) void {
        var err_buf: [256]u8 = undefined;
        const h = self.edge.freeHeld() orelse
            return self.sendForwardReply(frame.source_node, id, proto.Response.serializeRefusal(.overloaded, request_id, HELD_FORWARDS_FULL, &err_buf));
        const payload = self.allocator.dupe(u8, frame.payload) catch
            return self.sendForwardReply(frame.source_node, id, proto.Response.serializeRefusal(.internal_error, request_id, proto.notRun("internal error: out of memory"), &err_buf));
        h.* = .{
            .active = true,
            .payload = payload,
            .source_node = frame.source_node,
            .group_id = frame.group_id,
            .forward_id = id,
            .request_id = request_id,
            .published = published,
            .deadline_ms = nowMs() + edge_mod.FORWARD_WAIT_MS,
        };
        self.edge.held_count += 1;
    }

    /// Held forwards whose wait is over: this node's table reached the
    /// forwarder's index, so the write is checked again and runs or is
    /// refused as on arrival, or the wait ran out and it never ran.
    fn sweepHeldForwards(self: *Shard, now: u64) void {
        for (&self.edge.held) |*h| {
            if (!h.active) continue;
            if (self.namespace_handler.table.publishedIndex() >= h.published) {
                const payload = h.payload;
                h.payload = &.{};
                const frame: RaftFrame = .{ .source_node = h.source_node, .group_id = h.group_id, .msg_type = .forward_write, .payload = payload };
                self.edge.dropHeld(self.allocator, h);
                defer self.allocator.free(payload);
                self.runForwardedWrite(frame);
            } else if (now >= h.deadline_ms) {
                var err_buf: [256]u8 = undefined;
                self.sendForwardReply(h.source_node, h.forward_id, proto.Response.serializeRefusal(.unavailable, h.request_id, FORWARD_NOT_CAUGHT_UP, &err_buf));
                self.edge.dropHeld(self.allocator, h);
            }
        }
    }

    /// The answer to a forwarded write, with the index the client's node
    /// must have applied before handing it over: read-your-writes on the
    /// node the client wrote to.
    fn sendForwardReply(self: *Shard, peer: u32, id: u32, bytes: []const u8) void {
        // The forwarder holds its client until a reply comes: one that
        // cannot be sent whole is replaced by one that can.
        if (12 + bytes.len > transport.MAX_PAYLOAD_SIZE) {
            var err_buf: [256]u8 = undefined;
            const request_id: u64 = if (bytes.len >= 16) std.mem.readInt(u64, bytes[8..16], .little) else 0;
            const serialized = proto.Response.serializeRefusal(.internal_error, request_id, .{ .reason = .answer_lost, .ran = .unknown, .message = "internal error: answer too large to send" }, &err_buf);
            return self.sendForwardReply(peer, id, serialized);
        }
        const buf = self.allocator.alloc(u8, 12 + bytes.len) catch {
            log.warn("shard {d}: out of memory for a forwarded write's reply to node {d}", .{ self.id, peer });
            return;
        };
        defer self.allocator.free(buf);
        std.mem.writeInt(u32, buf[0..4], id, .little);
        std.mem.writeInt(u64, buf[4..12], self.raft_node.last_applied, .little);
        @memcpy(buf[12..], bytes);
        const rn = self.raft_network orelse return;
        // A reply that cannot be queued is lost; the forwarder's backstop
        // answers its client.
        switch (rn.sendForward(peer, .forward_reply, self.id, buf, 0)) {
            .queued => {},
            .full, .not_sent => {
                const now = nowMs();
                if (now -| self.forward_reply_warn_ms >= WARN_INTERVAL_MS) {
                    self.forward_reply_warn_ms = now;
                    log.warn("shard {d}: could not queue a forwarded write's answer for node {d} (its link is full or down); that client is answered by its node's backstop", .{ self.id, peer });
                }
            },
        }
    }

    fn takeForwardReply(self: *Shard, frame: RaftFrame) void {
        if (frame.payload.len < 12) return self.replica.badFrame(frame);
        const id = std.mem.readInt(u32, frame.payload[0..4], .little);
        const committed = std.mem.readInt(u64, frame.payload[4..12], .little);
        const f = blk: {
            for (self.forwards) |*f| if (f.active and f.id == id) break :blk f;
            return; // answered already, or the client gave up
        };
        if (f.reply != null) return;
        // Only the leader it went to may answer it, and only with an
        // answer to it.
        if (frame.source_node != f.sent_to) return self.replica.impostorFrame(frame, f.sent_to);
        const bytes = frame.payload[12..];
        const resp = proto.Response.parse(bytes) catch return self.replica.badFrame(frame);
        if (resp.header.request_id != f.request_id) return self.replica.badFrame(frame);
        if (f.ask) |name| {
            self.takeAskAnswer(name, resp);
            self.dropForward(f);
            return;
        }
        // A write's answer waits for this node to apply what it committed,
        // so its client reads its own write here; a read changed nothing.
        if (f.read or self.raft_node.last_applied >= committed) {
            self.deliverDeferred(f.reply_to, bytes);
            self.dropForward(f);
            return;
        }
        f.reply = self.allocator.dupe(u8, bytes) catch {
            self.finishForward(f, .internal_error, .internal, "could not hold the leader's answer");
            return;
        };
        f.applied_by = committed;
        f.deadline_ms = nowMs() + FORWARD_TIMEOUT_MS;
        self.replies_held += 1;
    }

    fn releaseReplies(self: *Shard) void {
        const applied = self.raft_node.last_applied;
        for (self.forwards) |*f| {
            if (!f.active or f.reply == null or f.applied_by > applied) continue;
            self.deliverDeferred(f.reply_to, f.reply.?);
            self.dropForward(f);
        }
    }

    // ─── Raft on the shard thread ────────────────────────────────────────

    /// A clock that never jumps: timeouts must not fire, or fail to, on
    /// an NTP step.
    fn nowMs() u64 {
        return @import("stdx").time.monotonicMs();
    }

    /// Rate-limits the write-overflow close line: the count of lines left
    /// unsaid, or null to stay quiet.
    fn overflowWarnDue(self: *Shard) ?u64 {
        const now = nowMs();
        if (now -| self.overflow_warn_ms < WARN_INTERVAL_MS) {
            self.overflow_unsaid += 1;
            return null;
        }
        self.overflow_warn_ms = now;
        const unsaid = self.overflow_unsaid;
        self.overflow_unsaid = 0;
        return unsaid;
    }

    fn strangerFrame(self: *Shard, frame: RaftFrame) void {
        // Only a committed removal is told: an uncommitted one may yet be
        // cut from the log.
        if (self.raft_node.committed_config.removedAt(frame.source_node)) |when| return self.sendRemovedNotice(frame.source_node, when);
        const now = nowMs();
        if (now -| self.stranger_warn_ms < WARN_INTERVAL_MS) return;
        self.stranger_warn_ms = now;
        log.warn("shard {d}: node {d} sent a {s} frame but is not a member; ignored (a node with the secret is a member only once the leader adds it)", .{ self.id, frame.source_node, @tagName(frame.msg_type) });
    }

    /// Tell a removed node so, at most once a second: it stops, rather than
    /// campaign or ask to join forever.
    fn sendRemovedNotice(self: *Shard, to: u32, when_ms: u64) void {
        const now = nowMs();
        if (now -| self.removed_notice_ms < 1000) return;
        self.removed_notice_ms = now;
        var buf: [REMOVAL_NOTICE_SIZE]u8 = undefined;
        std.mem.writeInt(u64, buf[0..8], when_ms, .little);
        std.mem.writeInt(u64, buf[8..16], self.raft_node.committed_config_index, .little);
        self.replica.sendRaft(to, .removed_notice, &buf);
    }

    /// A notice: when the group removed this node (the removing leader's
    /// clock, part of the replicated config, so every member that holds the
    /// removal names the same time), and the index of the committed config
    /// its sender holds.
    const REMOVAL_NOTICE_SIZE = 16;

    /// One member's word is not enough to stop this node: it acts once a
    /// majority of the other voters in its own committed config each hold a
    /// notice naming the same removal, in a config newer than its own. Each
    /// sender's latest notice is what counts, so one sender changing its
    /// word moves only its own vote. A node with no committed config yet,
    /// still joining, has no voters to count, and stops on one notice from a
    /// linked peer: that is all it can learn until links prove each node's
    /// identity.
    fn takeRemovedNotice(self: *Shard, frame: RaftFrame) void {
        if (frame.payload.len != REMOVAL_NOTICE_SIZE) return self.replica.badFrame(frame);
        const when_ms = std.mem.readInt(u64, frame.payload[0..8], .little);
        const config_index = std.mem.readInt(u64, frame.payload[8..16], .little);
        const raft = self.raft_node;
        const committed = &raft.committed_config;
        const from = frame.source_node;
        if (committed.member_count == 0) {
            self.noteRemovalNotice(.counted);
            self.removal = .{ .config_index = config_index };
            self.removal.hold(from, when_ms);
            return self.enterRemovedBy(when_ms, 1);
        }
        const why: ?[]const u8 = if (from == self.cluster_node_id or !committed.isVoter(from))
            "not a voter of this node's committed config"
        else if (config_index <= raft.committed_config_index)
            "it names a config no newer than this node's"
        else
            null;
        if (why) |reason| {
            self.noteRemovalNotice(.ignored);
            return self.warnRemovalNotice(from, reason);
        }
        if (self.removal.held(from)) |w| if (w == when_ms) return self.noteRemovalNotice(.duplicate);
        self.removal.config_index = @max(self.removal.config_index, config_index);
        self.removal.hold(from, when_ms);
        if (self.removal.disagree(when_ms)) {
            self.noteRemovalNotice(.conflict);
            self.warnRemovalNotice(from, "it names another removal than other members' notices");
        } else self.noteRemovalNotice(.counted);
        const needed = self.removalQuorum();
        if (self.removal.agreeing(when_ms) >= needed) return self.enterRemovedBy(when_ms, needed);
        self.publishRemoval(when_ms, needed, 0);
    }

    /// A strict majority of the voters other than this node in its committed
    /// config: in a group of three, both others.
    fn removalQuorum(self: *const Shard) u8 {
        var ids: [membership.MAX_MEMBERS]u32 = undefined;
        var others: u8 = 0;
        for (self.raft_node.committed_config.voterIds(&ids)) |id| others += @intFromBool(id != self.cluster_node_id);
        return others / 2 + 1;
    }

    /// A current-term leader still treats this node as a member: notices
    /// held so far are void.
    fn clearRemovalNotices(self: *Shard) void {
        if (self.removal.count == 0) return;
        self.removal = .{};
        self.publishRemoval(0, 0, 0);
    }

    fn enterRemovedBy(self: *Shard, when_ms: u64, needed: u8) void {
        self.publishRemoval(when_ms, needed, when_ms);
        self.enterRemoved(when_ms);
    }

    /// The senders whose notices name `when_ms`, for /status.
    fn publishRemoval(self: *Shard, when_ms: u64, needed: u8, at_ms: u64) void {
        const slot = self.health orelse return;
        var ids: [membership.MAX_MEMBERS]u32 = undefined;
        var n: usize = 0;
        for (self.removal.from[0..self.removal.count], self.removal.when[0..self.removal.count]) |id, w| {
            if (w != when_ms) continue;
            ids[n] = id;
            n += 1;
        }
        slot.removal.publish(ids[0..n], needed, self.removal.config_index, at_ms);
    }

    fn noteRemovalNotice(self: *Shard, outcome: ShardMetrics.RemovalOutcome) void {
        if (self.shard_metrics) |sm| sm.recordRemovalNotice(outcome);
    }

    fn warnRemovalNotice(self: *Shard, from: u32, why: []const u8) void {
        const now = nowMs();
        if (now -| self.removal_warn_ms < WARN_INTERVAL_MS) return;
        self.removal_warn_ms = now;
        log.warn("shard {d}: a removal notice from node {d} was not counted: {s}", .{ self.id, from, why });
    }

    /// The group removed this node. It stops taking part, says so to
    /// clients, and says how to come back.
    fn enterRemoved(self: *Shard, when_ms: u64) void {
        if (self.removed_at_ms != null) return;
        self.removed_at_ms = when_ms;
        var at: [32]u8 = undefined;
        self.removed_message = std.fmt.bufPrint(&self.removed_message_buf, "{s} at {s}", .{ REMOVED_MESSAGE, formatUtc(&at, when_ms) }) catch REMOVED_MESSAGE;
        const raft = self.raft_node;
        if (raft.role == .leader) {
            raft.role = .follower;
            raft.leader_id = 0;
        }
        raft.timer_enabled = false;
        if (self.raft_network) |rn| rn.stopDialing();
        self.stoppedLeading(self.removed_message);
        self.warnRemoved(nowMs());
    }

    fn warnRemoved(self: *Shard, now: u64) void {
        const when = self.removed_at_ms orelse return;
        if (self.removed_warn_ms != 0 and now -| self.removed_warn_ms < 30_000) return;
        self.removed_warn_ms = now;
        var at: [32]u8 = undefined;
        log.err("shard {d}: removed from the cluster at {s} (the removing leader's clock); this node takes no part. To bring this machine back, start it with a new node id and an empty data directory, then --join a live member", .{ self.id, formatUtc(&at, when) });
    }

    /// `YYYY-MM-DD HH:MM:SS UTC` of a time in ms since the epoch.
    fn formatUtc(buf: *[32]u8, ms: u64) []const u8 {
        const secs = std.time.epoch.EpochSeconds{ .secs = ms / 1000 };
        const day = secs.getDaySeconds();
        const yd = secs.getEpochDay().calculateYearDay();
        const md = yd.calculateMonthDay();
        return std.fmt.bufPrint(buf, "{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2} UTC", .{ yd.year, md.month.numeric(), @as(u32, md.day_index) + 1, day.getHoursIntoDay(), day.getMinutesIntoHour(), day.getSecondsIntoMinute() }) catch buf[0..0];
    }

    pub const REMOVED_MESSAGE = "unavailable: this node was removed from the cluster";

    /// The Raft node and durability, read where the replica reads them:
    /// the runtime, and tests, set them after init.
    fn raftNode(self: *Shard) *RaftNode {
        return self.raft_node;
    }

    /// An ack means "in my log, on disk".
    fn durableCommits(self: *const Shard) bool {
        return self.durability == .sync;
    }

    fn isRemoved(self: *const Shard) bool {
        return self.removed_at_ms != null;
    }

    /// Removed, or a committed config says so: the tick does nothing else.
    fn checkRemoved(self: *Shard, now: u64) bool {
        if (self.removed_at_ms != null) {
            self.warnRemoved(now);
            return true;
        }
        const when = self.raft_node.committed_config.removedAt(self.cluster_node_id) orelse return false;
        self.enterRemoved(when);
        return true;
    }

    /// Flush the batch just taken, before it is acked. False, counted and
    /// logged, when the flush failed: the batch is not acked.
    fn flushForAck(self: *Shard) bool {
        self.flushSegmentToDisk() catch |err| {
            self.noteFlushFailed();
            log.err("shard {d}: sync flush failed: {s}; not acking the batch (persist_failures={d})", .{ self.id, @errorName(err), self.persist_failures });
            return false;
        };
        return true;
    }

    /// The tick's membership steps: a leader's own changes, a joiner's
    /// request to be let in, and writes waiting on the leader.
    fn tickMembership(self: *Shard, now: u64) void {
        if (self.raft_node.role == .leader) self.adjustMembership(now);
        if (self.joinWanted(now)) self.askToJoin(now);
        if (self.forward_count > 0) self.sweepForwards(now);
        if (self.edge.count > 0) self.sweepEdge(now);
    }

    /// Stop at entry `e`, which no replica can apply: its `last_applied`
    /// stays just below it, the Raft node proposes only what elects a
    /// leader or changes membership, and writes waiting past it are told
    /// once their entries commit. Every replica halts at the same entry.
    fn halt(self: *Shard, e: *const entry_mod.Entry, comptime fmt: []const u8, args: anytype) void {
        if (self.halted != null) return;
        const type_name = std.enums.tagName(entry_mod.EntryType, @fromBackingInt(@intCast(e.header.entry_type))) orelse "unknown";
        self.halted = Halt.init(e, "entry {d} ({s}): " ++ fmt, .{ e.header.index, type_name } ++ args);
        const raft = self.raft_node;
        raft.halt_at = .{ .index = e.header.index, .term = e.header.term, .crc = e.header.crc32c };
        raft.last_applied = e.header.index - 1;
        self.last_entry_applied = false;
        self.skip_scan_from = e.header.index + 1;
        self.marker.halted(e.header.index, e.header.term, e.header.crc32c);
        log.err("shard {d} halted at {s}. It applies nothing past it and takes no writes; reads are served, marked stale. Restarting won't help: the entry has to be repaired (the node's /status says where it halted)", .{ self.id, self.halted.?.reason() });
        self.answerHaltedPending();
    }

    /// Go on past the halt once a committed repair skips it: the skip is
    /// among the committed entries after it. Each call looks only at what
    /// committed since the last.
    fn resumePastSkip(self: *Shard) bool {
        const h = self.halted orelse return true;
        const raft = self.raft_node;
        var idx = @max(self.skip_scan_from, h.index + 1);
        while (idx <= raft.commit_index) : (idx += 1) {
            const e = switch (raft.log.readForApply(idx, self.apply_buf)) {
                .found => |x| x,
                // A blocked read: can't tell if this is the skip, so pause the
                // scan here and try again rather than walk past it (which would
                // leave the node halted for good). Paced and surfaced like any
                // blocked read, not probed once per request.
                .blocked => |b| {
                    self.skip_scan_from = idx;
                    _ = self.noteReadBlock(b.disk_failing, b.permission, idx);
                    return false;
                },
                .absent => continue,
            };
            if (self.read_blocked) self.clearReadBlocked();
            const skip = repair.Skip.decode(&e) orelse continue;
            if (skip.index != h.index or skip.term != h.term or skip.crc != h.crc) continue;
            self.skips.add(self.allocator, &skip) catch {
                // Looked at again on the next call.
                self.skip_scan_from = idx;
                return false;
            };
            log.info("shard {d}: the repair at entry {d} skips entry {d} ({s}); going on past it", .{ self.id, idx, h.index, skip.reason });
            self.halted = null;
            raft.halt_at = null;
            self.marker.resumed();
            // The entry is passed over when the apply reaches it again. One
            // whose apply ran before it halted already left what a pass-over
            // leaves: the ring refuses a second take of all but a KV entry,
            // and the bar count takes no index twice.
            if (self.marker.crashed) |*c| if (c.index == h.index) self.marker.skipped();
            return true;
        }
        self.skip_scan_from = raft.commit_index + 1;
        return false;
    }

    /// Whether a committed repair skips `h`: one this shard took, or, for
    /// the entry it is halted at, one committed since it last looked, which
    /// it takes now and goes on past.
    fn repairedOpaque(ctx: ?*anyopaque, h: raft_node_mod.HaltAt) bool {
        const self: *Shard = @ptrCast(@alignCast(ctx.?));
        if (self.skips.holds(&.{ .index = h.index, .term = h.term, .crc = h.crc })) return true;
        const halted = self.halted orelse return false;
        if (halted.index != h.index or halted.term != h.term or halted.crc != h.crc) return false;
        return self.resumePastSkip() and self.halted == null;
    }

    /// A repair skip applied. Where its entry was skipped, or lies below
    /// the log's start, there is nothing to do; one that names no entry of
    /// this log, an entry at or past itself, or another skip skips nothing,
    /// the same on every replica. A replica that applied the entry it names
    /// holds what no other does: false, and the shard is damaged.
    fn checkSkip(self: *Shard, e: *const entry_mod.Entry) bool {
        const at = e.header.index;
        const skip = repair.Skip.decode(e) orelse {
            log.warn("shard {d}: entry {d} is a repair skip that won't decode; it skips nothing", .{ self.id, at });
            return true;
        };
        if (self.skips.holds(&skip)) return true;
        if (skip.index >= at) {
            log.warn("shard {d}: the repair at entry {d} names entry {d}, not one before it; it skips nothing", .{ self.id, at, skip.index });
            return true;
        }
        const raft = self.raft_node;
        if (skip.index < raft.log.start()) return true;
        // Overwrites `e`, and the reason with it.
        const named = switch (raft.log.readForApply(skip.index, self.apply_buf)) {
            .found => |x| x,
            // The named entry can't be read to decide the skip. Don't seal it
            // as naming nothing (which would silently keep what no other
            // replica holds). Hold the check by the skip's own index — the
            // apply loop runs it again, paced, before anything past the skip
            // applies — rather than drop it.
            .blocked => |b| {
                self.skip_check_pending = at;
                _ = self.noteReadBlock(b.disk_failing, b.permission, skip.index);
                return false;
            },
            .absent => {
                log.warn("shard {d}: the repair at entry {d} names entry {d}, which this node can't read back; it skips nothing here", .{ self.id, at, skip.index });
                return true;
            },
        };
        if (!skip.names(&named)) {
            log.warn("shard {d}: the repair at entry {d} names entry {d} in term {d}, which this log doesn't hold; it skips nothing", .{ self.id, at, skip.index, skip.term });
            return true;
        }
        if (isSkip(&named)) {
            log.warn("shard {d}: the repair at entry {d} names another repair; a skip is never skipped", .{ self.id, at });
            return true;
        }
        self.damaged(silent_loss.Damage.init(.applied_skipped, "entry {d} applied on this node, but the repair at entry {d} skips it on every replica", .{ skip.index, at }));
        return false;
    }

    /// Re-run a repair-skip check that an earlier blocked read held. The skip
    /// entry itself applied; only its check — whether it names an entry this
    /// node applied divergently — waited. True once the check has run (sealed,
    /// or the node damaged) or nothing is held; false while the read is still
    /// blocked, so the apply loop does not go past the skip meanwhile.
    fn runPendingSkipCheck(self: *Shard) bool {
        const at = self.skip_check_pending;
        if (at == 0) return true;
        switch (self.raft_node.log.readForApply(at, self.apply_buf)) {
            .found => |e| {
                if (self.checkSkip(&e)) {
                    self.skip_check_pending = 0;
                    self.seal_skip = true;
                    self.clearReadBlocked();
                    return true;
                }
                // checkSkip returned false: either its named read is still
                // blocked (it re-armed the back-off) or the node is now
                // damaged. Either way, hold here.
                if (self.offline != null or self.replica.diverged) self.skip_check_pending = 0;
                return false;
            },
            .blocked => |b| {
                _ = self.noteReadBlock(b.disk_failing, b.permission, at);
                return false;
            },
            // The skip entry was truncated away: nothing left to check.
            .absent => {
                self.skip_check_pending = 0;
                self.clearReadBlocked();
                return true;
            },
        }
    }

    /// Whether `err` is a halted shard refusing one of its own writes.
    /// Those come every tick, so they are counted and said once every 30
    /// seconds, and the caller logs nothing.
    pub fn quietHalted(self: *Shard, err: anyerror) bool {
        if (err != error.Halted) return false;
        self.halted_refusals += 1;
        const now = nowMs();
        if (now >= self.halted_line_ms) {
            self.halted_line_ms = now + 30_000;
            log.warn("shard {d} is halted: {d} of its own writes (checkpoints, acks, run steps) refused since the last line", .{ self.id, self.halted_refusals });
            self.halted_refusals = 0;
        }
        return true;
    }

    /// The entry at `index` is one a halt doesn't stop: a config, which
    /// takes effect at commit, or a term's no-op. Null when it can't be
    /// read right now.
    fn appliesAroundHalt(self: *Shard, index: u64) ?bool {
        const e = switch (self.raft_node.log.readForApply(index, self.apply_buf)) {
            .found => |e| e,
            .absent => return false,
            .blocked => return null,
        };
        return e.header.entry_type == @backingInt(entry_mod.EntryType.raft_config) or e.header.entry_type == @backingInt(entry_mod.EntryType.raft_noop);
    }

    /// What a write committed at `index`, at or past the halt, is told.
    /// The write the shard halted at never runs: a repair skips that entry.
    fn pendingMessage(self: *const Shard, buf: []u8, index: u64) []const u8 {
        const h = &(self.halted orelse return "shard is halted; your write will apply when the shard resumes — do not resend");
        if (index == h.index) return std.fmt.bufPrint(buf, "shard {d} halted at your write (entry {d}): {s}. It has not applied; a repair skips it, so it will not run. Don't resend it unchanged", .{ self.id, h.index, h.reason() }) catch "shard halted at your write; a repair skips it, so it will not run. Don't resend it unchanged";
        return std.fmt.bufPrint(buf, "shard {d} is halted at entry {d}; your write is entry {d} and will apply when the shard resumes — do not resend", .{ self.id, h.index, index }) catch "shard is halted; your write will apply when the shard resumes — do not resend";
    }

    /// What a write to a halted shard is refused with.
    fn haltedMessage(self: *const Shard, buf: []u8) []const u8 {
        const h = &(self.halted orelse return "unavailable: shard is halted");
        return std.fmt.bufPrint(buf, "unavailable: shard {d} is halted at {s}; this request was not run. Restarting won't help — the node's /status says where it halted", .{ self.id, h.reason() }) catch "unavailable: shard is halted; this request was not run";
    }

    /// Writes waiting on entries at or past the halt, once their entries
    /// commit: told the write applies when the shard resumes. One whose
    /// entry a later leader replaced never committed, and is told so; one
    /// not committed yet keeps waiting, since a leader change may still
    /// drop it.
    fn answerHaltedPending(self: *Shard) void {
        const h = &(self.halted orelse return);
        if (self.pending_count == 0) return;
        // A read below blocked: not again until the back-off has passed.
        if (nowMs() < self.read_retry_at_ms) return;
        const raft = self.raft_node;
        for (self.pending) |*slot| {
            if (!slot.active or slot.index < h.index or slot.index > raft.commit_index) continue;
            if (raft.log.entryTerm(slot.index)) |term| if (term != slot.term) {
                self.deliverDeferredRefusal(slot.reply_to, slot.request_id, .unavailable, proto.notRun("unavailable: leader changed, write not applied — retry"));
                self.endPending(slot);
                continue;
            };
            // A membership change or a term's no-op takes effect at commit,
            // halted or not: answered as done.
            // One that can't be read right now waits for the next pass,
            // rather than being told it applies when the shard resumes.
            const around = self.appliesAroundHalt(slot.index) orelse {
                self.read_retry_at_ms = nowMs() + READ_RETRY_MS;
                return;
            };
            if (around) {
                var done = persistence_mod.Result{ .index = slot.index };
                const proxy = self.respond_proxy;
                loadProxy(proxy, slot.reply_to);
                slot.answer(self, proxy, slot.request_id, &done);
                var err_buf: [256]u8 = undefined;
                if (self.takeProxyAnswer(proxy, slot.request_id, &err_buf)) |answer| {
                    defer answer.free(self.allocator);
                    self.deliverDeferred(slot.reply_to, answer.bytes());
                }
                self.endPending(slot);
                continue;
            }
            var buf: [320]u8 = undefined;
            self.deliverDeferredRefusal(slot.reply_to, slot.request_id, .outcome_pending, .{ .reason = .shard_halted, .ran = .unknown, .message = self.pendingMessage(&buf, slot.index) });
            self.endPending(slot);
        }
    }

    /// This node's own data is damaged: the projections are missing what
    /// `damage` names and cannot be rebuilt here. On a lone node the shard
    /// goes offline and the others serve; a member stops taking part in
    /// its group, as a diverged one does.
    fn damaged(self: *Shard, damage: silent_loss.Damage) void {
        if (self.offline != null or self.replica.diverged) return;
        // No longer waiting on the read: drop the block so its gauge does not
        // stick and `/status` shows the damage, not the stale block.
        self.clearReadBlocked();
        self.losses.note(damage.path, nowMs(), self.id, "{s}", .{damage.reason()});
        // Reads held for stream records are answered with the damage, never
        // later with records past it; nothing more is read from the log.
        if (self.stream_disk) |d| d.stopped = true;
        self.damage_for_waiters = damage;
        self.waiter_pool.expireKinds(&.{ .stream_disk_read, .stream_read }, answerDamaged, @ptrCast(self));
        if (self.raft_network == null) {
            self.offline = damage;
            self.offline_published.store(true, .release);
            const what = if (damage.out_of_memory) "Its log is intact: restart the node once memory is free" else "The data directory needs repair";
            log.err("shard {d} is offline on this node: {s}. Its requests are refused; the other shards serve. {s}", .{ self.id, damage.reason(), what });
            var buf: [320]u8 = undefined;
            self.stopTakingPart(self.offlineMessage(&buf));
            return;
        }
        self.replica.diverged = true;
        self.diverged_damage = damage;
        if (damage.out_of_memory) {
            log.err("shard {d}: {s}. Its log on disk is intact; it has stopped taking part in the group until it restarts. Restart it once memory is free", .{ self.id, damage.reason() });
            self.stopTakingPart(OUT_OF_MEMORY_MESSAGE);
            return;
        }
        log.err("shard {d}: {s}. This node's copy can no longer be trusted and it has stopped taking part in the group. Stop it, move its data directory aside, and start it again with --join <a live member>", .{ self.id, damage.reason() });
        self.stopTakingPart(DIVERGED_MESSAGE);
    }

    /// What this shard is doing, from the fields that decide it, so no
    /// path that changes one of them has to remember to publish.
    pub const COLD_READ_REFUSAL = "unavailable: this node restarted and is catching up with its group's leader; retry, or read from another node";
    pub const LEADER_NOT_READY_REFUSAL = "unavailable: the leader is still applying what earlier leaders committed; retry";

    /// Refuses `req`, a read of this shard's state, while that state is behind
    /// what its group committed: a cold boot's (`coldCaughtUp`), or a new
    /// leader's, which may not have applied what earlier terms committed. A
    /// write acknowledged by the old leader would read as missing.
    fn refusedRead(self: *Shard, conn: *Connection, req: proto.Request) bool {
        const message = if (!self.coldCaughtUp())
            COLD_READ_REFUSAL
        else if (self.leaderApplying())
            LEADER_NOT_READY_REFUSAL
        else
            return false;
        self.sendRefusal(conn, req.header.request_id, .unavailable, .{ .reason = .leader_unknown, .ran = .no, .message = message });
        return true;
    }

    /// This node leads and hasn't applied what earlier terms committed. A
    /// halted leader won't until a repair resumes it, and answers marked stale
    /// instead.
    fn leaderApplying(self: *const Shard) bool {
        const raft = self.raft_node;
        return raft.role == .leader and self.halted == null and !raft.leaderReady();
    }

    /// Whether a cold boot's projections hold what the group committed: a
    /// leader's append verified this node's log through that leader's
    /// commit and the apply has caught up, or this node leads and has
    /// applied its own log. Until then it serves no local reads and is not
    /// ready. Once per boot: a node that falls behind later serves as
    /// before, as a sync follower briefly behind always has, so a chunked
    /// apply under load doesn't turn into refused reads.
    fn coldCaughtUp(self: *Shard) bool {
        if (!self.cold_gate) return true;
        const raft = self.raft_node;
        const caught_up = raft.leaderReady() or (raft.role != .leader and raft.reached_leader_commit and raft.last_applied >= raft.commit_index);
        if (!caught_up) return false;
        self.cold_gate = false;
        log.info("shard {d}: caught up with the group after an async-durability boot (applied through {d}); serving reads", .{ self.id, raft.last_applied });
        return true;
    }

    const ReadBlockOutcome = enum { hold, damaged };

    /// Record that a committed read (entry `index`) is blocked right now, pace
    /// the retry, and surface it. Shared by the apply loop and the two
    /// skip-scan reads so all three back off and show a block the same way.
    /// `.damaged` means a disk-class block lasted past its grace and the node
    /// is now offline or diverged; `.hold` means keep the entry unapplied and
    /// try again after the back-off.
    /// What a read block is put down to, in its reports.
    fn blockCause(self: *const Shard) []const u8 {
        if (self.read_block_permission) return "permission denied on a segment; fix the file's permissions";
        return if (self.read_block_disk_failing) "the disk may be failing" else "a resource shortage";
    }

    fn noteReadBlock(self: *Shard, disk_failing: bool, permission: bool, index: u64) ReadBlockOutcome {
        const raft = self.raft_node;
        const now = nowMs();
        if (!self.read_blocked) {
            self.read_blocked = true;
            self.read_blocked_since_ms = now;
            if (self.shard_metrics) |sm| sm.recordReadBlockStart();
        }
        self.read_block_disk_failing = disk_failing;
        self.read_block_permission = permission;
        // The disk's grace is counted from when the cause first looks like the
        // disk: set the deadline on that change and leave it, and clear it when
        // the cause is a resource shortage, so a resource wait never shortens
        // the disk's grace (the countdown restarts at the change).
        if (disk_failing) {
            if (self.read_block_disk_deadline_ms == null) self.read_block_disk_deadline_ms = now + DISK_FAILING_MS;
        } else {
            self.read_block_disk_deadline_ms = null;
        }
        const blocked_for = now -| self.read_blocked_since_ms;
        // A disk-class block held past its grace is treated as damage: the node
        // diverges and is replaced, rather than wait on a disk that is not
        // coming back. A resource shortage holds indefinitely.
        if (self.read_block_disk_deadline_ms) |deadline| if (now >= deadline) {
            self.damaged(silent_loss.Damage.init(.unreadable_committed, "committed entry {d} could not be read for {d} ms; {s}", .{ index, blocked_for, self.blockCause() }));
            return .damaged;
        };
        // A leader that cannot apply freezes the group: tell Raft, which steps
        // it down past an election timeout.
        raft.setReadBlocked(self.read_blocked_since_ms, disk_failing);
        if (self.read_block_log_ms == null or now -| self.read_block_log_ms.? >= READ_BLOCK_LOG_MS) {
            self.read_block_log_ms = now;
            log.err("shard {d}: a committed entry has not been readable to apply for {d} ms ({s}); applied {d} of {d}, holding and retrying", .{ self.id, blocked_for, self.blockCause(), raft.last_applied, raft.commit_index });
        }
        self.read_retry_at_ms = now + READ_RETRY_MS;
        return .hold;
    }

    /// The block is over — a committed entry read again, or the node damaged
    /// and no longer waiting. Account the time, drop the gauge, and let the
    /// node lead and campaign once more. Safe to call when not blocked.
    fn clearReadBlocked(self: *Shard) void {
        if (!self.read_blocked) return;
        if (self.shard_metrics) |sm| sm.recordReadBlockEnd(nowMs() -| self.read_blocked_since_ms);
        self.read_blocked = false;
        self.read_block_disk_failing = false;
        self.read_block_permission = false;
        self.read_block_disk_deadline_ms = null;
        self.read_retry_at_ms = 0;
        self.read_block_log_ms = null;
        self.raft_node.clearReadBlocked();
    }

    fn healthState(self: *const Shard) health_mod.ShardState {
        if (self.removed_at_ms != null) return .removed;
        if (self.replica.diverged) return .diverged;
        if (self.offline != null) return .offline;
        if (self.halted != null) return .halted;
        const raft = self.raft_node;
        if (raft.writes_stopped) return .cannot_flush;
        // A node no config names is joining. It is guarded too, since an
        // empty log could be a lost one, but it holds nothing a group
        // counts on yet, and joining says what it waits for.
        if (self.raft_network != null and !raft.self_named) return .joining;
        if (raft.lost_log != .none) return .guarded;
        if (self.cold_gate) return .catching_up;
        if (self.raft_network != null) {
            if (raft.latest_config.find(raft.id)) |m| {
                if (!m.voter and !m.caught_up) return .catching_up;
            }
        }
        // After the catching-up states: a node still catching up shows that and
        // stays 503, rather than flipping to this and answering 200 while it
        // refuses reads. On a lone node a blocked read still serves (stale), and
        // `readiness` keeps it ready; in a cluster another node can serve, so it
        // is not ready.
        if (self.read_blocked) return .read_blocked;
        return .ok;
    }

    /// Publish every namespace's counts once any changed, for /metrics and
    /// the dashboard: they read them from another thread, never the store.
    /// A namespace whose metrics can't be registered is tried again next
    /// time.
    fn publishLiveKeys(self: *Shard) void {
        const kv = self.kv_handler.kv;
        if (!kv.countsChanged()) return;
        const registry = self.metrics_registry orelse return;
        var all = true;
        var it = kv.namespaces();
        while (it.next()) |n| {
            // Looked up once: a namespace's metrics never move.
            const km: *KVMetrics = if (kv.publish_to.get(n.ns)) |p| @ptrCast(@alignCast(p)) else blk: {
                const name = self.metricsNamespace(n.ns) orelse {
                    all = false;
                    continue;
                };
                const km = registry.registerKVNamespace(name) catch {
                    all = false;
                    continue;
                };
                kv.publish_to.put(self.allocator, n.ns, km) catch {};
                break :blk km;
            };
            km.publishCounts(self.id, n.counts.live, n.counts.bytes, n.counts.history_bytes, n.counts.history_evicted);
        }
        if (all) kv.markPublished();
    }

    /// Publish this shard's state and losses. The runtime calls it once
    /// before the client port opens, so the first answers are already right.
    pub fn publishHealth(self: *Shard) void {
        self.publishLiveKeys();
        self.duties.summarize(self.id, nowMs());
        if (self.shard_metrics) |sm| {
            sm.setSilentLoss(self.losses.counts, self.losses.duplicate_index, self.offline != null);
            sm.processing_failed_jobs.store(self.processing_handler.failed_jobs, .monotonic);
            sm.processing_held_jobs.store(self.processing_handler.held_jobs, .monotonic);
            sm.duties_held.store(self.duties.held(), .monotonic);
            sm.duty_oldest_held_ms.store(self.duties.oldestMs(nowMs()), .monotonic);
            sm.setVouch(self.replica.strangers_dropped, self.replica.vouch_asks, self.replica.vouches_taken, self.replica.vouchedIndex());
            sm.setReadBlocked(self.read_blocked);
            sm.persist_failures.store(self.persist_failures, .monotonic);
            sm.snapshot_skipped_leader_not_ready.store(self.snapshot_skips_leader_not_ready, .monotonic);
            sm.kv_sink_retry_pending.store(self.kv_sink_retries.items.len, .monotonic);
            sm.kv_sink_retry_overflow.store(self.kv_sink_retry_overflow, .monotonic);
            sm.bar_last.store(self.defaultPartition().last_bar, .monotonic);
            sm.bar_bytes.store(self.defaultPartition().bar_bytes, .monotonic);
            // A duration, not the monotonic start: a raw clock reading means
            // nothing to a reader and Prometheus can't subtract it.
            sm.flushes_failing_for_ms.store(if (self.flushes_failing_since_ms == 0) 0 else nowMs() -| self.flushes_failing_since_ms, .monotonic);
            if (self.hard_state_store) |hs| {
                sm.hardstate_failures.store(hs.hardstate_failures, .monotonic);
                sm.hardstate_failing_for_ms.store(if (hs.hardstate_failing_since_ms == 0) 0 else nowMs() -| hs.hardstate_failing_since_ms, .monotonic);
            }
            if (self.durable_log) |dl| {
                sm.buffer_failures.store(dl.writer.buffer_failures, .monotonic);
                sm.buffer_failing_for_ms.store(if (dl.writer.buffer_failing_since_ms == 0) 0 else nowMs() -| dl.writer.buffer_failing_since_ms, .monotonic);
            }
        }
        const slot = self.health orelse return;
        slot.publishVouch(self.replica.vouchedIndex(), self.replica.strangersWhileQuiet(nowMs()));
        // The reason before the state: a reader that sees offline, halted
        // or diverged finds it.
        // The reason is the state's: a shard halted, then diverged, says why
        // it diverged.
        if (self.halted) |*h| {
            slot.halt_index.store(h.index, .monotonic);
            slot.halt_term.store(h.term, .monotonic);
            slot.halt_crc.store(h.crc, .monotonic);
        }
        const raft = self.raft_node;
        // In `healthState`'s own order, strongest first, so a block that then
        // damages the node shows the damage, not the stale block — and
        // `damaged` clears the block anyway.
        if (self.diverged_damage) |*damage| {
            slot.setReason(damage.reason());
        } else if (self.replica.divergedReason()) |why| {
            slot.setReason(why);
        } else if (self.offline) |*damage| {
            slot.setReason(damage.reason());
        } else if (self.halted) |*h| {
            // Room for both; the slot keeps what fits.
            var buf: [2 * health_mod.REASON_MAX]u8 = undefined;
            // The note first: a long halt reason is cut short, the way out isn't.
            slot.setReason(if (self.replica.haltAppliedElsewhere()) |e| blk: {
                const note = if (e.builds_known)
                    "the leader's build applies this entry: upgrade this node"
                else
                    "the leader applied this entry; a build with no version can't be told apart: on the same build this node halted alone (wipe and rejoin), on another upgrade it";
                break :blk std.fmt.bufPrint(&buf, "{s}; {s}", .{ note, h.reason() }) catch note;
            } else h.reason());
        } else if (self.read_blocked) {
            slot.read_blocked_for_ms.store(nowMs() -| self.read_blocked_since_ms, .monotonic);
            var buf: [health_mod.REASON_MAX]u8 = undefined;
            slot.setReason(std.fmt.bufPrint(&buf, "a committed entry has not been readable to apply ({s}); applied {d} of {d}", .{
                self.blockCause(),
                raft.last_applied,
                raft.commit_index,
            }) catch "a committed entry could not be read to apply");
        }
        // A lone blocked shard keeps the node ready; a cluster one is a 503.
        slot.read_blocked_serves.store(self.read_blocked and self.raft_network == null, .release);
        slot.persist_failures.store(self.persist_failures, .monotonic);
        slot.snapshot_skipped_leader_not_ready.store(self.snapshot_skips_leader_not_ready, .monotonic);
        const part = self.defaultPartition();
        slot.bar_last.store(part.last_bar, .monotonic);
        slot.bar_bytes.store(part.bar_bytes, .monotonic);
        slot.bar_threshold.store(part.barThreshold(), .monotonic);
        const window = self.snapshot_window;
        slot.snapshot_bar.store(if (window) |w| w.s else 0, .monotonic);
        slot.snapshot_suspended_for_ms.store(if (window) |w| nowMs() -| w.opened_ms else 0, .monotonic);
        slot.flushes_failing_for_ms.store(if (self.flushes_failing_since_ms == 0) 0 else nowMs() -| self.flushes_failing_since_ms, .monotonic);
        if (self.hard_state_store) |hs| {
            slot.hardstate_failures.store(hs.hardstate_failures, .monotonic);
            slot.hardstate_failing_for_ms.store(if (hs.hardstate_failing_since_ms == 0) 0 else nowMs() -| hs.hardstate_failing_since_ms, .monotonic);
        }
        if (self.durable_log) |dl| {
            slot.buffer_failures.store(dl.writer.buffer_failures, .monotonic);
            slot.buffer_failing_for_ms.store(if (dl.writer.buffer_failing_since_ms == 0) 0 else nowMs() -| dl.writer.buffer_failing_since_ms, .monotonic);
        }
        slot.publish(self.healthState(), raft.role, raft.last_applied, raft.commit_index);
    }

    /// A shard on this node that is offline, if any.
    fn offlineShard(self: *const Shard) ?*const Shard {
        const shards = self.peer_shards orelse return if (self.offline != null) self else null;
        for (shards) |s| if (s.offline_published.load(.acquire)) return s;
        return null;
    }

    /// What an offline shard answers every request with.
    fn offlineMessage(self: *const Shard, buf: []u8) []const u8 {
        const damage = &(self.offline orelse return "unavailable: shard is offline on this node");
        const what = if (damage.out_of_memory) "its log is intact: restart the node once memory is free" else "the data directory needs repair";
        return std.fmt.bufPrint(buf, "unavailable: shard {d} is offline on this node: {s}; {s}", .{ self.id, damage.reason(), what }) catch "unavailable: shard is offline on this node";
    }

    /// Lead nothing, and answer what was in flight with `message`.
    fn stopTakingPart(self: *Shard, message: []const u8) void {
        // A diverged member is rarely the leader (only one that broke
        // one-leader-per-term); a damaged lone node is. Either way it
        // leads nothing now.
        if (self.raft_node.role == .leader) {
            self.raft_node.role = .follower;
            self.raft_node.leader_id = 0;
        }
        self.stoppedLeading(message);
        // An answer already held is the leader's, and the write it
        // answers committed; the client gets it.
        for (self.forwards) |*f| {
            if (!f.active) continue;
            if (f.reply) |reply| {
                self.deliverDeferred(f.reply_to, reply);
                self.dropForward(f);
            } else {
                self.finishForward(f, .unavailable, .unclassified, message);
            }
        }
    }

    /// A node the log has never named asks to be added; so does one whose
    /// membership was appended but never committed and whose leader has
    /// gone quiet, since a new leader without that entry never speaks to
    /// it.
    fn joinWanted(self: *Shard, now: u64) bool {
        const raft = self.raft_node;
        if (!raft.self_named) return true;
        if (raft.role == .leader) return false;
        const quiet = now -| raft.last_leader_contact_ms > raft.config.election_timeout_max_ms;
        // A replica that no leader speaks to may have been dropped (a
        // joiner that never caught up is aged out without being told):
        // asking again is answered by a leader only when it is not a
        // member.
        if (!raft.timer_enabled and quiet) return true;
        // Its committed config, not commit: a cold boot commits configs
        // through its watermark, and its data waits for a leader.
        return raft.membership_index > @max(raft.commit_index, raft.committed_config_index) and quiet;
    }

    /// What a leader had in flight is no longer its to finish: parked
    /// writes are answered with `message`, runs it had not stepped stay at
    /// their start, and implicit creates may have been dropped with the
    /// log's tail.
    /// From now on a leader reads sealed segments for its peers on `bulk`,
    /// which must outlive this shard's thread.
    pub fn attachBulkIo(self: *Shard, bulk: *BulkIo) void {
        if (self.stream_disk) |d| {
            d.bulk = bulk;
            d.notify = .{ .ctx = self.mailbox, .done = streamDiskReadDone };
        }
        const cu = self.catch_up orelse return;
        cu.bulk = bulk;
        cu.notify = .{ .ctx = self.mailbox, .done = catchUpReadDone };
    }

    /// Stream payloads read from disk are back: the reads held on them are
    /// made again.
    fn streamDiskReadsBack(self: *Shard) void {
        // Damaged: the reads that were held have been answered with it.
        if (self.offline != null or self.replica.diverged) return;
        const d = self.stream_disk orelse return;
        if (!d.drain()) return;
        self.waiter_pool.notifyAny(.stream_disk_read, resolveStreamWaiter, @ptrCast(self));
        // A blocking read parked for new appends may have met one too.
        self.waiter_pool.notifyAny(.stream_read, resolveStreamWaiter, @ptrCast(self));
    }

    fn stoppedLeading(self: *Shard, message: []const u8) void {
        // A follower takes no step passes; its polls wait again.
        self.more_work = false;
        if (self.catch_up) |cu| cu.forget();
        self.workflow_handler.dropStartedRuns(self);
        self.namespace_handler.forgetImplicitCreates(self);
        self.actions_handler.stoppedLeading(self);
        self.queue_handler.stoppedLeading(self);
        group_handler.stoppedLeading(self);
        self.resolvePending(message);
        // Blocking reads that hand out work belong to the leader: a parked
        // dequeue woken here would take a message from this node's copy
        // while the new leader hands the same message to someone else, and
        // a group read or an await would retry here rather than there. Reads
        // that only look (kv watch, stream read) stay: a follower serves them.
        self.waiter_pool.expireKinds(&.{ .queue_dequeue, .stream_group_read, .action_await }, answerNotLeading, @ptrCast(self));
    }

    /// Ask every peer this node can reach, once a second, until a config
    /// entry naming it arrives from the leader; say so at intervals while
    /// it goes on, since the leader's refusal is logged only there.
    fn askToJoin(self: *Shard, now: u64) void {
        if (now -| self.join_asked_ms < JOIN_ASK_INTERVAL_MS) return;
        self.join_asked_ms = now;
        if (self.join_first_asked_ms == 0) {
            self.join_first_asked_ms = now;
            self.join_warned_ms = now;
        } else if (now -| self.join_warned_ms >= JOIN_WARN_INTERVAL_MS) {
            self.join_warned_ms = now;
            log.warn("shard {d}: still asking to join after {d} s; a leader adds a node it can reach when the group holds fewer than {d} members and no other change is in flight — check the seeds and the secret", .{ self.id, (now - self.join_first_asked_ms) / 1000, membership.MAX_MEMBERS });
        }
        const rn = self.raft_network orelse return;
        var ids: [@import("../raft/network.zig").MAX_PEERS]u32 = undefined;
        for (rn.linkedPeers(&ids)) |peer| self.replica.sendRaft(peer, .join_request, "");
    }

    /// A proven peer wants in. The leader appends the config that names it
    /// as a replica: it votes only once it has caught up and the leader
    /// promotes it. Under the shared secret every joiner already holds the
    /// cluster's keys, so each may be promoted on its own (`may_vote`).
    fn handleJoinRequest(self: *Shard, from: u32) void {
        const raft = self.raft_node;
        if (raft.committed_config.removedAt(from)) |when| return self.sendRemovedNotice(from, when);
        if (raft.role != .leader) return;
        if (raft.latest_config.names(from)) return;
        if (raft.latest_config.member_count >= membership.MAX_MEMBERS) {
            const now = nowMs();
            if (now -| self.join_refused_warn_ms >= JOIN_WARN_INTERVAL_MS) {
                self.join_refused_warn_ms = now;
                log.warn("shard {d}: node {d} asked to join but the group already has {d} members, the most it can hold", .{ self.id, from, raft.latest_config.member_count });
            }
            return;
        }
        const next = raft.latest_config.withJoiner(from, true);
        if (self.proposeMembership(&next, "adding node")) {
            log.info("shard {d}: adding node {d} as a replica", .{ self.id, from });
        }
    }

    /// Propose a membership change, saying why one could not be made. True
    /// when proposed.
    fn proposeMembership(self: *Shard, next: *const membership.Config, what: []const u8) bool {
        const raft = self.raft_node;
        const outcome = raft.proposeConfig(next) catch |err| {
            log.err("shard {d}: could not propose {s}: {s}", .{ self.id, what, @errorName(err) });
            return false;
        };
        switch (outcome) {
            .proposed => {
                self.replica.pump(nowMs());
                return true;
            },
            // The leadership noop commits within a round trip.
            .no_own_commit => return false,
            .in_flight => {
                const now = nowMs();
                if (now -| self.join_refused_warn_ms >= JOIN_WARN_INTERVAL_MS) {
                    self.join_refused_warn_ms = now;
                    var waiting: [raft_node_mod.MAX_PEERS]u32 = undefined;
                    log.warn("shard {d}: {s} waits: an earlier membership change has not committed{s}{any}", .{ self.id, what, if (self.changeWaitsOn(&waiting).len > 0) "; waiting on " else "", self.changeWaitsOn(&waiting) });
                }
                return false;
            },
            .refused => |why| {
                log.warn("shard {d}: {s} refused: {s}", .{ self.id, what, why.message() });
                return false;
            },
        }
    }

    /// The voters that have not acked the change in flight.
    fn changeWaitsOn(self: *Shard, out: *[raft_node_mod.MAX_PEERS]u32) []u32 {
        const raft = self.raft_node;
        var n: usize = 0;
        for (raft.peers[0..raft.peer_count], raft.peer_ids[0..raft.peer_count]) |p, id| {
            if (p.voter and p.match_index < raft.membership_index) {
                out[n] = id;
                n += 1;
            }
        }
        return out[0..n];
    }

    /// The changes a leader makes on its own: promote caught-up replicas,
    /// age out joiners that never caught up (`membership.nextAutomatic`).
    fn adjustMembership(self: *Shard, now: u64) void {
        const raft = self.raft_node;
        if (raft.membership_index > raft.commit_index) return;
        var progress: [raft_node_mod.MAX_PEERS]membership.Progress = undefined;
        const p = raft.memberProgress(&progress);
        if (p.len == 0) return;
        const next = membership.nextAutomatic(&raft.latest_config, p, now, raft.voterCountBefore()) orelse return;
        const before = raft.latest_config;
        if (!self.proposeMembership(&next, "an automatic membership change")) return;
        for (before.memberSlice()) |m| {
            const after = next.find(m.id) orelse {
                log.warn("shard {d}: node {d} never caught up within {d} min of joining; removed (it may ask to join again)", .{ self.id, m.id, membership.JOIN_AGE_LIMIT_MS / 60_000 });
                continue;
            };
            if (after.voter and !m.voter) log.info("shard {d}: node {d} caught up; now a voter ({d} voters)", .{ self.id, m.id, next.voterCount() });
            if (!after.voter and after.caught_up and !m.caught_up) log.info("shard {d}: node {d} caught up; a replica{s}", .{ self.id, m.id, if (after.may_vote) " (promoted when that leaves an odd number of voters)" else " until promoted: flo cluster promote" });
        }
    }

    // ─── The one applier ─────────────────────────────────────────────────

    /// Apply one committed entry and tell its waiters. A leader, a follower
    /// and boot replay all run the same core (`applyEntryCore`), so the three
    /// can never disagree about what an entry means; only the live paths
    /// notify. False, counted and logged, when the projections are missing
    /// it; its client, if any, is told the write committed but did not apply.
    pub fn applyEntry(self: *Shard, entry: *const entry_mod.Entry, out: *persistence_mod.Result) bool {
        return self.applyOne(entry, out) == .applied;
    }

    /// Apply one committed entry and, when it applied, tell its waiters.
    fn applyOne(self: *Shard, entry: *const entry_mod.Entry, out: *persistence_mod.Result) Verdict {
        if (self.marker.crashedOn(entry)) return .{ .halt = CRASHED };
        // Only a step every replica repeats names the entry; `afterApply`
        // scopes its own.
        const verdict = v: {
            const prev = apply_marker.begin(&self.marker, entry);
            defer apply_marker.end(prev);
            break :v verdictOf(&self.losses, self.id, nowMs(), entry, applyEntryCore(self.defaultPartition(), &self.replay_registry, entry, out));
        };
        if (verdict == .applied) self.afterApply(entry, out);
        return verdict;
    }

    /// Apply every committed entry not yet applied. Only the shard's own
    /// loop calls this: at boot, on a Raft frame, on an election won alone,
    /// after each client request (its own client's or one forwarded from
    /// another shard), and in the tick; `park` applies up to its own entry through
    /// `applyThrough`. Module code never does: applying in the middle of its own
    /// work would run other writers' appliers and answers under its
    /// locks and over its pointers into the maps they change. False when an
    /// entry could not be applied.
    ///
    /// A waiter woken by an apply may propose in turn (a dequeue acks the
    /// message it took); that entry lands in the log and this loop reaches
    /// it on its next pass. A nested drain would copy the next entry over
    /// `apply_buf` while the notification is still reading the entry in
    /// hand, so the inner call is a no-op. That no-op returns true, which
    /// means "nothing failed", not "applied": a notification must not read
    /// projection state for an entry it proposed.
    ///
    /// A tick's calls together apply up to `APPLY_PASS_NS` of `applyCost`,
    /// its first at least one entry; a call outside a tick, up to that much. A backlog (a cold boot's whole log, a
    /// follower far behind) drains over several ticks, so the shard still
    /// answers heartbeats and requests between them.
    pub fn applyCommitted(self: *Shard) bool {
        return self.applyThrough(std.math.maxInt(u64));
    }

    /// Whether the entry just applied is a bar, and if so how long a test
    /// window holds (0 for none). Bars proper come with snapshots.
    fn barAt(self: *Shard, e: *const entry_mod.Entry) ?u64 {
        if (self.test_bar != 0 and e.header.index == self.test_bar) return 0;
        if (comptime BARS_OPEN_WINDOWS) {
            if (self.defaultPartition().last_bar == e.header.index) return 0;
        }
        if (comptime build_options.test_faults) {
            if (@import("test_faults.zig").of(e) == .snapshot_window) return TEST_FAULT_WINDOW_MS;
        }
        return null;
    }

    /// At bar `s`, just applied: suspend apply while the state at it is
    /// serialized, unless this node leads and hasn't applied what earlier
    /// terms committed. Such a leader passes the bar with no snapshot: holding
    /// apply here could keep it from ever getting ready, and its followers
    /// take theirs. It snapshots again at the next bar, not later at this one.
    /// Returns whether apply is now suspended.
    fn openSnapshotWindow(self: *Shard, s: u64, hold_ms: u64) bool {
        if (self.leaderApplying()) {
            self.snapshot_skips_leader_not_ready += 1;
            log.warn("shard {d}: passed snapshot bar {d} without a snapshot: this leader is still applying what earlier terms committed ({d} so far); its next snapshot is at the next bar", .{ self.id, s, self.snapshot_skips_leader_not_ready });
            return false;
        }
        const now = nowMs();
        self.snapshot_window = .{ .s = s, .opened_ms = now, .slices_left = TEST_BAR_SLICES, .hold_until_ms = if (hold_ms > 0) now + hold_ms else 0 };
        return true;
    }

    /// One tick of an open window: queue a slice, or, with none left, end it
    /// and apply what committed meanwhile. A shard that stopped applying
    /// (halted, offline, diverged) drops the window and its snapshot; its
    /// own state holds apply from there.
    fn stepSnapshotWindow(self: *Shard) void {
        const w = &(self.snapshot_window orelse return);
        if (self.halted != null or self.offline != null or self.replica.diverged) {
            log.warn("shard {d}: dropped the snapshot at bar {d}: the shard stopped applying", .{ self.id, w.s });
            self.snapshot_window = null;
            return;
        }
        // An async-durability rewind cut what it had applied below the bar:
        // the state at the bar is gone, and isn't what the group committed.
        if (self.raft_node.last_applied < w.s) {
            log.warn("shard {d}: dropped the snapshot at bar {d}: the log was cut below it", .{ self.id, w.s });
            self.snapshot_window = null;
            return;
        }
        // Elected while suspended, whether it led before or not: a leader not
        // yet ready passes the bar, as one that reached it so would have, and
        // applies on, or it would refuse writes for the rest of the window.
        if (self.leaderApplying()) {
            self.snapshot_skips_leader_not_ready += 1;
            log.warn("shard {d}: dropped the snapshot at bar {d}: this node was elected leader while suspended; its next snapshot is at the next bar", .{ self.id, w.s });
            self.snapshot_window = null;
            _ = self.applyCommitted();
            return;
        }
        if (w.slices_left > 0) {
            w.slices_left -= 1;
            return;
        }
        if (nowMs() < w.hold_until_ms) return;
        self.snapshot_window = null;
        _ = self.applyCommitted();
    }

    /// How long to wait between re-attempting a blocked read, so a block
    /// costs one disk probe a fraction of a second, not one per request.
    const READ_RETRY_MS: u64 = 250;
    /// How often to say a read is still blocked.
    const READ_BLOCK_LOG_MS: u64 = 30_000;
    /// A read blocked for a reason that may be the disk failing — an IO error,
    /// or an unmapped errno that may be one — becomes damage once it has lasted
    /// this long, rather than holding forever: the node then diverges and is
    /// replaced. A resource shortage never does.
    const DISK_FAILING_MS: u64 = 5 * 60 * 1000;

    /// The apply budget of one tick, in `applyCost` units.
    const APPLY_PASS_NS: u64 = std.time.ns_per_ms;
    const ENTRY_COST_NS: u64 = 1_400;
    const OP_COST_NS: u64 = 2_500;

    /// What applying `e` charges a pass: a stand-in for its time, never the
    /// clock, so a pass ends at the same entry on every host and every
    /// replay. Calibrated from bench_write_path's backlog (on
    /// Apple M-series): an entry of one op about 1.4 µs, each further op of
    /// a transaction about 2.5 µs, and about 0.15 ns a byte. A pass can
    /// overrun by its last entry, at most a full transaction.
    fn applyCost(e: *const entry_mod.Entry) u64 {
        const op_count: u64 = if (e.header.entry_type == @backingInt(entry_mod.EntryType.kv_batch)) kv_entries.batchOpCount(e.payload) else 1;
        return ENTRY_COST_NS + (op_count -| 1) * OP_COST_NS + e.payload.len * 3 / 20;
    }

    /// `applyCommitted`, stopping after index `limit`.
    fn applyThrough(self: *Shard, limit: u64) bool {
        // An offline shard's projections are missing an entry: nothing
        // after it may apply over the hole. A diverged member's state is
        // history the group disagrees with; applying the leader's entries
        // over it (after an async-flush rewind, say) would make it neither
        // its own history nor the group's, so it stays as it was.
        if (self.applying or self.offline != null or self.replica.diverged) return true;
        // With sync durability a leader's writes commit only once on disk:
        // flushing first lets what that commits apply now. Before any return
        // below: a halted leader's own repair skip, or a write while a read
        // is blocked, still has to reach disk to commit, and this is the
        // tick's one flush.
        self.syncFlushIfNeeded();
        // Blocked on a read and still inside the back-off: don't probe the disk
        // again this call. apply runs after every request, so re-attempting
        // here would mean one disk read per request and one log line per retry.
        if (self.read_blocked and nowMs() < self.read_retry_at_ms) return false;
        // A repair skip whose check an earlier blocked read held: re-run it
        // before anything past the skip applies, so the check is never dropped.
        if (self.skip_check_pending != 0 and !self.runPendingSkipCheck()) return false;
        // Halted: nothing past the entry applies until a committed repair
        // skips it, but writes committed after it are told so as their
        // entries commit.
        if (self.halted != null and !self.resumePastSkip()) {
            self.answerHaltedPending();
            return false;
        }
        // Suspended at a bar: after the flush, so a sync leader still makes
        // its writes durable and commits them; they apply on resume. Replies
        // held for entries at or below the bar go now.
        if (self.snapshot_window != null) {
            if (self.replies_held > 0) self.releaseReplies();
            return true;
        }
        // Called after every request: nothing to apply is the common case.
        if (self.raft_node.last_applied >= @min(self.raft_node.commit_index, limit) and self.replies_held == 0) {
            self.apply_behind = false;
            return true;
        }
        self.applying = true;
        defer self.applying = false;

        const raft = self.raft_node;
        var all_applied = true;
        var spent = if (self.in_tick) self.apply_tick_spent else 0;
        defer self.apply_tick_spent = spent;
        self.apply_behind = false;
        drain: while (true) {
            while (raft.last_applied < @min(raft.commit_index, limit)) {
                if (spent >= APPLY_PASS_NS) {
                    self.apply_behind = true;
                    break :drain;
                }
                const next_idx = raft.last_applied + 1;
                // Advanced before the apply: whatever a notification does, this
                // entry is never taken twice, and the loop cannot stall.
                raft.last_applied = next_idx;
                switch (raft.log.readForApply(next_idx, self.apply_buf)) {
                    .blocked => |b| {
                        // The entry's segment could not be read right now (a
                        // resource or IO failure), which is not a hole. Hold it
                        // unapplied and retry — paced by `read_retry_at_ms`, not
                        // per call, and without `apply_behind`, so the reactor
                        // keeps its poll wait and does not spin. `noteReadBlock`
                        // may instead damage the node (a disk failing too long).
                        raft.last_applied = next_idx - 1;
                        all_applied = false;
                        _ = self.noteReadBlock(b.disk_failing, b.permission, next_idx);
                        break :drain;
                    },
                    .found => |e| {
                        if (self.read_blocked) {
                            self.clearReadBlocked();
                            log.info("shard {d}: committed entries are readable again; applying from {d}", .{ self.id, next_idx });
                        }
                        spent += applyCost(&e);
                        if (skippedHere(&self.skips, &e)) {
                            self.last_entry_applied = false;
                            self.last_result.reset(&e);
                            self.defaultPartition().passOverSkipped(&e) catch |err| {
                                self.answerPending(next_idx, e.header.term, false, &self.last_result);
                                self.damaged(localDamage(err, silent_loss.Damage.init(.partition_reject, "entry {d}, which a repair skips, could not be passed over on this node: {s}", .{ next_idx, @errorName(err) })));
                                all_applied = false;
                                break :drain;
                            };
                            // Its client is told it didn't run; the shard is
                            // as the repair wants it.
                            self.answerPending(next_idx, e.header.term, false, &self.last_result);
                            self.queue_handler.skipped(self, &e);
                            group_handler.skipped(self, &e);
                            continue;
                        }
                        // The leader stamps each entry after the one before it,
                        // so an entry that isn't is a bug every replica sees. A
                        // skip never halts.
                        if (raft.applied_stamp != 0 and e.header.timestamp_ns <= raft.applied_stamp and !isSkip(&e)) {
                            self.halt(&e, "its stamp {d} is not after the last applied entry's, {d} (a Flo bug)", .{ e.header.timestamp_ns, raft.applied_stamp });
                            all_applied = false;
                            break :drain;
                        }
                        self.last_result.reset(&e);
                        const verdict = self.applyOne(&e, &self.last_result);
                        switch (verdict) {
                            .applied, .duplicate => {},
                            .halt => |why| {
                                self.halt(&e, "{s} (a Flo bug)", .{why});
                                all_applied = false;
                                break :drain;
                            },
                            .local => |damage| {
                                self.last_entry_applied = false;
                                self.answerPending(next_idx, e.header.term, false, &self.last_result);
                                self.damaged(damage);
                                all_applied = false;
                                break :drain;
                            },
                        }
                        raft.noteApplied(e.header.timestamp_ns);
                        const applied = verdict == .applied;
                        // A bug in an applier, never a valid request's doing:
                        // every answer is sized for the longest key.
                        if (self.last_result.overflowed) log.err("shard {d}: entry {d}'s answer didn't fit its result; its client is told the answer was lost", .{ self.id, next_idx });
                        if (!applied) all_applied = false;
                        self.last_entry_applied = applied;
                        self.answerPending(next_idx, e.header.term, applied, &self.last_result);
                        // Last: it reads the entry it names into the same buffer.
                        if (isSkip(&e)) {
                            if (!self.checkSkip(&e)) {
                                all_applied = false;
                                break :drain;
                            }
                            self.seal_skip = true;
                        }
                        if (self.barAt(&e)) |hold_ms| {
                            if (self.openSnapshotWindow(next_idx, hold_ms)) break :drain;
                        }
                    },
                    .absent => {
                        self.last_entry_applied = false;
                        self.last_result.index = next_idx;
                        self.answerPending(next_idx, 0, false, &self.last_result);
                        // A committed index is always within the log, in the
                        // ring or below it in the durable log, and the buffer
                        // fits every entry; one that isn't there is a bug or a
                        // damaged segment (a blocked read is handled above),
                        // and nothing after it may apply over the hole.
                        self.damaged(silent_loss.Damage.init(.unreadable_committed, "committed entry {d} could not be read back to apply", .{next_idx}));
                        all_applied = false;
                        break :drain;
                    },
                }
            }
            // Applying can propose (a workflow's next step); flushing that
            // can commit it, so apply again until a flush commits nothing new.
            self.syncFlushIfNeeded();
            if (raft.last_applied >= @min(raft.commit_index, limit)) break;
        }
        if (self.seal_skip) {
            self.seal_skip = false;
            self.flushSegmentToDisk() catch |err| {
                self.noteFlushFailed();
                log.warn("shard {d}: could not seal the segment holding a repair skip: {s}; it seals with the next flush", .{ self.id, @errorName(err) });
            };
        }
        if (self.wake_workers) {
            self.wake_workers = false;
            ActionsHandler.wakeWorkers(self);
        }
        if (self.replies_held > 0) self.releaseReplies();
        return all_applied;
    }

    /// The namespace to meter an applied entry under, from the id it
    /// carries; one this shard has never registered is not metered rather
    /// than mislabelled.
    fn metricsNamespace(self: *Shard, ns: ns_table.Id) ?[]const u8 {
        return self.namespace_handler.nameOf(ns);
    }

    /// What follows an entry's apply on the live paths, from the entry and
    /// its result alone. Replay skips it, but boot's apply of the entries
    /// above the replay watermark takes it.
    ///
    /// Triggers and metrics come from the entry on every replica, so a
    /// crash in them recurs and names the entry. The rest depends on this
    /// node: the reads waiting here, and the leader's own steps for its
    /// term (its workers, a started run's first step). A crash there
    /// doesn't recur at boot, where nothing waits and nothing leads yet, so
    /// it names nothing. A run started before the restart stays at its
    /// start, as it does when leadership moves (`dropStartedRuns`).
    fn afterApply(self: *Shard, entry: *const entry_mod.Entry, result: *const persistence_mod.Result) void {
        {
            const prev = apply_marker.begin(&self.marker, entry);
            defer apply_marker.end(prev);
            if (comptime build_options.test_faults) {
                const fault = @import("test_faults.zig").of(entry);
                if (fault == .panic_after_apply) @panic("test fault: panic after apply");
                if (fault == .seal_each_flush) if (self.durable_log) |dl| {
                    dl.max_segment_bytes = 1;
                };
            }
            self.recordApplied(entry, result);
        }
        self.wakeApplied(entry);
        // The leader's own action steps: the await a deliver answers,
        // workers woken for a run ready again (once a pass: each wake is a
        // message to every other shard), a workflow told its run ended.
        self.actions_handler.afterApply(self, entry, result);
        // A dequeue its deliver answers, dequeues woken for messages ready.
        self.queue_handler.afterApply(self, entry, result);
        group_handler.afterApply(self, entry, result);
        if (comptime build_options.test_faults) {
            const leads = self.raft_node.role == .leader and entry.header.term == self.raft_node.current_term;
            if (leads and @import("test_faults.zig").of(entry) == .panic_leader_step) @panic("test fault: panic in the leader's step after apply");
        }
        self.workflow_handler.startApplied(self, entry, result);
    }

    /// Triggers and per-namespace metrics for an entry that just applied:
    /// from the entry alone, so every replica that applies it does the same.
    fn recordApplied(self: *Shard, entry: *const entry_mod.Entry, result: *const persistence_mod.Result) void {
        const etype: entry_mod.EntryType = @fromBackingInt(@intCast(entry.header.entry_type));
        switch (etype) {
            .kv_put, .kv_delete, .kv_incr, .kv_expire, .kv_json_patch => {
                // Every single-key KV entry starts with its key.
                var diag: schema.Diagnostic = .{};
                var r: schema.Reader = .{ .bytes = entry.payload, .diag = &diag };
                const key = kv_state.Key.ofStored(kv_entries.Key.decode(&r, "key") catch return) orelse return;
                if (self.metrics_registry) |mr| {
                    const ns = self.metricsNamespace(key.ns) orelse return;
                    if (mr.registerKVNamespace(ns)) |km| switch (etype) {
                        .kv_put => if (result.refused() == null) km.recordSet(),
                        // A delete of nothing is answered and changes nothing.
                        .kv_delete => if (result.refused() == null) {
                            var answer = result.reader();
                            if (answer.int(u8) == 1) km.recordDelete();
                        },
                        // A whole document deleted is a delete; any other
                        // change, a set. A refused patch changed nothing.
                        .kv_json_patch => if (result.refused() != null) {} else if (kv_entries.JsonPatch.decodeAll(entry.payload, &diag)) |p| {
                            if (p.document == null and std.mem.eql(u8, p.path, "$")) km.recordDelete() else km.recordSet();
                        } else |_| {},
                        else => {},
                    } else |_| {}
                }
            },
            .stream_append => {
                const cmd = entry_mod.CommandPayload.deserialize(entry.payload) orelse return;
                if (cmd.key.len == 0) return;
                self.notifyStreamTriggers();
                if (self.metrics_registry) |mr| {
                    const ns = self.metricsNamespace(cmd.namespace_id) orelse return;
                    const av = stream_mod.decodeAppendValue(cmd.value);
                    if (mr.registerStream(ns, cmd.key, 0)) |sm| {
                        sm.recordAppend(stream_mod.batchRecordCount(av.payload), av.payload.len);
                    } else |_| {}
                }
            },
            .stream_delete => {
                // The stream is gone on every node that applied this entry;
                // drop its series here, not in the leader-only handler. One
                // refused for what the stream held changed nothing.
                if (result.refused() != null) return;
                const cmd = entry_mod.CommandPayload.deserialize(entry.payload) orelse return;
                if (self.metrics_registry) |mr| {
                    const ns = self.metricsNamespace(cmd.namespace_id) orelse return;
                    mr.unregisterStream(ns, cmd.key, 0);
                }
            },
            .queue_enqueue => if (result.refused() == null) {
                var diag: schema.Diagnostic = .{};
                const p = @import("../protocol/queue_entries.zig").Enqueue.decodeAll(entry.payload, &diag) catch return;
                if (self.metrics_registry) |mr| {
                    const ns = self.metricsNamespace(.of(p.ns)) orelse return;
                    if (mr.registerQueue(ns, p.queue)) |qm| {
                        qm.recordEnqueue(1, p.payload.len);
                    } else |_| {}
                }
            },
            else => {},
        }
    }

    /// The reads waiting on an entry that just applied, and a leader's
    /// workers. Keyed from the entry itself, never from the request, so a
    /// follower's blocking read wakes on the same event a leader's does.
    fn wakeApplied(self: *Shard, entry: *const entry_mod.Entry) void {
        const etype: entry_mod.EntryType = @fromBackingInt(@intCast(entry.header.entry_type));
        switch (etype) {
            .kv_put, .kv_delete, .kv_incr, .kv_expire, .kv_json_patch => {
                var diag: schema.Diagnostic = .{};
                var r: schema.Reader = .{ .bytes = entry.payload, .diag = &diag };
                const key = kv_entries.Key.decode(&r, "key") catch return;
                self.waiter_pool.notify(.kv_get, key, resolveKVWaiter, @ptrCast(self));
            },
            .kv_batch => {
                var diag: schema.Diagnostic = .{};
                const batch = kv_entries.Batch.decodeAll(entry.payload, &diag) catch return;
                var it = batch.ops.iterator();
                var kb: [limits.MAX_KV_KEY]u8 = undefined;
                while (it.next() catch return) |op| {
                    // A waiter keeps the key as state does: the batch's
                    // namespace in front.
                    const key = kv_state.Key.init(&kb, .of(batch.ns), op.key);
                    self.waiter_pool.notify(.kv_get, key.stored, resolveKVWaiter, @ptrCast(self));
                }
            },
            .stream_append => {
                const cmd = entry_mod.CommandPayload.deserialize(entry.payload) orelse return;
                if (cmd.key.len == 0) return;
                self.waiter_pool.notify(.stream_read, cmd.key, resolveStreamWaiter, @ptrCast(self));
                group_handler.appended(self, stream_mod.streamKey(cmd.namespace_id, cmd.key));
            },
            else => {},
        }
    }

    // ─── Event loop ──────────────────────────────────────────────────────

    /// Answer the reads whose wait ran out. On a halted or diverged shard, or
    /// one blocked reading a committed entry, they read stale state, and say so.
    fn expireWaiters(self: *Shard) void {
        const was_stale = proto.answering_stale;
        proto.answering_stale = was_stale or self.halted != null or self.replica.diverged or self.read_blocked;
        defer proto.answering_stale = was_stale;
        self.waiter_pool.expireTimeouts(handleWaiterTimeout, @ptrCast(self));
    }

    /// Run one iteration of the event loop (for testing).
    pub fn tick(self: *Shard, timeout_ms: u32) !usize {
        self.apply_tick_spent = 0;
        self.in_tick = true;
        defer self.in_tick = false;
        // Lazily register acceptor pipe with reactor on first tick
        if (!self.pipe_registered) {
            try self.reactor.addSource(.{
                .fd = self.acceptor_pipe_rd,
                .tag = .acceptor_pipe,
                .interests = .{ .readable = true },
            });
            self.pipe_registered = true;
        }
        if (!self.raft_queue_registered) {
            if (self.raft_queue) |q| {
                try self.reactor.addSource(.{ .fd = q.wake_rd, .tag = .raft_read, .interests = .{ .readable = true } });
                self.raft_queue_registered = true;
            }
        }

        // Only a tick that may sleep announces it; only one that did has a
        // wake to take back and a pipe to empty.
        const may_sleep = timeout_ms > 0 and self.mailbox.prepareSleep();
        const events = self.reactor.poll(if (may_sleep) timeout_ms else 0) catch |err| {
            if (may_sleep) self.mailbox.wake.woke();
            return err;
        };
        if (may_sleep) self.mailbox.wake.woke();
        if (self.shard_metrics) |sm| sm.recordReactorLoop();

        // Process all I/O events
        for (events) |ev| {
            self.processEvent(ev);
        }

        // Drain inbox each tick
        _ = self.drainInbox();
        self.drainRaftQueue();
        self.replica.tickRaft();
        self.reportStampSkew();
        self.publishHealth();

        // Expire stale blocking waiters across all subsystems
        self.expireWaiters();
        self.expireReplySlots();

        // Run cooperative background tasks (hot_flush, TTL sweep, etc.)
        _ = self.task_scheduler.tick(2_000_000); // 2ms budget

        // Drive processing pipelines (poll sources → write sinks)
        // Producers run only where this shard leads: a follower that also
        // proposed would write the same facts twice, in two logs. And only
        // once it has applied what earlier terms committed: before, their
        // cursors and counts are behind what the log says.
        const leads = self.raft_node.leaderReady() and self.offline == null;
        if (leads) self.producer_ticks += 1;
        // A halted shard's leader is never ready (its applied index stops
        // short of the halt), yet its duties are still its own: held.
        const holds = self.raft_node.role == .leader and self.offline == null and self.halted != null;
        if (leads or holds) self.runProducers() else self.duties.clear();

        // The producers above only proposed. What has committed (at once
        // on a single node) applies here, outside any module's work.
        _ = self.applyCommitted();
        self.stepSnapshotWindow();
        if (self.kv_sink_retries.items.len > 0) self.retryKvSinkPuts();
        _ = self.coldCaughtUp();

        // Shard 0: namespaces created this tick go to disk, then into the
        // node's table, and what waited for them is answered.
        self.namespace_handler.settle(self);
        // After shard 0 publishes, so a forward held there for this tick's
        // creates runs now.
        if (self.edge.held_count > 0) self.sweepHeldForwards(nowMs());

        if (leads or holds) self.runStepping();

        self.settleConnections();
        return events.len;
    }

    /// The leader's stepping duty: first steps of runs whose start has
    /// applied, and runs whose action or child finished.
    pub fn runStepping(self: *Shard) void {
        if (self.heldIfHalted(.workflow_steps, self.workflow_handler.hasDutyWork())) {
            // Nothing will step while halted: the loop needn't poll again
            // at once for it.
            self.more_work = false;
            return;
        }
        self.duties.note(.workflow_steps, null, nowMs());
        // Take the first step of runs whose start has applied, then
        // resume waiting runs whose action or child finished (both
        // propose the run's next entries, so leader-only too). On a
        // single node what a pass proposes applies at once, so a child
        // started in one pass takes its first step in the next rather
        // than a tick later.
        var pass: u8 = 0;
        self.more_work = true;
        while (pass < STEP_PASSES) : (pass += 1) {
            const before = self.raft_node.last_applied;
            self.workflow_handler.advanceStartedRuns(self);
            self.workflow_handler.checkPendingActions(self);
            _ = self.applyCommitted();
            // Only what applied can be stepped; in a cluster what a
            // pass proposed waits for an ack, so one pass is all.
            if (self.raft_node.last_applied == before) {
                self.more_work = false;
                break;
            }
        }
        // What the tick proposed goes to the followers now, not at the
        // next poll.
        if (self.raft_node.role == .leader) self.replica.pump(nowMs());
    }

    /// The producers a leader runs each tick: processing pulls, then stream
    /// triggers and schedules starting runs. They only propose.
    pub fn runProducers(self: *Shard) void {
        const now = nowMs();
        // Drive processing pipelines (poll sources → write sinks)
        if (!self.heldIfHalted(.processing, self.processing_handler.pipelines.count() > 0)) {
            self.duties.note(.processing, if (self.processing_handler.tickPipelines(self)) .sink_halted else null, now);
        }
        // Drive workflow stream triggers (poll streams → start runs)
        if (!self.heldIfHalted(.stream_triggers, self.workflow_handler.stream_triggers.count() > 0)) {
            self.workflow_handler.tickStreamTriggers(self);
            self.duties.note(.stream_triggers, null, now);
        }
        // Drive workflow scheduled triggers (interval → start runs)
        if (!self.heldIfHalted(.schedules, self.workflow_handler.schedules.count() > 0)) {
            self.workflow_handler.tickSchedules(self);
            self.duties.note(.schedules, null, now);
        }
    }

    /// A halted shard's duties stop: state before the halt is all there is,
    /// and a proposal would be refused. One with work to do counts as held.
    /// Returns whether `d` is held; when it isn't, the caller notes how it
    /// ran.
    pub fn heldIfHalted(self: *Shard, d: duties_mod.Duty, has_work: bool) bool {
        if (self.halted == null) return false;
        self.duties.note(d, if (has_work) .shard_halted else null, nowMs());
        return true;
    }

    /// Whether shard `id` on this node is halted, as it last published.
    pub fn shardHalted(self: *const Shard, id: u16) bool {
        if (id == self.id) return self.halted != null;
        if (id >= self.node_health.len) return false;
        return self.node_health[id].get() == .halted;
    }

    /// Whether any other shard on this node is halted.
    pub fn peerHalted(self: *const Shard) bool {
        for (self.node_health, 0..) |*slot, i| if (i != self.id and slot.get() == .halted) return true;
        return false;
    }

    /// Enter the main reactor loop. Blocks until `shutdown()` is called.
    pub fn run(self: *Shard) !void {
        log.debug("Shard {d} entering reactor loop", .{self.id});

        var last_warn_ms: u64 = 0;
        var unsaid: u64 = 0;
        var failing = false;
        while (!self.stop_requested.load(.acquire)) {
            // Connections re-queued while the last tick settled run next.
            const slicing = if (self.snapshot_window) |w| w.slices_left > 0 else false;
            const busy = self.more_work or self.apply_behind or slicing or self.resume_fds.items.len > 0;
            _ = self.tick(if (busy) 0 else 100) catch |err| {
                // A shard whose tick keeps failing serves nothing: say so,
                // not once per tick, and do not spin a core while it lasts.
                const now = nowMs();
                if (now -| last_warn_ms >= 10_000) {
                    if (unsaid > 0) {
                        log.err("shard {d}: tick failed: {s} ({d} more in the last 10 s); the shard is not serving while this repeats — restart the node if it persists", .{ self.id, @errorName(err), unsaid });
                    } else {
                        log.err("shard {d}: tick failed: {s}; the shard is not serving while this repeats — restart the node if it persists", .{ self.id, @errorName(err) });
                    }
                    last_warn_ms = now;
                    unsaid = 0;
                } else unsaid += 1;
                failing = true;
                @import("stdx").time.sleep(10 * std.time.ns_per_ms);
                continue;
            };
            if (failing) {
                failing = false;
                log.info("shard {d}: ticking again", .{self.id});
            }
        }

        log.debug("Shard {d} reactor loop exited", .{self.id});
        self.answerAtShutdown();
    }

    /// Signal the shard to stop; safe from any thread.
    pub fn shutdown(self: *Shard) void {
        self.stop_requested.store(true, .release);
    }

    /// The node's shards stopping together: each counts itself once it has
    /// answered what it holds, and keeps taking answers from the others
    /// until every shard has.
    pub const Stopping = struct {
        stopped: std.atomic.Value(u32) = .init(0),
        /// The shards running; set before any is told to stop.
        of: u32 = 0,
    };

    /// How long a stopping shard waits for the others' answers, and then
    /// for its clients to take theirs.
    const STOP_WAIT_MS: u64 = 1_000;
    const STOP_FLUSH_MS: u64 = 200;

    /// What the reply to a write still waiting for commit says when the
    /// server stops: it was proposed, so it may yet apply.
    pub const SHUTTING_DOWN = "unavailable: the server is shutting down; this write may have been applied — check before resending";
    /// The reply to a request the stop leaves unrun.
    pub const SHUTTING_DOWN_NOT_RUN = "unavailable: the server is shutting down; this request did not run — retry";

    /// The loop has stopped. Everything a client still waits on gets an
    /// answer before the runtime frees the shard and closes the sockets:
    /// writes waiting for commit or for the leader, blocking reads, and,
    /// once every shard has answered what it holds, requests sent to other
    /// shards whose answer never came.
    fn answerAtShutdown(self: *Shard) void {
        self.resolvePending(SHUTTING_DOWN);
        for (&self.edge.waits) |*w| if (w.active) {
            self.deliverDeferredRefusal(w.reply_to, w.request_id, .unavailable, proto.notRun(SHUTTING_DOWN_NOT_RUN));
            self.endEdgeWait(w);
        };
        for (self.forwards) |*f| {
            if (!f.active) continue;
            if (f.ask != null) {
                self.dropForward(f);
                continue;
            }
            if (f.reply) |r| {
                // The leader answered; it was only held for this node to catch up.
                self.deliverDeferred(f.reply_to, r);
            } else if (f.sent_to != 0) {
                self.deliverDeferredRefusal(f.reply_to, f.request_id, .unavailable, .{ .reason = .unclassified, .ran = .unknown, .message = SHUTTING_DOWN });
            } else {
                self.deliverDeferredRefusal(f.reply_to, f.request_id, .unavailable, proto.notRun(SHUTTING_DOWN_NOT_RUN));
            }
            self.dropForward(f);
        }
        self.waiter_pool.expireAll(handleWaiterTimeout, @ptrCast(self));
        self.refuseUnrunRequests();
        self.takeAnswersUntilAllStopped();
        const Stopped = struct {
            shard: *Shard,
            pub fn late(ctx: *@This(), slot: ReplyPool.Slot) void {
                const conn = ctx.shard.forwardAnswered(slot) orelse return;
                const r: proto.Refusal = if (slot.writes) .{ .reason = .unclassified, .ran = .unknown, .message = SHUTTING_DOWN } else proto.notRun(SHUTTING_DOWN_NOT_RUN);
                ctx.shard.sendRefusal(conn, slot.request_id, .unavailable, r);
            }
        };
        var unanswered = Stopped{ .shard = self };
        _ = self.reply_pool.expire(std.math.maxInt(u64), &unanswered);
        self.flushAtShutdown();
    }

    /// Count this shard stopped, and deliver the other shards' answers to
    /// its clients until every shard has counted itself: an answer one sends
    /// before counting is on this shard's reply ring by then.
    fn takeAnswersUntilAllStopped(self: *Shard) void {
        const stopping = self.stopping orelse return;
        _ = stopping.stopped.fetchAdd(1, .acq_rel);
        const give_up = nowMs() + STOP_WAIT_MS;
        var buf: [64]InboxMessage = undefined;
        while (true) {
            const all = stopping.stopped.load(.acquire) >= stopping.of;
            while (true) {
                const count = self.mailbox.replies.drain(&buf);
                if (count == 0) break;
                for (buf[0..count]) |msg| self.deliverReply(msg);
            }
            if (all) return;
            if (nowMs() >= give_up) {
                log.warn("shard {d}: {d} of {d} shards stopped after {d} ms; answers still due from the rest are told unavailable", .{ self.id, stopping.stopped.load(.acquire), stopping.of, STOP_WAIT_MS });
                return;
            }
            @import("stdx").time.sleep(std.time.ns_per_ms);
        }
    }

    /// Requests other shards sent here that the stop leaves unrun: each is
    /// told it did not run, before this shard counts itself stopped, so the
    /// answer reaches its asker. One arriving later is freed by `deinit`,
    /// and its asker answers it from the slot it holds.
    fn refuseUnrunRequests(self: *Shard) void {
        var buf: [64]InboxMessage = undefined;
        while (true) {
            const count = self.mailbox.inbox.drain(&buf);
            if (count == 0) return;
            for (buf[0..count]) |msg| switch (msg.tag) {
                .forward_request => {
                    const bytes = inboxPayload(msg);
                    defer if (bytes.len > 0) self.allocator.free(bytes);
                    const request_id: u64 = if (bytes.len >= 16) std.mem.readInt(u64, bytes[8..16], .little) else 0;
                    const fd: i32 = @bitCast(@as(u32, @truncate(msg.sequence)));
                    const held = msg.replySlot();
                    const reply_to: ReplyTo = .{ .socket = .{ .shard = msg.src_shard, .fd = fd, .conn_id = @truncate(msg.sequence >> 32), .slot = held.slot, .gen = held.gen } };
                    self.deliverDeferredRefusal(reply_to, request_id, .unavailable, proto.notRun(SHUTTING_DOWN_NOT_RUN));
                },
                .reply => self.deliverReply(msg),
                .action_start, .kv_sink_put, .action_finished, .action_result_ask, .action_abandon, .worker_report, .action_held, .action_unhold => {
                    const bytes = inboxPayload(msg);
                    if (bytes.len > 0) self.allocator.free(bytes);
                },
                .shutdown, .cancel_reads => {},
            };
        }
    }

    /// The bytes a message carries on the heap, if any.
    fn inboxPayload(msg: InboxMessage) []u8 {
        const ptr = msg.payload_ptr orelse return &.{};
        return @as([*]u8, @ptrCast(ptr))[0..msg.payload_len];
    }

    /// Whatever is still on this shard's rings once every shard has
    /// stopped: nothing will read it, so its heap copies are freed.
    fn freeUndelivered(self: *Shard) void {
        var buf: [64]InboxMessage = undefined;
        for ([_]*@TypeOf(self.mailbox.inbox){ &self.mailbox.inbox, &self.mailbox.replies }) |ring| {
            while (true) {
                const count = ring.drain(&buf);
                if (count == 0) break;
                for (buf[0..count]) |msg| {
                    const bytes = inboxPayload(msg);
                    if (bytes.len > 0) self.allocator.free(bytes);
                }
            }
        }
    }

    /// Send each client what it is owed, for a short while, then end the
    /// stream: a half-close puts a FIN after the answers, and discarding
    /// what the client sent that will never be read keeps the close that
    /// follows from resetting the connection, which can drop answers the
    /// client has not read yet.
    fn flushAtShutdown(self: *Shard) void {
        const give_up = nowMs() + STOP_FLUSH_MS;
        var it = self.connections.iterator();
        while (it.next()) |e| {
            const fd = e.key_ptr.*;
            const conn = e.value_ptr.*;
            self.refuseUnread(fd, conn);
            while (true) {
                self.flushToClient(fd);
                if (!conn.hasPendingWrites() or conn.closing or nowMs() >= give_up) break;
                @import("stdx").time.sleep(std.time.ns_per_ms);
            }
            _ = std.c.shutdown(fd, std.c.SHUT.WR);
            var unread: [4096]u8 = undefined;
            var rounds: u32 = 0;
            while (rounds < 64 and std.c.recv(fd, &unread, unread.len, std.c.MSG.DONTWAIT) > 0) : (rounds += 1) {}
        }
    }

    /// Every complete request a connection sent that this shard never read,
    /// in its read buffer (waiting for room, or behind a pause) or still in
    /// the kernel's, is told it did not run, after the answers already
    /// queued and in the order sent. Only binary requests are framed. The
    /// walk stops at a partial request, at one that doesn't decode (a stray
    /// byte run never answers an id the client didn't send), and before the
    /// answers would overflow the write buffer, which would drop them all.
    fn refuseUnread(self: *Shard, fd: i32, conn: *Connection) void {
        if (conn.closing or conn.write_overflow) return;
        var rounds: u32 = 0;
        while (rounds < 64) : (rounds += 1) {
            const room = @min(conn.read_buf.writable(), self.read_buf.len);
            if (room == 0) break;
            const n = std.c.recv(fd, self.read_buf.ptr, room, std.c.MSG.DONTWAIT);
            if (n <= 0) break;
            _ = conn.read_buf.write(self.read_buf[0..@intCast(n)]);
        }
        if (conn.protocol == .unknown) conn.detectAndSetProtocol();
        if (conn.protocol != .binary) return;
        const header_size = @sizeOf(proto.RequestHeader);
        while (conn.read_buf.readable() >= header_size) {
            var hb: [header_size]u8 = undefined;
            _ = conn.read_buf.copyOut(&hb);
            const header = std.mem.bytesToValue(proto.RequestHeader, &hb);
            const total = header_size + @as(usize, header.payload_length);
            if (total > self.parse_buf.len or conn.read_buf.readable() < total) return;
            _ = conn.read_buf.copyOut(self.parse_buf[0..total]);
            const req = proto.Request.parse(self.parse_buf[0..total]) catch return;
            if (conn.write_buf.readable() + REFUSAL_FRAME_MAX > Connection.MAX_WRITE_BUFFER) return;
            self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(SHUTTING_DOWN_NOT_RUN));
            conn.read_buf.consume(total);
        }
    }

    // ─── Background tasks ────────────────────────────────────────────────

    /// Register cooperative background tasks. Called from runtime AFTER
    /// the Shard is at its final heap address (since init returns by value).
    pub fn registerBackgroundTasks(self: *Shard) void {
        if (self.hot_flush_seconds > 0) {
            self.task_scheduler.register(
                "hot_flush",
                1_000, // check every 1 second
                hotFlushTask,
                @ptrCast(self),
            ) catch {};
        }

        // Stream retention enforcement — runs every 10 seconds
        self.task_scheduler.register(
            "stream_retention",
            10_000, // check every 10 seconds
            streamRetentionTask,
            @ptrCast(self),
        ) catch {};

        // Action leases past their deadline, on the leader. The key bound
        // needs it at least every half the shortest lease.
        self.task_scheduler.register(
            "action_timeout_sweep",
            @import("../actions/handler.zig").DUTY_INTERVAL_MS,
            actionTimeoutSweepTask,
            @ptrCast(self),
        ) catch {};

        // Queue leases past their deadline, on the leader, as for actions.
        self.task_scheduler.register(
            "queue_expire",
            @import("../queue/handler.zig").DUTY_INTERVAL_MS,
            queueExpireTask,
            @ptrCast(self),
        ) catch {};

        // Consumer-group leases past their deadline, likewise.
        self.task_scheduler.register(
            "group_expire",
            @import("../queue/handler.zig").DUTY_INTERVAL_MS,
            groupExpireTask,
            @ptrCast(self),
        ) catch {};

        // Workers that stopped heartbeating: unhealthy, then removed. The
        // registry is this shard's alone, so every shard sweeps its own.
        self.task_scheduler.register(
            "worker_health",
            1_000,
            workerHealthTask,
            @ptrCast(self),
        ) catch {};

        self.task_scheduler.register(
            "kv_txn_reap",
            1_000,
            kvTxnReapTask,
            @ptrCast(self),
        ) catch {};

        // Persist Raft log entries to .flseg files (async_flush durability).
        if (self.shard_data_dir != null and self.durability == .async_flush) {
            self.task_scheduler.register(
                "segment_flush",
                1_000, // flush at most once per second
                segmentFlushTask,
                @ptrCast(self),
            ) catch {};
        }
    }

    /// TaskScheduler callback: mark silent workers unhealthy, remove long-silent ones.
    fn workerHealthTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        return self.worker_handler.checkHealth(@import("stdx").time.monotonicMs());
    }

    /// TaskScheduler callback: drop the KV transactions left idle.
    fn kvTxnReapTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        const n = self.kv_handler.txn_table.reapIdle(@import("stdx").time.monotonicMs());
        if (n > 0) {
            log.info("shard {d}: dropped {d} KV transaction(s) idle for {d} s", .{ self.id, n, txn_mod.IDLE_TIMEOUT_MS / std.time.ms_per_s });
            if (self.shard_metrics) |sm| sm.recordKvTxnsReaped(n);
        }
        return n;
    }

    /// TaskScheduler callback: flush buffered Raft entries to disk.
    fn segmentFlushTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        self.flushSegmentToDisk() catch |err| {
            self.noteFlushFailed();
            log.err("shard {d}: async segment flush failed: {s} (persist_failures={d})", .{ self.id, @errorName(err), self.persist_failures });
        };
        return 0;
    }

    /// TaskScheduler callback: evict entries older than hot_flush_seconds
    /// from every partition's UAL hot ring.
    fn hotFlushTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        const now_ns: u64 = @intCast(@import("stdx").time.nanoTimestamp());
        const cutoff_ns = now_ns -| (self.hot_flush_seconds *| std.time.ns_per_s);

        var total_evicted: u64 = 0;
        for (self.partitions) |partition| {
            total_evicted += partition.ual.evictOlderThan(cutoff_ns);
        }
        return total_evicted;
    }

    /// TaskScheduler callback: enforce stream retention policies.
    /// Computes trim targets locally, then persists through Raft so
    /// replicas apply the same deterministic trims.
    fn streamRetentionTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        // Trims are proposals: only the leader makes them.
        if (self.raft_node.role != .leader) return 0;
        const proj = self.stream_handler.stream;
        if (self.heldIfHalted(.stream_retention, self.halted != null and anyRetention(proj))) return 0;
        self.duties.note(.stream_retention, null, nowMs());
        const now_ns = self.raft_node.now();
        var trims_proposed: u64 = 0;

        var it = proj.stream_metadata.iterator();
        while (it.next()) |kv| {
            const meta = kv.value_ptr;
            if (!meta.hasRetention()) continue;
            // Settings are keyed by the stream's id and name; its records,
            // by the id and the name's hash.
            const name_key = kv.key_ptr.*;
            const key = stream_mod.streamKey(stream_mod.keyNamespace(name_key), name_key[4..]);

            // Age-based retention: the trim carries the age, and each replica
            // cuts at its entry's stamp; this node's time only decides
            // whether anything is old enough to propose one.
            if (meta.retention_age_s > 0) {
                const bound: stream_handler_mod.TrimBound = .{ .age_ms = meta.retention_age_s *| std.time.ms_per_s };
                if (bound.resolve(now_ns)) |cutoff_id| {
                    const first_id = proj.streamFirstId(key);
                    if (!first_id.eql(StreamID.MIN) and !first_id.greaterThan(cutoff_id)) {
                        if (self.stream_handler.persistTrim(key, bound)) trims_proposed += 1;
                    }
                }
            }

            // Count-based retention: resolve Nth record ID, persist trim through Raft
            if (meta.retention_count > 0) {
                // Retention is expressed in records, not append entries.
                const count = proj.streamLogicalCount(key);
                if (count > meta.retention_count) {
                    const excess = count - meta.retention_count;
                    const trim_id = proj.resolveNthRecordId(key, excess);
                    if (!trim_id.eql(StreamID.MIN)) {
                        if (self.stream_handler.persistTrim(key, .{ .id = trim_id })) trims_proposed += 1;
                    }
                }
            }
        }

        return trims_proposed;
    }

    fn anyRetention(proj: anytype) bool {
        var it = proj.stream_metadata.valueIterator();
        while (it.next()) |meta| if (meta.hasRetention()) return true;
        return false;
    }

    /// TaskScheduler callback: on the leader, end action leases past their
    /// deadline. Returns how many deadline keys it named.
    fn actionTimeoutSweepTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        return self.actions_handler.expireDue(self);
    }

    /// TaskScheduler callback: on the leader, end queue leases past their
    /// deadline. Returns how many deadline keys it named.
    fn queueExpireTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        return self.queue_handler.expireDue(self);
    }

    /// TaskScheduler callback: on the leader, end consumer-group leases past
    /// their deadline. Returns how many deadline keys it named.
    fn groupExpireTask(ctx: *anyopaque) u64 {
        const self: *Shard = @ptrCast(@alignCast(ctx));
        return group_handler.expireDue(self);
    }

    // ─── Event processing ────────────────────────────────────────────────

    fn processEvent(self: *Shard, ev: ReactorEvent) void {
        // Handle errors and hangups (but not on the pipes)
        if (ev.tag != .acceptor_pipe and ev.tag != .raft_read and ev.tag != .inbox_ready and (ev.err or ev.hangup)) {
            self.closeConnection(ev.fd);
            return;
        }

        switch (ev.tag) {
            .acceptor_pipe => {
                if (ev.readable) {
                    self.acceptFromPipe();
                }
            },
            .raft_read => {
                if (self.raft_queue) |q| q.drainWake();
                self.drainRaftQueue();
            },
            .client_read => {
                if (ev.readable) {
                    self.readFromClient(ev.fd);
                }
                if (ev.writable) {
                    self.flushToClient(ev.fd);
                }
            },
            .client_write => {
                if (ev.writable) {
                    self.flushToClient(ev.fd);
                }
            },
            else => {},
        }
    }

    /// Read fd from the acceptor pipe, create a Connection, and register
    /// the client fd with the reactor for reading.
    fn acceptFromPipe(self: *Shard) void {
        // May have multiple fds pending — drain them all
        while (true) {
            var fd_buf: [@sizeOf(i32)]u8 = undefined;
            const n = posix.read(self.acceptor_pipe_rd, &fd_buf) catch return;
            if (n != @sizeOf(i32)) return;

            const tagged: i32 = @as(*align(1) const i32, @ptrCast(&fd_buf)).*;
            const client_fd = tagged & ~acceptor_mod.ADMIN_TAG;

            const conn = self.addConnection(client_fd) catch {
                _ = std.c.close(client_fd);
                // A client slot the acceptor reserved is released; an admin fd
                // was never counted.
                if (tagged & acceptor_mod.ADMIN_TAG == 0) if (self.active_connections) |active| {
                    _ = active.fetchSub(1, .monotonic);
                };
                continue;
            };
            conn.admin = tagged & acceptor_mod.ADMIN_TAG != 0;

            self.reactor.addSource(.{
                .fd = client_fd,
                .tag = .client_read,
                .interests = .{ .readable = true },
            }) catch {
                self.removeConnection(client_fd);
                _ = std.c.close(client_fd);
            };
        }
    }

    /// Read data from a client socket, parse request(s), and dispatch.
    fn readFromClient(self: *Shard, fd: i32) void {
        const conn = self.getConnection(fd) orelse return;
        // A readable event comes when data arrives, not while it waits
        // (io_uring polls are multishot). A read that filled the room it
        // had may have left the rest of a request in the socket with
        // nothing to announce it, so read again until a read comes back short.
        var reads: u32 = 0;
        while (true) {
            // A readable event can still arrive after a pause (same poll batch,
            // or an interest change not yet submitted); what it would read
            // could not drain, and would look like one oversized request.
            if (conn.reads_paused or conn.closing or conn.waiting != null) return;

            // Read no more than the read buffer has room for: bytes read and
            // not kept would be requests silently lost.
            const tmp_buf = self.read_buf;
            if (conn.read_buf.writable() == 0) {
                // A request may be larger than the buffer: grow it to hold one
                // whole request. Full at that size, the client sent more than a
                // request can be. Every request says its size in its header and
                // one that cannot fit is refused from it, so this should not be
                // reached; if it is, one connection is closed rather than its
                // buffer growing without bound.
                const cap = conn.read_buf.buf.len * 2;
                if (cap > MAX_READ_BUFFER) {
                    self.sendRefusal(conn, 0, .bad_request, .{ .reason = .field_too_long, .ran = .no, .message = "bad request: request over 256 KiB" });
                    self.flushToClient(fd);
                    return self.markClosing(fd);
                }
                conn.read_buf.resize(cap) catch return self.markClosing(fd);
            }
            const room = @min(tmp_buf.len, conn.read_buf.writable());

            // Any failure ends the connection.
            const rc = std.c.read(fd, tmp_buf.ptr, room);
            if (rc < 0) switch (posix.errno(rc)) {
                .AGAIN => return,
                .INTR => continue,
                else => {
                    self.closeConnection(fd);
                    return;
                },
            };
            const n: usize = @intCast(rc);
            if (n == 0) {
                // EOF — peer closed
                self.closeConnection(fd);
                return;
            }

            if (self.metrics_registry) |m| m.server.recordBytesReceived(@intCast(n));
            if (self.shard_metrics) |sm| sm.recordBytesReceived(@intCast(n));

            // Accumulate data in the read buffer
            _ = conn.read_buf.write(tmp_buf[0..n]);

            // Detect protocol on first data if not yet determined
            if (conn.protocol == .unknown) {
                conn.detectAndSetProtocol();
            }

            self.processRequests(fd, conn);
            // Closing is deferred, so the connection is still ours here.
            conn.shrinkReadBuffer();
            if (n < room) return;
            reads += 1;
            if (reads == self.reads_per_event) {
                // More may wait. It is read at the end of the tick, so one
                // busy client doesn't hold the shard's others back.
                self.queueResume(fd, conn);
                return;
            }
        }
    }

    /// Run `conn` again at the end of the tick: what it buffered, and
    /// what its socket still holds.
    fn queueResume(self: *Shard, fd: i32, conn: *Connection) void {
        if (conn.resume_queued) return;
        conn.resume_queued = true;
        self.resume_fds.appendAssumeCapacity(fd);
    }

    /// Try to parse and dispatch request(s) from a connection's read buffer.
    fn processRequests(self: *Shard, fd: i32, conn: *Connection) void {
        self.runRequests(fd, conn);
        // Read again once the request it waited on has gone or been refused.
        if (conn.reads_held and conn.waiting == null and !conn.reads_paused and !conn.closing) {
            self.reactor.modifyInterests(fd, .{ .readable = true, .writable = conn.hasPendingWrites() }) catch |err| {
                log.err("shard {d}: could not read connection fd={d} again: {s}; closing it", .{ self.id, fd, @errorName(err) });
                return self.markClosing(fd);
            };
            conn.reads_held = false;
        }
    }

    fn runRequests(self: *Shard, fd: i32, conn: *Connection) void {
        const header_size = @sizeOf(proto.RequestHeader);
        // A waiting connection is not read (`readFromClient`) or resumed
        // (`settleConnections`) until `resumeWaiting` lets it go.
        std.debug.assert(conn.waiting == null);

        while (conn.read_buf.readable() >= header_size) {
            if (conn.closing) return;
            if (shouldPause(conn)) return self.pauseReads(fd, conn);
            // We need contiguous bytes for parsing. Copy readable data out.
            const available = conn.read_buf.readable();
            const to_copy = @min(available, MAX_REQUEST_SIZE);

            // A contiguous copy to parse; bytes are consumed only once a
            // whole request is taken, so the rest stay in order.
            const parse_buf = self.parse_buf;
            const copied = conn.read_buf.copyOut(parse_buf[0..to_copy]);
            if (copied < header_size) break;

            // A request that cannot fit is refused as soon as its header
            // says so; waiting for its bytes would never end.
            const promised = std.mem.bytesToValue(proto.RequestHeader, parse_buf[0..header_size]);
            // Past the version byte, a foreign header's layout is unknown:
            // refuse it before trusting its length.
            if (promised.magic == proto.MAGIC and promised.foreign()) return self.refuseForeign(fd, conn, promised);
            if (promised.magic == proto.MAGIC and @as(u64, header_size) + promised.payload_length > MAX_REQUEST_SIZE) {
                self.sendRefusal(conn, promised.request_id, .bad_request, .{ .reason = .field_too_long, .ran = .no, .message = "bad request: request over 256 KiB" });
                self.flushToClient(fd);
                self.markClosing(fd);
                return;
            }

            const req = proto.Request.parse(parse_buf[0..copied]) catch |err| {
                switch (err) {
                    // Not enough data yet — wait for more
                    error.IncompleteRequest, error.IncompletePayload => break,
                    error.UnknownFlag => {
                        var msg_buf: [96]u8 = undefined;
                        const msg = std.fmt.bufPrint(&msg_buf, "bad request: header flags 0x{x:0>2} are set; no flag is defined", .{promised.flags}) catch unreachable;
                        self.sendRefusal(conn, promised.request_id, .bad_request, .{ .reason = .unknown_flag, .ran = .no, .message = msg });
                        self.flushToClient(fd);
                        self.markClosing(fd);
                        return;
                    },
                    else => {
                        // Bad request — send error and close
                        self.sendRefusal(conn, 0, .bad_request, .{ .reason = .malformed, .ran = .no, .message = "Invalid request" });
                        self.flushToClient(fd);
                        self.markClosing(fd);
                        return;
                    },
                }
            };

            const held = self.holdForward(conn, req);
            if (held != null and conn.give_up_bytes == 0) return self.waitForward(fd, conn, held.?);
            const waited: ?u64 = if (conn.head_since_ms) |t| nowMs() -| t else null;

            const consumed = header_size + req.header.payload_length;
            conn.read_buf.consume(consumed);
            conn.give_up_bytes -|= consumed;

            // Dispatch request, detecting if the handler sent a response
            const queued_before = conn.bytes_queued - conn.deferred_queued;
            const forwards_before = conn.forwards_in_flight;
            var answered_deferred = false;
            if (held) |w| self.refuseWaited(conn, req, w, waited) else answered_deferred = self.dispatchNoted(conn, req, if (conn.admin) .admin else .client);
            // Parked here as a blocking read: one more toward its cap.
            if (held == null and conn.response_deferred and conn.forwards_in_flight == forwards_before and blockingWait(req) != null) conn.local_reads +|= 1;
            // Its wait is spent (counted into its deadline if it went to
            // another shard); the next request, should it wait, starts its
            // own clock at the back of the line.
            conn.head_since_ms = null;
            conn.has_turn = false;

            // If handler didn't queue any response, check if it was deferred.
            // An answer refused because the client let 4 MiB of answers pile
            // up unread was produced; the connection closes on the next flush.
            if (conn.bytes_queued - conn.deferred_queued == queued_before and !conn.response_deferred and !conn.write_overflow and !conn.closing) {
                if (answered_deferred) {
                    self.answeredAsDeferred(req.header.request_id, req.header.op_code);
                } else {
                    self.sendErrorResponse(conn, req.header.request_id, .internal_error, self.noAnswer(req));
                }
            }
            // Each request says for itself whether it parked.
            conn.response_deferred = false;

            // Try to flush writes immediately
            self.flushToClient(fd);
        }
    }

    /// Unsent answers above which a connection's requests stop being read:
    /// a client that reads while it sends is paced, and a connection holds
    /// one large answer at a time rather than piling them up to the cap.
    const PAUSE_READS_AT: usize = 64 * 1024;

    /// How long a paused client may read nothing before pacing is lifted.
    /// A client that sends its whole pipeline before reading any answer
    /// cannot finish sending while paused; unpaced, it gets what the
    /// write cap allows, and is closed past it as it would be without
    /// pacing.
    pub const STALL_MS: u64 = 1000;

    fn shouldPause(conn: *const Connection) bool {
        return !conn.pacing_off and conn.write_buf.readable() > PAUSE_READS_AT;
    }

    /// Stop reading and running this connection's requests until its unsent
    /// answers drain (`flushToClient` resumes it) or it stalls.
    fn pauseReads(self: *Shard, fd: i32, conn: *Connection) void {
        conn.reads_paused = true;
        conn.reads_held = false; // interest is this pause's now
        conn.paused_progress_ms = @import("stdx").time.monotonicMs();
        self.paused_count += 1;
        self.reactor.modifyInterests(fd, .{ .readable = false, .writable = true }) catch {};
    }

    fn resumeReads(self: *Shard, fd: i32, conn: *Connection) void {
        conn.reads_paused = false;
        conn.reads_held = false;
        self.paused_count -= 1;
        self.reactor.modifyInterests(fd, .{ .readable = true, .writable = conn.hasPendingWrites() }) catch {};
        // What it had already sent runs at the end of the tick, not inside
        // whoever resumed it; its socket may hold more that announces
        // nothing, so it is queued even with nothing buffered.
        self.queueResume(fd, conn);
    }

    /// Lift pacing from paused clients that have read nothing for
    /// `STALL_MS`. Walks the connections, so it runs at most every
    /// `STALL_MS / 4` and only while one is paused.
    fn liftStalledPauses(self: *Shard) void {
        if (self.paused_count == 0) return;
        const now = @import("stdx").time.monotonicMs();
        if (now < self.stall_check_ms) return;
        self.stall_check_ms = now + STALL_MS / 4;
        var it = self.connections.iterator();
        while (it.next()) |entry| {
            const conn = entry.value_ptr.*;
            if (!conn.reads_paused or conn.closing) continue;
            if (now - conn.paused_progress_ms < STALL_MS) continue;
            conn.pacing_off = true;
            self.resumeReads(entry.key_ptr.*, conn);
        }
    }

    /// How long a client's request may wait, unread, for room to go to
    /// another shard before it is refused, counted from when it first
    /// waited. Waiting holds its connection's later requests too, so this
    /// bounds how long any caller waits for room, blocking reads included;
    /// for a client with one request out, as the SDKs have, the refusal
    /// arrives before their 5 s request timeout (a pipelined request's
    /// clock starts when it reaches the head). A request that does go has
    /// what is left of `reply_pool.DEADLINE_MS`, and at least
    /// `reply_pool.MIN_DEADLINE_MS`.
    pub const ASK_WAIT_MS: u64 = 3000;

    comptime {
        // PAUSE_REASONS: the wait reasons in order, then unsent_answers.
        const reasons = @typeInfo(Connection.WaitReason).@"enum".field_names;
        std.debug.assert(reasons.len + 1 == ShardMetrics.PAUSE_REASONS.len);
        for (reasons, ShardMetrics.PAUSE_REASONS[0..reasons.len]) |r, label| std.debug.assert(std.mem.eql(u8, r, label));
    }

    /// Stop reading `conn` until its next request has room to go where it is
    /// bound, or has waited `ASK_WAIT_MS` (`resumeWaiting`).
    fn waitForward(self: *Shard, fd: i32, conn: *Connection, w: Connection.Waiting) void {
        // Paused for its unsent answers, it would not have got this far; the
        // two pauses never overlap, so neither undoes the other.
        std.debug.assert(!conn.reads_paused);
        std.debug.assert(conn.waiting == null);
        conn.waiting = w;
        self.setReason(conn, w.reason);
        // A request waiting for the first time joins the back of the line; one
        // that lost the room it was resumed for keeps its place.
        if (conn.head_since_ms == null) {
            conn.head_since_ms = nowMs();
            self.wait_seq +%= 1;
            if (self.wait_seq == 0) self.wait_seq = 1;
            conn.wait_seq = self.wait_seq;
            self.waiting_fds.appendAssumeCapacity(.{ .fd = fd, .seq = conn.wait_seq });
        }
        if (conn.reads_held) return;
        self.reactor.modifyInterests(fd, .{ .readable = false, .writable = conn.hasPendingWrites() }) catch |err| {
            log.err("shard {d}: could not stop reading connection fd={d}: {s}; closing it", .{ self.id, fd, @errorName(err) });
            return self.markClosing(fd);
        };
        conn.reads_held = true;
    }

    /// `conn` waits for `why` now. Only a wait for the target's room holds
    /// others back (`queued`): one on the connection's own limits says
    /// nothing about the target.
    fn setReason(self: *Shard, conn: *Connection, why: Connection.WaitReason) void {
        const w = &conn.waiting.?;
        w.reason = why;
        const in_line = why == .slots or why == .inbox;
        if (in_line == conn.in_queue) return;
        conn.in_queue = in_line;
        const n = &self.queued[@intFromBool(w.blocking)][w.target];
        if (in_line) n.* += 1 else n.* -= 1;
    }

    /// `conn` waits no longer.
    fn endWait(self: *Shard, conn: *Connection) void {
        const w = conn.waiting orelse return;
        if (conn.in_queue) self.queued[@intFromBool(w.blocking)][w.target] -= 1;
        conn.in_queue = false;
        conn.waiting = null;
    }

    /// Answer a request that could not get room in time: it was not run.
    fn refuseWaited(self: *Shard, conn: *Connection, req: proto.Request, w: Connection.Waiting, waited_ms: ?u64) void {
        // Refused on the connection's own in-flight limit: the shard holding
        // its oldest unanswered request, found once per give-up.
        const blamed = if (w.reason != .in_flight) w.target else conn.give_up_blame orelse blk: {
            const oldest = self.reply_pool.oldestFor(conn.fd, conn.id) orelse w.target;
            conn.give_up_blame = oldest;
            break :blk oldest;
        };
        conn.recordRequest();
        if (self.metrics_registry) |m| m.server.recordCommand();
        if (self.shard_metrics) |sm| sm.recordCommand();
        var msg_buf: [160]u8 = undefined;
        const message = switch (w.reason) {
            .in_flight => std.fmt.bufPrint(&msg_buf, "overloaded: {d} requests on this connection are still waiting on other shards (the oldest on shard {d}); this request was not run — back off and retry", .{ Connection.MAX_FORWARDS_IN_FLIGHT, blamed }),
            .blocking_reads => std.fmt.bufPrint(&msg_buf, "overloaded: this connection has {d} blocking reads waiting already; this request was not run — retry once one returns", .{Connection.MAX_BLOCKING_IN_FLIGHT}),
            .slots => if (w.blocking)
                std.fmt.bufPrint(&msg_buf, "overloaded: shard {d} has no room for more blocking reads from shard {d}; this read was not run — retry", .{ w.target, self.id })
            else
                std.fmt.bufPrint(&msg_buf, NOT_KEEPING_UP, .{w.target}),
            .inbox => std.fmt.bufPrint(&msg_buf, NOT_KEEPING_UP, .{w.target}),
        } catch "overloaded: this request was not run — back off and retry";
        self.sendErrorResponse(conn, req.header.request_id, .overloaded, message);
        if (self.shard_metrics) |sm| sm.recordCrossShardOverloaded(.client_forward);
        self.forwards_refused += 1;
        // Said for the request that waited, once per interval per reason;
        // those refused behind it are counted.
        const waited = waited_ms orelse return;
        const now = nowMs();
        const last = &self.wait_warn_ms[@backingInt(w.reason)];
        if (now -| last.* < WARN_INTERVAL_MS) return;
        last.* = now;
        const why = switch (w.reason) {
            .in_flight => std.fmt.comptimePrint("its connection had {d} requests unanswered, the oldest on that shard", .{Connection.MAX_FORWARDS_IN_FLIGHT}),
            .blocking_reads => std.fmt.comptimePrint("its connection had {d} blocking reads out", .{Connection.MAX_BLOCKING_IN_FLIGHT}),
            .slots => if (w.blocking) "that shard held its share of this shard's blocking reads" else "that shard held its share of this shard's requests",
            .inbox => "that shard had not drained this shard's share of its inbox",
        };
        log.warn("shard {d}: refused a client request after {d} ms waiting on shard {d}: {s} ({d} refused so far; {d} ordinary and {d} blocking in flight to shard {d})", .{ self.id, waited, blamed, why, self.forwards_refused, self.reply_pool.heldBy(.ordinary, blamed), self.reply_pool.heldBy(.blocking, blamed), blamed });
    }

    /// Resume, in the order their requests began waiting, the connections
    /// whose next request now has room — no more to one target than it has
    /// room for, so the rest keep their place and their clock rather than
    /// all waking to lose the race — and those that have waited
    /// `ASK_WAIT_MS`, to be refused. A resumed connection sends that one
    /// request ahead of the line (`Connection.has_turn`); its next waits at
    /// the back.
    fn resumeWaiting(self: *Shard) void {
        if (self.waiting_fds.items.len == 0) return;
        const now = nowMs();
        const MAX = @import("../config/server.zig").MAX_SHARDS;
        // Room per target this pass, worked out when first needed.
        var slot_room: [2][MAX]i32 = .{ @splat(-1), @splat(-1) };
        var inbox_room: [MAX]i32 = @splat(-1);
        var kept: usize = 0;
        for (self.waiting_fds.items) |entry| {
            const conn = self.getConnection(entry.fd) orelse continue;
            // Its head went and a later request waits under a newer entry,
            // or the fd was reused.
            if (conn.wait_seq != entry.seq) continue;
            const w = conn.waiting orelse {
                // Resumed last pass. Its head went: out of the line. Or it
                // was paused for its unsent answers first: it keeps its
                // place, should its head wait again.
                if (conn.head_since_ms != null) {
                    self.waiting_fds.items[kept] = entry;
                    kept += 1;
                } else conn.wait_seq = 0;
                continue;
            };
            if (conn.closing) continue;
            const class: reply_pool_mod.Class = if (w.blocking) .blocking else .ordinary;
            var why = self.stillWaits(conn, .{ .target = w.target, .blocking = w.blocking }, w.reason);
            const slots = &slot_room[@backingInt(class)][w.target];
            const inbox = &inbox_room[w.target];
            // A blocking read here waits on nothing shared.
            const shared = w.target != self.id;
            if (why == null and shared) {
                const mailbox = self.peer_mailboxes.?[w.target];
                if (slots.* < 0) slots.* = self.reply_pool.room(class, w.target);
                if (inbox.* < 0) inbox.* = mailbox.shareRoom(@intCast(self.id));
                if (slots.* <= 0) {
                    why = .slots;
                } else if (inbox.* <= 0) {
                    // Those resumed ahead of it will fill the share: be told
                    // when the target drains it.
                    why = .inbox;
                    mailbox.wantShare(@intCast(self.id));
                }
            }
            if (why) |r| {
                if (now -| conn.head_since_ms.? < ASK_WAIT_MS) {
                    self.setReason(conn, r);
                    self.waiting_fds.items[kept] = entry;
                    kept += 1;
                    continue;
                }
            }
            self.endWait(conn);
            // A client that has gone is not answered, and what it sent is
            // not run.
            if (peerClosed(entry.fd)) {
                self.markClosing(entry.fd);
                continue;
            }
            if (why == null) {
                if (shared) {
                    slots.* -= 1;
                    inbox.* -= 1;
                }
                conn.has_turn = true;
            } else {
                conn.give_up_bytes = conn.read_buf.readable();
                conn.give_up_blame = null;
            }
            if (!conn.resume_queued) {
                conn.resume_queued = true;
                self.resume_fds.appendAssumeCapacity(entry.fd);
            }
            // Should its head lose the room it was resumed for this tick, it
            // waits again here, in its place.
            self.waiting_fds.items[kept] = entry;
            kept += 1;
        }
        self.waiting_fds.shrinkRetainingCapacity(kept);
    }

    /// Whether the client has gone: its end closed with nothing left to
    /// read, or reset. A client that only stopped sending is gone too, as a
    /// read of end-of-stream treats it (`readFromClient`).
    fn peerClosed(fd: i32) bool {
        var byte: [1]u8 = undefined;
        const n = std.c.recv(fd, &byte, 1, std.c.MSG.PEEK | std.c.MSG.DONTWAIT);
        if (n == 0) return true;
        if (n > 0) return false;
        return std.posix.errno(n) != .AGAIN;
    }

    /// Set the paused-connections gauge: those waiting, by reason, and
    /// those paused for their unsent answers.
    fn countPaused(self: *Shard) void {
        const sm = self.shard_metrics orelse return;
        var counts: [ShardMetrics.PAUSE_REASONS.len]u64 = @splat(0);
        for (self.waiting_fds.items) |entry| {
            const conn = self.getConnection(entry.fd) orelse continue;
            if (conn.wait_seq != entry.seq) continue;
            const w = conn.waiting orelse continue;
            counts[@backingInt(w.reason)] += 1;
        }
        counts[counts.len - 1] = self.paused_count;
        sm.setConnectionsPaused(counts);
    }

    /// Close `fd` once the tick's events are handled: code up the stack may
    /// still hold its connection.
    fn markClosing(self: *Shard, fd: i32) void {
        const conn = self.getConnection(fd) orelse return;
        if (conn.closing) return;
        conn.closing = true;
        self.closing_fds.appendAssumeCapacity(fd);
    }

    /// End of tick: close what was marked closing; run what a paused
    /// connection had buffered once its answers drained or it stalled.
    fn settleConnections(self: *Shard) void {
        self.liftStalledPauses();
        if (self.pending_cancels.items.len > 0) self.sendPendingCancels();
        self.resumeWaiting();
        std.mem.swap(std.ArrayListUnmanaged(i32), &self.resume_fds, &self.resume_running);
        var ran = false;
        for (self.resume_running.items) |fd| {
            const conn = self.getConnection(fd) orelse continue;
            conn.resume_queued = false;
            if (conn.closing or conn.reads_paused or conn.waiting != null) continue;
            ran = true;
            self.processRequests(fd, conn);
            // Bytes left in the socket while it waited or was paused get no
            // event of their own on Linux: read them now.
            self.readFromClient(fd);
        }
        self.resume_running.clearRetainingCapacity();
        // What they proposed goes out at the next tick's pump; that tick
        // must not sleep first.
        if (ran and self.raft_node.role == .leader) self.more_work = true;
        for (self.closing_fds.items) |fd| {
            const conn = self.getConnection(fd) orelse continue;
            if (conn.closing) self.closeConnection(fd);
        }
        self.closing_fds.clearRetainingCapacity();
        self.countPaused();
    }

    /// Flush pending write data from a connection to the socket.
    pub fn flushToClient(self: *Shard, fd: i32) void {
        const conn = self.getConnection(fd) orelse return;
        if (conn.closing) return;
        if (conn.write_overflow) {
            if (self.overflowWarnDue()) |unsaid| {
                const why = "over 4 MiB of answers unsent (client not reading, or one answer too large)";
                if (unsaid == 0) {
                    log.warn("shard {d}: closing connection {d}: " ++ why, .{ self.id, conn.id });
                } else {
                    log.warn("shard {d}: closing connection {d}: " ++ why ++ " ({d} more since the last line)", .{ self.id, conn.id, unsaid });
                }
            }
            self.markClosing(fd);
            return;
        }

        while (conn.hasPendingWrites()) {
            const data = conn.pendingWriteData();
            const written = @import("stdx").io.tryWriteFd(fd, data) catch |err| {
                if (err == error.WouldBlock) {
                    // Socket buffer full — arm writable and return
                    self.reactor.armWritable(fd) catch {};
                    return;
                }
                // Write error — close connection
                self.markClosing(fd);
                return;
            };
            if (written == 0) {
                self.markClosing(fd);
                return;
            }
            if (self.metrics_registry) |m| m.server.recordBytesSent(@intCast(written));
            if (self.shard_metrics) |sm| sm.recordBytesSent(@intCast(written));
            conn.consumeWritten(written);
            if (conn.reads_paused) conn.paused_progress_ms = @import("stdx").time.monotonicMs();
        }

        // All writes flushed — disarm writable, and read again if paused.
        conn.shrinkWriteBuffer();
        conn.pacing_off = false;
        if (conn.reads_paused) return self.resumeReads(fd, conn);
        self.reactor.disarmWritable(fd) catch {};
    }

    // ─── Response helpers ────────────────────────────────────────────────

    /// `cluster_status` — this node's identity, role and group:
    /// `[node:u32][leader:u32][term:u64][state:u8][members:u32]
    /// [vouched_index:u64][strangers_while_quiet:u8]`. A node running alone
    /// is the leader of a one-member group. States: 0 follower, 1 electing,
    /// 2 leader, 3 joining (no seat yet), 4 diverged, 5 and 6 guarded (no
    /// log or no hard state of its own, new or lost): catching up, then
    /// confirming the term; 7 replica, 8 removed; 9 a cold boot not yet
    /// caught up (`coldCaughtUp`), shown for a candidate too, so an operator
    /// sees why it serves no reads. `vouched_index` is the
    /// index of a committed membership config another member vouched for
    /// while this node is behind it (0 for none): it missed a membership
    /// change and is catching up, and also takes appends and vote requests
    /// from that config's members. `strangers_while_quiet` is set while it
    /// drops frames from a node no config of its names and has heard no
    /// leader: a member stuck on an old config looks like this.
    fn dispatchClusterStatus(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const shard: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));

        const raft = shard.raft_node;
        const state: u8 = if (shard.removed_at_ms != null)
            8
        else if (shard.replica.diverged)
            4
        else if (raft.lost_log == .catching_up)
            5
        else if (raft.lost_log == .confirming)
            6
        else if (shard.raft_network != null and !raft.self_named)
            3
            // Electing too: what keeps it from serving is its catch-up.
        else if (shard.cold_gate and raft.role != .leader)
            9
        else if (shard.raft_network != null and !raft.timer_enabled)
            7
        else switch (raft.role) {
            .follower => 0,
            .candidate => 1,
            .leader => 2,
        };

        // Membership is what the log says; a node the log has not named
        // yet (a joiner, or one running alone) is a group of itself.
        var ids: [membership.MAX_MEMBERS]u32 = undefined;
        const member_count: u32 = @intCast(@max(1, raft.memberIds(&ids).len));
        const leader_id: u32 = if (shard.raft_network != null) raft.leader_id else shard.cluster_node_id;

        var buf: [cluster_wire.Status.SIZE]u8 = undefined;
        const status: cluster_wire.Status = .{
            .node_id = shard.cluster_node_id,
            .leader_id = leader_id,
            .term = raft.current_term,
            .state = state,
            .member_count = member_count,
            .vouched_index = shard.replica.vouchedIndex(),
            .strangers_while_quiet = shard.replica.strangersWhileQuiet(nowMs()),
        };
        shard.sendOkResponse(conn, req.header.request_id, status.encode(&buf));
    }

    /// Each member's id, role, address, and, from the leader, its last
    /// contact, match and halt (`cluster_wire.Members`). A node knows its
    /// own halt; only the leader hears the others'.
    fn dispatchClusterMembers(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const shard: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        const raft = shard.raft_node;
        // A node running alone, or one not yet named, is a group of itself.
        const cfg = if (raft.latest_config.member_count > 0) raft.latest_config else membership.Config.ofVoters(&.{shard.cluster_node_id});
        var rows: [membership.MAX_MEMBERS]cluster_wire.Member = undefined;
        const now = nowMs();
        for (cfg.memberSlice(), 0..) |m, i| {
            const addr = if (shard.raft_network) |rn| rn.clientAddress(m.id) else null;
            var row: cluster_wire.Member = .{
                .id = m.id,
                .role = if (m.voter) 0 else if (m.caught_up) 1 else 2,
                .ip4 = if (addr) |a| a.ip4 else .{ 0, 0, 0, 0 },
                .port = if (addr) |a| a.port else 0,
                .contact_ago_ms = cluster_wire.Member.UNKNOWN_CONTACT,
                .match = cluster_wire.Member.UNKNOWN_MATCH,
                .halt = .unknown,
            };
            if (m.id == shard.cluster_node_id) {
                row.halt = if (raft.halt_at) |h| .{ .at = .{ .index = h.index, .term = h.term, .crc = h.crc } } else .none;
            } else if (raft.role == .leader) {
                if (raft.peerProgress(m.id)) |p| {
                    row.contact_ago_ms = @intCast(@min(now -| @max(p.last_contact_ms, raft.leader_since_ms), cluster_wire.Member.UNKNOWN_CONTACT - 1));
                    row.match = p.match_index;
                }
                row.halt = switch (raft.peerHalt(m.id)) {
                    .none => .none,
                    .unknown => .unknown,
                    .at => |h| .{ .at = .{ .index = h.index, .term = h.term, .crc = h.crc } },
                };
            }
            rows[i] = row;
        }
        var gone: [membership.MAX_REMOVED]cluster_wire.Removed = undefined;
        for (cfg.removedSlice(), 0..) |rm, i| gone[i] = .{ .id = rm.id, .when_ms = rm.when_ms };
        var buf: [cluster_wire.Members.maxSize(membership.MAX_MEMBERS, membership.MAX_REMOVED)]u8 = undefined;
        const leader: u32 = if (shard.raft_network != null) raft.leader_id else shard.cluster_node_id;
        shard.sendOkResponse(conn, req.header.request_id, cluster_wire.Members.encode(&buf, leader, raft.commit_index, rows[0..cfg.member_count], gone[0..cfg.removed_count]));
    }

    /// Make a caught-up replica a voter, answered once the change commits.
    fn dispatchClusterPromote(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const shard: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        if (shard.raft_network == null) return shard.sendErrorResponse(conn, req.header.request_id, .bad_request, ALONE_MESSAGE);
        const id = (cluster_wire.Promote.decode(req.value) catch return shard.sendErrorResponse(conn, req.header.request_id, .bad_request, "promote takes one node id")).id;
        const raft = shard.raft_node;
        var msg: [200]u8 = undefined;
        const m = raft.latest_config.find(id) orelse
            return shard.sendErrorResponse(conn, req.header.request_id, .not_found, std.fmt.bufPrint(&msg, "node {d} is not a member", .{id}) catch "not a member");
        // Asked twice, or raced by the leader's own promotion: done either way.
        if (m.voter) return shard.sendOkResponse(conn, req.header.request_id, "");
        // Caught up now, as the leader's own promotions are: a replica that
        // fell behind or lost its disk would be a voter that blocks commit.
        const caught_up = if (raft.peerProgress(id)) |p| raft.caughtUpNow(p) else false;
        if (!caught_up) return shard.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(std.fmt.bufPrint(&msg, "unavailable: node {d} has not caught up yet; a voter that is behind slows every commit — retry once it has", .{id}) catch "unavailable: not caught up"));
        const next = raft.latest_config.withMember(.{ .id = id, .voter = true, .may_vote = true, .caught_up = true });
        shard.proposeAdminChange(conn, req, &next);
    }

    /// Remove a member, answered once the change commits. The id is
    /// remembered, so the node cannot join again.
    fn dispatchClusterRemove(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const shard: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        if (shard.raft_network == null) return shard.sendErrorResponse(conn, req.header.request_id, .bad_request, ALONE_MESSAGE);
        const change = cluster_wire.Remove.decode(req.value) catch return shard.sendErrorResponse(conn, req.header.request_id, .bad_request, "remove takes one node id");
        const id = change.id;
        const yes = change.yes;
        const raft = shard.raft_node;
        var msg: [240]u8 = undefined;
        const m = raft.latest_config.find(id) orelse
            return shard.sendErrorResponse(conn, req.header.request_id, .not_found, std.fmt.bufPrint(&msg, "node {d} is not a member", .{id}) catch "not a member");
        if (m.voter) {
            const left = raft.latest_config.voterCount() - 1;
            if (left == 0) return shard.sendErrorResponse(conn, req.header.request_id, .bad_request, std.fmt.bufPrint(&msg, "node {d} is the only voter; removing it would leave a group that can never commit", .{id}) catch "the only voter");
            if (!yes and left % 2 == 0) {
                const why = if (left == 2)
                    std.fmt.bufPrint(&msg, "removing node {d} leaves 2 voters, which tolerate no failure; add --yes to remove it anyway", .{id}) catch "add --yes"
                else
                    std.fmt.bufPrint(&msg, "removing node {d} leaves {d} voters, which tolerate no more failures than {d} would; add --yes to remove it anyway", .{ id, left, left - 1 }) catch "add --yes";
                return shard.sendErrorResponse(conn, req.header.request_id, .bad_request, why);
            }
        }
        // Dated 0: the config entry dates it with its own stamp.
        const next = raft.latest_config.without(id, 0);
        shard.proposeAdminChange(conn, req, &next);
    }

    /// Skip the entry the group halted at: only on a leader halted at that
    /// very entry, with a majority of the voters known halted there too.
    /// Without `yes`, it says what it would skip and who is halted there,
    /// and changes nothing; with it, it is answered once the skip commits.
    /// A minority halted there halted alone, and a leader that applied the
    /// entry runs a build that can: neither is fixed by dropping the write.
    fn dispatchClusterRepairSkip(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const shard: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        const rid = req.header.request_id;
        if (shard.raft_network == null) return shard.sendErrorResponse(conn, rid, .bad_request, "this node runs alone (started without --cluster or --join); stop it and repair it offline: flo server repair skip");
        const ask = cluster_wire.RepairSkip.decode(req.value) catch return shard.sendErrorResponse(conn, rid, .bad_request, "bad request: a repair skip takes an entry index and a reason of at most 256 bytes");
        const raft = shard.raft_node;
        if (raft.role != .leader) return shard.sendRefusal(conn, rid, .unavailable, proto.notRun("unavailable: the leader changed — retry"));
        var msg: [512]u8 = undefined;
        const e = switch (shard.replica.readOwnEntry(ask.index)) {
            .found => |e| e,
            .blocked => return shard.sendRefusal(conn, rid, .unavailable, proto.notRun("unavailable: the leader can't read that entry right now — retry")),
            .absent => return shard.sendErrorResponse(conn, rid, .not_found, std.fmt.bufPrint(&msg, "the leader's log doesn't hold entry {d}", .{ask.index}) catch "no such entry"),
        };
        const etype = e.header.entry_type;
        if (etype == @backingInt(entry_mod.EntryType.repair_skip))
            return shard.sendErrorResponse(conn, rid, .bad_request, std.fmt.bufPrint(&msg, "entry {d} is itself a repair; a skip is never skipped", .{ask.index}) catch "a skip is never skipped");
        if (etype == @backingInt(entry_mod.EntryType.raft_config) or etype == @backingInt(entry_mod.EntryType.raft_noop))
            return shard.sendErrorResponse(conn, rid, .bad_request, std.fmt.bufPrint(&msg, "entry {d} is a config or a term's no-op, which a shard applies even while halted; it is never skipped", .{ask.index}) catch "never skipped");
        // The writes behind a create or bind carry its id: skipped, they
        // would apply under an id another namespace may take.
        if (etype == @backingInt(entry_mod.EntryType.namespace_create) or etype == @backingInt(entry_mod.EntryType.namespace_bind))
            return shard.sendErrorResponse(conn, rid, .bad_request, std.fmt.bufPrint(&msg, "entry {d} creates or binds a namespace, and the writes behind it carry its id: skipped, they would land under an id another namespace may take, so it is never skipped. A member that halted here alone: stop it, wipe its data (flo server wipe), and restart it to rejoin from the others. If every member halted here, no repair keeps the writes behind it: restore from a backup, or rebuild the cluster", .{ask.index}) catch "a namespace create or bind is never skipped");
        const target: raft_node_mod.HaltAt = .{ .index = ask.index, .term = e.header.term, .crc = e.header.crc32c };
        const entry_size: u32 = @intCast(e.payload.len);
        var ids: [raft_node_mod.MAX_PEERS + 1]raft_node_mod.NodeId = undefined;
        const halted = raft.votersHaltedAt(target, &ids);
        if (raft.repaired.of(target))
            return shard.sendErrorResponse(conn, rid, .bad_request, std.fmt.bufPrint(&msg, "entry {d} is skipped already; each node passes over it as the repair reaches it", .{ask.index}) catch "skipped already");
        const own_halt = raft.halt_at;
        if (own_halt == null or !std.meta.eql(own_halt.?, target)) {
            const text = if (own_halt) |h|
                std.fmt.bufPrint(&msg, "the leader is halted at entry {d} (term {d}), not {d}: only the entry the group halted at is skipped", .{ h.index, h.term, ask.index })
            else if (raft.last_applied >= ask.index and halted.len > 0)
                std.fmt.bufPrint(&msg, "the leader applied entry {d}, where node(s) {any} halted: they run a build that fails it and the leader's doesn't. Upgrade them to the leader's build, which applies it; a skip would drop a write the leader already applied", .{ ask.index, halted })
            else
                std.fmt.bufPrint(&msg, "the leader is not halted at entry {d}: only the entry the group halted at is skipped (flo cluster members shows each node's halt)", .{ask.index});
            return shard.sendErrorResponse(conn, rid, .bad_request, text catch "the leader is not halted at that entry");
        }
        const voters = raft.clusterSize();
        if (halted.len < raft.quorum()) {
            const text = std.fmt.bufPrint(&msg, "unavailable: only node(s) {any} of {d} voters are known halted at entry {d} (term {d}); a skip needs {d}. A voter that halted alone is diverged instead, and one that hasn't answered lately doesn't count — retry once they answer (flo cluster members shows each node's halt)", .{ halted, voters, ask.index, target.term, raft.quorum() }) catch "unavailable: no majority is halted at that entry";
            return shard.sendRefusal(conn, rid, .unavailable, proto.notRun(text));
        }
        if (!ask.yes) {
            const answer: cluster_wire.RepairSkipAnswer = .{
                .skipped = false,
                .skip_index = 0,
                .entry = .{ .index = target.index, .term = target.term, .crc = target.crc },
                .entry_type = etype,
                .entry_size = entry_size,
                .voters = voters,
                .halted = halted,
            };
            var buf: [cluster_wire.RepairSkipAnswer.maxSize(raft_node_mod.MAX_PEERS + 1)]u8 = undefined;
            return shard.sendOkResponse(conn, rid, answer.encode(&buf));
        }
        var payload: [repair.Skip.MAX_PAYLOAD]u8 = undefined;
        const skip: repair.Skip = .{ .index = target.index, .term = target.term, .crc = target.crc, .reason = ask.reason };
        const proposed = raft.propose(.repair_skip, entry_mod.Flags.NONE, skip.encode(&payload)) catch |err| return shard.sendRefusal(conn, rid, .unavailable, proto.notRun(switch (err) {
            error.NotLeader => "unavailable: the leader changed — retry",
            error.WritesStopped => "unavailable: the leader stopped taking writes (an entry could not reach disk); restart it, then repair",
            else => "unavailable: the repair could not be put in the log — retry",
        }));
        shard.replica.pump(nowMs());
        shard.park(conn, req, proposed, respondSkipCommitted);
    }

    fn respondSkipCommitted(shard: *Shard, conn: *Connection, request_id: u64, result: *const persistence_mod.Result) void {
        const answer: cluster_wire.RepairSkipAnswer = .{ .skipped = true, .skip_index = result.index, .entry = .{ .index = 0, .term = 0, .crc = 0 }, .entry_type = 0, .entry_size = 0, .voters = 0, .halted = &.{} };
        var buf: [cluster_wire.RepairSkipAnswer.maxSize(0)]u8 = undefined;
        shard.sendOkResponse(conn, request_id, answer.encode(&buf));
    }

    const ALONE_MESSAGE = "this node runs alone (started without --cluster or --join); there is no membership to change";

    fn proposeAdminChange(self: *Shard, conn: *Connection, req: proto.Request, next: *const membership.Config) void {
        const raft = self.raft_node;
        const outcome = raft.proposeConfig(next) catch |err| return self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(switch (err) {
            error.NotLeader => "unavailable: the leader changed — retry",
            else => "unavailable: the change could not be put in the log — retry",
        }));
        var msg: [200]u8 = undefined;
        switch (outcome) {
            .proposed => |p| {
                self.replica.pump(nowMs());
                self.park(conn, req, p, respondChangeCommitted);
            },
            .refused => |why| self.sendErrorResponse(conn, req.header.request_id, .bad_request, why.message()),
            .no_own_commit => self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun("unavailable: a leader was just elected; retry in a moment")),
            .in_flight => {
                var waiting: [raft_node_mod.MAX_PEERS]u32 = undefined;
                const w = self.changeWaitsOn(&waiting);
                const text = if (w.len > 0)
                    std.fmt.bufPrint(&msg, "unavailable: an earlier membership change waits on node(s) {any}; retry once it commits", .{w}) catch "unavailable: an earlier membership change has not committed"
                else
                    "unavailable: an earlier membership change has not committed; retry";
                self.sendRefusal(conn, req.header.request_id, .unavailable, proto.notRun(text));
            },
        }
    }

    fn respondChangeCommitted(shard: *Shard, conn: *Connection, request_id: u64, _: *const persistence_mod.Result) void {
        shard.sendOkResponse(conn, request_id, "");
    }

    /// Which side to upgrade when a client speaks protocol `client`: the
    /// older one. Two tables have no order, so a table mismatch always names
    /// the client.
    fn olderSide(client: u8) []const u8 {
        return if (client > proto.VERSION) "server" else "client";
    }

    /// Answers a client built from another protocol version or table in its
    /// own version byte, so it can read the refusal, then closes the
    /// connection: nothing more it sends can be read.
    fn refuseForeign(self: *Shard, fd: i32, conn: *Connection, theirs: proto.RequestHeader) void {
        var text_buf: [128]u8 = undefined;
        const text = (if (theirs.version == proto.VERSION)
            std.fmt.bufPrint(&text_buf, "server table 0x{x:0>16}, client table 0x{x:0>16}: upgrade the client", .{ proto.TABLE_HASH, theirs.table_hash })
        else
            std.fmt.bufPrint(&text_buf, "server protocol {d}, client protocol {d}: upgrade the {s}", .{ proto.VERSION, theirs.version, olderSide(theirs.version) })) catch unreachable;
        var body: [proto.Refusal.HEADER_LEN + text_buf.len]u8 = undefined;
        var answer = proto.Response.refusal(.bad_request, theirs.request_id, (proto.Refusal{ .reason = .table_mismatch, .ran = .no, .message = text }).encode(&body));
        answer.header.version = theirs.version;
        var buf: [@sizeOf(proto.ResponseHeader) + body.len]u8 = undefined;
        _ = conn.queueWrite(answer.serialize(&buf) catch unreachable);

        self.foreign_refused += 1;
        if (self.metrics_registry) |m| m.server.recordClientVersionRefused();
        const now = nowMs();
        if (now -| self.foreign_logged_ms >= 10_000) {
            var peer_buf: [24]u8 = undefined;
            const peer = if (@import("stdx").net.sysPeerIp4(fd)) |p|
                std.fmt.bufPrint(&peer_buf, "{d}.{d}.{d}.{d}:{d}", .{ p.ip4[0], p.ip4[1], p.ip4[2], p.ip4[3], p.port }) catch unreachable
            else |_|
                "a local socket";
            log.warn("shard {d}: refused a client at {s} built from protocol {d} table 0x{x:0>16}; this server is protocol {d} table 0x{x:0>16} ({d} more refused since the last report)", .{
                self.id, peer, theirs.version, theirs.table_hash, proto.VERSION, proto.TABLE_HASH, self.foreign_unlogged,
            });
            self.foreign_logged_ms = now;
            self.foreign_unlogged = 0;
        } else self.foreign_unlogged += 1;
        self.flushToClient(fd);
        self.markClosing(fd);
    }

    /// A refusal from a site not yet on the op table: its reason is
    /// `unclassified` and whether it ran is judged from its status.
    pub fn sendErrorResponse(self: *Shard, conn: *Connection, request_id: u64, status: proto.StatusCode, msg: []const u8) void {
        self.sendRefusal(conn, request_id, status, proto.unclassified(status, msg));
    }

    /// The most a refusal's frame takes: one too long is cut to fit.
    pub const REFUSAL_FRAME_MAX = 1024;

    /// A blocking read with no room left to wait: refused overloaded rather
    /// than answered empty. SDK workers back off and retry; a direct caller
    /// gets the error. Forwarded, the refusal goes back and frees the
    /// asking node's slot.
    pub fn refuseWaitersFull(self: *Shard, conn: *Connection, request_id: u64) void {
        self.sendRefusal(conn, request_id, .overloaded, .{ .reason = .too_many_waiters, .ran = .no, .message = "overloaded: too many reads waiting on this shard — retry" });
    }

    /// A refusal is always sent: one too long for its frame is cut, never
    /// dropped (a dropped one left the client the no-answer fallback).
    pub fn sendRefusal(self: *Shard, conn: *Connection, request_id: u64, status: proto.StatusCode, r: proto.Refusal) void {
        _ = self;
        var buf: [REFUSAL_FRAME_MAX]u8 = undefined;
        _ = conn.queueWrite(proto.Response.serializeRefusal(status, request_id, r, &buf));
    }

    /// Noted for `dispatchNoted`, which checks the request was parked.
    fn noteDeferred(self: *Shard, reply_to: ReplyTo, request_id: u64) void {
        if (self.dispatching) |*d| {
            if (request_id == d.request_id and std.meta.eql(reply_to, d.reply_to)) d.answered_deferred = true;
        }
    }

    /// The connection `reply_to` names, when it is this shard's and still
    /// the same client.
    pub fn localConnection(self: *Shard, reply_to: ReplyTo) ?*Connection {
        const to = switch (reply_to) {
            .remote => return null,
            .socket => |s| s,
        };
        if (to.shard != self.id) return null;
        const conn = self.getConnection(to.fd) orelse return null;
        return if (conn.id == to.conn_id) conn else null;
    }

    /// Deliver an already-serialized answer to wherever `reply_to` says.
    ///
    /// A connection's fd, buffers, and reactor registration belong to the
    /// shard that owns it. When that is this shard, write directly;
    /// otherwise marshal the bytes to that shard so the socket write happens
    /// on its thread — never touch another shard's connection from here. A
    /// node that forwarded the request gets the answer over the peer link.
    ///
    /// The connection's generation is checked against the live connection
    /// before writing, so that fd reuse (close + accept at the same fd)
    /// cannot misdirect a stale answer to the wrong client.
    pub fn deliverDeferred(self: *Shard, reply_to: ReplyTo, bytes: []const u8) void {
        if (bytes.len >= @sizeOf(proto.ResponseHeader)) {
            self.noteDeferred(reply_to, std.mem.readInt(u64, bytes[@offsetOf(proto.ResponseHeader, "request_id")..][0..8], .little));
        }
        const my_id: u16 = @intCast(self.id);
        const to = switch (reply_to) {
            .remote => |r| return self.sendForwardReply(r.node, r.forward_id, bytes),
            .socket => |s| s,
        };
        const owner_shard = to.shard;
        const fd = to.fd;
        const conn_id = to.conn_id;
        if (owner_shard == my_id) {
            const conn = self.getConnection(fd) orelse return;
            if (conn.id != conn_id) return; // fd was reused for a new connection
            conn.deferred_queued += conn.queueWrite(bytes);
            self.flushToClient(fd);
            return;
        }

        const mailboxes = self.peer_mailboxes orelse return;
        if (owner_shard >= mailboxes.len) return;
        if (to.slot == ReplyTo.NO_SLOT) {
            // Another shard's client reaches this one only by a request that
            // took a reply slot there.
            self.replies_dropped += 1;
            if (self.shard_metrics) |sm| sm.recordReplyDropped();
            log.err("shard {d}: dropped an answer for a client of shard {d} (fd {d}): it holds no reply slot. This is a bug; that client gets no answer", .{ my_id, owner_shard, fd });
            return;
        }

        var msg: InboxMessage = .{ .tag = .reply, .src_shard = @intCast(my_id) };
        msg.setReplySlot(to.slot, to.gen);
        // Without room for a copy, an answer with no bytes still frees the
        // slot and tells the client its answer was lost.
        if (self.allocator.alloc(u8, bytes.len)) |payload| {
            @memcpy(payload, bytes);
            msg.payload_len = @intCast(payload.len);
            msg.payload_ptr = payload.ptr;
        } else |_| {}
        if (!mailboxes[owner_shard].replies.send(msg)) {
            if (msg.payload_ptr) |p| self.allocator.free(@as([*]u8, @ptrCast(p))[0..msg.payload_len]);
            self.replies_dropped += 1;
            if (self.shard_metrics) |sm| sm.recordReplyDropped();
            log.err("shard {d}: dropped an answer for a client of shard {d} (fd {d}): its reply ring is full; that client is answered when its slot expires", .{ my_id, owner_shard, fd });
        }
    }

    /// Serialize an ok answer and deliver it via `deliverDeferred`.
    pub fn deliverDeferredOk(self: *Shard, reply_to: ReplyTo, request_id: u64, data: []const u8) void {
        // Same rule as `sendOkResponse`: a parked client is answered, never
        // left to its own timeout because the answer is too large to frame
        // (and on another shard, never left holding its reply slot).
        if (data.len > MAX_REQUEST_SIZE) {
            log.warn("shard {d}: deferred answer to request {d} is {d} bytes, over the frame limit; answered with an error", .{ self.id, request_id, data.len });
            return self.deliverDeferredRefusal(reply_to, request_id, .internal_error, TOO_LARGE);
        }
        if (self.localConnection(reply_to)) |conn| {
            self.noteDeferred(reply_to, request_id);
            const before = conn.bytes_queued;
            self.sendOkResponse(conn, request_id, data);
            conn.deferred_queued += conn.bytes_queued - before;
            self.flushToClient(conn.fd);
            return;
        }
        const size = @sizeOf(proto.ResponseHeader) + data.len;
        const buf = self.scratch.borrow(size);
        defer self.scratch.release(buf);
        @memcpy(buf[@sizeOf(proto.ResponseHeader)..], data);
        self.deliverDeferred(reply_to, proto.Response.sealOk(request_id, buf, data.len));
    }

    /// A refusal from a site not yet on the op table, delivered via
    /// `deliverDeferred`.
    pub fn deliverDeferredError(self: *Shard, reply_to: ReplyTo, request_id: u64, status: proto.StatusCode, msg: []const u8) void {
        self.deliverDeferredRefusal(reply_to, request_id, status, proto.unclassified(status, msg));
    }

    pub fn deliverDeferredRefusal(self: *Shard, reply_to: ReplyTo, request_id: u64, status: proto.StatusCode, r: proto.Refusal) void {
        var buf: [REFUSAL_FRAME_MAX]u8 = undefined;
        self.deliverDeferred(reply_to, proto.Response.serializeRefusal(status, request_id, r, &buf));
    }

    /// An answer that can't be framed: whatever it did stands, but its
    /// result is gone.
    const TOO_LARGE: proto.Refusal = .{ .reason = .answer_lost, .ran = .unknown, .message = "internal error: answer over 256 KiB — ask for less" };

    /// Send an OK response with data payload on a connection.
    pub fn sendOkResponse(self: *Shard, conn: *Connection, request_id: u64, data: []const u8) void {
        // A client waits for every request's answer: one too large to
        // frame is answered with an error, never left out.
        if (data.len > MAX_REQUEST_SIZE) return self.sendRefusal(conn, request_id, .internal_error, TOO_LARGE);
        const header_size = @sizeOf(proto.ResponseHeader);
        // Written in place; null only where `queueWrite` would refuse it too.
        const out = conn.reserveWrite(header_size + data.len) orelse {
            conn.write_overflow = true;
            return;
        };
        @memcpy(out[header_size..], data);
        conn.commitWrite(proto.Response.sealOk(request_id, out, data.len).len);
    }

    /// A request whose handler neither answered nor parked it: a handler
    /// bug, answered internal_error so the client isn't left waiting.
    /// Returns the answer's text.
    fn noAnswer(self: *Shard, req: proto.Request) []const u8 {
        const name = if (std.enums.tagName(proto.OpCode, @fromBackingInt(@intCast(req.header.op_code)))) |n| n else "?";
        log.err("shard {d}: request {d} ({s}) got no answer from its handler. This is a bug", .{ self.id, req.header.request_id, name });
        if (self.shard_metrics) |sm| sm.recordHandlerNoAnswer();
        if (builtin.mode == .debug and !builtin.is_test) @panic("a handler produced no answer");
        return "internal error: the handler produced no answer";
    }

    /// An op no handler serves: refused, the same way wherever it runs.
    fn answerUnknownOp(shard_ptr: *anyopaque, conn_ptr: *anyopaque, request_id: u64, op: u16) void {
        const self: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        const r = run_mod.unknownOp(op);
        self.sendRefusal(conn, request_id, r.status, r.refusal);
    }

    // ─── Built-in handlers ───────────────────────────────────────────────

    fn handlePing(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
        const self: *Shard = @ptrCast(@alignCast(shard_ptr));
        const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
        self.sendOkResponse(conn, req.header.request_id, "PONG");
    }

    // ─── Stats ───────────────────────────────────────────────────────────

    pub fn connectionCount(self: *const Shard) u32 {
        return self.connections.count();
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// Walk Serialization — standard list wire format
// ═══════════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════════
// Waiter Callbacks — used by WaiterPool for timeout and resolution
// ═══════════════════════════════════════════════════════════════════════════════

/// A blocking read dropped because its client closed: an empty answer, so
/// the asking shard's slot for it comes back; nobody reads it.
fn answerCancelled(waiter: *const Waiter, ctx: *anyopaque) void {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    shard.deliverDeferred(waiter.reply_to, "");
}

const NOT_LEADING_NOT_RUN = "unavailable: this node stopped leading while the read waited; nothing was delivered — retry";

/// A delivering blocking read parked on a node that stopped leading.
fn answerNotLeading(waiter: *const Waiter, ctx: *anyopaque) void {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    shard.deliverDeferredRefusal(waiter.reply_to, waiter.request_id, .unavailable, proto.notRun(NOT_LEADING_NOT_RUN));
}

/// Timeout callback: send an appropriate "no data" response based on waiter kind.
///
/// Routes through `deliverDeferred` so the response reaches the
/// connection-owning shard even when the waiter expired on a different
/// (data) shard after cross-shard request routing.
fn handleWaiterTimeout(waiter: *const Waiter, ctx: *anyopaque) void {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    switch (waiter.kind) {
        .kv_get => {
            // A watch on a key that exists but did not change answers what is
            // there now, so the asker can tell "unchanged" from "gone".
            if (shard.defaultPartition().kv.get(waiter.key())) |entry| {
                sendKVWaiterValue(shard, waiter, entry);
            } else {
                const r = KVHandler.refusal(error.NotFound);
                shard.deliverDeferredRefusal(waiter.reply_to, waiter.request_id, r.status, r.refusal);
            }
        },
        .queue_dequeue => QueueHandler.answerEmpty(shard, waiter.reply_to, waiter.request_id),
        .stream_read => shard.deliverDeferredOk(waiter.reply_to, waiter.request_id, ""),
        // A group read that took nothing in its wait.
        .stream_group_read => shard.deliverDeferredOk(waiter.reply_to, waiter.request_id, &group_handler.EMPTY),
        // Its payloads weren't back from disk in time: retryable, never a
        // short answer that looks complete.
        .stream_disk_read => shard.deliverDeferredRefusal(waiter.reply_to, waiter.request_id, .unavailable, proto.notRun(DISK_READ_LATE)),
        // No task in time: `{task: none}`, the optional's absent byte.
        .action_await => shard.deliverDeferredOk(waiter.reply_to, waiter.request_id, &.{0}),
    }
}

/// What a stream read refused for its disk reads is told, by why.
pub const DISK_READ_LATE = "unavailable: the stream's records are being read from disk and weren't back in time — retry";
pub const DISK_READ_PENDING = "unavailable: the stream's records are being read from disk — retry";
pub const DISK_READ_BLOCKED = "unavailable: the stream's records can't be read from disk right now (a resource or IO failure) — retry";
pub const DISK_READS_FULL = "unavailable: too many reads are waiting on this shard's disk — retry";
pub const DISK_READ_CACHE_FULL = "unavailable: the shard's cache of records read from disk is full of ones not yet served — retry";
pub const DISK_READ_MISMATCH = "unavailable: the stream's records read from disk don't match the log; reading them again — retry";
pub const DISK_READ_UNWRITTEN = "unavailable: the stream's records haven't reached the durable log yet — retry";

/// KV waiter resolver: look up the key in the KV projection and send the value
/// if version > min_version. Returns true if waiter was satisfied.
pub fn resolveKVWaiter(waiter: *Waiter, ctx: *anyopaque) bool {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    const entry = shard.defaultPartition().kv.get(waiter.key()) orelse return false;
    if (entry.version <= waiter.min_version) return false;
    sendKVWaiterValue(shard, waiter, entry);
    return true;
}

/// Answers a waiting `kv.get`.
fn sendKVWaiterValue(shard: *Shard, waiter: *const Waiter, entry: kv_state.Current) void {
    if (comptime build_options.test_faults) {
        if (@import("test_faults.zig").ofKey(waiter.key()) == .panic_answering_waiter) @panic("test fault: panic answering a waiting read");
    }
    const Response = KVHandler.GetResponse;
    const answer = KVHandler.getAnswer(entry);
    // This shard's own client: written in place.
    if (shard.localConnection(waiter.reply_to)) |conn| {
        shard.noteDeferred(waiter.reply_to, waiter.request_id);
        const before = conn.bytes_queued;
        table_run.answer(Response, shard, conn, waiter.request_id, answer);
        conn.deferred_queued += conn.bytes_queued - before;
        shard.flushToClient(conn.fd);
        return;
    }
    const size = @sizeOf(proto.ResponseHeader) + Response.max_size;
    const buf = shard.scratch.borrow(size)[0..size];
    defer shard.scratch.release(buf);
    if (table_run.encodeAnswer(Response, buf, waiter.request_id, answer)) |bytes| {
        shard.deliverDeferred(waiter.reply_to, bytes);
    } else {
        // The waiter is gone once this returns; an asker left without an
        // answer would hang until its own timeout.
        shard.deliverDeferredError(waiter.reply_to, waiter.request_id, .internal_error, "internal error: value too large to send");
    }
}

/// Stream waiter resolver: re-run the parked read's window. The read is the
/// test — an append to a same-named stream in another namespace, or one the
/// window excludes, finds nothing and leaves the waiter parked.
pub fn resolveStreamWaiter(waiter: *Waiter, ctx: *anyopaque) bool {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    const handler = shard.stream_handler;
    const window = &waiter.stream;
    var buf: [StreamHandler.MAX_READ_BATCH]@import("../projection/stream.zig").StreamRecord = undefined;
    const records, const result = handler.readReadable(window, &buf);
    defer handler.freeResult(result);
    if (result == .pending) switch (handler.held) {
        // Still being read from disk: held until it is back.
        .pending => return false,
        else => {
            shard.deliverDeferredRefusal(waiter.reply_to, waiter.request_id, .unavailable, proto.notRun(handler.diskRefusal()));
            return true;
        },
    };
    // A read held only for its disk payloads is answered as a fresh read
    // would be now, records or none: its stream may be trimmed or deleted.
    if (records.len == 0 and waiter.kind == .stream_disk_read) {
        switch (result) {
            .stream_messages => |m| shard.deliverDeferredOk(waiter.reply_to, waiter.request_id, m.data),
            .err => |e| shard.deliverDeferredRefusal(waiter.reply_to, waiter.request_id, e.code.toStatus(), e.refusal()),
            else => shard.deliverDeferredOk(waiter.reply_to, waiter.request_id, &.{ 0, 0, 0, 0 }),
        }
        return true;
    }
    if (records.len == 0) {
        // Everything up to the stream's last id (or `end`) was scanned and none
        // of it is in the window; ids only grow, so the next wake starts there
        // instead of rescanning from the parked cursor.
        const last = handler.stream.streamLastId(window.stream);
        const scanned = if (last.greaterThan(window.end)) window.end else last;
        if (scanned.greaterThan(window.after)) window.after = scanned;
        return false;
    }

    switch (result) {
        .stream_messages => |m| shard.deliverDeferredOk(waiter.reply_to, waiter.request_id, m.data),
        else => shard.deliverDeferredError(waiter.reply_to, waiter.request_id, .internal_error, ""),
    }
    return true;
}

// ═══════════════════════════════════════════════════════════════════════════════
// UAL Persistence Callback
// ═══════════════════════════════════════════════════════════════════════════════

/// Called by UAL.append() after every entry write. Feeds the entry to the
/// SegmentWriter so it's included in the next segment flush to disk.
/// The context is the heap-allocated SegmentWriter, not the Shard (returned
/// by value from init), so the hook is valid before bootstrap.
fn segmentBufferCallback(ctx: *anyopaque, entry: *const entry_mod.Entry) void {
    const writer: *SegmentWriter = @ptrCast(@alignCast(ctx));
    // Behind a gap nothing is buffered: the flush re-buffers from the gap.
    if (writer.stop_at_gap and writer.first_unbuffered != null) return;
    writer.addEntry(entry) catch |err| {
        writer.buffer_failures += 1;
        if (writer.buffer_failing_since_ms == 0) writer.buffer_failing_since_ms = Shard.nowMs();
        if (writer.stop_at_gap) {
            writer.first_unbuffered = entry.header.index;
            log.err("shard {d}: failed to buffer entry index={d} for persistence: {s}; buffering resumes from it at the next flush (buffer_failures={d})", .{ writer.partition_id, entry.header.index, @errorName(err), writer.buffer_failures });
        } else {
            log.err("shard {d}: failed to buffer entry index={d} for persistence: {s}; it will be missing from disk after a restart (buffer_failures={d})", .{ writer.partition_id, entry.header.index, @errorName(err), writer.buffer_failures });
        }
        return;
    };
    // Buffered again: end any failing run. The cumulative count stays.
    writer.buffer_failing_since_ms = 0;
}

/// A read held on this shard's stream when it found its log damaged.
fn answerDamaged(waiter: *const Waiter, ctx: *anyopaque) void {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    var buf: [400]u8 = undefined;
    const why = if (shard.damage_for_waiters) |*d| d.reason() else "its data is damaged";
    const message = std.fmt.bufPrint(&buf, "unavailable: shard {d} is damaged on this node ({s}); this read was not answered with records past it", .{ shard.id, why }) catch "unavailable: the shard is damaged on this node";
    shard.deliverDeferredRefusal(waiter.reply_to, waiter.request_id, .unavailable, proto.notRun(message));
}

/// The durable log couldn't give a committed stream entry back: damage, as
/// boot and apply report it.
fn streamDiskDamage(ctx: *anyopaque, index: u64, cause: @import("../stream/disk_reads.zig").Damage.Cause) void {
    const shard: *Shard = @ptrCast(@alignCast(ctx));
    const grace = shard.stream_disk.?.disk_failing_ms;
    shard.damaged(switch (cause) {
        .corrupt => silent_loss.Damage.init(.segment_unreadable, "the segment holding committed entry {d} is corrupt or doesn't hold it", .{index}),
        .disk_failing => silent_loss.Damage.init(.segment_unreadable, "the segment holding committed entry {d} could not be read for {d} ms; the disk may be failing", .{ index, grace }),
        .permission => silent_loss.Damage.init(.segment_unreadable, "the segment holding committed entry {d}: permission denied for {d} ms; fix the file's permissions and restart", .{ index, grace }),
    });
}

/// A stream payload the bulk I/O thread read for this shard is back.
fn streamDiskReadDone(ctx: *anyopaque) void {
    const mailbox: *Mailbox = @ptrCast(@alignCast(ctx));
    mailbox.wake.set(.stream_disk_read);
}

/// A read the bulk I/O thread made for this shard is back.
fn catchUpReadDone(ctx: *anyopaque) void {
    const mailbox: *Mailbox = @ptrCast(@alignCast(ctx));
    mailbox.wake.set(.catch_up_read);
}

/// Raft log truncation, carried into the durable log.
fn durableTruncate(ctx: *anyopaque, after_index: u64) void {
    const dl: *DurableLog = @ptrCast(@alignCast(ctx));
    dl.truncateAfter(after_index) catch |err| {
        log.err("durable log: cannot truncate segments after index {d}: {s} (truncate_failures={d}); no segment is flushed until the cut completes, which every flush retries", .{ after_index, @errorName(err), dl.truncate_failures });
    };
}

/// Per-shard HARDSTATE writer — the sink the Raft node persists through.
/// Heap-allocated so the sink's context pointer stays valid.
const HardStateStore = struct {
    /// Borrowed from `Shard.shard_data_dir`; the store is destroyed first.
    dir: []const u8,
    node_id: u32,
    shard_id: u16,
    /// Cumulative count of HARDSTATE writes (term + vote) that could not be
    /// persisted, and a raw monotonic reading when the current run of failures
    /// began (0 while they persist). Surfaced (metric and /status) rather than
    /// left in the log: while a run holds, each unpersisted vote or term change
    /// is refused, since the node must not forget a vote it may already have
    /// given; the next good persist ends the run. The since-reading is kept
    /// internal; publishHealth publishes the elapsed duration from it.
    hardstate_failures: u64 = 0,
    hardstate_failing_since_ms: u64 = 0,

    fn persist(ctx: *anyopaque, term: u64, voted_for: u32, lost_log: bool) bool {
        const self: *HardStateStore = @ptrCast(@alignCast(ctx));
        hard_state_mod.save(self.dir, .{ .node_id = self.node_id, .term = term, .voted_for = voted_for, .lost_log = lost_log }) catch |err| {
            self.hardstate_failures += 1;
            if (self.hardstate_failing_since_ms == 0) self.hardstate_failing_since_ms = Shard.nowMs();
            log.err("shard {d}: cannot write {s}/{s}: {s}; this node will not vote until it can (hardstate_failures={d})", .{ self.shard_id, self.dir, hard_state_mod.FILENAME, @errorName(err), self.hardstate_failures });
            return false;
        };
        // Persisted: end any failing run. The cumulative count stays.
        self.hardstate_failing_since_ms = 0;
        return true;
    }
};

/// The Raft ring keeps recent entries for replication catch-up. A quarter
/// of the hot buffer, capped at 16 MiB so many shards do not each take a
/// quarter of a large buffer, and floored so the largest entry (a full
/// transaction batch) still fits: a ring smaller than an entry rejects the
/// write.
pub const RAFT_RING_MAX: usize = 16 * 1024 * 1024;
pub const RAFT_RING_MIN: usize = 2 * 1024 * 1024;

comptime {
    std.debug.assert(limits.MAX_LOG_ENTRY_PAYLOAD + entry_mod.HEADER_SIZE <= RAFT_RING_MIN);
    std.debug.assert(limits.MAX_LOG_ENTRY_PAYLOAD + entry_mod.HEADER_SIZE <= @import("../config/tiered_log.zig").MIN_HOT_BUFFER);
}

/// How a shard's Raft group comes up.
pub const ClusterRole = enum {
    /// No peer listener: the one member, leading from init.
    single,
    /// The first member: an empty log bootstraps and writes the config
    /// naming this node; a log that already names members follows them.
    bootstrap,
    /// Joining members that exist: a follower with no vote until a config
    /// entry from the leader names it.
    join,
};

/// A write waiting for its entry to commit: where to answer, the request
/// to answer from, and the handler's tail that does it.
pub const Pending = struct {
    active: bool = false,
    index: u64 = 0,
    term: u64 = 0,
    reply_to: ReplyTo = undefined,
    request_id: u64 = 0,
    answer: Shard.AnswerFn = undefined,
    release: ?Shard.ReleaseFn = null,
    ctx: u64 = 0,
};
pub const PENDING_SLOTS: usize = 2 * raft_node_mod.MAX_OUTSTANDING;

/// Apply suspended at bar `s` while the state at it is serialized.
pub const SnapshotWindow = struct {
    s: u64,
    opened_ms: u64,
    /// Slices of the state still to queue. The serializer comes with
    /// snapshots; until then a window queues a stub slice per tick.
    slices_left: u32,
    /// A window opened by a test fault holds until this monotonic time, so
    /// an e2e test can write through it.
    hold_until_ms: u64 = 0,
};

/// Whether a bar suspends apply. Not until snapshots are written: bars are
/// found and reported, but a window with nothing to serialize would only
/// pause apply. Not a setting; the change that writes snapshots removes it.
const BARS_OPEN_WINDOWS = false;

/// Stub slices a test bar's window queues before it closes.
pub const TEST_BAR_SLICES: u32 = 3;
/// How long a window a test fault opens holds apply.
pub const TEST_FAULT_WINDOW_MS: u64 = 2_000;

/// A client's write sent to the leader, and what came back.
/// Removal notices held toward a quorum: each sender's latest, by the
/// removal it names, and the newest config index among them.
const RemovalNotices = struct {
    config_index: u64 = 0,
    from: [membership.MAX_MEMBERS]u32 = undefined,
    when: [membership.MAX_MEMBERS]u64 = undefined,
    count: u8 = 0,

    fn held(self: *const RemovalNotices, id: u32) ?u64 {
        for (self.from[0..self.count], self.when[0..self.count]) |f, w| if (f == id) return w;
        return null;
    }

    fn hold(self: *RemovalNotices, id: u32, when_ms: u64) void {
        for (self.from[0..self.count], 0..) |f, i| if (f == id) {
            self.when[i] = when_ms;
            return;
        };
        self.from[self.count] = id;
        self.when[self.count] = when_ms;
        self.count += 1;
    }

    fn agreeing(self: *const RemovalNotices, when_ms: u64) u8 {
        var n: u8 = 0;
        for (self.when[0..self.count]) |w| n += @intFromBool(w == when_ms);
        return n;
    }

    fn disagree(self: *const RemovalNotices, when_ms: u64) bool {
        return self.agreeing(when_ms) != self.count;
    }
};

const Forward = struct {
    active: bool = false,
    id: u32 = 0,
    reply_to: ReplyTo = undefined,
    request_id: u64 = 0,
    bytes: []u8 = &.{},
    /// The leader it went to, the term then, and the link it went over; 0
    /// until it has gone.
    sent_to: u32 = 0,
    sent_term: u64 = 0,
    sent_session: u64 = 0,
    sent_ms: u64 = 0,
    /// How long the request may wait for its data on the leader (a
    /// blocking read), which the backstop adds to its own wait.
    wait_ms: u64 = 0,
    deadline_ms: u64 = 0,
    /// The leader's answer, held until `applied_by` is applied here.
    reply: ?[]u8 = null,
    applied_by: u64 = 0,
    /// For a follower's ask of how far the leader's namespaces are
    /// published, the name it asks for (owned): its answer goes to the reads
    /// held for that name (`Shard.edge`), not to a client.
    ask: ?[]u8 = null,
    /// A read the leader answers: lost on the way, it ran nowhere, and is
    /// never answered from this node's memory.
    read: bool = false,
};
const FORWARD_SLOTS: usize = 1024;
/// Forward slots blocking reads may not take.
const FORWARD_WRITE_RESERVE: usize = 256;
/// How long a write waits for a leader to be known, and how long an
/// answer is held for this node to catch up to it.
pub const FORWARD_TIMEOUT_MS: u64 = 5000;
/// A write sent to a leader that stays linked and in office but never
/// answers is answered after this, past any time it may block there: the
/// last guard, for a leader that is wedged. Everything else that ends a
/// sent write answers sooner. Cut off sooner, a blocking read would leave
/// its waiter on the leader to take a message nobody receives. That can
/// still happen when it does fire (the leader is wedged) or when the
/// client closes and its forwards are dropped: closing it needs a cancel
/// sent to the leader's waiter.
pub const SENT_FORWARD_BACKSTOP_MS: u64 = 60_000;
/// A forwarded write's frame: its id, then the length of the fields carried
/// beside the client's bytes (none yet), then those fields, then the bytes.
const FORWARD_PREFIX: usize = 4 + 2;
/// The fields every forward carries after its prefix: the namespace's id
/// (u32, 0 when the forwarder didn't know it) and the forwarder's table's
/// published index (u64).
const FORWARD_FIELDS: u16 = 4 + 8;
/// Forward ids stand in for an fd on the leader's proxy connection: ids
/// from here up are negative as an fd, so a client closing on the leader
/// can never match one in the waiter pool.
const FORWARD_ID_FIRST: u32 = 0x8000_0000;
pub const DIVERGED_MESSAGE = replica_mod.DIVERGED_MESSAGE;
/// A member that ran out of memory applying the log: nothing is lost.
pub const OUT_OF_MEMORY_MESSAGE = "unavailable: this node ran out of memory applying the log and takes no part until it restarts; use another node";

/// How many step passes one tick takes: a chain of child starts that
/// deep resolves in one tick on a single node; a deeper one continues on
/// the next tick, which does not wait.
const STEP_PASSES: u8 = 4;
const WARN_INTERVAL_MS = replica_mod.WARN_INTERVAL_MS;
const JOIN_WARN_INTERVAL_MS: u64 = 30_000;

/// Most entries in one AppendEntries, and the payload bytes they may
/// hold: a batch is sized by bytes, and must hold the largest entry any
/// handler writes or no follower could ever pass it.
pub const RPC_MAX_ENTRIES: usize = 1024;
pub const RPC_BATCH_BYTES: usize = @max(1024 * 1024, limits.MAX_LOG_ENTRY_PAYLOAD + entry_mod.HEADER_SIZE);
comptime {
    std.debug.assert(transport.APPEND_REQ_PREFIX + RPC_MAX_ENTRIES * entry_mod.HEADER_SIZE + RPC_BATCH_BYTES <= transport.MAX_PAYLOAD_SIZE);
    // The largest entry alone in an AppendEntries fits a peer frame, or a
    // follower could never be sent it and replication would stall there.
    std.debug.assert(transport.APPEND_REQ_PREFIX + entry_mod.HEADER_SIZE + limits.MAX_LOG_ENTRY_PAYLOAD <= transport.MAX_PAYLOAD_SIZE);
}
const JOIN_ASK_INTERVAL_MS: u64 = 1000;

/// Membership at boot comes from the log's latest config entry; a single
/// node and a first member with nothing in the log lead at once.
/// `config_mark`: on a cold boot, the watermark its configs commit through.
fn bringUpGroup(raft: *RaftNode, role: ClusterRole, buf: []u8, shard_id: u16, node_id: u32, had_hard_state: bool, config_mark: u64) !void {
    // Everything replay put in the log came from disk.
    raft.markDurable(raft.log.lastIndex());
    const cfg_index = raft.log.last_config_index;
    if (role == .single) {
        // A data directory that belonged to a group must not lead alone:
        // it would take writes the group never sees.
        if (cfg_index > 0) {
            const e = raft.log.getEntryCopy(cfg_index, buf) orelse {
                log.err("shard {d}: the config entry at index {d} could not be read; refusing to guess whether this data directory belonged to a group", .{ shard_id, cfg_index });
                return error.MembershipUnreadable;
            };
            const cfg = membership.decode(e.payload) orelse {
                log.err("shard {d}: the config entry at index {d} is not a membership", .{ shard_id, cfg_index });
                return error.MembershipUnreadable;
            };
            if (cfg.member_count > 1 or !cfg.names(node_id)) {
                var ids: [membership.MAX_MEMBERS]u32 = undefined;
                log.err("shard {d}: this data directory belonged to a group of {d} (members {any}); start with --join to rejoin them, or point --data-dir at an empty directory to start alone", .{ shard_id, cfg.member_count, cfg.ids(&ids) });
                return error.DataDirWasClustered;
            }
        }
        // Alone, nothing was lost that another node could vote against;
        // bootstrap writes the cleared flag with its new term.
        raft.lost_log = .none;
        return raft.bootstrap();
    }
    const empty = raft.log.lastIndex() == 0;
    // The log is evidence of the term too: a hard state that is missing,
    // or behind it, never lets the node act in a term it already left.
    if (raft.log.lastTerm() > raft_node_mod.MAX_TERM) {
        log.err("shard {d}: the log's last entry is from term {d}, past the highest term a node takes ({d}); refusing to start on it", .{ shard_id, raft.log.lastTerm(), raft_node_mod.MAX_TERM });
        return error.TermSpaceExhausted;
    }
    raft.current_term = @max(raft.current_term, raft.log.lastTerm());
    if (cfg_index > 0) {
        const e = raft.log.getEntryCopy(cfg_index, buf) orelse {
            log.err("shard {d}: the config entry at index {d} could not be read; refusing to guess the membership", .{ shard_id, cfg_index });
            return error.MembershipUnreadable;
        };
        const cfg = membership.decode(e.payload) orelse {
            log.err("shard {d}: the config entry at index {d} is not a membership", .{ shard_id, cfg_index });
            return error.MembershipUnreadable;
        };
        raft.setMembership(&cfg, cfg_index);
        raft.membership_term = e.header.term;
        try raft.recordConfigsAbove(raft.last_applied, buf);
        raft.recordConfig(cfg_index, e.header.term, &cfg);
        if (cfg_index <= raft.last_applied) raft.commitMembership(&cfg, cfg_index);
        // A removed node that forgot its committed configs would answer
        // vouch asks with its founding one, and a member stuck on an old
        // config would never hear the leader.
        raft.commitConfigsThrough(config_mark);
        // What the segments flushed under a commit watermark is committed;
        // the rest of the log waits for a leader to say so.
        raft.commit_index = raft.last_applied;
        var ids: [membership.MAX_MEMBERS]u32 = undefined;
        log.info("shard {d}: members {any} (voters {d}) from the log (config index {d}); following until a leader speaks{s}", .{ shard_id, cfg.ids(&ids), cfg.voterCount(), cfg_index, if (!cfg.names(node_id)) " (this node is not a member)" else if (!raft.timer_enabled) " (this node is a replica)" else "" });
        // The log survived but the hard state did not: the vote cast in
        // the current term is gone, so the term is confirmed first. A
        // replica cast none.
        if (!had_hard_state and raft.lost_log == .none and raft.timer_enabled) {
            try raft.enterLostVote();
            log.warn("shard {d}: this node has a log but no {s}; it votes only once the members have confirmed the term", .{ shard_id, hard_state_mod.FILENAME });
        }
        return;
    }
    switch (role) {
        .single => unreachable,
        .bootstrap => {
            // Hard state without a log is a member whose log is gone, not
            // a first boot: founding would start a second cluster.
            if (empty and (raft.lost_log != .none or raft.current_term > 0)) {
                log.err("shard {d}: this node has no log but has hard state from a cluster (term {d}); it was a member and lost its log. Restart it with --join <a live member>, not --cluster", .{ shard_id, raft.current_term });
                return error.LostLogFounding;
            }
            try raft.bootstrap();
            var cluster_id: [membership.CLUSTER_ID_LEN]u8 = undefined;
            try stdx.io.instance().randomSecure(&cluster_id);
            const founding = membership.Config.founding(node_id, cluster_id);
            switch (try raft.proposeConfig(&founding)) {
                .proposed => {},
                else => return error.FoundingRefused,
            }
            if (empty) log.warn("shard {d}: founding a new cluster at term 1; if this node was a member of an existing cluster, stop it and restart with --join", .{shard_id}) else log.info("shard {d}: first member; leading a group of one", .{shard_id});
        },
        .join => {
            raft.commit_index = raft.last_applied;
            raft.timer_enabled = false;
            raft.self_named = false;
            // No log, or a log with no config and no hard state: a new node
            // and one that lost its disk look the same, and whatever the
            // latter voted for or acked is gone. Durable before it answers
            // anyone.
            const guard = empty or !had_hard_state;
            if (guard) try raft.enterLostLog();
            log.info("shard {d}: joining{s}; following until a config entry names this node", .{ shard_id, if (guard) " with nothing in the log and no hard state to vote from; voting only once caught up and the term is confirmed" else "" });
        },
    }
}

/// The config entry committed: what it names is the membership a
/// truncation falls back to.
fn applyRaftConfig(ctx: *anyopaque, entry: *const entry_mod.Entry, _: *persistence_mod.Result) persistence_mod.ApplyError!void {
    const raft: *RaftNode = @ptrCast(@alignCast(ctx));
    const cfg = membership.decode(entry.payload) orelse return error.Halt;
    raft.commitMembership(&cfg, entry.header.index);
    // At boot, replay applies the committed configs before the group comes
    // up: a node that lost its hard state checks the committed set even
    // when its latest config is not.
    raft.recordConfig(entry.header.index, entry.header.term, &cfg);
    var ids: [membership.MAX_MEMBERS]u32 = undefined;
    var voters: [membership.MAX_MEMBERS]u32 = undefined;
    log.info("Raft: membership committed: {any}, voters {any} (config index {d})", .{ cfg.ids(&ids), cfg.voterIds(&voters), entry.header.index });
}

/// After every shard of the node has replayed and before any runs: shard
/// 0 proposes no id another shard has bound. Its own log decides `next_id`,
/// and a log that lost its tail (damage, salvage) may have forgotten a
/// create whose id another shard's data is keyed by.
pub fn raiseNamespaceIdFloor(shards: []Shard) void {
    if (shards.len == 0) return;
    for (shards[1..]) |*s| {
        if (s.namespace_handler.highestId()) |id| shards[0].namespace_handler.raiseIdFloor(id);
        // Some writes stamp a published namespace's id without binding it
        // here first (a group read makes its group), so what was applied
        // counts too.
        const named = s.defaultPartition().highest_namespace;
        if (named != 0) shards[0].namespace_handler.raiseIdFloor(named);
    }
}

/// Raise `partition.highest_namespace` by the entry's namespace ids.
/// The fixed ids sit below every allocated one, and an id past the table
/// was never allocated, so neither can collide with a later create.
fn noteNamespace(partition: *Partition, entry: *const entry_mod.Entry) void {
    const id = entryNamespaceId(entry) orelse return;
    if (id < ns_table.FIRST_ALLOCATED.int() or id >= ns_table.CAPACITY) return;
    partition.highest_namespace = @max(partition.highest_namespace, id);
}

/// The highest namespace id an entry names, or null for none. Read by
/// payload layout, not by entry type, so a new entry is covered by its
/// layout: a command payload leads with the id; a table entry leads with
/// an `ns` id, a KV key (the id is its prefix), or a list of items that
/// each lead with an `ns` id. A table entry holding an `ns` id anywhere
/// else fails the build (`nsLead`).
pub fn entryNamespaceId(entry: *const entry_mod.Entry) ?u32 {
    const code: u8 = entry.header.entry_type;
    inline for (table.entry_table) |e| {
        if (e.type_code == code) return payloadNamespaceId(e.payload, entry.payload);
    }
    const etype = std.enums.fromInt(entry_mod.EntryType, code) orelse return null;
    if (!etype.hasKeyValue() or entry.payload.len < 4) return null;
    return std.mem.readInt(u32, entry.payload[0..4], .little);
}

const NsLead = enum { none, id, kv_key, items };

fn isNsId(comptime f: schema.Field) bool {
    return std.mem.eql(u8, f.name, "ns") and f.T == kv_entries.NamespaceId;
}

fn holdsNsId(comptime T: type) bool {
    if (T.kind == .list) return holdsNsId(T.Element);
    if (T.kind != .record) return false;
    for (T.field_list) |f| if (isNsId(f) or holdsNsId(f.T)) return true;
    return false;
}

fn nsLead(comptime P: type) NsLead {
    const first = P.field_list[0];
    if (isNsId(first)) return .id;
    if (std.mem.eql(u8, first.name, "key") and first.T == kv_entries.Key) return .kv_key;
    if (first.T.kind == .list and first.T.Element.kind == .record and isNsId(first.T.Element.field_list[0])) return .items;
    if (holdsNsId(P)) @compileError("an entry names a namespace id other than up front; entryNamespaceId can't find it");
    return .none;
}

fn payloadNamespaceId(comptime P: type, payload: []const u8) ?u32 {
    var diag: schema.Diagnostic = .{};
    var r: schema.Reader = .{ .bytes = payload, .diag = &diag };
    switch (comptime nsLead(P)) {
        .none => return null,
        .id => return kv_entries.NamespaceId.decode(&r, "") catch null,
        .kv_key => {
            const key = kv_entries.Key.decode(&r, "") catch return null;
            return if (key.len < 4) null else std.mem.readInt(u32, key[0..4], .big);
        },
        .items => {
            const items = P.field_list[0].T.decode(&r, "") catch return null;
            var it = items.iterator();
            var top: ?u32 = null;
            while (it.next() catch null) |item| top = @max(top orelse 0, item.ns);
            return top;
        },
    }
}

test "entryNamespaceId: an action entry, and an expire's items, name their namespace's id" {
    var buf: [512]u8 = undefined;
    const reg = try action_entries.Register.encodeInto(&buf, .{ .ns = 21, .name = "a", .owner = "", .lease_ms = 5000, .max_attempts = 1 });
    const e = entry_mod.buildEntry(.action_register, entry_mod.Flags.NONE, 1, 1, 1, reg);
    try std.testing.expectEqual(@as(?u32, 21), entryNamespaceId(&e));
    var items: [2 * action_entries.ExpireItem.max_size]u8 = undefined;
    var n: usize = 0;
    for ([_]u32{ 17, 30 }) |ns| n += (try action_entries.ExpireItem.encodeInto(items[n..], .{ .ns = ns, .action = "a", .run = "r", .expiry_ns = 1, .holder = "", .request_key = null })).len;
    const exp = try action_entries.Expire.encodeInto(&buf, .{ .items = .{ .bytes = items[0..n], .count = 2 } });
    const x = entry_mod.buildEntry(.action_expire, entry_mod.Flags.NONE, 1, 2, 1, exp);
    try std.testing.expectEqual(@as(?u32, 30), entryNamespaceId(&x));
}

pub fn raftRingCapacity(hot_buffer_capacity: usize) usize {
    return @max(RAFT_RING_MIN, @min(hot_buffer_capacity / 4, RAFT_RING_MAX));
}

/// What `applyEntryCore` made of an entry. Anything but `applied` is an
/// entry the projections are missing, counted on its own path.
pub const ApplyResult = union(enum) {
    applied,
    /// The partition refused it; nothing else saw it.
    partition_reject: anyerror,
    /// The projection the router owns could not apply it, and why.
    router_error: persistence_mod.ApplyError,
    /// Its registry applier could not apply it, and why.
    applier_failed: persistence_mod.ApplyError,
    /// No applier owns its type.
    no_applier,
};

/// An entry every replica fails the same way, and why. A shard halted at
/// it applies nothing from it on until a repair.
pub const Halt = struct {
    index: u64,
    term: u64,
    /// The entry's checksum: with its index and term, what a repair names.
    crc: u32,
    len: usize = 0,
    buf: [192]u8 = undefined,

    pub fn init(e: *const entry_mod.Entry, comptime fmt: []const u8, args: anytype) Halt {
        var h: Halt = .{ .index = e.header.index, .term = e.header.term, .crc = e.header.crc32c };
        // Too long for the buffer: kept cut short.
        h.len = if (std.fmt.bufPrint(&h.buf, fmt, args)) |w| w.len else |_| h.buf.len;
        return h;
    }

    pub fn reason(self: *const Halt) []const u8 {
        return self.buf[0..self.len];
    }
};

/// What an apply came to, for the shard: whether to go on.
const Verdict = union(enum) {
    applied,
    /// An index the partition already holds: counted, nothing lost.
    duplicate,
    /// No replica can apply it: why.
    halt: []const u8,
    /// This node couldn't, for want of memory or a disk; another may.
    local: silent_loss.Damage,
};

/// Why a shard halts at an entry whose apply crashed the node.
const CRASHED = "applying it crashed this node";

/// Judge one apply. Duplicates are counted here; losses are counted by
/// whoever acts on `local` (`Shard.damaged`, or boot's damage).
fn verdictOf(counts: *silent_loss.Counts, shard_id: u16, now_ms: u64, entry: *const entry_mod.Entry, result: ApplyResult) Verdict {
    const type_name = std.enums.tagName(entry_mod.EntryType, @fromBackingInt(@intCast(entry.header.entry_type))) orelse "unknown";
    const index = entry.header.index;
    return switch (result) {
        .applied => .applied,
        .partition_reject => |err| if (err == error.IndexNotIncreasing) blk: {
            counts.noteDuplicate(now_ms, shard_id, index, type_name);
            break :blk .duplicate;
        } else if (err == error.OutOfMemory)
            .{ .local = outOfMemory(silent_loss.Damage.init(.partition_reject, "entry {d} ({s}) could not be held: the partition is out of memory", .{ index, type_name })) }
        else
            .{ .halt = "the partition refused it" },
        .router_error => |err| if (err == error.Halt)
            .{ .halt = "its projection refused it as malformed" }
        else
            .{ .local = localDamage(err, silent_loss.Damage.init(.router_error, "entry {d} ({s}) could not be applied on this node: {s}", .{ index, type_name, applyErrorName(err) })) },
        .applier_failed => |err| if (err == error.Halt)
            .{ .halt = "its applier refused it as malformed" }
        else
            .{ .local = localDamage(err, silent_loss.Damage.init(.applier_failed, "entry {d} ({s}) could not be applied on this node: {s}", .{ index, type_name, applyErrorName(err) })) },
        .no_applier => .{ .halt = "no applier on this build takes its type" },
    };
}

fn outOfMemory(d: silent_loss.Damage) silent_loss.Damage {
    var m = d;
    m.out_of_memory = true;
    return m;
}

fn localDamage(err: persistence_mod.ApplyError, d: silent_loss.Damage) silent_loss.Damage {
    return if (err == error.OutOfMemory) outOfMemory(d) else d;
}

/// Entry types with nothing to apply: the term's no-op, and a repair skip,
/// whose effect is the shard's (`Shard.checkSkip`).
const APPLIES_NOTHING = [_]entry_mod.EntryType{ .raft_noop, .repair_skip };
/// Entry types nothing writes today. One that arrives anyway is counted as
/// having no applier.
const NEVER_WRITTEN = [_]entry_mod.EntryType{ .cg_create, .raft_snapshot };

fn listed(list: []const entry_mod.EntryType, etype: entry_mod.EntryType) bool {
    return std.mem.indexOfScalar(entry_mod.EntryType, list, etype) != null;
}

fn routedToProjection(etype: entry_mod.EntryType) bool {
    return switch (projection_router.routeTarget(etype)) {
        .ts => true,
        .none, .snapshot => false,
    };
}

/// The one apply path: the partition (hot ring plus the projection the
/// router owns: TS), then a contract machine for the types one owns (KV's,
/// actions', queues'), then the registry appliers for every other entry
/// type.
pub fn applyEntryCore(partition: *Partition, registry: *const ReplayRegistry, entry: *const entry_mod.Entry, out: *persistence_mod.Result) ApplyResult {
    return applyEntryCoreWith(&contract_machines.list, partition, registry, entry, out);
}

/// `applyEntryCore` over `machines`. A machine reads the partition's
/// streams as this entry finds them: every entry below it applied, in
/// index order, through this same function.
fn applyEntryCoreWith(comptime machines: []const contract_machine.Machine, partition: *Partition, registry: *const ReplayRegistry, entry: *const entry_mod.Entry, out: *persistence_mod.Result) ApplyResult {
    if (comptime build_options.test_faults) {
        if (@import("test_faults.zig").of(entry)) |f| {
            if (f == .halt) return .{ .applier_failed = error.Halt };
            @import("test_faults.zig").crash(f);
        }
    }
    const etype: entry_mod.EntryType = @fromBackingInt(@intCast(entry.header.entry_type));
    noteNamespace(partition, entry);
    const applied = partition.applyRouted(entry, out) catch |err| return .{ .partition_reject = err };
    if (routedToProjection(etype)) return if (applied.failed) |err| .{ .router_error = err } else .applied;
    if (contract_machine.ownerOf(machines, etype)) |m| {
        // The router has seen every index up to its own: one at or below it
        // was applied already, and must not be twice.
        if (applied.route == .skipped_already_applied) return .applied;
        contract_machine.applyEntryWith(m, &partition.store, &partition.apply_scratch, .{ .proj = &partition.stream }, entry, out) catch |err| return .{ .applier_failed = err };
        return .applied;
    }
    const had = registry.dispatch(entry, out) catch |err| return .{ .applier_failed = err };
    if (!had) return if (listed(&APPLIES_NOTHING, etype)) .applied else .no_applier;
    // A machine that follows this entry (a group, a trim of its stream),
    // after its owner, unless the owner refused it.
    if (out.refused() == null) if (contract_machine.observerOf(machines, etype)) |m| {
        contract_machine.observeEntry(m, &partition.store, &partition.apply_scratch, .{ .proj = &partition.stream }, entry) catch |err| return .{ .applier_failed = err };
    };
    return .applied;
}

fn applyErrorName(err: persistence_mod.ApplyError) []const u8 {
    return switch (err) {
        error.OutOfMemory => "out of memory",
        error.Io => "a disk write failed",
        error.Halt => "it breaks what the log holds true",
    };
}

/// Every entry type has exactly one applier (a contract machine, the
/// projection router or one registry callback) or is listed as needing none. Two appliers is how a
/// replayed entry gets inserted twice; none, how it is dropped; a second
/// registration, how one handler's applier never runs. Each is a bug in
/// this build, not in the data directory.
fn checkAppliers(shard_id: u16, registry: *const ReplayRegistry) !void {
    return checkAppliersWith(&contract_machines.list, shard_id, registry);
}

fn checkAppliersWith(comptime machines: []const contract_machine.Machine, shard_id: u16, registry: *const ReplayRegistry) !void {
    if (registry.duplicate) |etype| {
        log.err("shard {d}: entry type {s} was registered twice; this is a bug in this build, not in the data directory — refusing to start", .{ shard_id, @tagName(etype) });
        return error.EntryTypeRegisteredTwice;
    }
    const einfo = @typeInfo(entry_mod.EntryType).@"enum";
    inline for (einfo.field_names, einfo.field_values) |fname, fvalue| {
        const etype: entry_mod.EntryType = @fromBackingInt(@intCast(fvalue));
        const routed = routedToProjection(etype);
        // A machine's type has no other applier.
        const owner = contract_machine.ownerOf(machines, etype);
        if (owner) |m| if (routed or registry.has(etype)) {
            log.err("shard {d}: entry type {s} is owned by the {s} machine and has another applier too; this is a bug in this build, not in the data directory — refusing to start", .{ shard_id, fname, m.name });
            return error.EntryTypeHasTwoAppliers;
        };
        if (owner == null and routed and registry.has(etype)) {
            log.err("shard {d}: entry type {s} has two appliers (the projection router and a registry callback); this is a bug in this build, not in the data directory — refusing to start", .{ shard_id, fname });
            return error.EntryTypeHasTwoAppliers;
        }
        if (owner == null and !routed and !registry.has(etype) and !listed(&APPLIES_NOTHING, etype) and !listed(&NEVER_WRITTEN, etype)) {
            log.err("shard {d}: entry type {s} has no applier; this is a bug in this build, not in the data directory — refusing to start", .{ shard_id, fname });
            return error.EntryTypeHasNoApplier;
        }
    }
}

/// The sealed segments, after finishing any truncation a crash left
/// half done. Fails on a segment whose header will not read; the log names
/// it (`DurableLog.badHeaderSegment`).
fn listDurable(dl: *DurableLog) ![]const durable_log_mod.SegmentFile {
    try dl.recoverTruncation();
    return dl.segments();
}

/// Feed a durable entry back into the Raft log at boot: the last index, the
/// term index and the hot-ring tail all come from this pass. A hole is
/// damage: an entry this node committed is gone.
fn restoreRaftEntry(shard_id: u16, raft_log: *RaftLog, e: *const entry_mod.Entry) ?silent_loss.Damage {
    _ = raft_log.append(e) catch |err| switch (err) {
        error.IndexGap => {
            const tip = raft_log.lastIndex();
            if (e.header.index <= tip) {
                log.err("shard {d}: segments hold index {d} twice (log tip {d}); the later copy is ignored", .{ shard_id, e.header.index, tip });
                return null;
            }
            return silent_loss.Damage.init(.index_hole, "no segment holds entries {d}..{d}", .{ tip + 1, e.header.index - 1 });
        },
        else => log.err("shard {d}: cannot restore index {d}: {s}", .{ shard_id, e.header.index, @errorName(err) }),
    };
    return null;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Segment Replay — recover state from .flseg files on startup
// ═══════════════════════════════════════════════════════════════════════════════

/// What boot replay did: the last index it applied, and the damage it
/// stopped at, if any.
const ReplayOutcome = struct {
    applied_through: u64 = 0,
    damage: ?silent_loss.Damage = null,
    /// The entry replay halted at: the rest of the log is restored, and
    /// none of it applied.
    halt: ?Halt = null,
    /// The stamp of the last entry applied.
    last_stamp: u64 = 0,
    /// Another shard's boot failed, and this one stopped early.
    cancelled: bool = false,
    /// A segment that would not open for want of resources.
    blocked: ?BlockedRead = null,
    /// Entries read back, for the progress lines.
    entries: u64 = 0,
    started_ms: u64 = 0,
    next_line_ms: u64 = 0,
};

const BlockedRead = struct { name: []const u8, err: anyerror };

/// A file boot could not read for a resource failure: that says nothing
/// about the log, so boot refuses rather than taking it as damage and
/// telling the operator to repair a log that is whole. An IO failure is
/// damage (`segmentOpenDamage`): with no bound on how long to wait, a
/// failing disk would otherwise stop the node at every start.
fn refuseBlockedRead(shard_id: u16, name: []const u8, err: anyerror) error{BootReadBlocked} {
    log.err("shard {d}: {s} could not be read at boot ({s}), a resource failure. A restart may succeed; the node will not start until it can read it", .{ shard_id, name, @errorName(err) });
    return error.BootReadBlocked;
}

/// Whether a read that failed at boot refuses the boot rather than being
/// taken as damage: only for want of resources.
fn bootRefuses(err: anyerror) bool {
    return DurableLog.readBlockClass(err) == .resource;
}

/// What a segment that won't open is, as damage.
fn segmentOpenDamage(name: []const u8, err: anyerror) silent_loss.Damage {
    if (DurableLog.isPermission(err)) return silent_loss.Damage.init(.segment_unreadable, "segment {s}: permission denied; fix the file's permissions and restart", .{name});
    if (DurableLog.readBlockClass(err) == .disk) return silent_loss.Damage.init(.segment_unreadable, "segment {s} is unreadable ({s}); the disk may be failing", .{ name, @errorName(err) });
    return silent_loss.Damage.init(.segment_unreadable, "segment {s} is unreadable ({s})", .{ name, @errorName(err) });
}

/// How often a long replay says how far it has got.
const REPLAY_PROGRESS_MS: u64 = 5_000;

/// The committed repair skips in the log: those at or below `watermark`,
/// the one index boot knows committed, in the segments whose header says
/// they hold one. Every flush seals a whole segment, so there is no open
/// tail on disk to miss. A skip above the watermark, or not yet in this
/// replica's log (a follower behind the majority that committed it), is
/// honoured once it arrives. Until then a build that halts at the entry
/// halts and waits, and one that doesn't applies it first and then
/// diverges (`Shard.checkSkip`): the one window, a repair and an upgrade
/// at the same moment, widest for a lagging follower.
///
/// A log that starts after a snapshot needs nothing more: a skip comes
/// after its entry, so a snapshot past the skip covers both, and one
/// between them leaves a skip for an entry the log no longer holds.
fn collectSkips(allocator: std.mem.Allocator, files: []const durable_log_mod.SegmentFile, watermark: u64, skips: *repair.Skips, shard_id: u16) !?silent_loss.Damage {
    for (files) |sf| {
        if (!sf.holds_skip or sf.first_index > watermark) continue;
        const name = std.fs.path.basename(sf.path);
        const opened = SegmentReader.initFromFile(allocator, sf.path) catch |err| {
            if (bootRefuses(err)) return refuseBlockedRead(shard_id, name, err);
            return segmentOpenDamage(name, err);
        };
        defer allocator.free(opened.buf);
        var offset: usize = 0;
        const data_len = opened.reader.data_end - opened.reader.data_start;
        while (offset < data_len) {
            const e = opened.reader.readEntryAt(offset) orelse {
                return silent_loss.Damage.init(.segment_bad_entry, "segment {s} holds an entry at byte {d} that will not parse", .{ name, offset });
            };
            offset += e.totalSize();
            if (e.header.index > watermark) break;
            const skip = repair.Skip.decode(&e) orelse continue;
            if (skip.index >= e.header.index) continue;
            try skips.add(allocator, &skip);
        }
    }
    return null;
}

/// Whether a committed repair skips `e` on this shard. A skip entry itself
/// is never skipped: it changes nothing a pass-over would leave out.
fn skippedHere(skips: *const repair.Skips, e: *const entry_mod.Entry) bool {
    return !isSkip(e) and skips.skips(e);
}

fn isSkip(e: *const entry_mod.Entry) bool {
    return e.header.entry_type == @backingInt(entry_mod.EntryType.repair_skip);
}

/// Replay all .flseg segment files in `dir_path`: every entry is restored
/// into the Raft log and applied through `applyEntryCore`, exactly as when
/// it was first committed. Replay stops at the first damage: what follows
/// it would apply over a hole.
///
/// Entries above `watermark` are restored into the Raft log but not applied.
fn replaySegments(
    allocator: std.mem.Allocator,
    files: []const durable_log_mod.SegmentFile,
    partition: *Partition,
    replay_registry: *const ReplayRegistry,
    watermark: u64,
    raft_log: *RaftLog,
    shard_id: u16,
    losses: *silent_loss.Counts,
    marker: *apply_marker.Marker,
    skips: *const repair.Skips,
    boot: Shard.Boot,
) ReplayOutcome {
    // Listed in Raft index order so the projection router's applied_index
    // guard does not skip lower-index entries.
    const now = Shard.nowMs();
    var out: ReplayOutcome = .{ .started_ms = now, .next_line_ms = now + REPLAY_PROGRESS_MS };
    var last: u64 = 0;
    for (files) |sf| last = @max(last, sf.last_index);
    if (boot.health) |slot| slot.replay_last.store(last, .monotonic);
    for (files) |sf| {
        // Before reading and checksumming a whole segment it would not use.
        if (boot.cancelled()) {
            out.cancelled = true;
            break;
        }
        replaySegmentFile(allocator, sf.path, partition, replay_registry, watermark, raft_log, shard_id, losses, marker, skips, boot, last, &out);
        if (out.damage != null or out.cancelled or out.blocked != null) break;
    }
    if (out.entries > 0 and !out.cancelled) {
        log.info("shard {d}: replayed {d} entries in {d} ms", .{ shard_id, out.entries, Shard.nowMs() -| out.started_ms });
    }
    return out;
}

fn replaySegmentFile(
    allocator: std.mem.Allocator,
    full_path: []const u8,
    partition: *Partition,
    replay_registry: *const ReplayRegistry,
    watermark: u64,
    raft_log: *RaftLog,
    shard_id: u16,
    losses: *silent_loss.Counts,
    marker: *apply_marker.Marker,
    skips: *const repair.Skips,
    boot: Shard.Boot,
    last: u64,
    out: *ReplayOutcome,
) void {
    const name = std.fs.path.basename(full_path);
    // One result for the segment's entries, reset for each.
    var replay_result: persistence_mod.Result = .{};
    // Sealed segments are written whole and renamed into place, so one
    // that will not open, or fails its checksum, is damage, never a crash;
    // one that won't open for want of resources refuses the boot.
    const opened = SegmentReader.initFromFile(allocator, full_path) catch |err| {
        if (bootRefuses(err)) {
            out.blocked = .{ .name = name, .err = err };
            return;
        }
        out.damage = segmentOpenDamage(name, err);
        return;
    };
    defer allocator.free(opened.buf);

    var offset: usize = 0;
    const data_len = opened.reader.data_end - opened.reader.data_start;
    while (offset < data_len) {
        // The checksum held, so an entry that will not parse was written
        // that way: a writer or format bug.
        const seg_entry = opened.reader.readEntryAt(offset) orelse {
            out.damage = silent_loss.Damage.init(.segment_bad_entry, "segment {s} holds an entry at byte {d} that will not parse", .{ name, offset });
            return;
        };
        // An active segment has no whole-file checksum: each entry its own.
        // Recovery cut a torn tail past its mark, so one failing here was
        // recorded whole.
        if (!opened.reader.header.sealed()) seg_entry.validate() catch |err| {
            out.damage = silent_loss.Damage.init(.segment_bad_entry, "segment {s} holds an entry at byte {d} that fails its check ({s})", .{ name, offset, @errorName(err) });
            return;
        };
        // Apply switches on the type byte as an exhaustive enum: a type this
        // build doesn't know (retired, or a corrupt byte) must stop here.
        if (std.enums.fromInt(entry_mod.EntryType, seg_entry.header.entry_type) == null) {
            out.damage = silent_loss.Damage.init(.segment_bad_entry, "segment {s} holds an entry at byte {d} of unknown type 0x{x:0>2}", .{ name, offset, seg_entry.header.entry_type });
            return;
        }
        offset += seg_entry.totalSize();

        if (boot.cancelled()) {
            out.cancelled = true;
            return;
        }
        out.entries += 1;
        if (boot.health) |slot| slot.replay_index.store(seg_entry.header.index, .monotonic);
        if (out.entries % 4096 == 0) {
            const now = Shard.nowMs();
            if (now >= out.next_line_ms) {
                out.next_line_ms = now + REPLAY_PROGRESS_MS;
                log.info("shard {d} replaying: index {d} of {d}", .{ shard_id, seg_entry.header.index, last });
            }
        }

        // Every durable entry is part of the Raft log.
        if (restoreRaftEntry(shard_id, raft_log, &seg_entry)) |damage| {
            out.damage = damage;
            return;
        }

        // Above the watermark: in the log, not yet in the projections.
        // Past a halt: in the log, and nothing of it applies until a repair.
        if (seg_entry.header.index > watermark or out.halt != null) continue;

        // A repair skips it: taken as a halt on it left a replica that
        // halted live, and its applier never runs.
        if (skippedHere(skips, &seg_entry)) {
            partition.passOverSkipped(&seg_entry) catch |err| {
                out.damage = localDamage(err, silent_loss.Damage.init(.partition_reject, "entry {d}, which a repair skips, could not be passed over on this node: {s}", .{ seg_entry.header.index, @errorName(err) }));
                return;
            };
            log.info("shard {d}: entry {d} is skipped by a repair; passing over it", .{ shard_id, seg_entry.header.index });
            out.applied_through = seg_entry.header.index;
            continue;
        }
        if (out.last_stamp != 0 and seg_entry.header.timestamp_ns <= out.last_stamp and !isSkip(&seg_entry)) {
            out.halt = Halt.init(&seg_entry, "entry {d}: its stamp {d} is not after the last applied entry's, {d} (a Flo bug)", .{ seg_entry.header.index, seg_entry.header.timestamp_ns, out.last_stamp });
            continue;
        }
        // Nobody waits on a replayed entry's answer.
        replay_result.reset(&seg_entry);
        const verdict: Verdict = if (marker.crashedOn(&seg_entry)) .{ .halt = CRASHED } else v: {
            const prev = apply_marker.begin(marker, &seg_entry);
            defer apply_marker.end(prev);
            break :v verdictOf(losses, shard_id, Shard.nowMs(), &seg_entry, applyEntryCore(partition, replay_registry, &seg_entry, &replay_result));
        };
        switch (verdict) {
            .applied, .duplicate => {},
            .halt => |why| {
                const type_name = std.enums.tagName(entry_mod.EntryType, @fromBackingInt(@intCast(seg_entry.header.entry_type))) orelse "unknown";
                out.halt = Halt.init(&seg_entry, "entry {d} ({s}): {s} (a Flo bug)", .{ seg_entry.header.index, type_name, why });
                continue;
            },
            .local => |damage| {
                out.damage = damage;
                return;
            },
        }
        // A skip is exempt from the stamp check, so it may be stamped
        // before the entry ahead of it; the applied stamp never goes back,
        // as live.
        out.last_stamp = @max(out.last_stamp, seg_entry.header.timestamp_ns);
        out.applied_through = seg_entry.header.index;
    }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Tests
// ═══════════════════════════════════════════════════════════════════════════════

/// Apply an entry through a handler's applier, as the log does.
fn applyLoggedTo(handler: anytype, e: *const entry_mod.Entry) !void {
    var out = persistence_mod.Result.start(e);
    try handler.replayEntry(e, &out);
}

const action_entries = @import("../protocol/action_entries.zig");
const action_machine = @import("../actions/machine.zig");

/// An action entry applied to `shard`'s store, as its log applies it.
fn applyActionEntry(shard: *Shard, comptime etype: entry_mod.EntryType, body: anytype, index: u64, stamp_ns: u64) !persistence_mod.Result {
    const buf = try std.testing.allocator.alloc(u8, 70_000);
    defer std.testing.allocator.free(buf);
    const e = try ActionsHandler.for_tests.entry(etype, body, 1, index, stamp_ns, buf);
    var out = persistence_mod.Result.start(&e);
    const p = shard.defaultPartition();
    try contract_machine.applyEntry(&action_machine.machine, &p.store, &p.apply_scratch, &e, &out);
    return out;
}

/// An action entry proposed, as its handler proposes it.
fn proposeAction(shard: *Shard, comptime etype: entry_mod.EntryType, body: anytype) !raft_node_mod.ProposeResult {
    const buf = try std.testing.allocator.alloc(u8, 70_000);
    defer std.testing.allocator.free(buf);
    const P = action_entries.Payload(@backingInt(etype));
    return shard.raft_node.propose(etype, entry_mod.Flags.NONE, try P.encodeInto(buf, body));
}

fn testRegister(name: []const u8) action_entries.Register.Value {
    return .{ .ns = ns_table.DEFAULT.int(), .name = name, .owner = "", .lease_ms = 300_000, .max_attempts = 3 };
}

fn testInvoke(name: []const u8, run_id: []const u8) action_entries.Invoke.Value {
    return .{ .ns = ns_table.DEFAULT.int(), .action = name, .run = run_id, .input = "{}", .labels = null, .source = .direct, .caller_run = null, .caller_workflow = null, .caller_shard = null };
}

test "Shard: init and deinit" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    // Its mapped buffers bypass the testing allocator's leak check: they
    // are counted, and every one comes back at deinit.
    const mapped = large_buffer.mapped_bytes.load(.monotonic);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer std.testing.expectEqual(mapped, large_buffer.mapped_bytes.load(.monotonic)) catch @panic("a shard's mapped buffer was not freed");
    defer shard.deinit();
    try std.testing.expect(large_buffer.mapped_bytes.load(.monotonic) > mapped);

    try std.testing.expectEqual(@as(u16, 0), shard.id);
    try std.testing.expectEqual(@as(u32, 0), shard.connectionCount());
    try std.testing.expect(!shard.stop_requested.load(.acquire));
}

test "Shard: add and remove connections" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();

    // Create test pipes to use as fake connection fds
    const conn_pipe = try @import("stdx").io.pipe();
    defer _ = std.c.close(conn_pipe[0]);
    defer _ = std.c.close(conn_pipe[1]);

    const conn = try shard.addConnection(conn_pipe[0]);
    try std.testing.expectEqual(@as(u32, 1), shard.connectionCount());
    try std.testing.expectEqual(@as(u32, 1), conn.id);

    shard.removeConnection(conn_pipe[0]);
    try std.testing.expectEqual(@as(u32, 0), shard.connectionCount());
}

test "Shard: dispatch ping via pipe-based connection" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();

    // Track dispatched pings
    const PingTracker = struct {
        var ping_count: u32 = 0;

        fn handlePing(_: *anyopaque, _: *anyopaque, _: proto.Request) void {
            ping_count += 1;
        }
    };
    PingTracker.ping_count = 0;

    // Register ping handler
    shard.dispatcher.register(.ping, PingTracker.handlePing);

    // Create a fake connection
    const conn_pipe = try @import("stdx").io.pipe();
    // Note: conn_pipe[0] is owned by shard (closed in deinit), only close write end
    defer _ = std.c.close(conn_pipe[1]);

    const conn = try shard.addConnection(conn_pipe[0]);

    // Build a ping request
    const header = proto.RequestHeader.init(.ping, 1);
    const req = proto.Request{
        .header = header,
        .namespace = "",
        .key = "",
        .value = "",
    };

    // Dispatch it
    shard.runRequest(conn, req, .client);

    try std.testing.expectEqual(@as(u32, 1), PingTracker.ping_count);
    try std.testing.expectEqual(@as(u64, 1), shard.requests_dispatched);
    try std.testing.expectEqual(@as(u64, 1), conn.requests_total);
}

test "Shard: inbox shutdown message" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();

    try std.testing.expect(!shard.stop_requested.load(.acquire));

    // Send shutdown via inbox
    const sent = shard.mailbox.inbox.send(.{
        .tag = .shutdown,
        .src_shard = 1,

        .payload_len = 0,
        .sequence = 0,
        .payload_ptr = null,
        ._padding = .{ 0, 0, 0, 0, 0, 0, 0, 0 },
    });
    try std.testing.expect(sent);

    // Drain inbox
    const processed = shard.drainInbox();
    try std.testing.expectEqual(@as(usize, 1), processed);
    try std.testing.expect(shard.stop_requested.load(.acquire));
}

test "Shard: a founded cluster gets a random id, at generation 1, its next id past the founder" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var a = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 7, .bootstrap, .{}, .{});
    defer a.deinit();
    var b = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 7, .bootstrap, .{}, .{});
    defer b.deinit();
    const ca = a.raft_node.latest_config;
    const unset: [membership.CLUSTER_ID_LEN]u8 = @splat(0);
    try std.testing.expect(!std.mem.eql(u8, &unset, &ca.cluster_id));
    try std.testing.expect(!std.mem.eql(u8, &ca.cluster_id, &b.raft_node.latest_config.cluster_id));
    try std.testing.expectEqual(@as(u64, 1), ca.generation);
    try std.testing.expectEqual(@as(u32, 8), ca.next_id);
}

test "Shard: a first member leads a group of itself from the log; a joiner waits to be named" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var first = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 7, .bootstrap, .{}, .{});
    defer first.deinit();
    try std.testing.expectEqual(raft_node_mod.Role.leader, first.raft_node.role);
    // The term's noop, then the config naming this node; both committed.
    try std.testing.expectEqual(@as(u64, 2), first.raft_node.commit_index);
    try std.testing.expectEqual(@as(u64, 2), first.raft_node.log.last_config_index);
    try std.testing.expect(first.applyCommitted());
    var ids: [membership.MAX_MEMBERS]u32 = undefined;
    try std.testing.expectEqualSlices(u32, &.{7}, first.raft_node.memberIds(&ids));
    try std.testing.expectEqual(@as(u8, 1), first.raft_node.committed_config.member_count);
    try std.testing.expectEqual(@as(u32, 7), first.raft_node.committed_config.members[0].id);

    var joiner = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
    defer joiner.deinit();
    try std.testing.expectEqual(raft_node_mod.Role.follower, joiner.raft_node.role);
    try std.testing.expect(!joiner.raft_node.timer_enabled);
    try std.testing.expectEqual(@as(u64, 0), joiner.raft_node.commit_index);
    try std.testing.expectEqual(@as(usize, 0), joiner.raft_node.memberIds(&ids).len);
}

test "Shard: a joiner enters as a replica the lone voter commits alone; caught up, two become voters in one entry; a later change waits for the one in flight" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    try std.testing.expect(shard.applyCommitted());
    const raft = shard.raft_node;
    var ids: [membership.MAX_MEMBERS]u32 = undefined;

    // No ack needed: a replica counts toward nothing, so a joiner that
    // never answers cannot hold the leader.
    shard.handleJoinRequest(2);
    try std.testing.expectEqualSlices(u32, &.{ 1, 2 }, raft.memberIds(&ids));
    try std.testing.expect(!raft.latest_config.isVoter(2));
    try std.testing.expectEqual(raft.membership_index, raft.commit_index);
    try std.testing.expect(shard.applyCommitted());
    shard.handleJoinRequest(3);
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqualSlices(u32, &.{ 1, 2, 3 }, raft.committed_config.ids(&ids));

    // Both catch up: one entry makes three voters.
    const Ack = struct {
        fn all(r: *RaftNode, from: u32) void {
            const last = r.log.lastIndex();
            r.peers[r.peerIndex(from).?].sent_up_to = last;
            r.handleAppendResponse(.{ .term = r.current_term, .success = true, .match_index = last, .from = from });
        }
    };
    for (0..raft_node_mod.CAUGHT_UP_ACKS) |_| {
        Ack.all(raft, 2);
        Ack.all(raft, 3);
    }
    shard.adjustMembership(Shard.nowMs());
    try std.testing.expectEqual(@as(u8, 3), raft.latest_config.voterCount());
    Ack.all(raft, 2);
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(raft.membership_index, raft.commit_index);

    // With voters to answer, a change waits for its majority; the next one
    // waits for it.
    shard.handleJoinRequest(4);
    const pending = raft.membership_index;
    try std.testing.expect(raft.commit_index < pending);
    shard.handleJoinRequest(5);
    try std.testing.expect(!raft.latest_config.names(5));
    try std.testing.expectEqual(pending, raft.membership_index);
    // A member asking again changes nothing.
    shard.handleJoinRequest(2);
    try std.testing.expectEqual(pending, raft.membership_index);
}

