test "Shard: a wait of 0 answers at once with no waiter, and a wait over 5 minutes is refused rather than shortened" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);

    const Case = struct { op: proto.OpCode, tag: proto.OptionTag, ms: u32, key: []const u8, value: []const u8, status: proto.StatusCode, waits: bool };
    var await_buf: [64]u8 = undefined;
    const await_value = try ActionsHandler.for_tests.awaitBody(&await_buf, &.{"a"}, 0, null);
    const cases = [_]Case{
        .{ .op = .queue_dequeue, .tag = .block_ms, .ms = 0, .key = "q", .value = "", .status = .ok, .waits = false },
        .{ .op = .kv_get, .tag = .block_ms, .ms = 0, .key = "missing", .value = "", .status = .not_found, .waits = false },
        .{ .op = .action_await, .tag = .block_ms, .ms = 0, .key = "", .value = await_value, .status = .ok, .waits = false },
        .{ .op = .kv_get, .tag = .block_ms, .ms = waiter_pool_mod.MAX_BLOCK_MS, .key = "missing", .value = "", .status = .ok, .waits = true },
        .{ .op = .kv_get, .tag = .block_ms, .ms = waiter_pool_mod.MAX_BLOCK_MS + 1, .key = "missing", .value = "", .status = .bad_request, .waits = false },
    };
    for (cases, 0..) |case, i| {
        var opt_buf: [16]u8 = undefined;
        var opts = proto.OptionsBuilder.init(&opt_buf);
        try opts.addU32(case.tag, case.ms);
        const bytes = try testRequestWith(case.op, 30 + i, case.key, case.value, opt_buf[0..opts.offset]);
        defer std.testing.allocator.free(bytes);
        const active = shard.waiter_pool.totalActive();
        shard.runRequest(c.conn, try proto.Request.parse(bytes), .client);
        if (case.waits) {
            try std.testing.expectEqual(active + 1, shard.waiter_pool.totalActive());
            continue;
        }
        try std.testing.expectEqual(active, shard.waiter_pool.totalActive());
        var out: [512]u8 = undefined;
        const n = try readAnswer(c.pair[1], &shard, c.conn.fd, &out, @sizeOf(proto.ResponseHeader));
        const resp = try proto.Response.parse(out[0..n]);
        try std.testing.expectEqual(@as(u64, 30 + i), resp.header.request_id);
        try std.testing.expectEqual(@backingInt(case.status), resp.header.status);
    }
}

test "Shard: a proxy answer comes out whole; one the proxy refused comes out as an error, and the next is unaffected" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const proxy = shard.forward_proxy;
    var err_buf: [256]u8 = undefined;
    try std.testing.expect(shard.takeProxyAnswer(proxy, 1, &err_buf) == null);

    // Past the proxy's cap: an error naming the request, and nothing left behind.
    const huge = try std.testing.allocator.alloc(u8, Connection.MAX_WRITE_BUFFER - 1);
    defer std.testing.allocator.free(huge);
    @memset(huge, 'h');
    _ = proxy.queueWrite(huge[0..16]);
    try std.testing.expectEqual(@as(usize, 0), proxy.queueWrite(huge));
    const refused = shard.takeProxyAnswer(proxy, 2, &err_buf).?;
    defer refused.free(std.testing.allocator);
    const resp = try proto.Response.parse(refused.bytes());
    try std.testing.expectEqual(@backingInt(proto.StatusCode.internal_error), resp.header.status);
    try std.testing.expectEqual(@as(u64, 2), resp.header.request_id);
    try std.testing.expect(!proxy.write_overflow);
    try std.testing.expectEqual(@as(usize, 0), proxy.write_buf.readable());

    // Larger than the proxy's first buffer: whole.
    try std.testing.expectEqual(huge.len, proxy.queueWrite(huge));
    const whole = shard.takeProxyAnswer(proxy, 3, &err_buf).?;
    defer whole.free(std.testing.allocator);
    try std.testing.expectEqualSlices(u8, huge, whole.bytes());
}

/// A client request as it arrives on the wire, CRC set; the caller frees it.
/// Sends `bytes` to shard `target` as `route` would, once authorized.
fn forwardForTest(s: *Shard, target: u16, conn: *Connection, bytes: []const u8) !void {
    const req = try proto.Request.parse(bytes);
    s.forwardToShard(target, conn, req, run_mod.authorize(.anonymous, .client, req).ok);
}

fn testRequest(op: proto.OpCode, request_id: u64, key: []const u8, value: []const u8) ![]u8 {
    return testRequestWith(op, request_id, key, value, "");
}

fn testRequestWith(op: proto.OpCode, request_id: u64, key: []const u8, value: []const u8, options: []const u8) ![]u8 {
    return Shard.serializeRequest(std.testing.allocator, testReq(op, request_id, "", key, value, options));
}

/// Bodies for test requests: a ring, so the few built together stay valid.
var test_bodies: [8][160 * 1024]u8 = undefined;
var test_body_next: usize = 0;

/// A request as a client sends it. For a table op, `value` and `options`
/// become its body: kv.set's value, and kv.get's `block_ms` as a wait for
/// the key to exist, written by hand so a wait past its bound reaches the
/// server.
fn testReq(op: proto.OpCode, id: u64, ns: []const u8, key: []const u8, value: []const u8, options: []const u8) proto.Request {
    const header = proto.RequestHeader.init(op, id);
    if (!table.isOp(@backingInt(op))) return .{ .header = header, .namespace = ns, .key = key, .value = value, .options = options };
    const buf = &test_bodies[test_body_next % test_bodies.len];
    test_body_next += 1;
    return .{ .header = header, .namespace = ns, .key = key, .value = testBody(buf, op, value, options) };
}

fn testBody(buf: []u8, op: proto.OpCode, value: []const u8, options: []const u8) []const u8 {
    switch (op) {
        .kv_put => return table_run.op("kv.set").request.encodeInto(buf, .{ .value = value, .ttl_ms = null, .condition = .always, .cas_version = null, .txn = null }) catch unreachable,
        .kv_get => {
            const opts: proto.Request = .{ .header = undefined, .namespace = "", .key = "", .value = "", .options = options };
            var w: schema.Writer = .{ .buf = buf };
            if (if (opts.findOption(.block_ms)) |o| o.asU32() else null) |ms| {
                w.put(&.{1}) catch unreachable;
                w.int(u64, ms) catch unreachable;
                w.put(&.{ 1, @backingInt(kv_ops.WaitFor.exists) }) catch unreachable;
            } else w.put(&.{ 0, 0 }) catch unreachable;
            w.put(&.{0}) catch unreachable; // no txn
            return w.written();
        },
        // The namespace ops' bodies are empty records.
        .namespace_create, .namespace_delete, .namespace_info, .namespace_ensure => return "",
        // An await's body as given, its wait taken from `block_ms` if set.
        .action_await => {
            const opts: proto.Request = .{ .header = undefined, .namespace = "", .key = "", .value = "", .options = options };
            const ms = if (opts.findOption(.block_ms)) |o| o.asU32() orelse return value else return value;
            var diag: schema.Diagnostic = .{};
            var body = table_run.op("action.await").request.decodeAll(value, &diag) catch unreachable;
            body.block_ms = ms;
            return table_run.op("action.await").request.encodeInto(buf, body) catch unreachable;
        },
        .action_complete, .action_fail, .action_touch, .action_deliver => return value,
        // A dequeue's count and wait from its options, encoded as the op's
        // body would be but with the wait unbounded, so one past its bound
        // reaches the server.
        .queue_dequeue => {
            if (value.len > 0) return value;
            const opts: proto.Request = .{ .header = undefined, .namespace = "", .key = "", .value = "", .options = options };
            const ms: u64 = if (opts.findOption(.block_ms)) |o| o.asU32() orelse 0 else 0;
            const count: u32 = if (opts.findOption(.count)) |o| o.asU32() orelse 1 else 1;
            const Fields = table_run.op("queue.dequeue").request.field_list;
            const Wide = schema.Record(&.{ Fields[0], Fields[1], Fields[2], .{ .name = "block_ms", .T = schema.Defaulted(schema.Int(u64), 0) }, Fields[4] });
            return Wide.encodeInto(buf, .{ .consumer = "", .count = count, .lease_ms = null, .block_ms = ms, .ack = false }) catch unreachable;
        },
        .queue_complete, .queue_fail, .queue_touch => return value,
        else => unreachable,
    }
}

test "Shard: a forward's copy of a request keeps the client's table hash, and a foreign one doesn't parse" {
    // Named, as decoding names every request: an empty namespace decodes as "default", so its copy is longer.
    const put = try Shard.serializeRequest(std.testing.allocator, testReq(.kv_put, 3, proto.DEFAULT_NAMESPACE, "k", "v", ""));
    defer std.testing.allocator.free(put);
    const copy = try Shard.serializeRequest(std.testing.allocator, try proto.Request.parse(put));
    defer std.testing.allocator.free(copy);
    try std.testing.expectEqualSlices(u8, put, copy);
    try std.testing.expectEqual(proto.TABLE_HASH, (try proto.Request.parse(copy)).header.table_hash);

    var header = std.mem.bytesToValue(proto.RequestHeader, copy[0..@sizeOf(proto.RequestHeader)]);
    header.table_hash +%= 1;
    header.crc32 = header.computeCRC32(copy[@sizeOf(proto.RequestHeader)..]);
    @memcpy(copy[0..@sizeOf(proto.RequestHeader)], std.mem.asBytes(&header));
    try std.testing.expectError(error.TableMismatch, proto.Request.parse(copy));
}

/// A shard alone and a connected client socket pair, both ends non-blocking
/// as an accepted socket is.
const TestClient = struct {
    pair: [2]std.posix.fd_t,
    conn: *Connection,

    fn open(shard: *Shard) !TestClient {
        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        try @import("stdx").net.sysFcntlSetNonblocking(pair[1]);
        try @import("stdx").net.sysFcntlSetNonblocking(pair[0]);
        return .{ .pair = pair, .conn = try shard.addConnection(pair[0]) };
    }
};

test "Shard: a client that sends without reading is paced: its requests wait until its answers drain, then run in order" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    // A small kernel buffer, so unsent answers stay with the shard.
    const small: c_int = 4096;
    _ = std.c.setsockopt(c.pair[0], std.posix.SOL.SOCKET, std.posix.SO.SNDBUF, @ptrCast(&small), @sizeOf(c_int));

    const value = try std.testing.allocator.alloc(u8, 2 * Shard.PAUSE_READS_AT);
    defer std.testing.allocator.free(value);
    @memset(value, 'v');
    const put = try testRequest(.kv_put, 1, "k", value);
    defer std.testing.allocator.free(put);
    try std.testing.expectEqual(put.len, feedClient(c.pair[1], &shard, c.conn.fd, put));
    var drain: [4096]u8 = undefined;
    _ = try readAnswer(c.pair[1], &shard, c.conn.fd, &drain, @sizeOf(proto.ResponseHeader));

    // Three reads of it in one write: the first answer alone passes the
    // pause mark, so the other two wait unread.
    var gets: [3][]u8 = undefined;
    for (&gets, 0..) |*g, i| g.* = try testRequest(.kv_get, 11 + i, "k", "");
    defer for (gets) |g| std.testing.allocator.free(g);
    const all = try std.mem.concat(std.testing.allocator, u8, &gets);
    defer std.testing.allocator.free(all);
    try std.testing.expectEqual(@as(isize, @intCast(all.len)), std.c.write(c.pair[1], all.ptr, all.len));
    shard.readFromClient(c.conn.fd);
    try std.testing.expect(c.conn.reads_paused);
    try std.testing.expectEqual(gets[1].len + gets[2].len, c.conn.read_buf.readable());

    // Read on the client side: each drained answer lets the next request run.
    // kv.get answers [version:u64][value_len:u32][value][expires_at_ms: absent].
    const answer_len = @sizeOf(proto.ResponseHeader) + 8 + 4 + value.len + 1;
    const out = try std.testing.allocator.alloc(u8, 3 * answer_len);
    defer std.testing.allocator.free(out);
    var got: usize = 0;
    var tries: usize = 0;
    while (got < out.len and tries < 100_000) : (tries += 1) {
        shard.flushToClient(c.conn.fd);
        shard.settleConnections();
        const n = std.c.read(c.pair[1], out[got..].ptr, out.len - got);
        if (n > 0) got += @intCast(n);
    }
    try std.testing.expectEqual(out.len, got);
    for (0..3) |i| {
        const resp = try proto.Response.parse(out[i * answer_len ..][0..answer_len]);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
        try std.testing.expectEqual(@as(u64, 11 + i), resp.header.request_id);
    }
    try std.testing.expect(!c.conn.reads_paused);
}

test "Shard: a client that sends its whole pipeline before reading is unpaced once it stalls, and gets every answer; one that reads stays paced" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    const small: c_int = 4096;
    _ = std.c.setsockopt(c.pair[0], std.posix.SOL.SOCKET, std.posix.SO.SNDBUF, @ptrCast(&small), @sizeOf(c_int));
    _ = std.c.setsockopt(c.pair[1], std.posix.SOL.SOCKET, std.posix.SO.SNDBUF, @ptrCast(&small), @sizeOf(c_int));

    const value = @as([1024]u8, @splat('v'));
    const put = try testRequest(.kv_put, 1, "k", &value);
    defer std.testing.allocator.free(put);
    try std.testing.expectEqual(put.len, feedClient(c.pair[1], &shard, c.conn.fd, put));
    var drain: [4096]u8 = undefined;
    _ = try readAnswer(c.pair[1], &shard, c.conn.fd, &drain, @sizeOf(proto.ResponseHeader));

    // A thousand reads, all sent before any answer is read: their bytes
    // are more than the kernel buffers hold, so the client cannot finish
    // sending while paced; their answers (about 1 MiB) fit the cap.
    const count = 1000;
    var gets: [count][]u8 = undefined;
    for (&gets, 0..) |*g, i| g.* = try testRequest(.kv_get, 100 + i, "k", "");
    defer for (gets) |g| std.testing.allocator.free(g);
    const all = try std.mem.concat(std.testing.allocator, u8, &gets);
    defer std.testing.allocator.free(all);
    var sent: usize = 0;
    var tries: usize = 0;
    while (sent < all.len and tries < 10_000) : (tries += 1) {
        const n = std.c.write(c.pair[1], all[sent..].ptr, all.len - sent);
        if (n > 0) sent += @intCast(n);
        shard.readFromClient(c.conn.fd);
        shard.flushToClient(c.conn.fd);
        shard.settleConnections();
        // Time passes with the client reading nothing.
        if (c.conn.reads_paused) {
            c.conn.paused_progress_ms -|= Shard.STALL_MS;
            shard.stall_check_ms = 0;
        }
    }
    try std.testing.expectEqual(all.len, sent);
    // Unpaced until it drains: not paused again with its answers unread.
    shard.readFromClient(c.conn.fd);
    shard.settleConnections();
    try std.testing.expect(c.conn.pacing_off);
    try std.testing.expect(!c.conn.reads_paused);
    try std.testing.expect(c.conn.write_buf.readable() > Shard.PAUSE_READS_AT);

    // kv.get answers [version:u64][value_len:u32][value][expires_at_ms: absent].
    const answer_len = @sizeOf(proto.ResponseHeader) + 8 + 4 + value.len + 1;
    const out = try std.testing.allocator.alloc(u8, count * answer_len);
    defer std.testing.allocator.free(out);
    var got: usize = 0;
    tries = 0;
    while (got < out.len and tries < 100_000) : (tries += 1) {
        shard.readFromClient(c.conn.fd);
        shard.flushToClient(c.conn.fd);
        shard.settleConnections();
        const n = std.c.read(c.pair[1], out[got..].ptr, out.len - got);
        if (n > 0) got += @intCast(n);
    }
    try std.testing.expectEqual(out.len, got);
    for (0..count) |i| {
        const resp = try proto.Response.parse(out[i * answer_len ..][0..answer_len]);
        try std.testing.expectEqual(@as(u64, 100 + i), resp.header.request_id);
    }
    try std.testing.expect(!c.conn.pacing_off);
    try std.testing.expect(!c.conn.closing);

    // A paused client that reads something is not unpaced; while paused,
    // nothing more of what it sends is taken.
    const again = try std.mem.concat(std.testing.allocator, u8, gets[0..90]);
    defer std.testing.allocator.free(again);
    try std.testing.expectEqual(@as(isize, @intCast(again.len)), std.c.write(c.pair[1], again.ptr, again.len));
    shard.readFromClient(c.conn.fd);
    try std.testing.expect(c.conn.reads_paused);
    const held = c.conn.read_buf.readable();
    try std.testing.expectEqual(@as(isize, 40), std.c.write(c.pair[1], all.ptr, 40));
    shard.readFromClient(c.conn.fd);
    try std.testing.expectEqual(held, c.conn.read_buf.readable());
    c.conn.paused_progress_ms -|= Shard.STALL_MS;
    try std.testing.expect(std.c.read(c.pair[1], &drain, drain.len) > 0);
    shard.flushToClient(c.conn.fd);
    shard.stall_check_ms = 0;
    shard.settleConnections();
    try std.testing.expect(c.conn.reads_paused);
}

test "Shard: a connection marked closing runs no more of its requests and is closed at the end of the tick" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    const fd = c.conn.fd;

    // The first answer finds the connection over its cap, so the flush
    // after it marks the connection closing; the second request must not run.
    c.conn.write_overflow = true;
    var pings: [2][]u8 = undefined;
    for (&pings, 0..) |*p, i| p.* = try testRequest(.kv_get, 21 + i, "k", "");
    defer for (pings) |p| std.testing.allocator.free(p);
    const both = try std.mem.concat(std.testing.allocator, u8, &pings);
    defer std.testing.allocator.free(both);
    try std.testing.expectEqual(@as(isize, @intCast(both.len)), std.c.write(c.pair[1], both.ptr, both.len));
    shard.readFromClient(fd);
    try std.testing.expectEqual(@as(u64, 1), shard.requests_dispatched);
    // Still open for whoever up the stack holds it; gone once settled.
    try std.testing.expect(shard.getConnection(fd) != null);
    shard.settleConnections();
    try std.testing.expect(shard.getConnection(fd) == null);
}

/// Two shards of one node, wired to each other as the runtime wires them.
const TwoShards = struct {
    pipes: [2][2]std.posix.fd_t,
    shards: [2]Shard,
    mailboxes: [2]*Mailbox,
    peers: [2]*Shard,
    /// The node's namespace table, as the runtime shares it.
    namespaces: *@import("../namespace/table.zig").Table,

    fn init(self: *TwoShards) !void {
        self.namespaces = try @import("../namespace/table.zig").Table.create(std.testing.allocator);
        for (&self.pipes, 0..) |*p, i| {
            p.* = try @import("stdx").io.pipe();
            self.shards[i] = try Shard.init(std.testing.allocator, @intCast(i), 2, 4096, p[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{ .namespaces = self.namespaces });
        }
        for (0..2) |i| {
            self.mailboxes[i] = self.shards[i].mailbox;
            self.peers[i] = &self.shards[i];
        }
        for (&self.shards) |*s| {
            s.peer_mailboxes = &self.mailboxes;
            s.peer_shards = &self.peers;
        }
    }

    /// Each shard takes what the other sent it, until neither has more:
    /// requests run, and their answers come back. What committed applies,
    /// and shard 0 publishes its namespaces, as each tick does.
    fn settle(self: *TwoShards) void {
        while (true) {
            var n: usize = 0;
            // Replies count too: a gather completes on one.
            for (&self.shards) |*s| n += s.mailbox.replies.pending() + s.drainInbox();
            for (&self.shards) |*s| {
                const before = s.raft_node.last_applied;
                _ = s.applyCommitted();
                n += @intCast(s.raft_node.last_applied - before);
            }
            const nh = self.shards[0].namespace_handler;
            const waiting = nh.waiters.items.len + nh.unpublished.items.len;
            nh.settle(&self.shards[0]);
            n += waiting - (nh.waiters.items.len + nh.unpublished.items.len);
            if (n == 0) return;
        }
    }

    fn deinit(self: *TwoShards) void {
        for (&self.shards) |*s| s.deinit();
        self.namespaces.destroy();
        for (self.pipes) |p| {
            _ = std.c.close(p[0]);
            _ = std.c.close(p[1]);
        }
    }
};

/// The next answer on a test client's socket, parsed.
fn nextAnswer(c: TestClient, shard: *Shard, out: []u8) !proto.Response {
    const n = try readAnswer(c.pair[1], shard, c.conn.fd, out, @sizeOf(proto.ResponseHeader));
    return proto.Response.parse(out[0..n]);
}

/// kv.get inside transaction `id`, its body in `buf`.
fn txnGet(buf: []u8, id: u64) proto.Request {
    const body = table_run.op("kv.get").request.encodeInto(buf, .{ .wait_ms = 0, .wait_for = .exists, .txn = id }) catch unreachable;
    return .{ .header = proto.RequestHeader.init(.kv_get, 9), .namespace = "", .key = "k", .value = body };
}

test "Shard: a kv.mget another shard sent refuses a key it doesn't own, and answers its own" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    // A key each shard owns.
    var names: [2][8]u8 = undefined;
    var owned: [2]?[]const u8 = .{ null, null };
    var i: u8 = 0;
    while (owned[0] == null or owned[1] == null) : (i += 1) {
        var scratch: [8]u8 = undefined;
        const k = try std.fmt.bufPrint(&scratch, "k{d}", .{i});
        const owner = b.router.partitionToShard(b.router.hashToPartition(node_router.routeNsKey(.default, k)));
        if (owned[owner] == null) {
            @memcpy(names[owner][0..k.len], k);
            owned[owner] = names[owner][0..k.len];
        }
    }

    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    c.conn.proxy_for = ReplyTo.socketOf(0, 99, 1);
    var body: [64]u8 = undefined;
    var out: [512]u8 = undefined;
    b.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.kv_mget, 5), .namespace = "", .key = "", .value = try mget_mod.pieceBody(&body, &.{owned[0].?}) }, .shard);
    const refused = try proto.Response.parse(out[0..c.conn.write_buf.read(&out)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.internal_error), refused.header.status);

    b.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.kv_mget, 6), .namespace = "", .key = "", .value = try mget_mod.pieceBody(&body, &.{owned[1].?}) }, .shard);
    const own = try proto.Response.parse(out[0..c.conn.write_buf.read(&out)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), own.header.status);
}

test "Shard: a request in a transaction goes to the shard its id names, and commit and rollback by the id alone" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const makeId = txn_mod.makeId;

    var buf: [64]u8 = undefined;
    // Another shard's id goes there; this shard's, or a shard that doesn't
    // exist, runs here, where the second is refused as no transaction.
    for ([_]struct { id: u64, to: ?u16 }{
        .{ .id = makeId(1, 7), .to = 1 },
        .{ .id = makeId(0, 7), .to = null },
        .{ .id = makeId(9, 7), .to = null },
    }) |case| {
        switch (a.resolveTarget(@backingInt(proto.OpCode.kv_get), txnGet(&buf, case.id))) {
            .local => try std.testing.expectEqual(@as(?u16, null), case.to),
            .shard => |t| try std.testing.expectEqual(case.to.?, t.shard_id),
        }
    }
    inline for (.{ "kv.txn.commit", "kv.txn.rollback" }) |name| {
        const op = table_run.op(name);
        var body_buf: [16]u8 = undefined;
        const body = try op.request.encodeInto(&body_buf, .{ .txn = makeId(1, 3) });
        const req: proto.Request = .{ .header = proto.RequestHeader.init(@fromBackingInt(@intCast(op.code)), 4), .namespace = "", .key = "", .value = body };
        switch (a.resolveTarget(op.code, req)) {
            .local => return error.TestUnexpectedResult,
            .shard => |t| try std.testing.expectEqual(@as(u16, 1), t.shard_id),
        }
    }
}

test "Shard: kv.mget runs where it lands, and tagged keys another shard owns are answered through the gather" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const shardOf = struct {
        fn of(sh: *Shard, key: []const u8) u16 {
            // Parsed requests name the default namespace "default".
            return sh.router.partitionToShard(sh.router.hashToPartition(node_router.routeNsKey(.default, key)));
        }
    }.of;
    const a = &two.shards[0];
    // Two keys sharing a {tag} that shard 1 owns, and one shard 0 owns.
    var name_bufs: [3][16]u8 = undefined;
    const tagged = for (0..64) |i| {
        const k = try std.fmt.bufPrint(&name_bufs[0], "{{t{d}}}a", .{i});
        if (shardOf(a, k) == 1) break k;
    } else return error.TestUnexpectedResult;
    const close = i: {
        @memcpy(name_bufs[1][0..tagged.len], tagged);
        name_bufs[1][tagged.len - 1] = 'b';
        break :i name_bufs[1][0..tagged.len];
    };
    try std.testing.expectEqual(@as(u16, 1), shardOf(a, close));
    const own = for (0..64) |i| {
        const k = try std.fmt.bufPrint(&name_bufs[2], "own{d}", .{i});
        if (shardOf(a, k) == 0) break k;
    } else return error.TestUnexpectedResult;
    var qbuf: [limits.MAX_KV_KEY]u8 = undefined;
    try two.shards[1].defaultPartition().kv.putForTest(testKvKey(&qbuf, tagged), "va");
    try two.shards[1].defaultPartition().kv.putForTest(testKvKey(&qbuf, close), "vb");
    try two.shards[0].defaultPartition().kv.putForTest(testKvKey(&qbuf, own), "vo");

    const keys = [_][]const u8{ tagged, own, close };
    var body_buf: [128]u8 = undefined;
    const req: proto.Request = .{ .header = proto.RequestHeader.init(.kv_mget, 1), .namespace = "default", .ns_id = .default, .key = "", .value = try mget_mod.pieceBody(&body_buf, &keys) };
    // Nothing in the body picks a shard: it runs where it lands.
    switch (a.resolveTarget(@backingInt(proto.OpCode.kv_mget), req)) {
        .local => {},
        .shard => return error.TestUnexpectedResult,
    }

    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    a.runRequest(c.conn, req, .client);
    two.settle();
    var out: [4096]u8 = undefined;
    const resp = try nextAnswer(c, a, &out);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), resp.header.status);
    var diag: schema.Diagnostic = .{};
    const got = try table_run.op("kv.mget").response.decodeAll(resp.data, &diag);
    try std.testing.expectEqual(@as(?u16, null), got.next);
    try std.testing.expectEqual(@as(u16, keys.len), got.entries.count);
    var it = got.entries.iterator();
    for ([_][]const u8{ "va", "vo", "vb" }) |want| {
        const e = (try it.next()).?;
        try std.testing.expect(e.found);
        try std.testing.expectEqualStrings(want, e.value);
    }
}

/// Two shards with keys on each, and a client on shard 0 asking kv.mget:
/// the gather's tests.
const MgetGatherFixture = struct {
    two: TwoShards,
    client: TestClient,
    /// keys[i] is owned by shard i % 2, valued `vals[i]`.
    names: [8][12]u8,
    keys: [8][]const u8,
    body_buf: [512]u8,
    out: []u8,

    const N = 8;

    fn init(self: *MgetGatherFixture, value_len: usize) !void {
        try self.two.init();
        errdefer self.two.deinit();
        const a = &self.two.shards[0];
        var found: [2]usize = .{ 0, 0 };
        var i: usize = 0;
        while (found[0] + found[1] < N) : (i += 1) {
            var scratch: [12]u8 = undefined;
            const k = try std.fmt.bufPrint(&scratch, "key{d}", .{i});
            const owner = a.router.partitionToShard(a.router.hashToPartition(node_router.routeNsKey(.default, k)));
            const slot = 2 * found[owner] + owner;
            if (found[owner] == N / 2) continue;
            @memcpy(self.names[slot][0..k.len], k);
            self.keys[slot] = self.names[slot][0..k.len];
            found[owner] += 1;
        }
        const value = try std.testing.allocator.alloc(u8, value_len);
        defer std.testing.allocator.free(value);
        var qbuf: [limits.MAX_KV_KEY]u8 = undefined;
        for (self.keys, 0..) |k, n| {
            // Each value names its key, so order shows in the answer.
            @memset(value, @intCast('a' + n));
            try self.two.shards[n % 2].defaultPartition().kv.putForTest(testKvKey(&qbuf, k), value);
        }
        self.client = try TestClient.open(a);
        self.out = try std.testing.allocator.alloc(u8, proto.MAX_ANSWER_BYTES);
    }

    fn deinit(self: *MgetGatherFixture) void {
        std.testing.allocator.free(self.out);
        _ = std.c.close(self.client.pair[1]);
        self.two.deinit();
    }

    fn ask(self: *MgetGatherFixture, id: u64, keys: []const []const u8) !void {
        const a = &self.two.shards[0];
        a.runRequest(self.client.conn, .{ .header = proto.RequestHeader.init(.kv_mget, id), .namespace = "default", .key = "", .value = try mget_mod.pieceBody(&self.body_buf, keys) }, .client);
    }

    /// The next whole answer, however large.
    fn answer(self: *MgetGatherFixture) !proto.Response {
        const a = &self.two.shards[0];
        const head = @sizeOf(proto.ResponseHeader);
        var got = try readAnswer(self.client.pair[1], a, self.client.conn.fd, self.out, head);
        if (got < head) return error.IncompleteResponse;
        const header = @as(*align(1) const proto.ResponseHeader, @ptrCast(self.out.ptr)).*;
        const total = head + header.data_len;
        if (got < total) got += try readAnswer(self.client.pair[1], a, self.client.conn.fd, self.out[got..], total - got);
        return proto.Response.parse(self.out[0..got]);
    }

    /// Nothing left behind: every slot back, no gather open, and the
    /// client's in-flight count where it started.
    fn expectSettled(self: *MgetGatherFixture, in_flight: u16) !void {
        const a = &self.two.shards[0];
        try std.testing.expectEqual(@as(usize, 0), a.reply_pool.taken());
        try std.testing.expectEqual(@as(usize, 0), a.gathers.inUse());
        if (a.getConnection(self.client.conn.fd)) |conn| try std.testing.expectEqual(in_flight, conn.forwards_in_flight);
    }
};

test "Shard: kv.mget gathers keys from every shard that owns one, answered in the order asked" {
    var f: MgetGatherFixture = undefined;
    try f.init(8);
    defer f.deinit();
    try f.ask(1, &f.keys);
    // Nothing comes back until shard 1 has answered its part.
    try std.testing.expectEqual(@as(usize, 1), f.two.shards[0].gathers.inUse());
    try std.testing.expectEqual(@as(u16, 1), f.client.conn.forwards_in_flight);
    f.two.settle();
    const resp = try f.answer();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    var diag: schema.Diagnostic = .{};
    const got = try mget_mod.Response.decodeAll(resp.data, &diag);
    try std.testing.expectEqual(@as(?u16, null), got.next);
    try std.testing.expectEqual(@as(u16, MgetGatherFixture.N), got.entries.count);
    var it = got.entries.iterator();
    for (0..MgetGatherFixture.N) |n| {
        const e = (try it.next()).?;
        try std.testing.expect(e.found);
        try std.testing.expectEqual(@as(u8, @intCast('a' + n)), e.value[0]);
    }
    try f.expectSettled(0);
}

test "Shard: a gathered kv.mget too large for one answer stops at the first key left out, in the order asked" {
    var f: MgetGatherFixture = undefined;
    // Eight values of a sixth of an answer: some fit, the rest page.
    try f.init(mget_mod.Response.max_size / 6);
    defer f.deinit();
    try f.ask(1, &f.keys);
    f.two.settle();
    const resp = try f.answer();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    var diag: schema.Diagnostic = .{};
    const got = try mget_mod.Response.decodeAll(resp.data, &diag);
    const next = got.next orelse return error.TestExpectedNext;
    // Every key before `next` is answered, in order, from both shards.
    try std.testing.expectEqual(next, got.entries.count);
    try std.testing.expect(next >= 2 and next < MgetGatherFixture.N);
    var it = got.entries.iterator();
    for (0..next) |n| try std.testing.expectEqual(@as(u8, @intCast('a' + n)), (try it.next()).?.value[0]);
    try f.expectSettled(0);
}

/// Two shards each holding a list of names, under a walk op, and a client
/// on shard 0 asking for pages.
const WalkFixture = struct {
    two: TwoShards,
    client: TestClient,
    lists: [2]NameList,
    out: []u8,

    const NameList = struct {
        names: []const []const u8,
        refuse: bool = false,
        scans: u32 = 0,

        fn byOffset(ctx: *anyopaque, _: dispatcher_mod.WalkNamespace, _: []const u8, _: ?[]const u8, limit: u32) dispatcher_mod.NameWalker.ScanResult {
            const self: *NameList = @ptrCast(@alignCast(ctx));
            self.scans += 1;
            if (self.refuse) dispatcher_mod.noteScanShort();
            return .{ .items = self.names[0..@min(limit, self.names.len)], .next_cursor = null };
        }

        fn byKey(ctx: *anyopaque, _: dispatcher_mod.WalkNamespace, _: []const u8, after: ?[]const u8, limit: u32) dispatcher_mod.NameWalker.ScanResult {
            const self: *NameList = @ptrCast(@alignCast(ctx));
            self.scans += 1;
            var from: usize = 0;
            if (after) |a| {
                while (from < self.names.len and std.mem.order(u8, self.names[from], a) != .gt) from += 1;
            }
            const end = @min(from + limit, self.names.len);
            return .{ .items = self.names[from..end], .next_cursor = if (end < self.names.len) self.names[end - 1] else null };
        }

        fn handle(_: *anyopaque, _: *anyopaque, _: proto.Request) void {}
    };

    fn init(self: *WalkFixture, a: []const []const u8, b: []const []const u8, paged: bool) !void {
        try self.two.init();
        errdefer self.two.deinit();
        self.lists = .{ .{ .names = a }, .{ .names = b } };
        for (&self.two.shards) |*s| {
            if (paged)
                s.dispatcher.registerPagedWalk(.ts_list, NameList.handle, NameList.byKey)
            else
                s.dispatcher.registerWalk(.ts_list, NameList.handle, NameList.byOffset);
        }
        for (&self.two.shards, &self.lists) |*s, *list| {
            s.dispatcher.setWalkContext(.ts_list, @ptrCast(list));
        }
        self.client = try TestClient.open(&self.two.shards[0]);
        self.out = try std.testing.allocator.alloc(u8, proto.MAX_ANSWER_BYTES);
    }

    fn deinit(self: *WalkFixture) void {
        std.testing.allocator.free(self.out);
        _ = std.c.close(self.client.pair[1]);
        self.two.deinit();
    }

    /// One page: its names, appended to `names`, and its cursor, copied
    /// into `cursor_buf`; null on the last page.
    fn page(self: *WalkFixture, id: u64, limit: u32, cursor: []const u8, names: *std.ArrayListUnmanaged([]u8), cursor_buf: []u8) !?[]const u8 {
        var body: [4 + 2 + kv_ops.MAX_CURSOR]u8 = undefined;
        std.mem.writeInt(u32, body[0..4], limit, .little);
        @memcpy(body[4..][0..cursor.len], cursor);
        const a = &self.two.shards[0];
        a.runRequest(self.client.conn, .{ .header = proto.RequestHeader.init(.ts_list, id), .namespace = "default", .key = "", .value = body[0 .. 4 + cursor.len] }, .client);
        self.two.settle();
        const head = @sizeOf(proto.ResponseHeader);
        var got = try readAnswer(self.client.pair[1], a, self.client.conn.fd, self.out, head);
        const header = @as(*align(1) const proto.ResponseHeader, @ptrCast(self.out.ptr)).*;
        const total = head + header.data_len;
        // A page is one answer, whatever its shards held.
        try std.testing.expect(total <= proto.MAX_ANSWER_BYTES);
        if (got < total) got += try readAnswer(self.client.pair[1], a, self.client.conn.fd, self.out[got..], total - got);
        const resp = try proto.Response.parse(self.out[0..got]);
        if (resp.header.status != @backingInt(proto.StatusCode.ok)) return error.Refused;
        var r = @import("../util/wire.zig").WireReader.init(resp.data);
        const count = r.readU32().?;
        for (0..count) |_| try names.append(std.testing.allocator, try std.testing.allocator.dupe(u8, r.readLengthPrefixed(u16).?));
        const more = r.readU8().? != 0;
        const next = r.readLengthPrefixed(u16).?;
        try std.testing.expectEqual(more, next.len > 0);
        if (!more) return null;
        @memcpy(cursor_buf[0..next.len], next);
        return cursor_buf[0..next.len];
    }

    /// Every page at `limit`, in order: the names, and how many pages.
    fn pageThrough(self: *WalkFixture, limit: u32, names: *std.ArrayListUnmanaged([]u8)) !usize {
        var cursor_buf: [kv_ops.MAX_CURSOR]u8 = undefined;
        var cursor: []const u8 = "";
        var pages: usize = 0;
        while (pages < 1000) {
            pages += 1;
            cursor = (try self.page(pages, limit, cursor, names, &cursor_buf)) orelse return pages;
        }
        return error.EndlessWalk;
    }

    fn freeNames(names: *std.ArrayListUnmanaged([]u8)) void {
        for (names.items) |n| std.testing.allocator.free(n);
        names.deinit(std.testing.allocator);
    }
};

