test "Shard: a list reads each shard's names on that shard, never from the shard that took it" {
    for ([_]bool{ false, true }) |paged| {
        var f: WalkFixture = undefined;
        try f.init(&.{ "a1", "a2" }, &.{ "b1", "b2" }, paged);
        defer f.deinit();
