test "Shard: a processing sink in a namespace not yet published writes nothing until it is, then is held when the id puts its stream on another shard" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    const streams = [_]*StreamHandler{ a.stream_handler, b.stream_handler };
    for (&two.shards) |*s| {
        s.wireHandlerShardPtrs();
        s.processing_handler.setPeerStreamHandlers(&streams);
    }
    // A sink stream that id 0 would put here and the namespace's real id
    // puts on shard 1: routed before the publish, it lands on the wrong shard.
    const id = nextNamespaceId(a);
    var tbuf: [16]u8 = undefined;
    var i: usize = 0;
    const target = while (true) : (i += 1) {
        const t = try std.fmt.bufPrint(&tbuf, "out{d}", .{i});
        const before = a.router.partitionToShard(a.router.hashToPartition(node_router.routeNsKey(.invalid, t)));
        const after = a.router.partitionToShard(a.router.hashToPartition(node_router.routeNsKey(id, t)));
        if (before == 0 and after == 1) break t;
    };
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    try a.stream_handler.appendPayloadToStream(source, "default", "rec-1");
    two.settle();

    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [256]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: early
        \\namespace: pns
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s}, namespace: default }}
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
    , .{ source, target });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "pns", "", yaml, ""), .client);
    // The create and the submit apply; shard 0 hasn't published yet.
    _ = a.applyCommitted();
    try std.testing.expect(two.namespaces.lookup("pns") == null);
    try std.testing.expectEqual(@as(u32, 1), a.processing_handler.jobs.count());

    const from_a = a.raft_node.log.lastIndex() + 1;
    const from_b = b.raft_node.log.lastIndex() + 1;
    _ = a.processing_handler.tickPipelines(a);
    two.settle();
    try std.testing.expectEqual(id, two.namespaces.lookup("pns").?);
    // Published: the stream is on shard 1, so the job is held, unrun.
    var it = a.processing_handler.pipelines.valueIterator();
    while (it.next()) |pipe| pipe.last_poll_ms = 0;
    _ = a.processing_handler.tickPipelines(a);
    two.settle();
    try std.testing.expectEqual(@as(usize, 0), entriesOf(a, .stream_append, from_a));
    try std.testing.expectEqual(@as(usize, 0), entriesOf(b, .stream_append, from_b));
    var jobs = a.processing_handler.jobs.valueIterator();
    const job = jobs.next().?;
    try std.testing.expect(job.held);
    try std.testing.expect(std.mem.indexOf(u8, job.held_owned, "is on another") != null);
}

test "Shard: a pipeline's KV sinks send another shard no more than its inbox has room for, so a tick isn't held at the same record every time" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    const streams = [_]*StreamHandler{ a.stream_handler, b.stream_handler };
    for (&two.shards) |*s| {
        s.wireHandlerShardPtrs();
        s.processing_handler.setPeerStreamHandlers(&streams);
    }
    // Two sinks, each writing one hot key owned by shard 1: two sends a record.
    var pbuf: [2][16]u8 = undefined;
    var prefixes: [2][]const u8 = undefined;
    var found: usize = 0;
    var i: usize = 0;
    while (found < 2) : (i += 1) {
        const p = try std.fmt.bufPrint(&pbuf[found], "hot{d}", .{i});
        var full: [32]u8 = undefined;
        if (a.processing_handler.kvOwner(a, "default", try std.fmt.bufPrint(&full, "{s}:", .{p})) == 1) {
            prefixes[found] = p;
            found += 1;
        }
    }
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    const records = 600;
    for (0..records) |_| try a.stream_handler.appendPayloadToStream(source, "default", "v");
    two.settle();

    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: hot
        \\batch_size: 2000
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\sinks:
        \\  - name: one
        \\    kv: {{ key_prefix: {s} }}
        \\  - name: two
        \\    kv: {{ key_prefix: {s} }}
    , .{ source, prefixes[0], prefixes[1] });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "default", "", yaml, ""), .client);
    two.settle();
    try std.testing.expectEqual(@as(u32, 1), a.processing_handler.jobs.count());

    // Shard 1's inbox already part full, from senders it hasn't drained.
    const filler = 600;
    for (0..filler) |_| {
        const m = (KVHandler.SinkPut{ .namespace = "default", .key = "cold", .value = "x", .ttl_ms = 0 }).encode(a.allocator).?;
        try std.testing.expect(b.mailbox.inbox.send(.{ .tag = .kv_sink_put, .src_shard = 0, .payload_len = @intCast(m.len), .payload_ptr = m.ptr }));
    }
    const from_b = b.raft_node.log.lastIndex() + 1;
    var it = a.processing_handler.pipelines.valueIterator();
    const pipe = it.next().?;
    pipe.last_poll_ms = 0;
    _ = a.processing_handler.tickPipelines(a);
    // What fit was read and sent, and nothing held.
    const room = b.mailbox.inbox.capacity - filler;
    try std.testing.expectEqual(@as(u64, room / 2), pipe.records_in);
    try std.testing.expectEqual(@as(i64, 0), pipe.held_since_ms);
    two.settle();
    var rounds: u32 = 0;
    while (pipe.records_in < records and rounds < 20) : (rounds += 1) {
        pipe.last_poll_ms = 0;
        _ = a.processing_handler.tickPipelines(a);
        try std.testing.expectEqual(@as(i64, 0), pipe.held_since_ms);
        two.settle();
    }
    // Each write sent once.
    try std.testing.expectEqual(@as(u64, records), pipe.records_in);
    try std.testing.expectEqual(@as(usize, filler + 2 * records), entriesOf(b, .kv_put, from_b));
    try std.testing.expectEqual(@as(u64, 0), a.processing_handler.sink_drops);
}

test "Shard: a pipeline tick held partway through a batch resumes at the record it stopped in, sending none before it again" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    const streams = [_]*StreamHandler{ a.stream_handler, b.stream_handler };
    for (&two.shards) |*s| {
        s.wireHandlerShardPtrs();
        s.processing_handler.setPeerStreamHandlers(&streams);
    }
    // One hot key, owned by shard 1.
    var kbuf: [16]u8 = undefined;
    var i: usize = 0;
    const sku = while (true) : (i += 1) {
        const k = try std.fmt.bufPrint(&kbuf, "s{d}", .{i});
        var full: [32]u8 = undefined;
        if (a.processing_handler.kvOwner(a, "default", try std.fmt.bufPrint(&full, "hot:{s}", .{k})) == 1) break k;
    };
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    // Each record explodes into ten writes: a batch sends more than the
    // owner's inbox holds, so a tick is held partway through it.
    const records = 300;
    const fanout = 10;
    var rbuf: [512]u8 = undefined;
    var w: std.Io.Writer = .fixed(&rbuf);
    try w.writeAll("{\"order\":{\"items\":[");
    for (0..fanout) |j| try w.print("{s}{{\"sku\":\"{s}\"}}", .{ if (j == 0) "" else ",", sku });
    try w.writeAll("]}}");
    for (0..records) |_| try a.stream_handler.appendPayloadToStream(source, "default", w.buffered());
    two.settle();

    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: hot
        \\batch_size: 2000
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - type: flatmap
        \\    name: o
        \\    array_field: "$.order.items"
        \\    element_key: "$.sku"
        \\sinks:
        \\  - name: out
        \\    kv: {{ key_prefix: hot }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "default", "", yaml, ""), .client);
    two.settle();
    try std.testing.expectEqual(@as(u32, 1), a.processing_handler.jobs.count());

    const from_b = b.raft_node.log.lastIndex() + 1;
    var it = a.processing_handler.pipelines.valueIterator();
    const pipe = it.next().?;
    var held: usize = 0;
    var rounds: u32 = 0;
    while (rounds < 50) : (rounds += 1) {
        pipe.last_poll_ms = 0;
        _ = a.processing_handler.tickPipelines(a);
        const was_held = pipe.held_since_ms != 0;
        two.settle();
        if (!was_held) break;
        held += 1;
    }
    try std.testing.expect(held > 0);
    try std.testing.expect(rounds < 50);
    // Every write landed; again only those of a record a held tick stopped in.
    const puts = entriesOf(b, .kv_put, from_b);
    try std.testing.expect(puts >= records * fanout);
    try std.testing.expect(puts <= records * fanout + held * fanout);
    try std.testing.expectEqual(@as(u64, 0), a.processing_handler.sink_drops);
}

test "Shard: a start's retry choosing its run id, sent before its namespace is published, is decided on its workflow's shard by the namespace's id" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    // A workflow whose shard is 0 by the namespace's id, and 1 by none.
    const id = nextNamespaceId(a);
    var wbuf: [16]u8 = undefined;
    var i: usize = 0;
    const w = while (true) : (i += 1) {
        const n = try std.fmt.bufPrint(&wbuf, "wf{d}", .{i});
        const by_id = a.router.partitionToShard(a.router.hashToPartition(node_router.routeNsKey(id, n)));
        const by_none = a.router.partitionToShard(a.router.hashToPartition(node_router.routeNsKey(.invalid, n)));
        if (by_id == 0 and by_none == 1) break n;
    };
    var dbuf: [256]u8 = undefined;
    const def = try std.fmt.bufPrint(&dbuf,
        \\{{"kind":"Workflow","name":"{s}","version":"1.0.0",
        \\"start":{{"wait_for_signal":{{"type":"go"}},"transitions":{{"success":"flo.Completed"}}}}}}
    , .{w});
    // Created on shard 0 with the namespace; applied, not yet published.
    const ca = try TestClient.open(a);
    defer _ = std.c.close(ca.pair[1]);
    a.runRequest(ca.conn, try ParkTest.request(.workflow_create, 1, "wfresh", w, def, ""), .client);
    _ = a.applyCommitted();
    var out: [512]u8 = undefined;
    var resp = try nextAnswer(ca, a, &out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(two.namespaces.lookup("wfresh") == null);

    // Started there, with its idempotency key and its own run id.
    const both = [_]u8{ 0, 0, 1, 1, 0, 'z', 1, 2, 0, 'r', '1' };
    a.runRequest(ca.conn, try ParkTest.request(.workflow_start, 2, "wfresh", w, &both, ""), .client);
    // Every shard says whether it holds the id; nothing publishes.
    for (0..8) |_| for (&two.shards) |*s| {
        _ = s.drainInbox();
        _ = s.applyCommitted();
    };
    resp = try nextAnswer(ca, a, &out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(a.workflow_handler.holdsRun(id, "r1"));
    try std.testing.expect(two.namespaces.lookup("wfresh") == null);

    // Its retry from shard 1 is the same start, decided on shard 0: the
    // run's holder is its workflow's shard, not another workflow's.
    const cb = try TestClient.open(b);
    defer _ = std.c.close(cb.pair[1]);
    b.runRequest(cb.conn, try ParkTest.request(.workflow_start, 9, "wfresh", w, &both, ""), .client);
    two.settle();
    resp = try nextAnswer(cb, b, &out);
    try std.testing.expectEqual(@as(u64, 9), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expectError(error.IncompleteResponse, nextAnswer(cb, b, &out));
}

test "Shard: worker.list on a node of two shards lists both shards' workers, in id order and paged" {
    var f: MgetGatherFixture = undefined;
    try f.init(8);
    defer f.deinit();
    const a = &f.two.shards[0];
    // Each registration runs on its worker's shard.
    var name: [8]u8 = undefined;
    for (0..12) |i| {
        const id = try std.fmt.bufPrint(&name, "w{d:0>2}", .{i});
        a.runRequest(f.client.conn, .{ .header = proto.RequestHeader.init(.worker_register, 100 + i), .namespace = "default", .key = id, .value = "" }, .client);
        f.two.settle();
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try f.answer()).header.status);
    }
    try std.testing.expect(f.two.shards[0].worker_handler.workers.count() > 0);
    try std.testing.expect(f.two.shards[1].worker_handler.workers.count() > 0);

    const List = table_run.op("worker.list");
    var body_buf: [List.request.max_size]u8 = undefined;
    var cursor_buf: [64]u8 = undefined;
    var cursor: []const u8 = "";
    var seen: usize = 0;
    var pages: usize = 0;
    while (true) : (pages += 1) {
        const body = try List.request.encodeInto(&body_buf, .{ .limit = 5, .cursor = cursor, .action = "" });
        a.runRequest(f.client.conn, .{ .header = proto.RequestHeader.init(.worker_list, 200 + pages), .namespace = "default", .key = "", .value = body }, .client);
        f.two.settle();
        const resp = try f.answer();
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
        var diag: schema.Diagnostic = .{};
        const page = try List.response.decodeAll(resp.data, &diag);
        var it = page.workers.iterator();
        while (try it.next()) |w| : (seen += 1) {
            try std.testing.expectEqualStrings(try std.fmt.bufPrint(&name, "w{d:0>2}", .{seen}), w.id);
        }
        const next = page.cursor orelse break;
        // Each page moves the cursor on, so a regression fails, not hangs.
        try std.testing.expect(std.mem.order(u8, next, cursor) == .gt and pages < 12);
        @memcpy(cursor_buf[0..next.len], next);
        cursor = cursor_buf[0..next.len];
    }
    try std.testing.expectEqual(@as(usize, 12), seen);
    try std.testing.expectEqual(@as(usize, 2), pages);
    try f.expectSettled(0);
}

test "Shard: stream.group.members answers the named group's members by id, and a group that isn't there is not found" {
    var f: MgetGatherFixture = undefined;
    try f.init(8);
    defer f.deinit();
    // Each shard holds the group: the request is answered by whichever owns
    // the stream. Its members are the consumers holding its records.
    for (&f.two.shards) |*s| {
        const p = s.defaultPartition();
        for (0..4) |i| _ = try p.stream.appendToStreamAt(stream_mod.streamKey(.default, "s"), i + 1, 0, 1, 1, 10);
        // Delivered out of order; listed by id.
        for ([_][]const u8{ "c-9", "c-1", "c-5", "c-3" }, 0..) |id, i| {
            var pb: [ge_mod.Deliver.max_size]u8 = undefined;
            const body = try ge_mod.Deliver.encodeInto(&pb, .{ .ns = 1, .stream = "s", .group = "g", .count = 1, .max_bytes = 1 << 20, .holder = id, .lease_ms = 30_000, .create = true, .ready = .{ .bytes = "", .count = 0 }, .through_ms = std.math.maxInt(u64), .through_seq = std.math.maxInt(u64), .max_held = qe_caps.DEFAULT_MAX_MESSAGES, .max_held_bytes = qe_caps.DEFAULT_MAX_BYTES, .shard_held_bytes = qe_caps.DEFAULT_SHARD_HELD_BYTES });
            const e = entry_mod.buildEntry(.group_deliver, entry_mod.Flags.NONE, 1, 100 + i, 2_000_000, body);
            var out: persistence_mod.Result = .{};
            out.reset(&e);
            try contract_machine.applyEntryWith(&@import("../stream/group_machine.zig").machine, &p.store, &p.apply_scratch, .{ .proj = &p.stream }, &e, &out);
            try std.testing.expect(out.refused() == null);
        }
    }
    const a = &f.two.shards[0];
    const Members = table_run.op("stream.group.members");
    var body_buf: [Members.request.max_size]u8 = undefined;
    for ([_][]const u8{ "g", "nope" }, 0..) |group, i| {
        const body = try Members.request.encodeInto(&body_buf, .{ .group = group });
        a.runRequest(f.client.conn, .{ .header = proto.RequestHeader.init(.stream_group_members, 300 + i), .namespace = "default", .key = "s", .value = body }, .client);
        f.two.settle();
        const resp = try f.answer();
        if (i == 1) {
            try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), resp.header.status);
            continue;
        }
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
        var diag: schema.Diagnostic = .{};
        const v = try Members.response.decodeAll(resp.data, &diag);
        var it = v.members.iterator();
        for ([_][]const u8{ "c-1", "c-3", "c-5", "c-9" }) |want| {
            const m = (try it.next()).?;
            try std.testing.expectEqualStrings(want, m.id);
            try std.testing.expectEqual(@as(i64, 2), m.joined_at_ms);
        }
        try std.testing.expect((try it.next()) == null);
        try std.testing.expect(!v.more);
    }
    try f.expectSettled(0);
}

