test "Shard: a connection's blocking reads held for the leader count toward its cap" {
    var t: FollowerTest = undefined;
    try t.init();
    defer t.deinit();

    const reads = Connection.MAX_BLOCKING_IN_FLIGHT + 2;
    var reqs: [reads][]u8 = undefined;
    for (&reqs, 0..) |*r, i| r.* = try FollowerTest.blockingDequeue(100 + i);
    defer for (reqs) |r| std.testing.allocator.free(r);
    const all = try std.mem.concat(std.testing.allocator, u8, &reqs);
    defer std.testing.allocator.free(all);
    _ = feedClient(t.pair[1], &t.shard, t.conn.fd, all);

    // Eight go to the leader; the ninth waits for one of them to return.
    try std.testing.expectEqual(@as(u32, Connection.MAX_BLOCKING_IN_FLIGHT), t.shard.forward_count);
    try std.testing.expectEqual(@as(u32, Connection.MAX_BLOCKING_IN_FLIGHT), t.shard.blocking_forwards);
    try std.testing.expect(t.conn.waiting != null);

    // The client goes: its forwards go, and the count with them.
    t.shard.dropForwardsFor(t.conn.fd, t.conn.id);
    try std.testing.expectEqual(@as(u32, 0), t.shard.forward_count);
    try std.testing.expectEqual(@as(u32, 0), t.shard.blocking_forwards);
}

test "Shard: blocking reads held for the leader leave forward slots for writes" {
    var t: FollowerTest = undefined;
    try t.init();
    defer t.deinit();

    // Every slot blocking reads may hold is taken.
    t.shard.blocking_forwards = FORWARD_SLOTS - FORWARD_WRITE_RESERVE;
    defer t.shard.blocking_forwards = 0;
    t.shard.runRequest(t.conn, testReq(.queue_dequeue, 1, "", "q", "", blk: {
        var opts: [8]u8 = undefined;
        var ob = proto.OptionsBuilder.init(&opts);
        try ob.addU32(.block_ms, 60_000);
        break :blk ob.getOptions();
    }), .client);
    var out: [256]u8 = undefined;
    const n = try readAnswer(t.pair[1], &t.shard, t.conn.fd, &out, @sizeOf(proto.ResponseHeader));
    var resp = try proto.Response.parse(out[0..n]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), resp.header.status);
    try std.testing.expectEqual(proto.Ran.no, (try resp.refused()).ran);
    try std.testing.expectEqual(@as(u32, 0), t.shard.forward_count);

    // A write still gets a slot.
    t.shard.runRequest(t.conn, testReq(.kv_put, 2, "", "k", "v", ""), .client);
    try std.testing.expectEqual(@as(u32, 1), t.shard.forward_count);
}

test "Shard: a blocking read with no room left to wait is refused overloaded, not answered empty" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    for (0..waiter_pool_mod.MAX_WAITERS) |i| {
        _ = shard.waiter_pool.register(.{ .kind = .kv_get, .reply_to = ReplyTo.socketOf(0, 1000, @intCast(i)), .request_id = i, .key = "x", .timeout_ms = 60_000 });
    }

    var opts: [8]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&opts);
    try ob.addU32(.block_ms, 60_000);
    // [group_len:u16][group][consumer_len:u16][consumer]
    const group_consumer = "\x01\x00" ++ "g" ++ "\x01\x00" ++ "c";
    var await_buf: [64]u8 = undefined;
    const await_value = try ActionsHandler.for_tests.awaitBody(&await_buf, &.{"job"}, 60_000, null);
    for ([_]struct { op: proto.OpCode, key: []const u8, value: []const u8 }{
        .{ .op = .queue_dequeue, .key = "q", .value = "" },
        .{ .op = .stream_read, .key = "s", .value = "" },
        .{ .op = .stream_group_read, .key = "s", .value = group_consumer },
        .{ .op = .action_await, .key = "w", .value = await_value },
    }, 7..) |r, id| {
        const req = try testRequestWith(r.op, id, r.key, r.value, ob.getOptions());
        defer std.testing.allocator.free(req);
        _ = feedClient(c.pair[1], &shard, c.conn.fd, req);
        var out: [256]u8 = undefined;
        var resp = try nextAnswer(c, &shard, &out);
        try std.testing.expectEqual(@as(u64, id), resp.header.request_id);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), resp.header.status);
        try std.testing.expectEqual(proto.Ran.no, (try resp.refused()).ran);
    }
}

test "Shard: a forward waits for its leader's answer, is answered when that leader is replaced, and runs here once this node leads" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 8, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    const raft = shard.raft_node;

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var header = proto.RequestHeader.init(.kv_put, 5);
    shard.runRequest(conn, testReq(.kv_put, header.request_id, "", "k", "v", ""), .client);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    // Ids sit outside the fd range: a client closing on the leader can
    // never match one in its waiter pool.
    try std.testing.expect(shard.forwards[0].reply_to.isSocket(0, pair[0], conn.id));
    try std.testing.expect(@as(i32, @bitCast(shard.forwards[0].id)) < 0);

    // A leader is known but there is no link to it: the write is not
    // marked sent, and past the deadline the client hears why.
    raft.leader_id = 2;
    const now = Shard.nowMs();
    shard.sweepForwards(now);
    try std.testing.expectEqual(@as(u32, 0), shard.forwards[0].sent_to);
    shard.sweepForwards(now + FORWARD_TIMEOUT_MS + 1);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    var out: [256]u8 = undefined;
    var n = std.c.read(pair[1], &out, out.len);
    var resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expect(std.mem.indexOf(u8, resp.data, "not reachable") != null);

    // Sent to a leader: it waits past any deadline for that leader's
    // answer, until the term moves on. (No network here, so the link is
    // not consulted.)
    shard.runRequest(conn, testReq(.kv_put, header.request_id, "", "k", "v", ""), .client);
    shard.forwards[0].sent_to = 2;
    shard.forwards[0].sent_term = raft.current_term;
    shard.forwards[0].sent_ms = now;
    shard.raft_network = null;
    shard.sweepForwards(now + 10 * FORWARD_TIMEOUT_MS);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    raft.current_term += 1;
    shard.sweepForwards(now + 10 * FORWARD_TIMEOUT_MS);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    shard.raft_network = &rn;
    n = std.c.read(pair[1], &out, out.len);
    resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), resp.header.status);
    // Sent, then the term moved on: it may still have applied.
    const lost = try resp.refused();
    try std.testing.expectEqualStrings("unavailable: lost leadership before commit — write may still apply", lost.message);
    try std.testing.expectEqual(proto.Ran.unknown, lost.ran);

    // Sent over a link that then went down, with the term unchanged: the
    // answer will never come either.
    shard.runRequest(conn, testReq(.kv_put, header.request_id, "", "k", "v", ""), .client);
    shard.forwards[0].sent_to = 2;
    shard.forwards[0].sent_term = raft.current_term;
    shard.sweepForwards(now);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    n = std.c.read(pair[1], &out, out.len);
    resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expect(std.mem.indexOf(u8, resp.data, "lost the link") != null);

    // The link went down and came back between two ticks: a new session,
    // so the answer is not coming over it either.
    rn.linked_ids[0].store(2, .release);
    rn.linked_sessions[0].store(5, .release);
    shard.runRequest(conn, testReq(.kv_put, header.request_id, "", "k", "v", ""), .client);
    shard.forwards[0].sent_to = 2;
    shard.forwards[0].sent_term = raft.current_term;
    shard.forwards[0].sent_session = 4;
    shard.forwards[0].sent_ms = now;
    shard.sweepForwards(now);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    n = std.c.read(pair[1], &out, out.len);
    resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expect(std.mem.indexOf(u8, resp.data, "lost the link") != null);

    // Same link, same leader, same term, and no answer: waited on until
    // the backstop, then answered.
    shard.runRequest(conn, testReq(.kv_put, header.request_id, "", "k", "v", ""), .client);
    shard.forwards[0].sent_to = 2;
    shard.forwards[0].sent_term = raft.current_term;
    shard.forwards[0].sent_session = 5;
    shard.forwards[0].sent_ms = now;
    shard.sweepForwards(now + SENT_FORWARD_BACKSTOP_MS - 1);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    shard.sweepForwards(now + SENT_FORWARD_BACKSTOP_MS);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    n = std.c.read(pair[1], &out, out.len);
    resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expectEqualStrings("unavailable: no answer from the leader — write may still apply", (try resp.refused()).message);
    // Sent to a leader that is gone: it may still apply.
    try std.testing.expectEqual(proto.Ran.unknown, (try resp.refused()).ran);

    // A blocking dequeue may wait on the leader as long as it asked to:
    // the backstop runs from the end of that wait, not from its start.
    var opts: [8]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&opts);
    try ob.addU32(.block_ms, 90_000);
    shard.runRequest(conn, testReq(.queue_dequeue, header.request_id, "", "q", "", ob.getOptions()), .client);
    shard.forwards[0].sent_to = 2;
    shard.forwards[0].sent_term = raft.current_term;
    shard.forwards[0].sent_session = 5;
    shard.forwards[0].sent_ms = now;
    shard.sweepForwards(now + SENT_FORWARD_BACKSTOP_MS);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    shard.sweepForwards(now + SENT_FORWARD_BACKSTOP_MS + 90_000 - 1);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    shard.sweepForwards(now + SENT_FORWARD_BACKSTOP_MS + 90_000);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    n = std.c.read(pair[1], &out, out.len);
    resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expectEqualStrings("unavailable: no answer from the leader — write may still apply", (try resp.refused()).message);
    try std.testing.expectEqual(proto.Ran.unknown, (try resp.refused()).ran);
    rn.linked_ids[0].store(0, .release);
    rn.linked_sessions[0].store(0, .release);

    // A write held while no leader was known, then this node leads: it
    // runs here as the client's own request.
    raft.leader_id = 0;
    header.request_id = 6;
    shard.runRequest(conn, testReq(.kv_put, header.request_id, "", "k", "v", ""), .client);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    raft.role = .leader;
    raft.leader_id = 8;
    shard.sweepForwards(now);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    n = std.c.read(pair[1], &out, out.len);
    resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expectEqual(@as(u64, 6), resp.header.request_id);
}

test "shard: a real flush failure shows in the field, the metric snapshot and text, and a write that reaches disk ends the run" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var registry = @import("../metrics/registry.zig").MetricsRegistry.init(std.testing.allocator);
    defer registry.deinit();
    try registry.initShards(1);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], data_dir, 8 * 1024 * 1024, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    shard.shard_metrics = registry.shardMetrics(0);
    try std.testing.expect(shard.applyCommitted());

    // Buffer an entry, then make the segment directory unwritable so a real
    // flush to disk fails.
    const raft = shard.raft_node;
    _ = try raft.propose(.raft_noop, entry_mod.Flags.NONE, "x");
    const segs = try std.fmt.allocPrint(std.testing.allocator, "{s}/00000/segs", .{data_dir});
    defer std.testing.allocator.free(segs);
    var zbuf: [600:0]u8 = undefined;
    const z = try std.fmt.bufPrintSentinel(&zbuf, "{s}", .{segs}, 0);
    try std.testing.expectEqual(@as(c_int, 0), std.c.chmod(z, 0o500));
    defer _ = std.c.chmod(z, 0o700);

    try std.testing.expect(!shard.flushForAck()); // the flush fails for real
    try std.testing.expect(shard.persist_failures >= 1);
    try std.testing.expect(shard.flushes_failing_since_ms != 0);

    // The run is published as a duration in the metric snapshot and the text.
    shard.flushes_failing_since_ms = Shard.nowMs() -| 1000; // one second in
    shard.publishHealth();
    const snap = shard.shard_metrics.?.snapshot();
    try std.testing.expect(snap.persist_failures >= 1);
    try std.testing.expect(snap.flushes_failing_for_ms >= 1000);
    const text = try registry.exportPrometheus(std.testing.allocator);
    defer std.testing.allocator.free(text);
    try std.testing.expect(std.mem.indexOf(u8, text, "flo_shard_persist_failures_total{shard_id=\"0\"}") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "flo_shard_flushes_failing_for_seconds{shard_id=\"0\"} 1.") != null);

    // It also reaches /status through the health slot, not only the metric.
    var nh = try health_mod.NodeHealth.init(std.testing.allocator, 1, 1);
    defer nh.deinit(std.testing.allocator);
    nh.accepting.store(true, .release);
    shard.health = &nh.shards[0];
    shard.publishHealth();
    shard.health = null; // the slot outlives this test's use; don't dangle into deinit
    var out: std.Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();
    try nh.writeStatus(&out.writer, null);
    try std.testing.expect(std.mem.indexOf(u8, out.written(), "\"persist_failures\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, out.written(), "\"flushes_failing_for_ms\"") != null);

    // Writable again: a flush that reaches disk ends the run; the total stays.
    _ = std.c.chmod(z, 0o700);
    try std.testing.expect(shard.flushForAck());
    try std.testing.expectEqual(@as(u64, 0), shard.flushes_failing_since_ms);
    shard.publishHealth();
    try std.testing.expectEqual(@as(u64, 0), shard.shard_metrics.?.snapshot().flushes_failing_for_ms);
}

