/// Writes parked behind a second member's ack, driven over a socket pair
/// the way a client drives them.
const ParkTest = struct {
    /// The shard leads alone, then adds member 2 and makes it a voter:
    /// from here nothing commits until `ack`.
    fn joinPeer(sh: *Shard) !void {
        try std.testing.expect(sh.applyCommitted());
        sh.handleJoinRequest(2);
        try ack(sh);
        const r = sh.raft_node;
        const voter = r.latest_config.withMember(.{ .id = 2, .voter = true, .may_vote = true, .caught_up = true });
        try std.testing.expect((try r.proposeConfig(&voter)) == .proposed);
        try ack(sh);
    }

    /// Member 2 acks everything in the log; the shard applies it.
    fn ack(sh: *Shard) !void {
        const r = sh.raft_node;
        const last = r.log.lastIndex();
        r.peers[0].sent_up_to = last;
        r.handleAppendResponse(.{ .term = r.current_term, .success = true, .match_index = last, .from = 2 });
        try std.testing.expect(sh.applyCommitted());
    }

    fn request(op: proto.OpCode, id: u64, ns: []const u8, key: []const u8, value: []const u8, options: []const u8) !proto.Request {
        return testReq(op, id, ns, key, value, options);
    }

    fn send(sh: *Shard, c: *Connection, op: proto.OpCode, id: u64, key: []const u8, value: []const u8) !void {
        // Named as decoding names it: a parked request is decoded again when answered.
        sh.runRequest(c, try request(op, id, proto.DEFAULT_NAMESPACE, key, value, ""), .client);
    }

    /// Every response the shard has for `c`, flushed and read from `fd`
    /// without blocking; fails unless exactly `into.len` whole responses
    /// arrived and nothing is left.
    fn responses(sh: *Shard, c: *Connection, fd: std.posix.fd_t, buf: []u8, into: []proto.Response) !void {
        sh.flushToClient(c.fd);
        var total: usize = 0;
        while (total < buf.len) {
            const n = std.c.recv(fd, buf[total..].ptr, buf.len - total, std.c.MSG.DONTWAIT);
            if (n <= 0) break;
            total += @intCast(n);
        }
        var off: usize = 0;
        for (into) |*r| {
            r.* = try proto.Response.parse(buf[off..total]);
            off += @sizeOf(proto.ResponseHeader) + r.data.len;
        }
        try std.testing.expectEqual(total, off);
    }
};

/// A shard leading member 2, with a client whose two writes both pass the
/// leader's checks before either applies.
const RaceTest = struct {
    rn: RaftNetwork,
    shard: Shard,
    pair: [2]std.posix.fd_t,
    conn: *Connection,
    pipe_fds: [2]std.posix.fd_t,

    fn init(t: *RaceTest) !void {
        t.pipe_fds = try @import("stdx").io.pipe();
        t.rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        t.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, t.pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
        t.shard.raft_network = &t.rn;
        t.shard.wireHandlerShardPtrs();
        try ParkTest.joinPeer(&t.shard);
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &t.pair));
        t.conn = try t.shard.addConnection(t.pair[0]);
    }

    fn deinit(t: *RaceTest) void {
        for (t.rn.outbound.items) |o| std.testing.allocator.free(o.frame);
        t.rn.outbound.clearRetainingCapacity();
        _ = std.c.close(t.pair[1]);
        t.shard.deinit();
        t.rn.deinit();
        _ = std.c.close(t.pipe_fds[0]);
        _ = std.c.close(t.pipe_fds[1]);
    }

    /// Body already schema-coded, sent as it is.
    fn send(t: *RaceTest, op: proto.OpCode, id: u64, key: []const u8, body: []const u8) void {
        t.shard.runRequest(t.conn, .{ .header = proto.RequestHeader.init(op, id), .namespace = "", .key = key, .value = body }, .client);
    }
};

test "Shard: of two incrs that both pass the leader's check, the one that would overflow is refused, not answered with the old value" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var buf: [2048]u8 = undefined;
    var two: [2]proto.Response = undefined;
    var one: [1]proto.Response = undefined;
    var diag: schema.Diagnostic = .{};

    const set = table_run.op("kv.set");
    var set_buf: [64]u8 = undefined;
    var counter: [8]u8 = undefined;
    std.mem.writeInt(i64, &counter, std.math.maxInt(i64) - 1, .little);
    _ = &counter;
    t.send(.kv_put, 1, "c", try set.request.encodeInto(&set_buf, .{ .value = &counter, .ttl_ms = null, .condition = .always, .cas_version = null, .txn = null }));
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);

    const incr = table_run.op("kv.incr");
    var incr_buf: [32]u8 = undefined;
    const by_one = try incr.request.encodeInto(&incr_buf, .{ .delta = 1, .txn = null });
    t.send(.kv_incr, 2, "c", by_one);
    t.send(.kv_incr, 3, "c", by_one);
    try std.testing.expectEqual(@as(u32, 2), t.shard.pending_count);
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &two);
    try std.testing.expectEqual(@as(i64, std.math.maxInt(i64)), (try incr.response.decodeAll(two[0].data, &diag)).value.?);
    // On dev the second was answered ok with the value it didn't change.
    try std.testing.expectEqual(@as(u64, 3), two[1].header.request_id);
    const r = try two[1].refused();
    try std.testing.expectEqual(proto.Reason.out_of_range, r.reason);
    try std.testing.expectEqual(proto.Ran.no, r.ran);
}

test "Shard: of two deletes of one key that both pass the leader's check, only the first says the key existed" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var buf: [2048]u8 = undefined;
    var two: [2]proto.Response = undefined;
    var one: [1]proto.Response = undefined;
    var diag: schema.Diagnostic = .{};

    const set = table_run.op("kv.set");
    var set_buf: [64]u8 = undefined;
    t.send(.kv_put, 1, "k", try set.request.encodeInto(&set_buf, .{ .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null, .txn = null }));
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);

    const delete = table_run.op("kv.delete");
    var del_buf: [32]u8 = undefined;
    const body = try delete.request.encodeInto(&del_buf, .{ .cas_version = null, .txn = null });
    t.send(.kv_delete, 2, "k", body);
    t.send(.kv_delete, 3, "k", body);
    try std.testing.expectEqual(@as(u32, 2), t.shard.pending_count);
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &two);
    try std.testing.expectEqual(@as(?bool, true), (try delete.response.decodeAll(two[0].data, &diag)).existed);
    // On dev both said it existed.
    try std.testing.expectEqual(@as(?bool, false), (try delete.response.decodeAll(two[1].data, &diag)).existed);
}

test "Shard: a parked write that committed but didn't apply says so, with ran = yes, so it isn't resent" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    defer {
        for (rn.outbound.items) |o| std.testing.allocator.free(o.frame);
        rn.outbound.clearRetainingCapacity();
    }

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    try ParkTest.send(&shard, conn, .kv_put, 7, "k", "v");
    try std.testing.expectEqual(@as(usize, 1), shard.pending_count);
    const slot = for (shard.pending) |p| {
        if (p.active) break p;
    } else unreachable;

    shard.answerPending(slot.index, slot.term, false, &persistence_mod.Result{});
    var one: [1]proto.Response = undefined;
    var buf: [512]u8 = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.internal_error), one[0].header.status);
    const r = try one[0].refused();
    try std.testing.expectEqual(proto.Reason.committed_not_applied, r.reason);
    try std.testing.expectEqual(proto.Ran.yes, r.ran);
}

/// A shard leading a group of two, so nothing commits until `ParkTest.ack`,
/// and a client connection to it.
const RanTest = struct {
    pipe_fds: [2]std.posix.fd_t,
    rn: RaftNetwork,
    shard: Shard,
    pair: [2]std.posix.fd_t,
    conn: *Connection,

    fn init(t: *RanTest) !void {
        t.pipe_fds = try @import("stdx").io.pipe();
        t.rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        t.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, t.pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
        t.shard.raft_network = &t.rn;
        t.shard.wireHandlerShardPtrs();
        try ParkTest.joinPeer(&t.shard);
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &t.pair));
        t.conn = try t.shard.addConnection(t.pair[0]);
    }

    fn deinit(t: *RanTest) void {
        for (t.rn.outbound.items) |o| std.testing.allocator.free(o.frame);
        t.rn.outbound.clearRetainingCapacity();
        t.shard.deinit();
        t.rn.deinit();
        _ = std.c.close(t.pair[1]);
        _ = std.c.close(t.pipe_fds[0]);
        _ = std.c.close(t.pipe_fds[1]);
    }

    /// The one refusal waiting for the client.
    fn refusal(t: *RanTest, buf: []u8) !struct { status: u8, r: proto.Refusal } {
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&t.shard, t.conn, t.pair[1], buf, &one);
        return .{ .status = one[0].header.status, .r = try one[0].refused() };
    }

    /// The one parked write's slot.
    fn parked(t: *RanTest) Pending {
        for (t.shard.pending) |p| if (p.active) return p;
        unreachable;
    }
};

test "Shard: ran is no for a parked write whose index another term took, and unknown for one whose flush failed" {
    var buf: [512]u8 = undefined;
    {
        var t: RanTest = undefined;
        try t.init();
        defer t.deinit();
        try ParkTest.send(&t.shard, t.conn, .kv_put, 7, "k", "v");
        const slot = t.parked();
        // Another leader's entry committed at this index: this write didn't.
        t.shard.answerPending(slot.index, slot.term + 1, true, &persistence_mod.Result{});
        const got = try t.refusal(&buf);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), got.status);
        try std.testing.expectEqual(proto.Ran.no, got.r.ran);
    }
    {
        var t: RanTest = undefined;
        try t.init();
        defer t.deinit();
        try ParkTest.send(&t.shard, t.conn, .kv_put, 8, "k", "v");
        const slot = t.parked();
        // In the log, not on disk: it may still apply.
        t.shard.failPendingAbove(slot.index - 1, Shard.NOT_ON_DISK);
        const got = try t.refusal(&buf);
        try std.testing.expectEqual(proto.Ran.unknown, got.r.ran);
    }
}

test "Shard: a node forwards only writes to its leader; a forwarded read is refused, not run" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    try std.testing.expect(shard.applyCommitted());
    shard.raft_network = &rn;
    defer {
        for (rn.outbound.items) |o| std.testing.allocator.free(o.frame);
        rn.outbound.clearRetainingCapacity();
    }
    const wire = try Shard.serializeRequest(std.testing.allocator, testReq(.kv_get, 9, "", "k", "", ""));
    defer std.testing.allocator.free(wire);
    const frame = try std.testing.allocator.alloc(u8, FORWARD_PREFIX + FORWARD_FIELDS + wire.len);
    defer std.testing.allocator.free(frame);
    std.mem.writeInt(u32, frame[0..4], 93, .little);
    std.mem.writeInt(u16, frame[4..6], FORWARD_FIELDS, .little);
    @memset(frame[FORWARD_PREFIX..][0..FORWARD_FIELDS], 0);
    @memcpy(frame[FORWARD_PREFIX + FORWARD_FIELDS ..], wire);
    shard.runForwardedWrite(.{ .source_node = 2, .group_id = 0, .msg_type = .forward_write, .payload = frame });
    try std.testing.expectEqual(@as(usize, 1), rn.outbound.items.len);
    const reply = rn.outbound.items[0].frame[transport.HEADER_SIZE..];
    const resp = try proto.Response.parse(reply[12..]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), resp.header.status);
    try std.testing.expectEqualStrings("bad request: only writes, reads the leader answers, and a follower's ask about the namespaces, are forwarded to a leader", (try resp.refused()).message);
    try std.testing.expectEqual(proto.Ran.no, (try resp.refused()).ran);
}

test "Shard: a create not on disk by its deadline is answered unavailable, once" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    // Proposed, never committed: the peer doesn't answer.
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 50, "", "late", "", ""), .client);
    const nh = shard.namespace_handler;
    try std.testing.expectEqual(@as(usize, 1), nh.waiters.items.len);
    nh.settle(&shard);
    try std.testing.expectEqual(@as(usize, 1), nh.waiters.items.len);
    nh.waiters.items[0].deadline_ms = 0;
    nh.settle(&shard);
    try std.testing.expectEqual(@as(usize, 0), nh.waiters.items.len);
    var buf: [512]u8 = undefined;
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expectEqualStrings(handler_mod.NamespaceHandler.FLUSH_MESSAGE, (try one[0].refused()).message);
    // It commits later and is published, with no one left to answer.
    try ParkTest.ack(&shard);
    nh.settle(&shard);
    try std.testing.expect(shard.namespace_handler.table.lookup("late") != null);
}

test "Shard: a write to a new namespace holds its room before it commits, so writes in flight cannot overshoot the limit" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    // An explicit create in flight holds its name and id as a write's does.
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 42, "", "explicit", "", ""), .client);
    try std.testing.expect(shard.namespace_handler.pending_creates.contains("explicit"));
    try ParkTest.ack(&shard);
    try std.testing.expect(!shard.namespace_handler.pending_creates.contains("explicit"));
    // Answered once on disk and published: the tick's settle.
    shard.namespace_handler.settle(&shard);
    var created: [1]proto.Response = undefined;
    var created_buf: [256]u8 = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &created_buf, &created);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), created[0].header.status);

    // One namespace short of the limit.
    var name_buf: [16]u8 = undefined;
    const room = @import("../namespace/table.zig").MAX_LIVE - shard.namespace_handler.namespaces.count() - 1;
    for (0..room) |i| _ = shard.namespace_handler.applyCreate(try std.fmt.bufPrint(&name_buf, "ns{d}", .{i}));

    // Two writes to new namespaces, neither committed: the first holds
    // the last room, the second is refused at once.
    shard.runRequest(conn, try ParkTest.request(.kv_put, 40, "first", "k", "v", ""), .client);
    shard.runRequest(conn, try ParkTest.request(.kv_put, 41, "second", "k", "v", ""), .client);
    var buf: [1024]u8 = undefined;
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 41), one[0].header.request_id);
    try std.testing.expectEqualStrings(handler_mod.NamespaceHandler.LIMIT_MESSAGE, (try one[0].refused()).message);

    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 40), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expect(shard.namespace_handler.namespaces.contains("first"));
    try std.testing.expect(!shard.namespace_handler.namespaces.contains("second"));
}

test "Shard: a KV transaction whose commit waits on a peer takes no second commit, write or rollback" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    var diag: schema.Diagnostic = .{};
    // Bodies already schema-coded, sent as they are.
    const send = struct {
        fn run(sh: *Shard, c: *Connection, op: proto.OpCode, id: u64, key: []const u8, body: []const u8) void {
            sh.runRequest(c, .{ .header = proto.RequestHeader.init(op, id), .namespace = "", .key = key, .value = body }, .client);
        }
    }.run;

    const id = try shard.kv_handler.txn_table.begin(node_router.routeNsKey(.default, "k"), .default);
    const set = table_run.op("kv.set");
    var set_buf: [64]u8 = undefined;
    const in_txn = try set.request.encodeInto(&set_buf, .{ .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null, .txn = id });
    send(&shard, conn, .kv_put, 1, "k", in_txn);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);

    // The commit proposes its batch and waits on the peer's ack.
    const commit = table_run.op("kv.txn.commit");
    var txn_buf: [16]u8 = undefined;
    const by_id = try commit.request.encodeInto(&txn_buf, .{ .txn = id });
    send(&shard, conn, .kv_commit_txn, 2, "", by_id);
    try std.testing.expectEqual(@as(u32, 1), shard.pending_count);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &.{});

    // Until it applies, the transaction is closed: a second commit would
    // propose the batch again, and a write or rollback would change what
    // the first commit answers for.
    const later_set = try set.request.encodeInto(&set_buf, .{ .value = "w", .ttl_ms = null, .condition = .always, .cas_version = null, .txn = id });
    for ([_]struct { op: proto.OpCode, key: []const u8, body: []const u8 }{
        .{ .op = .kv_commit_txn, .key = "", .body = by_id },
        .{ .op = .kv_rollback_txn, .key = "", .body = by_id },
        .{ .op = .kv_put, .key = "k2", .body = later_set },
    }, 3..) |c, rid| {
        send(&shard, conn, c.op, rid, c.key, c.body);
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        try std.testing.expectEqual(@as(u64, rid), one[0].header.request_id);
        const r = try one[0].refused();
        try std.testing.expectEqual(proto.Reason.no_such_transaction, r.reason);
        try std.testing.expectEqual(proto.Ran.no, r.ran);
    }
    try std.testing.expectEqual(@as(u32, 1), shard.pending_count);

    // The batch applies once; the first commit answers for its one write.
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
    try std.testing.expectEqual(@as(u16, 1), (try commit.response.decodeAll(one[0].data, &diag)).ops);
    try std.testing.expect(shard.kv_handler.txn_table.get(id) == null);
    var qbuf: [limits.MAX_KV_KEY]u8 = undefined;
    const kv = &shard.defaultPartition().kv;
    try std.testing.expectEqualStrings("v", kv.get(testKvKey(&qbuf, "k")).?.value);
    try std.testing.expect(kv.get(testKvKey(&qbuf, "k2")) == null);
}

/// Two clients of a leader whose writes wait on member 2's ack, for KV's
/// conditional writes: the condition is decided when the entry applies.
const CondTest = struct {
    t: AdminTest,
    pair: [2]std.posix.fd_t,
    other: *Connection,
    buf: [2048]u8 = undefined,

    fn init(self: *CondTest) !void {
        try self.t.init(1, .bootstrap);
        try ParkTest.joinPeer(&self.t.shard);
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &self.pair));
        self.other = try self.t.shard.addConnection(self.pair[0]);
    }

    fn deinit(self: *CondTest) void {
        self.t.deinit();
        _ = std.c.close(self.pair[1]);
    }

    fn send(self: *CondTest, c: *Connection, op: proto.OpCode, id: u64, key: []const u8, comptime name: []const u8, body: table_run.op(name).request.Value) !void {
        var enc: [256]u8 = undefined;
        const bytes = try table_run.op(name).request.encodeInto(&enc, body);
        self.t.shard.runRequest(c, .{ .header = proto.RequestHeader.init(op, id), .namespace = "", .key = key, .value = bytes }, .client);
    }

    fn set(self: *CondTest, c: *Connection, id: u64, key: []const u8, value: []const u8, condition: kv_ops.Condition, cas: ?u64, txn: ?u64) !void {
        try self.send(c, .kv_put, id, key, "kv.set", .{ .value = value, .ttl_ms = null, .condition = condition, .cas_version = cas, .txn = txn });
    }

    /// The one answer on the first client.
    fn answer(self: *CondTest) !proto.Response {
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&self.t.shard, self.t.conn, self.t.pair[1], &self.buf, &one);
        return one[0];
    }

    /// The one answer on the second client.
    fn otherAnswer(self: *CondTest) !proto.Response {
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&self.t.shard, self.other, self.pair[1], &self.buf, &one);
        return one[0];
    }

    fn expectConflict(resp: proto.Response, reason: proto.Reason) !void {
        try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), resp.header.status);
        const r = try resp.refused();
        try std.testing.expectEqual(reason, r.reason);
        try std.testing.expectEqual(proto.Ran.no, r.ran);
    }

    fn held(self: *CondTest, key: []const u8) ?@import("../kv/machine.zig").Current {
        var q: [limits.MAX_KV_KEY]u8 = undefined;
        return self.t.shard.defaultPartition().kv.get(testKvKey(&q, key));
    }
};

test "Shard: a condition counts a write that hasn't applied yet: of two racing writers, the second is refused" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();

    // Both proposed before either applies: at propose time the key is absent
    // to both.
    try c.set(c.t.conn, 1, "k", "first", .if_absent, null, null);
    try c.set(c.other, 2, "k", "second", .if_absent, null, null);
    try std.testing.expectEqual(@as(u32, 2), c.t.shard.pending_count);
    try ParkTest.ack(&c.t.shard);

    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try CondTest.expectConflict(try c.otherAnswer(), .condition_failed);
    try std.testing.expectEqualStrings("first", c.held("k").?.value);
    try std.testing.expectEqual(@as(u64, 1), c.held("k").?.version);
    try std.testing.expectEqual(@as(u32, 0), c.t.shard.pending_count);
}

test "Shard: of two racing writers with one cas_version, the second is refused; so are a delete's and an expire's" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    try c.set(c.t.conn, 1, "k", "v1", .always, null, null);
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();

    try c.set(c.t.conn, 2, "k", "v2", .always, 1, null);
    try c.send(c.other, .kv_delete, 3, "k", "kv.delete", .{ .cas_version = 1, .txn = null });
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try CondTest.expectConflict(try c.otherAnswer(), .cas_mismatch);
    try std.testing.expectEqualStrings("v2", c.held("k").?.value);

    try c.set(c.t.conn, 4, "k", "v3", .always, 2, null);
    try c.send(c.other, .kv_expire, 5, "k", "kv.expire", .{ .ttl_ms = 1000, .cas_version = 2, .txn = null });
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try CondTest.expectConflict(try c.otherAnswer(), .cas_mismatch);
    try std.testing.expectEqual(@as(u64, 0), c.held("k").?.expiry_ns);
}

test "Shard: a condition counts a write its leader inherited, committed and not yet applied" {
    var t: AdminTest = undefined;
    try t.init(1, .bootstrap);
    defer t.deinit();
    try std.testing.expect(t.shard.applyCommitted());
    var pbuf: [64]u8 = undefined;
    // Committed by its one member, not yet applied: as a new leader holds
    // what the last leader committed.
    _ = try t.shard.raft_node.propose(.kv_put, entry_mod.Flags.NONE, try kv_entries.Put.encodeInto(&pbuf, .{ .key = TEST_KV_K, .value = "from-old-leader", .ttl_ms = null, .condition = .always, .cas_version = null }));
    var enc: [64]u8 = undefined;
    const body = try table_run.op("kv.set").request.encodeInto(&enc, .{ .value = "mine", .ttl_ms = null, .condition = .if_absent, .cas_version = null, .txn = null });
    t.shard.runRequest(t.conn, .{ .header = proto.RequestHeader.init(.kv_put, 1), .namespace = "", .key = "k", .value = body }, .client);
    try std.testing.expect(t.shard.applyCommitted());
    var buf: [512]u8 = undefined;
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try CondTest.expectConflict(one[0], .condition_failed);
    var q: [limits.MAX_KV_KEY]u8 = undefined;
    try std.testing.expectEqualStrings("from-old-leader", t.shard.defaultPartition().kv.get(testKvKey(&q, "k")).?.value);
}

test "Shard: an incr is decided as it applies: a write not yet applied can make the key a counter, or stop it being one" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    try c.set(c.t.conn, 1, "k", "text", .always, null, null);
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();

    // Not a counter as it stands; one by the time the incr applies.
    var counter: [8]u8 = undefined;
    std.mem.writeInt(i64, &counter, 41, .little);
    try c.set(c.t.conn, 2, "k", &counter, .always, null, null);
    try c.send(c.other, .kv_incr, 3, "k", "kv.incr", .{ .delta = 1, .txn = null });
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();
    var diag: schema.Diagnostic = .{};
    try std.testing.expectEqual(@as(i64, 42), (try table_run.op("kv.incr").response.decodeAll((try c.otherAnswer()).data, &diag)).value.?);

    // And the other way round: refused as it applies, ran=no.
    try c.set(c.t.conn, 4, "k", "text", .always, null, null);
    try c.send(c.other, .kv_incr, 5, "k", "kv.incr", .{ .delta = 1, .txn = null });
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();
    const refused = try (try c.otherAnswer()).refused();
    try std.testing.expectEqual(proto.Reason.wrong_type, refused.reason);
    try std.testing.expectEqual(proto.Ran.no, refused.ran);
}

test "Shard: a conditional write its leader lost before it committed is told it didn't run, not that it conflicted" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    try c.set(c.t.conn, 1, "k", "v1", .always, null, null);
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();

    // It would be refused, but no one knows yet.
    try c.set(c.t.conn, 2, "k", "no", .if_absent, null, null);
    c.t.shard.resolvePending("unavailable: stepped down");
    const resp = try c.answer();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), resp.header.status);
    try std.testing.expect((try resp.refused()).reason != .condition_failed);
}

test "Shard: a transaction's condition is answered at commit, not at the op, and the batch applies nothing" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    try c.set(c.t.conn, 1, "k", "v1", .always, null, null);
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();

    const id = try c.t.shard.kv_handler.txn_table.begin(node_router.routeNsKey(.default, "k"), .default);
    try c.set(c.t.conn, 2, "{k}other", "x", .always, null, id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    // Would fail now, and buffers all the same.
    try c.set(c.t.conn, 3, "k", "no", .if_absent, null, id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try c.send(c.t.conn, .kv_commit_txn, 4, "", "kv.txn.commit", .{ .txn = id });
    try ParkTest.ack(&c.t.shard);
    const resp = try c.answer();
    try CondTest.expectConflict(resp, .condition_failed);
    try std.testing.expectEqualStrings("the transaction's op 2: conflict: the condition didn't hold; nothing in the transaction applied", (try resp.refused()).message);
    try std.testing.expect(c.held("{k}other") == null);
    try std.testing.expectEqualStrings("v1", c.held("k").?.value);
}

test "Shard: a delete or expire in a transaction keeps its cas_version: a wrong one is refused at commit" {
    inline for (.{ "kv.delete", "kv.expire" }, .{ proto.OpCode.kv_delete, proto.OpCode.kv_expire }) |name, op| {
        var c: CondTest = undefined;
        try c.init();
        defer c.deinit();
        try c.set(c.t.conn, 1, "k", "v1", .always, null, null);
        try ParkTest.ack(&c.t.shard);
        _ = try c.answer();

        const id = try c.t.shard.kv_handler.txn_table.begin(node_router.routeNsKey(.default, "k"), .default);
        const body: table_run.op(name).request.Value = if (op == .kv_delete)
            .{ .cas_version = 9, .txn = id }
        else
            .{ .ttl_ms = 1000, .cas_version = 9, .txn = id };
        try c.send(c.t.conn, op, 2, "k", name, body);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
        try c.send(c.t.conn, .kv_commit_txn, 3, "", "kv.txn.commit", .{ .txn = id });
        try ParkTest.ack(&c.t.shard);
        try CondTest.expectConflict(try c.answer(), .cas_mismatch);
        try std.testing.expectEqualStrings("v1", c.held("k").?.value);
        try std.testing.expectEqual(@as(u64, 0), c.held("k").?.expiry_ns);
    }
}

test "Shard: a delete or expire of a missing key goes through the log, and is answered as it applies" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    const raft = c.t.shard.raft_node;
    var last = raft.log.lastIndex();

    try c.send(c.t.conn, .kv_delete, 1, "none", "kv.delete", .{ .cas_version = null, .txn = null });
    try std.testing.expectEqual(last + 1, raft.log.lastIndex());
    try ParkTest.ack(&c.t.shard);
    var diag: schema.Diagnostic = .{};
    try std.testing.expectEqual(false, (try KVHandler.DeleteResponse.decodeAll((try c.answer()).data, &diag)).existed.?);
    try std.testing.expect(c.held("none") == null);

    last = raft.log.lastIndex();
    try c.send(c.t.conn, .kv_expire, 2, "none", "kv.expire", .{ .ttl_ms = 1000, .cas_version = 7, .txn = null });
    try std.testing.expectEqual(last + 1, raft.log.lastIndex());
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(proto.Reason.not_found, (try (try c.answer()).refused()).reason);
}

test "Shard: a KV commit answered with a failure instead of its batch drops its transaction" {
    for ([_]bool{ true, false }) |by_index| {
        const pipe_fds = try @import("stdx").io.pipe();
        defer _ = std.c.close(pipe_fds[0]);
        defer _ = std.c.close(pipe_fds[1]);
        var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        defer rn.deinit();
        var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
        defer shard.deinit();
        shard.raft_network = &rn;
        shard.wireHandlerShardPtrs();
        try ParkTest.joinPeer(&shard);

        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        defer _ = std.c.close(pair[1]);
        const conn = try shard.addConnection(pair[0]);
        var buf: [2048]u8 = undefined;
        var one: [1]proto.Response = undefined;

        const table_ = &shard.kv_handler.txn_table;
        const commit = table_run.op("kv.txn.commit");
        var txn_buf: [16]u8 = undefined;
        const id2 = try table_.begin(node_router.routeNsKey(.default, "rk"), .default);
        try table_.appendOp(id2, .put, "k", "v", 0, .always, null);
        shard.runRequest(conn, .{ .header = proto.RequestHeader.init(.kv_commit_txn, 2), .namespace = "", .key = "", .value = try commit.request.encodeInto(&txn_buf, .{ .txn = id2 }) }, .client);
        try std.testing.expectEqual(@as(u32, 1), shard.pending_count);
        try std.testing.expect(table_.get(id2).?.committing);

        // The batch won't be answered for: the transaction goes with it.
        if (by_index) shard.failPendingAbove(shard.raft_node.log.lastIndex() - 1, Shard.NOT_ON_DISK) else shard.resolvePending("unavailable: stepped down");
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
        try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.unavailable)), one[0].header.status);
        try std.testing.expect(table_.get(id2) == null);
        try std.testing.expectEqual(@as(usize, 0), table_.count());
    }
}

test "Shard: appends, enqueues and a time-series write parked behind a peer's ack each answer from their own entry" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    const raft = shard.raft_node;

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    var f64_bytes: [8]u8 = undefined;
    std.mem.writeInt(u64, &f64_bytes, @bitCast(@as(f64, 1.5)), .little);
    // Two appends and two enqueues, interleaved with a time-series write:
    // each is answered from its own entry's result, not from what the
    // pair's second entry left behind.
    // An append's value is a batch: [count:u32]([len:u32][payload][header_count:u16])*
    try ParkTest.send(&shard, conn, .stream_append, 10, "s", "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "a" ++ "\x00\x00");
    try ParkTest.send(&shard, conn, .queue_enqueue, 11, "q", "m1");
    try ParkTest.send(&shard, conn, .ts_write, 12, "cpu", &f64_bytes);
    const ts_index = raft.log.lastIndex();
    try ParkTest.send(&shard, conn, .stream_append, 13, "s", "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "b" ++ "\x00\x00");
    try ParkTest.send(&shard, conn, .queue_enqueue, 14, "q", "m2");
    try std.testing.expectEqual(@as(u32, 5), shard.pending_count);
    var buf: [2048]u8 = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &.{});

    try ParkTest.ack(&shard);
    try std.testing.expectEqual(@as(u32, 0), shard.pending_count);

    var rs: [5]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &rs);
    for (rs, 0..) |resp, i| {
        // Answered in log order.
        try std.testing.expectEqual(@as(u64, 10 + i), resp.header.request_id);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    }
    const first_seq = std.mem.readInt(u64, rs[0].data[0..8], .little);
    const first_ts = std.mem.readInt(u64, rs[0].data[8..16], .little);
    // The second record's id follows the first's: the next sequence in the
    // same millisecond, or a later millisecond.
    const seq = std.mem.readInt(u64, rs[3].data[0..8], .little);
    const ts = std.mem.readInt(u64, rs[3].data[8..16], .little);
    try std.testing.expect(ts > first_ts or (ts == first_ts and seq == first_seq + 1));
    try std.testing.expectEqual(@as(u64, 1), std.mem.readInt(u64, rs[1].data[0..8], .little));
    try std.testing.expectEqual(@as(u64, 2), std.mem.readInt(u64, rs[4].data[0..8], .little));
    // Server-stamped: the point's timestamp is its entry header's clock,
    // its sequence its entry's index.
    const hdr_ms = raft.log.getEntry(ts_index).?.header.timestamp_ns / 1_000_000;
    try std.testing.expectEqual(hdr_ms, std.mem.readInt(u64, rs[2].data[8..16], .little));
    try std.testing.expectEqual(ts_index, std.mem.readInt(u64, rs[2].data[16..24], .little));
}

test "Shard: two action invokes parked behind a peer's ack each answer with the run their own entry created" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    const raft = t.shard.raft_node;
    var buf: [2048]u8 = undefined;

    _ = try proposeAction(&t.shard, .action_register, testRegister("act"));
    try ParkTest.ack(&t.shard);
    // An invoke's value starts with its has_labels byte.
    try ParkTest.send(&t.shard, t.conn, .action_invoke, 1, "act", "\x00");
    const first = raft.log.lastIndex();
    try ParkTest.send(&t.shard, t.conn, .action_invoke, 2, "act", "\x00");
    const second = raft.log.lastIndex();
    try std.testing.expectEqual(@as(u32, 2), t.shard.pending_count);
    try ParkTest.ack(&t.shard);

    var rs: [2]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &rs);
    for (rs, [_]u64{ first, second }) |resp, index| {
        // [run_id_len:u16][run_id]...: the run its entry created.
        const n = std.mem.readInt(u16, resp.data[0..2], .little);
        var diag: schema.Diagnostic = .{};
        const inv = try action_entries.Invoke.decodeAll(raft.log.getEntry(index).?.payload, &diag);
        try std.testing.expectEqualStrings(inv.run, resp.data[2..][0..n]);
    }
}

test "Shard: on a cluster leader a workflow's first step invokes its action without waiting for the commit, and the run resumes once the action's completion applies" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    const raft = shard.raft_node;

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [1024]u8 = undefined;
    var one: [1]proto.Response = undefined;

    // An action workers take, and a workflow whose first step invokes it.
    _ = try proposeAction(&shard, .action_register, testRegister("act"));
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"run":"@actions/act","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 20, "flow", def);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);

    // The start is answered once it applies; its first step waits.
    try ParkTest.send(&shard, conn, .workflow_start, 21, "flow", "");
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    const wf = shard.workflow_handler;
    const Run = struct {
        fn byId(h: *WorkflowHandler, id: []const u8) *WorkflowHandler.RunRecord {
            var it = h.runs.valueIterator();
            while (it.next()) |r| if (std.mem.eql(u8, r.run_id_owned, id)) return r;
            @panic("no run with that id");
        }
    };
    var a_id_buf: [32]u8 = undefined;
    const a_id = a_id_buf[0..one[0].data.len];
    @memcpy(a_id, one[0].data);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.running, Run.byId(wf, a_id).status);
    try std.testing.expectEqual(@as(u32, 1), wf.to_step.count());

    // Only a leader takes a step: a follower's proposal would be refused.
    raft.role = .follower;
    wf.advanceStartedRuns(&shard);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.running, Run.byId(wf, a_id).status);
    raft.role = .leader;

    // The leader logs the first step; once that commits, it's queued.
    wf.advanceStartedRuns(&shard);
    try ParkTest.ack(&shard);
    try std.testing.expectEqual(@as(usize, 1), wf.started_to_advance.items.len);

    // A second client's start is parked when the first run takes its
    // step. The step proposes the invoke and moves on: nothing waits for
    // its commit with the workflow's lock held.
    try ParkTest.send(&shard, conn, .workflow_start, 22, "flow", "");
    wf.advanceStartedRuns(&shard);
    const a = Run.byId(wf, a_id);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, a.status);
    const action_run = a.pending_action_run_id_owned.?;
    try std.testing.expect(ActionsHandler.for_tests.run(&shard, .default, action_run) == null);
    try std.testing.expectEqual(@as(u32, 1), shard.pending_count);

    // One ack commits both: the second start is answered (its applier
    // takes the workflow's lock, which nothing holds), and the invoke
    // applies, so workers can take the action run.
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 22), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expectEqual(action_machine.Status.ready, ActionsHandler.for_tests.run(&shard, .default, action_run).?.status);
    wf.advanceStartedRuns(&shard);
    try ParkTest.ack(&shard);
    wf.advanceStartedRuns(&shard);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, Run.byId(wf, one[0].data).status);

    // A worker takes it: answered once its deliver applies.
    var aw_buf: [64]u8 = undefined;
    try ParkTest.send(&shard, conn, .action_await, 23, "w", try ActionsHandler.for_tests.awaitBody(&aw_buf, &.{"act"}, 0, null));
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 23), one[0].header.request_id);
    const task = (try ActionsHandler.for_tests.task(one[0].data)).?;
    try std.testing.expectEqualStrings(action_run, task.run);

    // Its completion is parked like any write; once it applies, the run
    // resumes and follows its success transition.
    var done: [512]u8 = undefined;
    try ParkTest.send(&shard, conn, .action_complete, 24, action_run, try ActionsHandler.for_tests.completeBody(&done, task, "w", "", ""));
    // Proposed, not applied: the run still waits.
    wf.checkPendingActions(&shard);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, Run.byId(wf, a_id).status);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 24), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    wf.checkPendingActions(&shard);
    // Its completion is logged; the run ends when that commits, and is
    // held until then.
    const ending = Run.byId(wf, a_id);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.running, ending.status);
    try std.testing.expect(WorkflowHandler.endingInFlight(&shard, ending));
    try ParkTest.ack(&shard);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.completed, Run.byId(wf, a_id).status);
}

test "Shard: what the tick's workflow steps propose is sent to the followers in that tick" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    _ = try proposeAction(&shard, .action_register, testRegister("act"));
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"run":"@actions/act","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 60, "flow", def);
    try ParkTest.ack(&shard);
    try ParkTest.send(&shard, conn, .workflow_start, 61, "flow", "");
    try ParkTest.ack(&shard);

    // The tick takes the run's first step, which proposes an invoke; the
    // follower hears of it before the tick ends, not at the next poll.
    const raft = shard.raft_node;
    const before = raft.log.lastIndex();
    const sent = rn.outbound.items.len;
    _ = try shard.tick(0);
    try std.testing.expect(raft.log.lastIndex() > before);
    try std.testing.expect(rn.outbound.items.len > sent);
    // What went out carries the new entry, not only a heartbeat.
    try std.testing.expectEqual(raft.log.lastIndex(), raft.peers[0].sent_up_to);
}

