test "Shard: an idempotency key of any length is scoped to its namespace, a retry with key and run id is the same start, and a run id started twice is refused" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [2048]u8 = undefined;

    const def =
        \\{"kind":"Workflow","name":"gate","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 80, "a", "gate", def, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 81, "b", "gate", def, ""), .client);
    try ParkTest.ack(&shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);

    const keyed = [_]u8{ 0, 0, 1, 3, 0, 'k', 'e', 'y', 0 };
    const named = [_]u8{ 0, 0, 0, 1, 2, 0, 'r', '1' };
    // A retry carrying both its key and its own run id is the same start.
    const both = [_]u8{ 0, 0, 1, 1, 0, 'z', 1, 2, 0, 'r', '2' };
    // A key longer than any fixed buffer is still a key.
    var long: [2 + 1 + 2 + 2000 + 1]u8 = undefined;
    @memset(&long, 'x');
    long[0] = 0;
    long[1] = 0;
    long[2] = 1;
    std.mem.writeInt(u16, long[3..5], 2000, .little);
    long[long.len - 1] = 0;
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 82, "a", "gate", &keyed, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 83, "b", "gate", &keyed, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 84, "a", "gate", &named, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 85, "a", "gate", &named, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 86, "a", "gate", &both, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 87, "a", "gate", &both, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 88, "a", "gate", &long, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 89, "a", "gate", &long, ""), .client);
    try ParkTest.ack(&shard);
    var rs: [8]proto.Response = undefined;
    var big: [4096]u8 = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &big, &rs);
    // One key in two namespaces is two runs.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[1].header.status);
    try std.testing.expect(!std.mem.eql(u8, rs[0].data, rs[1].data));
    // The run id is the first start's; the second is refused.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[2].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), rs[3].header.status);
    // Key and run id together: the retry is answered with the first run.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[5].header.status);
    try std.testing.expectEqualStrings(rs[4].data, rs[5].data);
    // A long key: one run, both answered with it.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[7].header.status);
    try std.testing.expectEqualStrings(rs[6].data, rs[7].data);
    try std.testing.expectEqual(@as(usize, 5), shard.workflow_handler.runs.count());

    // A namespace a run key cannot carry (the key is read back up to its
    // first ':') is refused, for a definition and for a start, before
    // anything is proposed.
    const before = shard.raft_node.log.lastIndex();
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 90, "a:b", "gate", def, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 91, "a:b", "gate", &keyed, ""), .client);
    try ParkTest.responses(&shard, conn, pair[1], &big, &two);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), two[0].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), two[1].header.status);
    try std.testing.expect(std.mem.startsWith(u8, (try two[1].refused()).message, "invalid namespace name"));
    try std.testing.expectEqual(before, shard.raft_node.log.lastIndex());
}

test "Shard: concurrent conditional writes are decided in log order: one run per idempotency key, one create per namespace, one version per register" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [2048]u8 = undefined;

    const def =
        \\{"kind":"Workflow","name":"gate","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 70, "gate", def);
    try ParkTest.ack(&shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);

    // Each pair passes its handler's check before the other applies.
    const start = [_]u8{ 0, 0, 1, 3, 0, 'k', 'e', 'y', 0 };
    try ParkTest.send(&shard, conn, .workflow_start, 71, "gate", &start);
    try ParkTest.send(&shard, conn, .workflow_start, 72, "gate", &start);
    try ParkTest.send(&shard, conn, .namespace_create, 73, "team", "");
    try ParkTest.send(&shard, conn, .namespace_create, 74, "team", "");
    try ParkTest.send(&shard, conn, .action_register, 75, "act", "");
    try ParkTest.send(&shard, conn, .action_register, 76, "act", "");
    // The creates aren't parked writes: the first waits for its publish,
    // and the second finds the name being created.
    try std.testing.expectEqual(@as(u32, 4), shard.pending_count);
    try ParkTest.ack(&shard);
    shard.namespace_handler.settle(&shard);

    var got: [6]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &got);
    // In request order, whatever order they were answered in.
    var rs: [6]proto.Response = undefined;
    for (got) |r| rs[r.header.request_id - 71] = r;
    // The second start is answered with the first's run, and created none.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[0].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[1].header.status);
    try std.testing.expectEqualStrings(rs[0].data, rs[1].data);
    try std.testing.expectEqual(@as(usize, 1), shard.workflow_handler.runs.count());
    try std.testing.expectEqual(@as(u32, 1), shard.workflow_handler.to_step.count());
    // The second create finds the namespace being created.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[2].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), rs[3].header.status);
    // Two registers are two versions.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[5].header.status);
    try std.testing.expectEqual(@as(?u32, 2), ActionsHandler.for_tests.version(&shard, .default, "act"));
}

test "Shard: park answers from its own entry when a later one has already committed" {
    try parkAnswersFromOwnEntry(false);
}

test "Shard: park answers from its own entry when the later one is a millisecond on" {
    try parkAnswersFromOwnEntry(true);
}

/// `apart` sleeps between the two appends, so they are stamped in different
/// milliseconds and both have sequence 0: the records differ only by
/// timestamp.
fn parkAnswersFromOwnEntry(apart: bool) !void {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    // On a single node both appends commit as they are proposed; the second
    // stands for another thread's proposal landing before this write parks.
    // The first write is answered from the first's result.
    const Seen = struct {
        var index: u64 = 0;
        var id: ?StreamID = null;
        fn respond(_: *Shard, _: *Connection, _: u64, result: *const persistence_mod.Result) void {
            index = result.index;
            var r = result.reader();
            const seq = r.int(u64) orelse return;
            id = .{ .sequence = seq, .timestamp_ms = r.int(u64) orelse return };
        }
    };
    Seen.id = null;
    const v = try stream_mod.encodeAppendValue(std.testing.allocator, 0, "a");
    defer std.testing.allocator.free(v);
    const first = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    if (apart) @import("stdx").time.sleep(2 * std.time.ns_per_ms);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    shard.park(conn, try ParkTest.request(.stream_append, 50, "", "s", "a", ""), first, Seen.respond);
    try std.testing.expectEqual(first.index, Seen.index);
    // The dispatch that parked applies the rest; the second record is not
    // the one the first write was answered with. A record is named by its
    // whole ID: the sequence alone restarts each millisecond.
    try std.testing.expect(shard.applyCommitted());
    const hash = stream_mod.streamKey(.default, "s");
    const first_id = shard.stream_handler.stream.streamFirstId(hash);
    const last_id = shard.stream_handler.stream.streamLastId(hash);
    try std.testing.expect(Seen.id.?.eql(first_id));
    try std.testing.expect(!Seen.id.?.eql(last_id));
    if (apart) {
        try std.testing.expectEqual(@as(u64, 0), first_id.sequence);
        try std.testing.expectEqual(@as(u64, 0), last_id.sequence);
    }
}

/// A lone shard with a small hot ring and a warm store that keeps almost
/// nothing, holding one-record appends to stream "s", each followed by
/// `filler` appends to stream "f".
const ColdStream = struct {
    tmp: std.testing.TmpDir,
    data_dir: []const u8,
    pipe_fds: [2]i32,
    shard: Shard,
    value: []u8,

    fn init(self: *ColdStream, durability: Durability, appends: usize, filler: usize, flush_every: usize) !void {
        self.tmp = std.testing.tmpDir(.{});
        self.data_dir = try testDataDir(&self.tmp);
        self.pipe_fds = try @import("stdx").io.pipe();
        self.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, self.pipe_fds[0], self.data_dir, 64 * 1024, 0, 0, durability, 1, .single, .{}, .{});
        // Each flush its own sealed segment, as the bulk thread reads them.
        self.shard.durable_log.?.max_segment_bytes = 1;
        self.shard.wireHandlerShardPtrs();
        try std.testing.expect(self.shard.applyCommitted());
        self.shard.defaultPartition().setWarmBudget(4096);
        // One record per append: [count][len][payload][header_count].
        var batch: [4 + 4 + 2048 + 2]u8 = undefined;
        std.mem.writeInt(u32, batch[0..4], 1, .little);
        std.mem.writeInt(u32, batch[4..8], 2048, .little);
        @memset(batch[8 .. 8 + 2048], 'r');
        std.mem.writeInt(u16, batch[8 + 2048 ..][0..2], 0, .little);
        self.value = try stream_mod.encodeAppendValue(std.testing.allocator, 0, &batch);
        for (0..appends) |i| {
            _ = try persistence_mod.proposeEntry(&self.shard, .stream_append, entry_mod.Flags.NONE, "", "s", self.value);
            for (0..filler) |_| _ = try persistence_mod.proposeEntry(&self.shard, .stream_append, entry_mod.Flags.NONE, "", "f", self.value);
            try std.testing.expect(self.shard.applyCommitted());
            if (flush_every > 0 and i % flush_every == flush_every - 1) try self.shard.flushSegmentToDisk();
        }
        if (flush_every > 0) try self.shard.flushSegmentToDisk();
    }

    fn deinit(self: *ColdStream) void {
        self.shard.deinit();
        std.testing.allocator.free(self.value);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
        std.testing.allocator.free(self.data_dir);
        self.tmp.cleanup();
    }

    fn window(limit: u32) waiter_pool_mod.StreamWindow {
        return .{ .stream = stream_mod.streamKey(.default, "s"), .limit = limit };
    }

    /// Read `w`, landing disk reads and reading again while it is held, as
    /// the shard's tick and a held read's wake do.
    fn read(self: *ColdStream, w: *waiter_pool_mod.StreamWindow, buf: *[StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord) !struct { []stream_mod.StreamRecord, @import("../protocol/result.zig").CommandResult } {
        const handler = self.shard.stream_handler;
        for (0..5_000) |_| {
            const records, const result = handler.readReadable(w, buf);
            if (result != .pending) return .{ records, result };
            if (handler.held == .blocked) return error.Blocked;
            var waited: usize = 0;
            while (!self.shard.stream_disk.?.drain()) : (waited += 1) {
                if (waited == 2_000) return error.NeverLanded;
                @import("stdx").time.sleep(std.time.ns_per_ms);
            }
        }
        return error.NeverServed;
    }
};

test "Shard: a stream record past the hot ring and the warm store is read back from its segment" {
    var c: ColdStream = undefined;
    // Async durability, flushed every 10 appends: segments of 10. (Under sync
    // each commit seals a segment of its own.)
    try c.init(.async_flush, 100, 0, 10);
    defer c.deinit();
    // From the start: held once, then every record, the first ones from the
    // durable log, none skipped.
    var w = ColdStream.window(10);
    var buf: [StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord = undefined;
    const records, const result = try c.read(&w, &buf);
    defer c.shard.stream_handler.freeResult(result);
    try std.testing.expectEqual(@as(usize, 10), records.len);
    try std.testing.expectEqual(@as(u32, 10), std.mem.readInt(u32, result.stream_messages.data[0..4], .little));
    try std.testing.expectEqual(@as(u64, 0), c.shard.stream_handler.skipped_appends);
    // The first record's tier byte says disk: after the count, sequence
    // and timestamp.
    try std.testing.expectEqual(@backingInt(proto.StorageTier.disk), result.stream_messages.data[4 + 8 + 8]);
}

test "Shard: a stream record past the warm store but not yet flushed is read from the writer's buffer, not skipped" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 100, 0, 0);
    defer c.deinit();
    // Under async durability a burst outruns the flush: nothing is sealed.
    try std.testing.expect(c.shard.durable_log.?.writer.entry_count > 0);
    var w = ColdStream.window(10);
