test "Shard: a parked request leaves the pending table before it is answered, so a sweep during its answer answers the client once" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    // An answer that sweeps the pending table: the request it answers
    // must not be in it.
    const Sweep = struct {
        fn respond(sh: *Shard, conn_: *Connection, request_id: u64, _: *const persistence_mod.Result) void {
            sh.resolvePending("swept");
            sh.sendOkResponse(conn_, request_id, "answered");
        }
    };
    // Any entry will do: the answer under test never reads it.
    const proposed = try KVHandler.testProposePut(&shard, "k", "");
    shard.park(conn, try ParkTest.request(.kv_put, 30, "", "k", "v", ""), proposed, Sweep.respond);
    try std.testing.expectEqual(@as(u32, 1), shard.pending_count);

    try ParkTest.ack(&shard);
    try std.testing.expectEqual(@as(u32, 0), shard.pending_count);
    // One answer, the answer function's.
    var buf: [256]u8 = undefined;
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 30), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expectEqualStrings("answered", one[0].data);
}

test "Shard: a burst of first writes to a new namespace proposes one implicit create, and none once it applied" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    const raft = shard.raft_node;
    const ns = shard.namespace_handler;

    const Count = struct {
        fn creates(r: *RaftNode, from: u64) u32 {
            var n: u32 = 0;
            var i = from;
            while (i <= r.log.lastIndex()) : (i += 1) {
                if (r.log.getEntry(i).?.header.entry_type == @backingInt(entry_mod.EntryType.namespace_create)) n += 1;
            }
            return n;
        }
    };
    const first = raft.log.lastIndex() + 1;
    for (0..3) |_| ns.markNamespaceHasData("fresh", &shard);
    try std.testing.expectEqual(@as(u32, 1), Count.creates(raft, first));

    // Once it applies the namespace exists, and its next write proposes nothing.
    try ParkTest.ack(&shard);
    try std.testing.expect(ns.namespaces.contains("fresh"));
    const again = raft.log.lastIndex() + 1;
    ns.markNamespaceHasData("fresh", &shard);
    try std.testing.expectEqual(@as(u32, 0), Count.creates(raft, again));
}

