test "Shard: a backlog applies in passes, each ending at its budget" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    // More entries than one pass takes, none applied at boot.
    const n: u64 = 3 * (Shard.APPLY_PASS_NS / Shard.ENTRY_COST_NS);
    try writeMemberSegment(data_dir, n, 0);

    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .join, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    const raft = shard.raft_node;
    raft.commit_index = raft.log.lastIndex();

    var passes: u64 = 0;
    while (raft.last_applied < raft.commit_index) : (passes += 1) {
        // Inside a tick, as the loop runs it: a second call applies nothing.
        shard.in_tick = true;
        defer shard.in_tick = false;
        shard.apply_tick_spent = 0;
        const before = raft.last_applied;
        try std.testing.expect(shard.applyCommitted());
        try std.testing.expect(raft.last_applied > before);
        try std.testing.expectEqual(raft.last_applied < raft.commit_index, shard.apply_behind);
        if (shard.apply_behind) {
            const at = raft.last_applied;
            try std.testing.expect(shard.applyCommitted());
            try std.testing.expectEqual(at, raft.last_applied);
        }
    }
    try std.testing.expect(passes >= 3 and passes <= 5);
    try std.testing.expectEqual(n, queue_handler_mod.countQueue(&shard, .default, "q"));
}

test "Shard: a leader still applying earlier terms' entries refuses the reads it answers from memory" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try queue_handler_mod.enqueueHere(&shard, "q", "here");
    const conn_pipe = try @import("stdx").io.pipe();
    defer _ = std.c.close(conn_pipe[1]);
    const conn = try shard.addConnection(conn_pipe[0]);
    defer shard.removeConnection(conn_pipe[0]);

    const Peek = table_run.op("queue.peek");
    var body_buf: [Peek.request.max_size]u8 = undefined;
    const body = try Peek.request.encodeInto(&body_buf, .{ .limit = 5 });
    const raft = shard.raft_node;
    try std.testing.expect(raft.leaderReady());
    // Elected with entries of earlier terms still to apply.
    raft.ready_index = raft.log.lastIndex() + 100;
    var out: [512]u8 = undefined;
    for ([_]proto.OpCode{ .queue_peek, .queue_dlq_list, .stream_group_info }, 0..) |op, i| {
        shard.runRequest(conn, .{ .header = proto.RequestHeader.init(op, 10 + i), .namespace = "default", .key = "q", .value = if (op == .queue_peek) body else "" }, .client);
        const refused = try proto.Response.parse(out[0..conn.write_buf.read(&out)]);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), refused.header.status);
        try std.testing.expect(std.mem.indexOf(u8, refused.data, "still applying what earlier leaders committed") != null);
    }
    // Ready, it answers from what it holds.
    raft.ready_index = 0;
    shard.runRequest(conn, .{ .header = proto.RequestHeader.init(.queue_peek, 20), .namespace = "default", .key = "q", .value = body }, .client);
    const got = try proto.Response.parse(out[0..conn.write_buf.read(&out)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), got.header.status);
    try std.testing.expect(std.mem.indexOf(u8, got.data, "here") != null);
}

test "Shard: a new leader refuses plain reads until it has applied earlier terms, then answers them" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    var out: [4096]u8 = undefined;

    var body_buf: [64]u8 = undefined;
    shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.kv_put, 1), .namespace = "", .key = "k", .value = try kv_ops.plainSetBody(&body_buf, "the-value") }, .client);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), (try nextAnswer(c, &shard, &out)).header.status);
    const run_id = "chosen-run";
    _ = try applyActionEntry(&shard, .action_register, testRegister("echo"), shard.raft_node.last_applied + 1, 1);
    _ = try applyActionEntry(&shard, .action_invoke, testInvoke("echo", run_id), shard.raft_node.last_applied + 1, 1000 * std.time.ns_per_ms);

    const get: proto.Request = .{ .header = proto.RequestHeader.init(.kv_get, 2), .namespace = "", .key = "k", .value = try kv_ops.plainGetBody(&body_buf) };
    const status: proto.Request = .{ .header = proto.RequestHeader.init(.action_status, 3), .namespace = "", .key = run_id, .value = "" };
    const raft = shard.raft_node;
    try std.testing.expect(raft.leaderReady());
    // Elected with entries of earlier terms still to apply.
    raft.ready_index = raft.log.lastIndex() + 100;

    // Asked by a client and by another shard, both are refused, retryably.
    for ([_]proto.Request{ get, status }) |req| for ([_]@import("run.zig").Origin{ .client, .shard }) |origin| {
        shard.runRequest(c.conn, req, origin);
        const refused = try nextAnswer(c, &shard, &out);
        try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.unavailable)), refused.header.status);
        const why = try refused.refused();
        try std.testing.expectEqual(@import("../protocol/reason.zig").Reason.leader_unknown, why.reason);
        try std.testing.expectEqual(proto.Ran.no, why.ran);
        try std.testing.expectEqualStrings(Shard.LEADER_NOT_READY_REFUSAL, why.message);
    };
    // What reads no projection still answers.
    shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.ping, 4), .namespace = "", .key = "", .value = "" }, .client);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), (try nextAnswer(c, &shard, &out)).header.status);
    shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.cluster_status, 5), .namespace = "", .key = "", .value = "" }, .client);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), (try nextAnswer(c, &shard, &out)).header.status);

    // Ready, both answer what the log holds.
    raft.ready_index = raft.last_applied;
    shard.runRequest(c.conn, get, .client);
    const got = try nextAnswer(c, &shard, &out);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), got.header.status);
    try std.testing.expect(std.mem.indexOf(u8, got.data, "the-value") != null);
    shard.runRequest(c.conn, status, .client);
    const answered = try nextAnswer(c, &shard, &out);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), answered.header.status);
    var diag: schema.Diagnostic = .{};
    try std.testing.expectEqual(@import("../protocol/action_ops.zig").RunStatus.pending, (try table_run.op("action.status").response.decodeAll(answered.data, &diag)).status);
}

test "Shard: a leader still applying earlier terms refuses writes chosen from its state, and proposes nothing" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    var out: [4096]u8 = undefined;

    const raft = shard.raft_node;
    const refused_while_applying = [_]proto.OpCode{ .stream_delete, .stream_append, .stream_group_create, .queue_enqueue, .queue_dequeue, .ts_write, .workflow_cancel, .workflow_signal, .action_invoke };
    raft.ready_index = raft.log.lastIndex() + 100;
    const last = raft.log.lastIndex();
    for (refused_while_applying, 0..) |op, i| for ([_]@import("run.zig").Origin{ .client, .shard, .peer }) |origin| {
        shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(op, i + 1), .namespace = "", .key = "k", .value = "" }, origin);
        try expectLeaderNotReady(try nextAnswer(c, &shard, &out));
    };
    try std.testing.expectEqual(last, raft.log.lastIndex());
}

test "Shard: a stream's appends a new leader hasn't applied: a delete is refused, then weighed against them" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    const raft = c.t.shard.raft_node;
    try ParkTest.send(&c.t.shard, c.t.conn, .stream_append, 1, "s", "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "a" ++ "\x00\x00");

    // As a leader finds its predecessor's entry: in its log, not applied, so
    // the stream looks empty here. Without the refusal the delete is proposed, and
    // only its apply would stop it.
    raft.ready_index = raft.log.lastIndex();
    const last = raft.log.lastIndex();
    try ParkTest.send(&c.t.shard, c.other, .stream_delete, 2, "s", "");
    try expectLeaderNotReady(try c.otherAnswer());
    try std.testing.expectEqual(last, raft.log.lastIndex());

    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try std.testing.expect(raft.leaderReady());
    try ParkTest.send(&c.t.shard, c.other, .stream_delete, 3, "s", "");
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), (try c.otherAnswer()).header.status);
}

test "Shard: a stream delete proposed behind an append not yet applied is refused when it applies, and the record stays" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    const record = "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "a" ++ "\x00\x00";
    // Both proposed before either applies: at propose time the stream is empty.
    try ParkTest.send(&c.t.shard, c.t.conn, .stream_append, 1, "s", record);
    try ParkTest.send(&c.t.shard, c.other, .stream_delete, 2, "s", "");
    try std.testing.expectEqual(@as(u32, 2), c.t.shard.pending_count);
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    const refused = try c.otherAnswer();
    try CondTest.expectConflict(refused, .unclassified);
    try std.testing.expectEqualStrings(@import("../stream/handler.zig").StreamHandler.NOT_EMPTY_MESSAGE, (try refused.refused()).message);
    const name_hash = stream_mod.streamKey(.default, "s");
    try std.testing.expectEqual(@as(usize, 1), c.t.shard.defaultPartition().stream.streamRecordCount(name_hash));

    // Forced, it goes whatever the stream holds.
    var ob: [8]u8 = undefined;
    var options = proto.OptionsBuilder.init(&ob);
    try options.addFlag(.force);
    c.t.shard.runRequest(c.other, try ParkTest.request(.stream_delete, 3, proto.DEFAULT_NAMESPACE, "s", "", options.getOptions()), .client);
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.otherAnswer()).header.status);
    try std.testing.expectEqual(@as(usize, 0), c.t.shard.defaultPartition().stream.streamRecordCount(name_hash));
}

test "Shard: a run a new leader hasn't seen finish: a cancel is refused, then told it finished" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    const raft = c.t.shard.raft_node;
    _ = try proposeAction(&c.t.shard, .action_register, testRegister("act"));
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"run":"@actions/act","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(&c.t.shard, c.t.conn, .workflow_create, 1, "flow", def);
    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try ParkTest.send(&c.t.shard, c.t.conn, .workflow_start, 2, "flow", "");
    try ParkTest.ack(&c.t.shard);
    const started = try c.answer();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), started.header.status);
    var id_buf: [32]u8 = undefined;
    const run_id = id_buf[0..started.data.len];
    @memcpy(run_id, started.data);

    // What finishes the run: as a new leader finds it, in its log, not applied.
    // A cancel is answered when it applies, so this one waits for the ack.
    try ParkTest.send(&c.t.shard, c.t.conn, .workflow_cancel, 3, run_id, "first");
    raft.ready_index = raft.log.lastIndex();
    const last = raft.log.lastIndex();
    try ParkTest.send(&c.t.shard, c.other, .workflow_cancel, 4, run_id, "second");
    try expectLeaderNotReady(try c.otherAnswer());
    try std.testing.expectEqual(last, raft.log.lastIndex());

    try ParkTest.ack(&c.t.shard);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);
    try std.testing.expect(raft.leaderReady());
    try ParkTest.send(&c.t.shard, c.other, .workflow_cancel, 5, run_id, "third");
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), (try c.otherAnswer()).header.status);
    try std.testing.expectEqual(last, raft.log.lastIndex());
}

test "Shard: a leader still applying earlier terms still takes KV's writes, its transactions and a membership change" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    const raft = c.t.shard.raft_node;
    try c.set(c.t.conn, 1, "k", "v1", .always, null, null);
    try ParkTest.ack(&c.t.shard);
    _ = try c.answer();
    const id = try c.t.shard.kv_handler.txn_table.begin(node_router.routeNsKey(.default, "in-txn"), .default);
    try c.set(c.t.conn, 2, "in-txn", "x", .always, null, id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.answer()).header.status);

    raft.ready_index = raft.log.lastIndex() + 100;
    var last = raft.log.lastIndex();
    // A plain write and a commit, each proposed: decided as they apply.
    try c.set(c.t.conn, 3, "k", "v2", .if_present, null, null);
    try std.testing.expectEqual(last + 1, raft.log.lastIndex());
    last = raft.log.lastIndex();
    try c.send(c.other, .kv_commit_txn, 4, "", "kv.txn.commit", .{ .txn = id });
    try std.testing.expectEqual(last + 1, raft.log.lastIndex());

    // The leader's first commit is behind it, so a membership change is proposed.
    last = raft.log.lastIndex();
    var remove: [5]u8 = undefined;
    std.mem.writeInt(u32, remove[0..4], 2, .little);
    remove[4] = 1;
    c.t.shard.runRequest(c.other, try ParkTest.request(.cluster_remove, 5, "", "", &remove, ""), .admin);
    try std.testing.expectEqual(last + 1, raft.log.lastIndex());
}

test "Shard: a leader still applying earlier terms answers a repair, a worker and a namespace create for themselves" {
    var c: CondTest = undefined;
    try c.init();
    defer c.deinit();
    const shard = &c.t.shard;
    const raft = shard.raft_node;
    raft.ready_index = raft.log.lastIndex() + 100;
    const last = raft.log.lastIndex();

    // Not understood by the repair itself, which never met the refusal.
    shard.runRequest(c.other, try ParkTest.request(.cluster_repair_skip, 1, "", "", "", ""), .admin);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), (try c.otherAnswer()).header.status);

    // Only this node's memory: each answered, and nothing proposed.
    inline for (.{ proto.OpCode.worker_register, proto.OpCode.worker_heartbeat, proto.OpCode.worker_drain, proto.OpCode.worker_deregister }, 2..) |op, id| {
        shard.runRequest(c.other, try ParkTest.request(op, id, "", "w1", "", ""), .client);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try c.otherAnswer()).header.status);
    }

    // Its own refusal, naming what didn't happen.
    shard.runRequest(c.other, try ParkTest.request(.namespace_create, 6, "", "fresh", "", ""), .client);
    const refused = try c.otherAnswer();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), refused.header.status);
    try std.testing.expectEqualStrings(handler_mod.NamespaceHandler.CATCHING_UP_MESSAGE, (try refused.refused()).message);
    try std.testing.expectEqual(last, raft.log.lastIndex());
}

