    noop.header.crc32c = noop.computeCrc();
    try w.addEntry(&noop);
    try w.addEntry(&testEnqueueEntry(2, "q", "A"));
    try w.addEntry(&testEnqueueEntry(3, "q", "B"));
    w.commit_index_at_seal = 2;
