test "a restarted node stamps after the last entry its log replays, though its clock is now behind it" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    // A clock a day ahead stamps the first run's writes.
    const Ahead = struct {
        ns: u64,
        fn read(ctx: ?*anyopaque) u64 {
            const self: *const @This() = @ptrCast(@alignCast(ctx.?));
            return self.ns;
        }
    };
    var ahead: Ahead = .{ .ns = @intCast(@import("stdx").time.nanoTimestamp() + std.time.ns_per_day) };
    var last: u64 = 0;
    {
        var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .sync, 1, .single, .{}, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        shard.raft_node.wall_clock = .{ .ctx = &ahead, .now_ns = Ahead.read };
        _ = try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'A'});
        last = (try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'B'})).timestamp_ns;
        try std.testing.expect(shard.applyCommitted());
    }

    // Back on the true clock, a day behind what it stamped.
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .sync, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    shard.applyDeferredTail();
    const next = try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'C'});
    try std.testing.expect(next.timestamp_ns > last);
    try std.testing.expect(shard.raft_node.stamp_clock_behind);
}

test "KV reads on a shard judge expiry by its Raft node's time, not the host's wall clock" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    // The node's clock runs a day ahead of the host's: a read by the
    // host's clock would see the key live a day longer.
    const Ahead = struct {
        ns: u64,
        fn read(ctx: ?*anyopaque) u64 {
            const self: *const @This() = @ptrCast(@alignCast(ctx.?));
            return self.ns;
        }
    };
    var ahead: Ahead = .{ .ns = @intCast(@import("stdx").time.nanoTimestamp() + std.time.ns_per_day) };
    shard.raft_node.wall_clock = .{ .ctx = &ahead, .now_ns = Ahead.read };
    var buf: [64]u8 = undefined;
    const put = try kv_entries.Put.encodeInto(&buf, .{ .key = TEST_KV_K, .value = "v", .ttl_ms = 1_000, .condition = .always, .cas_version = null });
    _ = try shard.raft_node.propose(.kv_put, entry_mod.Flags.NONE, put);
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expect(shard.kv_handler.kv.getIn(.default, "k") != null);
    ahead.ns += 2 * std.time.ns_per_s;
    try std.testing.expect(shard.kv_handler.kv.getIn(.default, "k") == null);
}

/// A lone shard answering one client over a socket pair; `client` is the
/// client's end.
const ReadTest = struct {
    pipe_fds: [2]i32,
    pair: [2]std.posix.fd_t,
    shard: Shard,
    conn: *Connection,

    fn init(self: *ReadTest) !void {
        self.pipe_fds = try @import("stdx").io.pipe();
        self.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, self.pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        self.shard.wireHandlerShardPtrs();
        try std.testing.expect(self.shard.applyCommitted());
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &self.pair));
        const flags = std.c.fcntl(self.pair[0], std.c.F.GETFL, @as(c_int, 0));
        _ = std.c.fcntl(self.pair[0], std.c.F.SETFL, flags | @as(c_int, @bitCast(std.c.O{ .NONBLOCK = true })));
        self.conn = try self.shard.addConnection(self.pair[0]);
    }

    fn deinit(self: *ReadTest) void {
        self.shard.deinit();
        _ = std.c.close(self.pair[1]);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
    }

    /// A kv_get as the client sends it.
    fn sendGet(self: *ReadTest, id: u64) !void {
        const wire = try Shard.serializeRequest(std.testing.allocator, try ParkTest.request(.kv_get, id, "", "some-key-for-the-test", "", ""));
        defer std.testing.allocator.free(wire);
        try std.testing.expectEqual(@as(isize, @intCast(wire.len)), std.c.write(self.pair[1], wire.ptr, wire.len));
    }

    /// End-of-tick passes until `want` answers arrived, or none came in a pass.
    fn answers(self: *ReadTest, want: usize) !usize {
        var buf: [4096]u8 = undefined;
        var total: usize = 0;
        var got: usize = 0;
        for (0..64) |_| {
            self.shard.settleConnections();
            self.shard.flushToClient(self.conn.fd);
            while (true) {
                const n = std.c.recv(self.pair[1], buf[total..].ptr, buf.len - total, std.c.MSG.DONTWAIT);
                if (n <= 0) break;
                total += @intCast(n);
            }
            var off: usize = 0;
            got = 0;
            while (proto.Response.parse(buf[off..total])) |r| : (got += 1) {
                off += @sizeOf(proto.ResponseHeader) + r.data.len;
            } else |_| {}
            if (got >= want) break;
        }
        return got;
    }
};

test "Shard: a request read a little per event is still answered, the rest read at the end of the tick" {
    var t: ReadTest = undefined;
    try t.init();
    defer t.deinit();
    // One read per event, into a buffer smaller than the request: every
    // read fills its room, so each event stops with more in the socket.
    t.shard.reads_per_event = 1;
    t.conn.read_buf.deinit();
    t.conn.read_buf = try RingBuffer.initWithCapacity(std.testing.allocator, 16);

    try t.sendGet(1);
    t.shard.readFromClient(t.conn.fd);
    try std.testing.expect(t.conn.resume_queued);
    try std.testing.expectEqual(@as(usize, 1), try t.answers(1));
}

test "Shard: what a client sent while its reads were paused is read when they resume" {
    var t: ReadTest = undefined;
    try t.init();
    defer t.deinit();

    t.shard.pauseReads(t.conn.fd, t.conn);
    try t.sendGet(1);
    t.shard.readFromClient(t.conn.fd);
    try std.testing.expectEqual(@as(usize, 0), t.conn.read_buf.readable());
    t.shard.resumeReads(t.conn.fd, t.conn);
    try std.testing.expectEqual(@as(usize, 1), try t.answers(1));
}

/// A lone node with sync durability, its data dir under `tmp`, answering a
/// client over a socket pair.
const SyncAlone = struct {
    data_dir: []const u8,
    segs_z: [:0]u8,
    pipe_fds: [2]i32,
    pair: [2]std.posix.fd_t,
    shard: Shard,
    conn: *Connection,

    fn init(self: *SyncAlone, tmp: *std.testing.TmpDir) !void {
        self.data_dir = try testDataDir(tmp);
        self.segs_z = try std.fmt.allocPrintSentinel(std.testing.allocator, "{s}/00000/segs", .{self.data_dir}, 0);
        self.pipe_fds = try @import("stdx").io.pipe();
        self.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, self.pipe_fds[0], self.data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .sync, 1, .single, .{ .self_counts_when_durable = true }, .{});
        self.shard.wireHandlerShardPtrs();
        try std.testing.expect(self.shard.applyCommitted());
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &self.pair));
        self.conn = try self.shard.addConnection(self.pair[0]);
    }

    fn deinit(self: *SyncAlone) void {
        _ = std.c.chmod(self.segs_z, 0o700);
        self.shard.deinit();
        _ = std.c.close(self.pair[1]);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
        std.testing.allocator.free(self.segs_z);
        std.testing.allocator.free(self.data_dir);
    }

    /// The answer borrows from `buf`.
    fn put(self: *SyncAlone, id: u64, key: []const u8, buf: []u8) !proto.Response {
        try ParkTest.send(&self.shard, self.conn, .kv_put, id, key, "v");
        _ = self.shard.applyCommitted();
        var r: [1]proto.Response = undefined;
        try ParkTest.responses(&self.shard, self.conn, self.pair[1], buf, &r);
        return r[0];
    }
};

test "Shard: alone with sync durability, a write whose flush fails is not acked, and applies once the disk recovers" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();

    // The segments directory refuses new files, and the active segment,
    // closed, won't open for writing: the flush fails.
    const dl = s.shard.durable_log.?;
    dl.closeActive();
    const files = try dl.segments();
    var seg_z: [520:0]u8 = undefined;
    _ = try std.fmt.bufPrintSentinel(&seg_z, "{s}", .{files[files.len - 1].path}, 0);
    try std.testing.expectEqual(@as(c_int, 0), std.c.chmod(&seg_z, 0o400));
    try std.testing.expectEqual(@as(c_int, 0), std.c.chmod(s.segs_z, 0o500));
    var buf: [1024]u8 = undefined;
    const refused = try s.put(1, "k1", &buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, refused.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, refused.data, "not on disk") != null);
    try std.testing.expect(s.shard.kv_handler.kv.getIn(.default, "k1") == null);

    try std.testing.expectEqual(@as(c_int, 0), std.c.chmod(s.segs_z, 0o700));
    try std.testing.expectEqual(@as(c_int, 0), std.c.chmod(&seg_z, 0o600));
    const acked = try s.put(2, "k2", &buf);
    try std.testing.expectEqual(proto.StatusCode.ok, acked.getStatus());
    // The refused write was in the log; it reached disk with this one.
    try std.testing.expect(s.shard.kv_handler.kv.getIn(.default, "k1") != null);
    try std.testing.expect(s.shard.kv_handler.kv.getIn(.default, "k2") != null);
}

test "Shard: alone with sync durability, the writes a tick parks share one flush, and none is answered before it" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    const dl = s.shard.durable_log.?;
    const before = dl.appends;
    // Three writes parked in one tick, before its apply pass: none flushed,
    // none answered.
    for (0..3) |i| {
        var kbuf: [8]u8 = undefined;
        try ParkTest.send(&s.shard, s.conn, .kv_put, 10 + i, try std.fmt.bufPrint(&kbuf, "g{d}", .{i}), "v");
    }
    try std.testing.expectEqual(before, dl.appends);
    try std.testing.expect(s.shard.raft_node.durable_index < s.shard.raft_node.log.lastIndex());
    var rbuf: [64]u8 = undefined;
    try std.testing.expect(std.c.recv(s.pair[1], &rbuf, rbuf.len, std.c.MSG.DONTWAIT) <= 0);
    // The apply pass: one flush for the three, then their answers.
    _ = s.shard.applyCommitted();
    try std.testing.expectEqual(before + 1, dl.appends);
    var buf: [2048]u8 = undefined;
    var r: [3]proto.Response = undefined;
    try ParkTest.responses(&s.shard, s.conn, s.pair[1], &buf, &r);
    for (r) |one| try std.testing.expectEqual(proto.StatusCode.ok, one.getStatus());
}

test "Shard: an entry the writer could not buffer is buffered again from the log before the flush" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();

    // As if the append hook had failed on the next entry: nothing from it
    // on is buffered, and the flush must buffer it from the log.
    const writer = s.shard.durable_log.?.writer;
    writer.first_unbuffered = s.shard.raft_node.log.lastIndex() + 1;
    var buf: [1024]u8 = undefined;
    const acked = try s.put(1, "k1", &buf);
    try std.testing.expectEqual(proto.StatusCode.ok, acked.getStatus());
    try std.testing.expect(writer.first_unbuffered == null);
    var got: [4]entry_mod.Entry = undefined;
    var arena: [256]u8 = undefined;
    try std.testing.expect(s.shard.durable_log.?.readRange(s.shard.raft_node.log.lastIndex(), &got, &arena).count == 1);
}

test "Shard: with sync durability, entries after one the writer could not buffer reach disk once each, in order" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());

    // An empty buffer with no room: buffering the next entry allocates,
    // and that allocation fails. The one after it is appended before any
    // flush, as a follower appends a batch.
    const writer = s.shard.durable_log.?.writer;
    try std.testing.expectEqual(@as(u32, 0), writer.entry_count);
    writer.data.clearAndFree(writer.allocator);
    writer.sparse_index.clearAndFree(writer.allocator);
    const real = writer.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    writer.allocator = failing.allocator();
    const first = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k1", "v");
    writer.allocator = real;
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);

    s.shard.syncFlushIfNeeded();
    try std.testing.expectEqual(first.index + 1, s.shard.raft_node.durable_index);
    var got: [4]entry_mod.Entry = undefined;
    var arena: [256]u8 = undefined;
    try std.testing.expectEqual(@as(usize, 2), s.shard.durable_log.?.readRange(first.index, &got, &arena).count);
    try std.testing.expectEqual(first.index, got[0].header.index);
    try std.testing.expectEqual(first.index + 1, got[1].header.index);
}

test "Shard: in sync mode a buffer-failure run holds behind the gap and ends once rebuffering catches up" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());

    // Empty the buffer and fail the next growth, as the sync-durability test above.
    const writer = s.shard.durable_log.?.writer;
    writer.data.clearAndFree(writer.allocator);
    writer.sparse_index.clearAndFree(writer.allocator);
    const real = writer.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    writer.allocator = failing.allocator();
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k1", "v");
    writer.allocator = real;
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);
    // The run started. Behind the sync gap the append hook returns early, so
    // the next entry does not clear it — it holds until rebuffering catches up.
    try std.testing.expect(writer.buffer_failing_since_ms != 0);
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    try std.testing.expect(writer.buffer_failing_since_ms != 0);

    // The sync flush rebuffers the gap, ending the run; the count stays.
    s.shard.syncFlushIfNeeded();
    try std.testing.expect(writer.first_unbuffered == null);
    try std.testing.expectEqual(@as(u64, 0), writer.buffer_failing_since_ms);
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);
}

test "Shard: with sync durability, an entry that left memory before reaching disk stops the shard's writes, by name" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k1", &buf)).getStatus());

    // The hook could not buffer k2, and the ring evicted it before the
    // flush: it is nowhere.
    const writer = s.shard.durable_log.?.writer;
    writer.first_unbuffered = s.shard.raft_node.log.lastIndex() + 1;
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    _ = s.shard.raft_node.log.ual.evictOlderThan(std.math.maxInt(u64));

    const lost = try s.put(3, "k3", &buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, lost.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, lost.data, "lost when the node restarts") != null);
    try std.testing.expect(s.shard.raft_node.writes_stopped);

    // The next write is refused before it reaches the log.
    const last = s.shard.raft_node.log.lastIndex();
    const refused = try s.put(4, "k4", &buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, refused.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, refused.data, "stopped taking writes") != null);
    try std.testing.expectEqual(last, s.shard.raft_node.log.lastIndex());
}

test "Shard: a namespace create is published, and answered, only once its segment and directory are on disk" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    {
        var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        try std.testing.expect(shard.applyCommitted());
        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        defer _ = std.c.close(pair[1]);
        const conn = try shard.addConnection(pair[0]);

        shard.runRequest(conn, try ParkTest.request(.namespace_create, 1, "", "orders", "", ""), .client);
        _ = shard.applyCommitted();
        const nh = shard.namespace_handler;
        // Applied, so shard 0 knows it; not on disk, so nothing else does,
        // and its client waits.
        try std.testing.expect(nh.namespaces.contains("orders"));
        try std.testing.expect(nh.table.lookup("orders") == null);
        try std.testing.expect(conn.response_deferred);

        const syncs = @import("stdx").fs.dir_syncs.load(.monotonic);
        nh.settle(&shard);
        // The flush synced the segment directory before the table moved.
        try std.testing.expect(@import("stdx").fs.dir_syncs.load(.monotonic) > syncs);
        const id = nh.table.lookup("orders").?;
        try std.testing.expectEqual(@import("../namespace/table.zig").FIRST_ALLOCATED, id);
        var buf: [256]u8 = undefined;
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    }
    // A restart publishes it from its segment, under the same id, with no
    // flush owed.
    var again = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer again.deinit();
    again.wireHandlerShardPtrs();
    _ = again.applyCommitted();
    again.namespace_handler.settle(&again);
    try std.testing.expectEqual(@as(?ns_table.Id, ns_table.FIRST_ALLOCATED), again.namespace_handler.table.lookup("orders"));
    try std.testing.expectEqual(ns_table.FIRST_ALLOCATED.int() + 1, again.namespace_handler.next_id);
}

test "Shard: a second create of a name being created waits for the first, and is never told it exists when it doesn't" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [512]u8 = undefined;
    var two: [2]proto.Response = undefined;

    // The first create's outcome never comes: this node stops leading.
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 1, "", "team", "", ""), .client);
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 2, "", "team", "", ""), .client);
    try std.testing.expect(conn.response_deferred);
    shard.namespace_handler.forgetImplicitCreates(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    for (two) |r| try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), r.header.status);

    // A node leads again only in a new term, ready once it has applied
    // what it proposed before: the late "team" create among them. So the
    // next create's id is past it.
    try ParkTest.ack(&shard);
    shard.namespace_handler.settle(&shard);
    // This time it applies: the first made it, the second finds it there.
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 3, "", "crew", "", ""), .client);
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 4, "", "crew", "", ""), .client);
    for (0..2) |_| {
        try ParkTest.ack(&shard);
        shard.namespace_handler.settle(&shard);
    }
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    var by_id: [2]proto.Response = undefined;
    for (two) |r| by_id[r.header.request_id - 3] = r;
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), by_id[0].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), by_id[1].header.status);
}

