test "Shard: an answer refused for a full write buffer is not taken for a missing answer" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    var sm = ShardMetrics{ .shard_id = 0 };
    shard.shard_metrics = &sm;
    defer shard.shard_metrics = null;
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);

    // A client unpaced after stalling, its unsent answers 8 bytes short of
    // the cap: the ping's answer doesn't fit and is refused.
    c.conn.pacing_off = true;
    const filler = try std.testing.allocator.alloc(u8, Connection.MAX_WRITE_BUFFER - 8);
    defer std.testing.allocator.free(filler);
    @memset(filler, 0);
    try std.testing.expectEqual(filler.len, c.conn.queueWrite(filler));

    const ping = try testRequest(.ping, 13, "", "");
    defer std.testing.allocator.free(ping);
    try std.testing.expectEqual(@as(isize, @intCast(ping.len)), std.c.write(c.pair[1], ping.ptr, ping.len));
    shard.readFromClient(c.conn.fd);
    try std.testing.expect(c.conn.write_overflow);
    try std.testing.expectEqual(@as(u64, 0), sm.snapshot().handler_no_answer);
}

test "Shard: a worker's await runs where the worker is registered, so a labelled run finds its labels" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| {
        s.wireHandlerShardPtrs();
        try std.testing.expect(s.applyCommitted());
    }
    const owner = &two.shards[0];
    const other = &two.shards[1];
    // The action on shard 0, the worker routed to shard 1.
    var name_buf: [16]u8 = undefined;
    const name = for (0..256) |i| {
        const n = try std.fmt.bufPrint(&name_buf, "act-{d}", .{i});
        if (owner.router.route(node_router.routeNsKey(.default, n)) == .local) break n;
    } else return error.NoLocalName;
    var worker_buf: [16]u8 = undefined;
    const worker = for (0..256) |i| {
        const w = try std.fmt.bufPrint(&worker_buf, "w-{d}", .{i});
        if (other.router.route(node_router.routeNsKey(.default, w)) == .local) break w;
    } else return error.NoLocalWorker;

    const ca = try TestClient.open(owner);
    defer _ = std.c.close(ca.pair[1]);
    const cb = try TestClient.open(other);
    defer _ = std.c.close(cb.pair[1]);
    var out: [4096]u8 = undefined;
    const labels = "{\"gpu\":true}";

    // The run requires the label; the worker has it.
    var invoke_value: [64]u8 = undefined;
    invoke_value[0] = 1;
    std.mem.writeInt(u16, invoke_value[1..3], labels.len, .little);
    @memcpy(invoke_value[3..][0..labels.len], labels);
    @memcpy(invoke_value[3 + labels.len ..][0..3], "job");
    for ([_]struct { op: proto.OpCode, id: u64, value: []const u8 }{
        .{ .op = .action_register, .id = 1, .value = "" },
        .{ .op = .action_invoke, .id = 2, .value = invoke_value[0 .. 6 + labels.len] },
    }) |r| {
        const frame = try testRequest(r.op, r.id, name, r.value);
        defer std.testing.allocator.free(frame);
        _ = feedClient(ca.pair[1], owner, ca.conn.fd, frame);
        _ = owner.applyCommitted();
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(ca, owner, &out)).header.status);
    }
    var reg: [128]u8 = undefined;
    var off: usize = 0;
    reg[off] = @backingInt(@import("../worker/handler.zig").WorkerType.action);
    std.mem.writeInt(u32, reg[off + 1 ..][0..4], 1, .little);
    std.mem.writeInt(u16, reg[off + 5 ..][0..2], 1, .little);
    off += 7;
    std.mem.writeInt(u16, reg[off..][0..2], @intCast(name.len), .little);
    @memcpy(reg[off + 2 ..][0..name.len], name);
    off += 2 + name.len;
    reg[off] = @backingInt(@import("../worker/handler.zig").ProcessKind.action);
    reg[off + 1] = 1;
    std.mem.writeInt(u16, reg[off + 2 ..][0..2], labels.len, .little);
    @memcpy(reg[off + 4 ..][0..labels.len], labels);
    off += 4 + labels.len;
    const register = try testRequest(.worker_register, 3, worker, reg[0..off]);
    defer std.testing.allocator.free(register);
    _ = feedClient(cb.pair[1], other, cb.conn.fd, register);
    _ = other.applyCommitted();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(cb, other, &out)).header.status);

    // The await arrives on shard 0 and runs on shard 1, where the worker's
    // labels are; it asks shard 0, which owns the action, for the run.
    var await_buf: [64]u8 = undefined;
    const aw = try testRequest(.action_await, 4, worker, try ActionsHandler.for_tests.awaitBody(&await_buf, &.{name}, 30_000, null));
    defer std.testing.allocator.free(aw);
    _ = feedClient(ca.pair[1], owner, ca.conn.fd, aw);
    two.settle();
    const resp = try nextAnswer(ca, owner, &out);
    try std.testing.expectEqual(@as(u64, 4), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(std.mem.endsWith(u8, resp.data, "job"));
    // Handing it a task doesn't count toward its load: that is what the
    // worker reports.
    try std.testing.expectEqual(@as(u32, 0), other.worker_handler.find(.default, worker).?.current_load);
}

test "Shard: an await parked before its worker was drained is refused as it drains, and a run that arrives later waits" {
    try expectParkedAwaitRefused(.drained);
}

test "Shard: an await parked before its worker went silent is refused when work arrives" {
    try expectParkedAwaitRefused(.silent);
}

/// A worker parks an await with nothing to take, then is drained or misses
/// its heartbeats. A drain answers the await at once; a silent worker's is
/// refused when a run arrives. Either way the run waits for another worker.
fn expectParkedAwaitRefused(how: enum { drained, silent }) !void {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| {
        s.wireHandlerShardPtrs();
        try std.testing.expect(s.applyCommitted());
    }
    const owner = &two.shards[0];
    const other = &two.shards[1];
    var name_buf: [16]u8 = undefined;
    const name = for (0..256) |i| {
        const n = try std.fmt.bufPrint(&name_buf, "act-{d}", .{i});
        if (owner.router.route(node_router.routeNsKey(.default, n)) == .local) break n;
    } else return error.NoLocalName;
    var worker_buf: [16]u8 = undefined;
    const worker = for (0..256) |i| {
        const w = try std.fmt.bufPrint(&worker_buf, "w-{d}", .{i});
        if (other.router.route(node_router.routeNsKey(.default, w)) == .local) break w;
    } else return error.NoLocalWorker;

    const ca = try TestClient.open(owner);
    defer _ = std.c.close(ca.pair[1]);
    const cb = try TestClient.open(other);
    defer _ = std.c.close(cb.pair[1]);
    var out: [4096]u8 = undefined;

    const register_action = try testRequest(.action_register, 1, name, "");
    defer std.testing.allocator.free(register_action);
    _ = feedClient(ca.pair[1], owner, ca.conn.fd, register_action);
    _ = owner.applyCommitted();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(ca, owner, &out)).header.status);
    const reg = [_]u8{ @backingInt(@import("../worker/handler.zig").WorkerType.action), 1, 0, 0, 0, 0, 0 };
    for ([_]struct { op: proto.OpCode, id: u64, value: []const u8 }{
        .{ .op = .worker_register, .id = 2, .value = &reg },
    }) |r| {
        const frame = try testRequest(r.op, r.id, worker, r.value);
        defer std.testing.allocator.free(frame);
        _ = feedClient(cb.pair[1], other, cb.conn.fd, frame);
        _ = other.applyCommitted();
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(cb, other, &out)).header.status);
    }

    // Parked with nothing to take (shard 0, which owns the action, said
    // so), then drained.
    var await_buf: [64]u8 = undefined;
    const aw = try testRequest(.action_await, 3, worker, try ActionsHandler.for_tests.awaitBody(&await_buf, &.{name}, 30_000, null));
    defer std.testing.allocator.free(aw);
    _ = feedClient(cb.pair[1], other, cb.conn.fd, aw);
    two.settle();
    other.flushToClient(cb.conn.fd);
    try std.testing.expectEqual(@as(c_int, 0), unreadBytes(cb.pair[1]));
    switch (how) {
        .drained => {
            const drain = try testRequest(.worker_drain, 4, worker, "");
            defer std.testing.allocator.free(drain);
            _ = feedClient(cb.pair[1], other, cb.conn.fd, drain);
            // The parked await first: the drain frees it, rather than its
            // block running out. Both answers come in one read.
            const got = try readAnswer(cb.pair[1], other, cb.conn.fd, &out, 2 * @sizeOf(proto.ResponseHeader));
            const refused = try proto.Response.parse(out[0..got]);
            try std.testing.expectEqual(@as(u64, 3), refused.header.request_id);
            try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), refused.header.status);
            try std.testing.expectEqual(proto.Reason.worker_draining, (try refused.refused()).reason);
            const drained = try proto.Response.parse(out[@sizeOf(proto.ResponseHeader) + refused.header.data_len .. got]);
            try std.testing.expectEqual(@as(u64, 4), drained.header.request_id);
            try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), drained.header.status);
        },
        .silent => {
            // The sweep's clock moves past the timeout; moving the worker's
            // last sight back instead would stop at 0 on a machine up for
            // less than the timeout.
            const seen = other.worker_handler.find(.default, worker).?.last_seen_ms;
            try std.testing.expectEqual(@as(usize, 1), other.worker_handler.checkHealth(seen + other.worker_handler.heartbeat_timeout_ms + 1));
        },
    }

    // A run arrives. A silent worker's await is refused now; a drained
    // worker's was answered already, and nothing more comes.
    const invoke = try testRequest(.action_invoke, 5, name, "\x00job");
    defer std.testing.allocator.free(invoke);
    _ = feedClient(ca.pair[1], owner, ca.conn.fd, invoke);
    _ = owner.applyCommitted();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(ca, owner, &out)).header.status);
    _ = other.drainInbox();
    switch (how) {
        .drained => {
            other.flushToClient(cb.conn.fd);
            try std.testing.expectEqual(@as(c_int, 0), unreadBytes(cb.pair[1]));
        },
        .silent => {
            const resp = try nextAnswer(cb, other, &out);
            try std.testing.expectEqual(@as(u64, 3), resp.header.request_id);
            try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), resp.header.status);
            try std.testing.expectEqual(proto.Reason.worker_unhealthy, (try resp.refused()).reason);
        },
    }
    try std.testing.expectEqual(action_machine.Status.ready, ActionsHandler.for_tests.anyRun(owner).?.status);
}

test "Shard: a failed attempt sent back to pending wakes an await parked on another shard" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| {
        s.wireHandlerShardPtrs();
        try std.testing.expect(s.applyCommitted());
    }
    const owner = &two.shards[0];
    const other = &two.shards[1];
    var name_buf: [16]u8 = undefined;
    const name = for (0..256) |i| {
        const n = try std.fmt.bufPrint(&name_buf, "act-{d}", .{i});
        if (owner.router.route(node_router.routeNsKey(.default, n)) == .local) break n;
    } else return error.NoLocalName;

    const ca = try TestClient.open(owner);
    defer _ = std.c.close(ca.pair[1]);
    var out: [4096]u8 = undefined;
    for ([_]struct { op: proto.OpCode, id: u64, value: []const u8 }{
        .{ .op = .action_register, .id = 1, .value = "" },
        .{ .op = .action_invoke, .id = 2, .value = "\x00job" },
    }) |r| {
        const frame = try testRequest(r.op, r.id, name, r.value);
        defer std.testing.allocator.free(frame);
        _ = feedClient(ca.pair[1], owner, ca.conn.fd, frame);
        _ = owner.applyCommitted();
        const resp = try nextAnswer(ca, owner, &out);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    }

    // Worker w0 takes the run; w1 then waits for work on the other shard.
    var await_buf: [64]u8 = undefined;
    const await_value = try ActionsHandler.for_tests.awaitBody(&await_buf, &.{name}, 0, null);
    const take = try testRequest(.action_await, 9, "w0", await_value);
    defer std.testing.allocator.free(take);
    _ = feedClient(ca.pair[1], owner, ca.conn.fd, take);
    two.settle();
    var task_out: [4096]u8 = undefined;
    const taken = try nextAnswer(ca, owner, &task_out);
    try std.testing.expectEqual(@as(u64, 9), taken.header.request_id);
    const task = (try ActionsHandler.for_tests.task(taken.data)) orelse return error.NoRun;
    const cb = try TestClient.open(other);
    defer _ = std.c.close(cb.pair[1]);
    var wait_buf: [64]u8 = undefined;
    const wait_value = try ActionsHandler.for_tests.awaitBody(&wait_buf, &.{name}, 30_000, null);
    // A worker registered on the other shard, where its await runs.
    var worker_buf: [16]u8 = undefined;
    const worker = for (0..256) |i| {
        const w = try std.fmt.bufPrint(&worker_buf, "w-{d}", .{i});
        if (other.router.route(node_router.routeNsKey(.default, w)) == .local) break w;
    } else return error.NoLocalWorker;
    const aw = try testRequest(.action_await, 3, worker, wait_value);
    defer std.testing.allocator.free(aw);
    _ = feedClient(cb.pair[1], other, cb.conn.fd, aw);
    two.settle();
    other.flushToClient(cb.conn.fd);
    try std.testing.expectEqual(@as(c_int, 0), unreadBytes(cb.pair[1]));

    // w0 fails its attempt asking for another: once that applies, the run
    // is ready again and w1 gets it now, not when its wait runs out.
    var fail_value: [512]u8 = undefined;
    const fail = try testRequest(.action_fail, 4, task.run, try ActionsHandler.for_tests.failBody(&fail_value, task, "w0", true, "boom"));
    defer std.testing.allocator.free(fail);
    _ = feedClient(ca.pair[1], owner, ca.conn.fd, fail);
    two.settle();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(ca, owner, &out)).header.status);

    two.settle();
    const resp = try nextAnswer(cb, other, &out);
    try std.testing.expectEqual(@as(u64, 3), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(std.mem.endsWith(u8, resp.data, "job"));
}

test "Shard: on a leader, an invoke and a retry wake workers; a settle, and anything on a follower, don't" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const shard = &two.shards[0];
    const role = shard.raft_node.role;
    defer shard.raft_node.role = role;
    const token: action_entries.Token.Value = .{ .term = 1, .index = 1 };
    const release: action_entries.Release.Value = .{ .ns = ns_table.DEFAULT.int(), .action = "a", .run = "r", .holder = "w", .request_key = null, .deliveries = 1, .token = token, .expiry_ns = 0, .abandoned = false, .retry = true, .delay_ms = 0, .@"error" = "" };
    const settle: action_entries.Settle.Value = .{ .ns = ns_table.DEFAULT.int(), .action = "a", .run = "r", .holder = "w", .request_key = null, .deliveries = 1, .token = token, .expiry_ns = 0, .outcome = "", .result = "" };
    var buf: [1024]u8 = undefined;
    for ([_]struct { leads: bool, e: entry_mod.Entry, wakes: bool }{
        .{ .leads = true, .e = try ActionsHandler.for_tests.entry(.action_invoke, testInvoke("a", "r"), 1, 1, 0, buf[0..512]), .wakes = true },
        .{ .leads = true, .e = try ActionsHandler.for_tests.entry(.action_release, release, 1, 2, 0, buf[512..]), .wakes = true },
        .{ .leads = false, .e = try ActionsHandler.for_tests.entry(.action_invoke, testInvoke("a", "r"), 1, 1, 0, buf[0..512]), .wakes = false },
    }) |c| {
        shard.raft_node.role = if (c.leads) .leader else .follower;
        shard.wake_workers = false;
        var out = persistence_mod.Result.start(&c.e);
        shard.actions_handler.afterApply(shard, &c.e, &out);
        try std.testing.expectEqual(c.wakes, shard.wake_workers);
    }
    shard.raft_node.role = .leader;
    shard.wake_workers = false;
    const e = try ActionsHandler.for_tests.entry(.action_settle, settle, 1, 3, 0, &buf);
    var out = persistence_mod.Result.start(&e);
    shard.actions_handler.afterApply(shard, &e, &out);
    try std.testing.expect(!shard.wake_workers);
}

/// A clustered shard leading alone (node 1), with a client connection.
const AdminTest = struct {
    pipe_fds: [2]std.posix.fd_t,
    rn: RaftNetwork,
    shard: Shard,
    pair: [2]std.posix.fd_t,
    conn: *Connection,

    fn init(self: *AdminTest, node_id: u32, role: ClusterRole) !void {
        return self.initWith(node_id, role, null, .async_flush);
    }

    /// `init`, keeping its log in `data_dir` under `durability`.
    fn initWith(self: *AdminTest, node_id: u32, role: ClusterRole, data_dir: ?[]const u8, durability: Durability) !void {
        self.pipe_fds = try @import("stdx").io.pipe();
        self.rn = try RaftNetwork.init(std.testing.allocator, node_id, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        // As the server sets it: under sync a leader counts its own copy only
        // once it is on disk.
        self.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, self.pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, durability, node_id, role, .{ .self_counts_when_durable = durability == .sync }, .{});
        self.shard.raft_network = &self.rn;
        self.shard.wireHandlerShardPtrs();
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &self.pair));
        self.conn = try self.shard.addConnection(self.pair[0]);
    }

    fn deinit(self: *AdminTest) void {
        self.shard.deinit();
        self.rn.deinit();
        _ = std.c.close(self.pair[1]);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
    }

    /// Send `op` with `value` from a client; return the one answer.
    fn ask(self: *AdminTest, op: proto.OpCode, value: []const u8, buf: []u8) !proto.Response {
        return self.askFrom(.client, op, value, buf);
    }

    /// Send `op` with `value` from `origin`; return the one answer.
    fn askFrom(self: *AdminTest, origin: run_mod.Origin, op: proto.OpCode, value: []const u8, buf: []u8) !proto.Response {
        self.shard.runRequest(self.conn, try ParkTest.request(op, 7, "", "", value, ""), origin);
        var into: [1]proto.Response = undefined;
        try ParkTest.responses(&self.shard, self.conn, self.pair[1], buf, &into);
        return into[0];
    }

    // Membership changes are admin-only: a client is refused, so they come
    // over the admin socket (`.admin`).
    fn promote(self: *AdminTest, id: u32, buf: []u8) !proto.Response {
        var v: [4]u8 = undefined;
        std.mem.writeInt(u32, &v, id, .little);
        return self.askFrom(.admin, .cluster_promote, &v, buf);
    }

    fn remove(self: *AdminTest, id: u32, yes: bool, buf: []u8) !proto.Response {
        var v: [5]u8 = undefined;
        std.mem.writeInt(u32, v[0..4], id, .little);
        v[4] = @intFromBool(yes);
        return self.askFrom(.admin, .cluster_remove, &v, buf);
    }

    /// A repair skip of `index` from `origin`.
    fn repairSkip(self: *AdminTest, origin: run_mod.Origin, index: u64, yes: bool, buf: []u8) !?proto.Response {
        var v: [cluster_wire.RepairSkip.MAX_SIZE]u8 = undefined;
        const body = try (cluster_wire.RepairSkip{ .index = index, .yes = yes, .reason = "test" }).encode(&v);
        self.shard.runRequest(self.conn, try ParkTest.request(.cluster_repair_skip, 7, "", "", body, ""), origin);
        if (self.conn.response_deferred) return null;
        var into: [1]proto.Response = undefined;
        try ParkTest.responses(&self.shard, self.conn, self.pair[1], buf, &into);
        return into[0];
    }

    fn caughtUp(self: *AdminTest, id: u32) void {
        const raft = self.shard.raft_node;
        const p = &raft.peers[raft.peerIndex(id).?];
        p.caught_up_streak = raft_node_mod.CAUGHT_UP_ACKS;
        p.last_contact_ms = raft.current_time_ms;
    }
};

fn expectAnswer(r: proto.Response, status: proto.StatusCode, text: []const u8) !void {
    try std.testing.expectEqual(status, r.getStatus());
    if (std.mem.indexOf(u8, r.data, text) == null) {
        std.debug.print("answer: {s}\n", .{r.data});
        return error.TestUnexpectedResult;
    }
}

test "Shard: promote and remove refuse by name; promoting a voter is done already" {
    var t: AdminTest = undefined;
    try t.init(1, .bootstrap);
    defer t.deinit();
    const raft = t.shard.raft_node;
    try std.testing.expect(t.shard.applyCommitted());
    var buf: [512]u8 = undefined;

    try expectAnswer(try t.remove(1, false, &buf), .bad_request, "node 1 is the only voter");
    try expectAnswer(try t.promote(9, &buf), .not_found, "node 9 is not a member");
    try expectAnswer(try t.remove(9, false, &buf), .not_found, "node 9 is not a member");
    t.shard.handleJoinRequest(2);
    try std.testing.expect(t.shard.applyCommitted());
    // Once caught up is not enough: it must be caught up now.
    try expectAnswer(try t.promote(2, &buf), .unavailable, "node 2 has not caught up yet");
    var m = raft.latest_config.find(2).?;
    m.caught_up = true;
    raft.latest_config = raft.latest_config.withMember(m);
    try expectAnswer(try t.promote(2, &buf), .unavailable, "node 2 has not caught up yet");

    // Caught up now: promoted, answered once it commits.
    t.caughtUp(2);
    t.shard.runRequest(t.conn, try ParkTest.request(.cluster_promote, 8, "", "", &[_]u8{ 2, 0, 0, 0 }, ""), .admin);
    try ParkTest.ack(&t.shard);
    var into: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &into);
    try std.testing.expectEqual(proto.StatusCode.ok, into[0].getStatus());
    try std.testing.expect(raft.latest_config.isVoter(2));
    // Again: nothing to do, and said so plainly.
    try std.testing.expectEqual(proto.StatusCode.ok, (try t.promote(2, &buf)).getStatus());

    // Three to two, and five to four, ask for --yes; each says what it leaves.
    const five = membership.Config.ofVoters(&.{ 1, 2, 3, 4, 5 });
    raft.setMembership(&five, raft.commit_index);
    try expectAnswer(try t.remove(5, false, &buf), .bad_request, "leaves 4 voters, which tolerate no more failures than 3 would; add --yes");
    const three = membership.Config.ofVoters(&.{ 1, 2, 3 });
    raft.setMembership(&three, raft.commit_index);
    try expectAnswer(try t.remove(3, false, &buf), .bad_request, "leaves 2 voters, which tolerate no failure; add --yes");
}

test "Shard: cluster status answers the vouched index while the node is behind it, and the stuck-member sign" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    var buf: [512]u8 = undefined;
    var resp = try t.ask(.cluster_status, "", &buf);
    try std.testing.expectEqual(proto.StatusCode.ok, resp.getStatus());
    try std.testing.expectEqual(@as(usize, 30), resp.data.len);
    try std.testing.expectEqual(@as(u64, 0), std.mem.readInt(u64, resp.data[21..29], .little));
    try std.testing.expectEqual(@as(u8, 0), resp.data[29]);

    // A vouch for a config committed past this node's log, and a stranger
    // dropped just now with no leader heard.
    const raft = t.shard.raft_node;
    t.shard.replica.vouch.index = raft.commit_index + 50;
    t.shard.replica.strangers_quiet_ms = Shard.nowMs();
    resp = try t.ask(.cluster_status, "", &buf);
    try std.testing.expectEqual(raft.commit_index + 50, std.mem.readInt(u64, resp.data[21..29], .little));
    try std.testing.expectEqual(@as(u8, 1), resp.data[29]);

    // Once its own log reaches the vouched index, it answers none.
    raft.commit_index += 50;
    resp = try t.ask(.cluster_status, "", &buf);
    try std.testing.expectEqual(@as(u64, 0), std.mem.readInt(u64, resp.data[21..29], .little));
}

test "Shard: a removed node answers clients with when, takes no frames, ticks nothing and dials no one" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2, 3 });
    raft.setMembership(&cfg, 1);
    raft.lost_log = .none;

    t.shard.enterRemoved(1_791_563_614_450);
    var buf: [512]u8 = undefined;
    try expectAnswer(try t.ask(.kv_get, "", &buf), .unavailable, "this node was removed from the cluster at 2026-10-09 ");
    // Its status still answers, as removed.
    try std.testing.expectEqual(proto.StatusCode.ok, (try t.ask(.cluster_status, "", &buf)).getStatus());
    try std.testing.expect(t.rn.dialing_stopped.load(.acquire));

    const term0 = raft.current_term;
    var abuf: [transport.APPEND_REQ_PREFIX + 64]u8 = undefined;
    const n = transport.serializeAppendRequest(.{ .term = term0 + 5, .leader_id = 1, .prev_log_index = 0, .prev_log_term = 0, .leader_commit = 0, .entries = &.{} }, &abuf).?;
    t.shard.replica.handleRaftFrame(.{ .source_node = 1, .group_id = 0, .msg_type = .append_entries, .payload = abuf[0..n] });
    try std.testing.expectEqual(term0, raft.current_term);
    t.shard.replica.tickRaft();
