    const h = (try r.propose(.cg_create, entry_mod.Flags.NONE, "")).index;
    var set_buf: [64]u8 = undefined;
    t.send(.kv_put, 1, "k", try table_run.op("kv.set").request.encodeInto(&set_buf, .{ .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null, .txn = null }));
    const last = r.log.lastIndex();
    r.peers[0].sent_up_to = last;
    r.handleAppendResponse(.{ .term = r.current_term, .success = true, .match_index = last, .from = 2 });
    try std.testing.expect(!t.shard.applyCommitted());
    try std.testing.expectEqual(h, t.shard.halted.?.index);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.outcome_pending), one[0].header.status);
    const m = (try one[0].refused()).message;
    try std.testing.expect(std.mem.indexOf(u8, m, "will apply when the shard resumes") != null);
    try std.testing.expect(std.mem.indexOf(u8, m, "halted at your write") == null);
}

test "a write parked past the halt whose entry a later leader replaces is told the leader changed, never that it is pending" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const r = t.shard.raft_node;
    // H halts; the write after it is still uncommitted when it does.
    const h = (try r.propose(.cg_create, entry_mod.Flags.NONE, "")).index;
    const set = table_run.op("kv.set");
    var set_buf: [64]u8 = undefined;
    t.send(.kv_put, 1, "k", try set.request.encodeInto(&set_buf, .{ .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null, .txn = null }));
    try std.testing.expectEqual(@as(u32, 1), t.shard.pending_count);
    const term = r.current_term;
    r.peers[0].sent_up_to = h;
    r.handleAppendResponse(.{ .term = term, .success = true, .match_index = h, .from = 2 });
    try std.testing.expect(!t.shard.applyCommitted());
    try std.testing.expectEqual(h, t.shard.halted.?.index);
    // Not committed: still waiting.
    try std.testing.expectEqual(@as(u32, 1), t.shard.pending_count);
    // Node 2 leads term + 1, replaces the write's entry with its no-op and
    // commits it.
    var noop = entry_mod.buildEntry(.raft_noop, entry_mod.Flags.NONE, term + 1, h + 1, r.log.last_stamp + 1, "");
    noop.header.crc32c = noop.computeCrc();
    _ = try r.handleAppendEntries(.{ .term = term + 1, .leader_id = 2, .prev_log_index = h, .prev_log_term = term, .entries = (&noop)[0..1], .leader_commit = h + 1 });
    try std.testing.expect(!t.shard.applyCommitted());
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expect(std.mem.indexOf(u8, (try one[0].refused()).message, "leader changed") != null);
    try std.testing.expectEqual(@as(u32, 0), t.shard.pending_count);
}

fn raceTestRun(t: *RaceTest, id: []const u8) *WorkflowHandler.RunRecord {
    var it = t.shard.workflow_handler.runs.valueIterator();
    while (it.next()) |r| if (std.mem.eql(u8, r.run_id_owned, id)) return r;
    @panic("no run with that id");
}

fn raceTestWaitingRun(t: *RaceTest, buf: []u8, one: []proto.Response) ![]const u8 {
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    t.send(.workflow_create, 40, "flow", def);
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], buf, one);
    t.send(.workflow_start, 41, "flow", "");
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], buf, one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    // Its first step logged, then taken.
    t.shard.workflow_handler.advanceStartedRuns(&t.shard);
    try ParkTest.ack(&t.shard);
    t.shard.workflow_handler.advanceStartedRuns(&t.shard);
    return one[0].data;
}

test "a workflow cancel is answered when its entry applies, and the run ends then, not before" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    var id_buf: [32]u8 = undefined;
    const data = try raceTestWaitingRun(&t, &buf, &one);
    const id = id_buf[0..data.len];
    @memcpy(id, data);
    const run = raceTestRun(&t, id);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);

    t.send(.workflow_cancel, 42, id, "");
    try std.testing.expectEqual(@as(u32, 1), t.shard.pending_count);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);
    try std.testing.expect(WorkflowHandler.endingInFlight(&t.shard, run));

    // A signal meanwhile is refused as retryable, and doesn't move it.
    var sig: [4]u8 = undefined;
    std.mem.writeInt(u16, sig[0..2], 2, .little);
    @memcpy(sig[2..4], "go");
    t.send(.workflow_signal, 43, id, &sig);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);

    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expectEqual(@as(u64, 42), one[0].header.request_id);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.cancelled, run.status);
}

test "a workflow cancel on a leader elected again still holds the run, applies, and counts once" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var registry = MetricsRegistry.init(std.testing.allocator);
    defer registry.deinit();
    try registry.initShards(1);
    t.shard.setMetricsRegistry(&registry);
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    var id_buf: [32]u8 = undefined;
    const data = try raceTestWaitingRun(&t, &buf, &one);
    const id = id_buf[0..data.len];
    @memcpy(id, data);
    const run = raceTestRun(&t, id);
    const r = t.shard.raft_node;

    // Two cancels in the window: one run cancelled.
    t.send(.workflow_cancel, 42, id, "");
    t.send(.workflow_cancel, 43, id, "");
    // Elected again, as `becomeLeader` leaves it: its entries kept.
    r.current_term += 1;
    r.ready_index = r.log.lastIndex();
    var sig: [4]u8 = undefined;
    std.mem.writeInt(u16, sig[0..2], 2, .little);
    @memcpy(sig[2..4], "go");
    t.send(.workflow_signal, 44, id, &sig);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);

    // An entry of its own term, so the earlier ones commit with it.
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    try ParkTest.ack(&t.shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &two);
    for (two) |a| try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), a.header.status);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.cancelled, run.status);
    try std.testing.expectEqual(@as(u64, 1), registry.workflow.cancelled_total.load(.monotonic));
}

test "a workflow cancel whose entry a later leader replaces is told the leader changed, and the run isn't cancelled" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    var id_buf: [32]u8 = undefined;
    const data = try raceTestWaitingRun(&t, &buf, &one);
    const id = id_buf[0..data.len];
    @memcpy(id, data);
    const run = raceTestRun(&t, id);
    const r = t.shard.raft_node;
    const before = r.log.lastIndex();
    const term = r.current_term;
    const prev_term = term;

    t.send(.workflow_cancel, 42, id, "");
    try std.testing.expectEqual(@as(u32, 1), t.shard.pending_count);

    // Node 2 leads term + 1, replaces the cancel's entry with its no-op and
    // commits it.
    var noop = entry_mod.buildEntry(.raft_noop, entry_mod.Flags.NONE, term + 1, before + 1, r.log.last_stamp + 1, "");
    noop.header.crc32c = noop.computeCrc();
    _ = try r.handleAppendEntries(.{ .term = term + 1, .leader_id = 2, .prev_log_index = before, .prev_log_term = prev_term, .entries = (&noop)[0..1], .leader_commit = before + 1 });
    _ = t.shard.applyCommitted();
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expect(std.mem.indexOf(u8, (try one[0].refused()).message, "leader changed") != null);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);
    try std.testing.expect(!WorkflowHandler.endingInFlight(&t.shard, run));
}

/// A waiting run signalled to its completion: the completion is logged,
/// not yet committed. Returns the run.
fn raceTestEndingRun(t: *RaceTest, buf: []u8, one: []proto.Response, id_buf: *[32]u8) ![]const u8 {
    const data = try raceTestWaitingRun(t, buf, one);
    const id = id_buf[0..data.len];
    @memcpy(id, data);
    var sig: [4]u8 = undefined;
    std.mem.writeInt(u16, sig[0..2], 2, .little);
    @memcpy(sig[2..4], "go");
    t.send(.workflow_signal, 50, id, &sig);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], buf, one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    return id;
}

test "a workflow completion a later leader's log drops leaves the run unfinished, and the node ends it once it leads again" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var registry = MetricsRegistry.init(std.testing.allocator);
    defer registry.deinit();
    try registry.initShards(1);
    t.shard.setMetricsRegistry(&registry);
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    var id_buf: [32]u8 = undefined;
    const r = t.shard.raft_node;
    const id = try raceTestEndingRun(&t, &buf, &one, &id_buf);
    const run = raceTestRun(&t, id);
    const before = r.log.lastIndex() - 1;
    const term = r.current_term;

    // Logged, not committed: the run hasn't ended, here or to a reader.
    try std.testing.expect(!run.status.isTerminal());
    try std.testing.expect(WorkflowHandler.endingInFlight(&t.shard, run));
    try std.testing.expectEqual(@as(u64, 0), registry.workflow.completed_total.load(.monotonic));

    // Node 2 leads term + 1, replaces the completion with its no-op and
    // commits it.
    var noop = entry_mod.buildEntry(.raft_noop, entry_mod.Flags.NONE, term + 1, before + 1, r.log.last_stamp + 1, "");
    noop.header.crc32c = noop.computeCrc();
    _ = try r.handleAppendEntries(.{ .term = term + 1, .leader_id = 2, .prev_log_index = before, .prev_log_term = term, .entries = (&noop)[0..1], .leader_commit = before + 1 });
    _ = t.shard.applyCommitted();
    try std.testing.expect(!run.status.isTerminal());
    try std.testing.expect(!WorkflowHandler.endingInFlight(&t.shard, run));
    try std.testing.expectEqual(@as(u64, 0), registry.workflow.completed_total.load(.monotonic));

    // Elected again, it proposes the completion again; once that commits
    // the run has ended, counted once.
    r.current_term = term + 2;
    r.role = .leader;
    r.ready_index = r.log.lastIndex();
    t.shard.workflow_handler.checkPendingActions(&t.shard);
    try std.testing.expect(WorkflowHandler.endingInFlight(&t.shard, run));
    try ParkTest.ack(&t.shard);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.completed, run.status);
    try std.testing.expectEqual(@as(u64, 1), registry.workflow.completed_total.load(.monotonic));
    try std.testing.expectEqual(@as(usize, 0), t.shard.workflow_handler.completion_retries.items.len);
}

test "a cancel or signal while a workflow's completion is in flight is told to retry, and after it commits, that the run finished" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    var id_buf: [32]u8 = undefined;
    const id = try raceTestEndingRun(&t, &buf, &one, &id_buf);
    const run = raceTestRun(&t, id);

    t.send(.workflow_cancel, 51, id, "");
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expectEqualStrings("run is ending — retry", (try one[0].refused()).message);
    var sig: [4]u8 = undefined;
    std.mem.writeInt(u16, sig[0..2], 2, .little);
    @memcpy(sig[2..4], "go");
    t.send(.workflow_signal, 52, id, &sig);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expectEqual(@as(u32, 0), t.shard.pending_count);

    try ParkTest.ack(&t.shard);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.completed, run.status);
    t.send(.workflow_cancel, 53, id, "");
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), one[0].header.status);
    try std.testing.expectEqualStrings("run already finished", (try one[0].refused()).message);
}

test "a halted shard's duties stop, and one with work counts as held until the shard serves again" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    // A workflow whose schedule is due on every tick.
    const def =
        \\{"kind":"Workflow","name":"tick","version":"1.0.0","schedule":{"interval":1,"max_concurrent":1000},
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 1, "tick", def);
    try std.testing.expectEqual(@as(u32, 1), shard.workflow_handler.schedules.count());

    shard.halted = .{ .index = 1, .term = 1, .crc = 0 };
    const before = shard.raft_node.log.lastIndex();
    @import("stdx").time.sleep(2 * std.time.ns_per_ms);
    shard.runProducers();
    try std.testing.expectEqual(before, shard.raft_node.log.lastIndex());
    try std.testing.expectEqual(@as(u32, 1), shard.duties.held());

    shard.halted = null;
    @import("stdx").time.sleep(2 * std.time.ns_per_ms);
    shard.runProducers();
    try std.testing.expect(shard.raft_node.log.lastIndex() > before);
    try std.testing.expectEqual(@as(u32, 0), shard.duties.held());

    // A run started and not yet stepped, held while halted.
    _ = shard.applyCommitted();
    try std.testing.expect(shard.workflow_handler.to_step.count() > 0);
    shard.halted = .{ .index = 1, .term = 1, .crc = 0 };
    const queued = shard.workflow_handler.to_step.count();
    const logged = shard.raft_node.log.lastIndex();
    shard.runStepping();
    try std.testing.expectEqual(queued, shard.workflow_handler.to_step.count());
    try std.testing.expectEqual(logged, shard.raft_node.log.lastIndex());
    try std.testing.expectEqual(@as(u32, 1), shard.duties.held());
    shard.halted = null;
    shard.runStepping();
    try std.testing.expectEqual(@as(u32, 0), shard.workflow_handler.to_step.count());
    try std.testing.expectEqual(@as(usize, 0), shard.workflow_handler.started_to_advance.items.len);
    try std.testing.expectEqual(@as(u32, 0), shard.duties.held());

    // A stream past its retention: no trim while halted.
    const h = stream_mod.streamKey(.default, "kept");
    var k_buf: [stream_mod.MAX_NAME_KEY]u8 = undefined;
    try shard.stream_handler.stream.registerStreamMetadata(stream_mod.nameKey(&k_buf, .default, "kept").?, .{ .retention_count = 1 });
    for (1..4) |i| _ = try shard.stream_handler.stream.appendToStreamAt(h, i, 0, 1, 1, 1);
    shard.halted = .{ .index = 1, .term = 1, .crc = 0 };
    try std.testing.expectEqual(@as(u64, 0), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expectEqual(@as(u32, 1), shard.duties.held());
    shard.halted = null;
    try std.testing.expect(Shard.streamRetentionTask(@ptrCast(&shard)) > 0);
    try std.testing.expectEqual(@as(u32, 0), shard.duties.held());
}

test "a halted shard's leader, ready or not, holds its duties and doesn't spin the loop for them" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    const scheduled =
        \\{"kind":"Workflow","name":"tick","version":"1.0.0","schedule":{"interval":1,"max_concurrent":1000},
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 1, "tick", scheduled);
    const triggered =
        \\{"kind":"Workflow","name":"on-events","version":"1.0.0","trigger":{"stream":"events"},
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 2, "on-events", triggered);
    try std.testing.expectEqual(@as(u32, 1), shard.workflow_handler.stream_triggers.count());
    // A run waiting on its first step: stepping has work.
    try ParkTest.send(&shard, conn, .workflow_start, 3, "tick", "");
    try std.testing.expect(shard.workflow_handler.hasDutyWork());

    shard.halted = .{ .index = 1, .term = 1, .crc = 0 };
    for ([_]bool{ true, false }) |ready| {
        // Elected again while halted, a leader's applied index stops short
        // of what it must apply first: never ready.
        const r = shard.raft_node;
        const ready_index = r.ready_index;
        if (!ready) r.ready_index = r.last_applied + 100;
        defer r.ready_index = ready_index;
        try std.testing.expectEqual(ready, r.leaderReady());
        shard.duties.clear();
        shard.more_work = true;
        const before = r.log.lastIndex();
        _ = try shard.tick(0);
        _ = try shard.tick(0);
        try std.testing.expect(!shard.more_work);
        try std.testing.expectEqual(before, r.log.lastIndex());
        // Schedules, stream triggers and stepping.
        try std.testing.expectEqual(@as(u32, 3), shard.duties.held());
    }
    shard.halted = null;
}

test "a shard reads whether another on its node is halted from that one's published state" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 3, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    var slots: [3]health_mod.ShardSlot = @splat(.{});
    shard.node_health = &slots;
    try std.testing.expect(!shard.peerHalted());
    slots[0].set(.halted); // its own slot: its own state says
    try std.testing.expect(!shard.peerHalted());
    try std.testing.expect(!shard.shardHalted(0));
    slots[2].set(.halted);
    try std.testing.expect(shard.peerHalted());
    try std.testing.expect(shard.shardHalted(2));
    try std.testing.expect(!shard.shardHalted(1));
}

test "an entry stamped no later than the one before it halts its shard" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'A'});
    try std.testing.expect(shard.applyCommitted());
    const r = shard.raft_node;
    // An entry no leader would stamp: the same stamp as the one before.
    const idx = r.log.lastIndex() + 1;
    var e = entry_mod.buildEntry(.raft_noop, entry_mod.Flags.NONE, r.current_term, idx, r.applied_stamp, "");
    e.header.crc32c = e.computeCrc();
    _ = try r.log.append(&e);
    r.commit_index = idx;
    try std.testing.expect(!shard.applyCommitted());
    const h = shard.halted orelse return error.NotHalted;
    try std.testing.expectEqual(idx, h.index);
    try std.testing.expect(std.mem.indexOf(u8, h.reason(), "stamp") != null);
    try std.testing.expectEqual(idx - 1, r.last_applied);
}

test "Shard: a halted shard counts its own refused writes and says so once per 30 seconds" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    try std.testing.expect(!shard.quietHalted(error.NotLeader));
    // The first is said at once; the next two wait for the line after.
    try std.testing.expect(shard.quietHalted(error.Halted));
    try std.testing.expectEqual(@as(u64, 0), shard.halted_refusals);
    try std.testing.expect(shard.quietHalted(error.Halted));
    try std.testing.expect(shard.quietHalted(error.Halted));
    try std.testing.expectEqual(@as(u64, 2), shard.halted_refusals);
    shard.halted_line_ms = 0;
    try std.testing.expect(shard.quietHalted(error.Halted));
    try std.testing.expectEqual(@as(u64, 0), shard.halted_refusals);
}

