/// Drop the frames a test's network queued.
fn clearOutbound(rn: *RaftNetwork) void {
    for (rn.outbound.items) |o| std.testing.allocator.free(o.frame);
    rn.outbound.clearRetainingCapacity();
}

/// The one append frame the leader queued, decoded.
fn onlyAppend(rn: *RaftNetwork) !transport.AppendRequestHeader {
    try std.testing.expectEqual(@as(usize, 1), rn.outbound.items.len);
    return transport.deserializeAppendRequestHeader(rn.outbound.items[0].frame[transport.HEADER_SIZE..]) orelse error.BadFrame;
}

test "Shard: a follower whose uncommitted tail shares a term run with its commit is resent from its commit, not from index 1" {
    for ([_]bool{ true, false }) |durable| {
        const pipe_fds = try @import("stdx").io.pipe();
        defer _ = std.c.close(pipe_fds[0]);
        defer _ = std.c.close(pipe_fds[1]);
        var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        defer rn.deinit();
        var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
        defer shard.deinit();
        shard.raft_network = &rn;
        shard.wireHandlerShardPtrs();
        defer clearOutbound(&rn);
        try ParkTest.joinPeer(&shard);
        const raft = shard.raft_node;

        // Committed in the first term; then a later term's two entries.
        for (0..3) |_| _ = try kv_handler_mod.KVHandler.testProposePut(&shard, "k", "v");
        try ParkTest.ack(&shard);
        const committed = raft.commit_index;
        const first_term = raft.current_term;
        raft.current_term += 1;
        for (0..2) |_| _ = try kv_handler_mod.KVHandler.testProposePut(&shard, "k", "w");
        const last = raft.log.lastIndex();

        // The follower holds the committed prefix, then a longer tail in
        // the first term: one run from index 1 to its end.
        var follower = try raft_node_mod.RaftNode.init(std.testing.allocator, 2, 1, 16384, .{ .durable_commits = durable });
        defer follower.deinit();
        var copies: [32]entry_mod.Entry = undefined;
        var arena: [8192]u8 = undefined;
        const got = raft.log.getRange(1, &copies, &arena);
        try std.testing.expectEqual(committed, got - 2);
        for (copies[0..committed]) |*e| {
            try std.testing.expectEqual(first_term, e.header.term);
            _ = try follower.log.append(e);
        }
        for (committed + 1..committed + 5) |i| {
            var e = entry_mod.buildEntry(.kv_put, entry_mod.Flags.NONE, first_term, i, 0, "x");
            e.header.crc32c = e.computeCrc();
            _ = try follower.log.append(&e);
        }
        follower.commit_index = committed;
        follower.current_term = raft.current_term;

        // The leader probes the follower at its own end; the follower refuses.
        raft.peers[0].next_index = last + 1;
        raft.peers[0].inflight = false;
        raft.peers[0].heartbeat_at_ms = 0;
        clearOutbound(&rn);
        shard.replica.pump(Shard.nowMs());
        const probe = try onlyAppend(&rn);
        try std.testing.expectEqual(last, probe.prev_log_index);
        const refusal = try follower.handleAppendEntries(.{ .term = probe.term, .leader_id = probe.leader_id, .prev_log_index = probe.prev_log_index, .prev_log_term = probe.prev_log_term, .entries = &.{}, .leader_commit = probe.leader_commit });
        try std.testing.expect(!refusal.success);
        raft.handleAppendResponse(refusal);

        // What the pump sends next starts at the follower's commit.
        clearOutbound(&rn);
        shard.replica.pump(Shard.nowMs());
        const resend = try onlyAppend(&rn);
        try std.testing.expectEqual(committed, resend.prev_log_index);
        try std.testing.expect(resend.entry_count > 0);
    }
}

test "Shard: a peer below everything the leader knows the term of gets heartbeats with no term, and its refusals leave it where it is" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    defer clearOutbound(&rn);
    try ParkTest.joinPeer(&shard);
    const raft = shard.raft_node;
    const p = &raft.peers[0];

    // No term is known for the index before this peer's next.
    const stranded = raft.log.lastIndex() + 2;
    p.next_index = stranded;
    p.inflight = false;
    p.heartbeat_at_ms = 0;
    clearOutbound(&rn);
    const now = Shard.nowMs();
    shard.replica.pump(now);
    const beat = try onlyAppend(&rn);
    try std.testing.expectEqual(stranded - 1, beat.prev_log_index);
    try std.testing.expectEqual(@as(u64, 0), beat.prev_log_term);
    try std.testing.expectEqual(@as(u32, 0), beat.entry_count);
    try std.testing.expect(p.below_log);
    const warned = shard.replica.peer_batch_warn_ms[0];
    try std.testing.expect(warned != 0);

    // Before the next heartbeat is due, nothing goes, though it is behind.
    clearOutbound(&rn);
    shard.replica.pump(now + 1);
    try std.testing.expectEqual(@as(usize, 0), rn.outbound.items.len);

    // Its refusal of the heartbeat moves nothing; the next one goes on time
    // and the error is not repeated within its interval.
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = false, .match_index = 0, .from = raft.peer_ids[0], .hint_index = 1 });
    try std.testing.expectEqual(stranded, p.next_index);
    shard.replica.pump(now + raft.config.heartbeat_interval_ms + 1);
    try std.testing.expectEqual(@as(usize, 1), rn.outbound.items.len);
    try std.testing.expectEqual(warned, shard.replica.peer_batch_warn_ms[0]);

    // Stranded inside the log, as below a snapshot: behind, yet it still
    // hears only a heartbeat per interval, not a frame per pump.
    const floor = raft.log.lastIndex() + 5;
    raft.log.resetToSnapshot(floor, raft.current_term);
    var above = entry_mod.buildEntry(.kv_put, entry_mod.Flags.NONE, raft.current_term, floor + 1, 0, "v");
    above.header.crc32c = above.computeCrc();
    _ = try raft.log.append(&above);
    p.next_index = 3;
    p.inflight = false;
    p.heartbeat_at_ms = 0;
    clearOutbound(&rn);
    const later = now + 10 * raft.config.heartbeat_interval_ms;
    shard.replica.pump(later);
    try std.testing.expectEqual(@as(u32, 0), (try onlyAppend(&rn)).entry_count);
    clearOutbound(&rn);
    shard.replica.pump(later + 1);
    try std.testing.expectEqual(@as(usize, 0), rn.outbound.items.len);

    // At the floor itself, reset with no term: no follower can match a
    // term of 0, so it is below the log too.
    raft.log.resetToSnapshot(floor, 0);
    p.next_index = floor + 1;
    p.heartbeat_at_ms = 0;
    clearOutbound(&rn);
    shard.replica.pump(later + 2);
    try std.testing.expect(p.below_log);
    try std.testing.expectEqual(@as(u32, 0), (try onlyAppend(&rn)).entry_count);
    clearOutbound(&rn);
    raft.log.resetToSnapshot(floor, raft.current_term);
    _ = try raft.log.append(&above);

    // At index 1, below where the log now starts: index 0's term is known,
    // but nothing after it can be sent.
    p.next_index = 1;
    p.heartbeat_at_ms = 0;
    shard.replica.pump(later + 2);
    try std.testing.expect(p.below_log);
    try std.testing.expectEqual(@as(u32, 0), (try onlyAppend(&rn)).entry_count);
    clearOutbound(&rn);
    shard.replica.pump(later + 3);
    try std.testing.expectEqual(@as(usize, 0), rn.outbound.items.len);
}

/// A removal notice from `from`, naming removal time `when_ms` and its
/// sender's committed config index.
fn removalNotice(shard: *Shard, from: u32, when_ms: u64, config_index: u64) void {
    var buf: [Shard.REMOVAL_NOTICE_SIZE]u8 = undefined;
    std.mem.writeInt(u64, buf[0..8], when_ms, .little);
    std.mem.writeInt(u64, buf[8..16], config_index, .little);
    shard.replica.handleRaftFrame(.{ .source_node = from, .group_id = 0, .msg_type = .removed_notice, .payload = &buf });
}

test "Shard: removal notices need a quorum of the other voters, all naming one removal in a newer config, and a leader of this term voids them" {
    var t: AdminTest = undefined;
    try t.init(1, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    // Voters 1, 2 and 3, and replica 4, committed at index 5.
    const cfg = membership.Config.ofVoters(&.{ 1, 2, 3 }).withJoiner(4, false);
    raft.setMembership(&cfg, 5);
    raft.commitMembership(&cfg, 5);
    raft.lost_log = .none;
    var slot: health_mod.ShardSlot = .{};
    t.shard.health = &slot;
    defer t.shard.health = null;
    var sm = ShardMetrics{ .shard_id = 0 };
    t.shard.shard_metrics = &sm;
    defer t.shard.shard_metrics = null;

    // One of the two others: held, not acted on, and shown as one of two.
    removalNotice(&t.shard, 2, 1000, 9);
    try std.testing.expect(t.shard.removed_at_ms == null);
    var shown = slot.removal.read();
    try std.testing.expectEqual(@as(u8, 1), shown.notices);
    try std.testing.expectEqual(@as(u8, 2), shown.needed);
    try std.testing.expectEqual(@as(u32, 2), shown.from[0]);
    // The same sender again counts once.
    removalNotice(&t.shard, 2, 1000, 9);
    try std.testing.expectEqual(@as(u8, 1), t.shard.removal.count);
    // This node, a replica, and a config no newer than this node's say nothing.
    removalNotice(&t.shard, 1, 1000, 9);
    removalNotice(&t.shard, 4, 1000, 9);
    removalNotice(&t.shard, 3, 1000, 5);
    try std.testing.expectEqual(@as(u8, 1), t.shard.removal.count);
    try std.testing.expect(t.shard.removed_at_ms == null);
    // Another removal than 2's: held as 3's word, and the two don't agree.
    removalNotice(&t.shard, 3, 2000, 9);
    try std.testing.expectEqual(@as(u8, 2), t.shard.removal.count);
    try std.testing.expect(t.shard.removed_at_ms == null);

    // A leader of this term sends to this node as a member: the notices are void.
    var abuf: [transport.APPEND_REQ_PREFIX + 64]u8 = undefined;
    const n = transport.serializeAppendRequest(.{ .term = raft.current_term, .leader_id = 2, .prev_log_index = 0, .prev_log_term = 0, .leader_commit = 0, .entries = &.{} }, &abuf).?;
    t.shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .append_entries, .payload = abuf[0..n] });
    try std.testing.expectEqual(@as(u8, 0), t.shard.removal.count);
    try std.testing.expectEqual(@as(u8, 0), slot.removal.read().notices);

    // Both others, naming one removal: removed, and the quorum is shown.
    removalNotice(&t.shard, 2, 1000, 9);
    removalNotice(&t.shard, 3, 1000, 10);
    try std.testing.expectEqual(@as(?u64, 1000), t.shard.removed_at_ms);
    shown = slot.removal.read();
    try std.testing.expectEqual(@as(u8, 2), shown.notices);
    try std.testing.expectEqual(@as(u64, 1000), shown.at_ms);
    try std.testing.expectEqual(@as(u64, 10), shown.config_index);

    const counts = sm.snapshot().removal_notices;
    try std.testing.expectEqual(@as(u64, 3), counts[@backingInt(ShardMetrics.RemovalOutcome.counted)]);
    try std.testing.expectEqual(@as(u64, 1), counts[@backingInt(ShardMetrics.RemovalOutcome.duplicate)]);
    try std.testing.expectEqual(@as(u64, 3), counts[@backingInt(ShardMetrics.RemovalOutcome.ignored)]);
    try std.testing.expectEqual(@as(u64, 1), counts[@backingInt(ShardMetrics.RemovalOutcome.conflict)]);
}

test "Shard: one member naming a different removal each time cannot hold off the others' quorum" {
    var t: AdminTest = undefined;
    try t.init(1, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2, 3, 4, 5 });
    raft.setMembership(&cfg, 5);
    raft.commitMembership(&cfg, 5);
    raft.lost_log = .none;
    removalNotice(&t.shard, 2, 1000, 9);
    removalNotice(&t.shard, 5, 7, 9);
    removalNotice(&t.shard, 3, 1000, 9);
    removalNotice(&t.shard, 5, 8, 9);
    try std.testing.expect(t.shard.removed_at_ms == null);
    removalNotice(&t.shard, 4, 1000, 9);
    try std.testing.expectEqual(@as(?u64, 1000), t.shard.removed_at_ms);
}

test "Shard: a node with no committed config yet stops on one removal notice, and a notice of the wrong size is not one" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    try std.testing.expectEqual(@as(u8, 0), t.shard.raft_node.committed_config.member_count);
    var short: [8]u8 = @splat(0);
    t.shard.replica.handleRaftFrame(.{ .source_node = 1, .group_id = 0, .msg_type = .removed_notice, .payload = &short });
    try std.testing.expect(t.shard.removed_at_ms == null);
    removalNotice(&t.shard, 1, 1234, 7);
    try std.testing.expectEqual(@as(?u64, 1234), t.shard.removed_at_ms);
