test "Shard: in a group of five, a removal acts on three of the four others" {
    var t: AdminTest = undefined;
    try t.init(1, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2, 3, 4, 5 });
    raft.setMembership(&cfg, 5);
    raft.commitMembership(&cfg, 5);
    raft.lost_log = .none;
    removalNotice(&t.shard, 2, 1000, 9);
    removalNotice(&t.shard, 3, 1000, 9);
    try std.testing.expect(t.shard.removed_at_ms == null);
    removalNotice(&t.shard, 4, 1000, 9);
    try std.testing.expectEqual(@as(?u64, 1000), t.shard.removed_at_ms);
}

/// A one-shard node with one client, for what it answers as it stops.
const StopTest = struct {
    pipe: [2]std.posix.fd_t,
    shard: Shard,
    client: TestClient,

    fn init(self: *StopTest) !void {
        self.pipe = try @import("stdx").io.pipe();
        self.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, self.pipe[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        self.client = try TestClient.open(&self.shard);
    }

    fn deinit(self: *StopTest) void {
        self.shard.deinit();
        _ = std.c.close(self.client.pair[1]);
        _ = std.c.close(self.pipe[0]);
        _ = std.c.close(self.pipe[1]);
    }

    /// What the client sends, as it sends it, without the shard reading it.
    fn send(self: *StopTest, bytes: []const u8) !void {
        try std.testing.expectEqual(@as(isize, @intCast(bytes.len)), std.c.write(self.client.pair[1], bytes.ptr, bytes.len));
    }

    fn stop(self: *StopTest, out: []u8, answers: []proto.Response) !usize {
        self.shard.shutdown();
        try self.shard.run();
        return answersUntilEnd(self.client.pair[1], out, answers);
    }
};

fn expectNotRun(r: proto.Response, id: u64) !void {
    try std.testing.expectEqual(id, r.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), r.header.status);
    const told = try r.refused();
    try std.testing.expectEqual(proto.Ran.no, told.ran);
    try std.testing.expectEqualStrings(Shard.SHUTTING_DOWN_NOT_RUN, told.message);
}

test "Shard: requests a stopping shard never read are told they did not run, in the order sent, after what was already answered" {
    var t: StopTest = undefined;
    try t.init();
    defer t.deinit();
    // An answer already queued, and a request held unread in the read buffer.
    var ok_buf: [64]u8 = undefined;
    _ = t.client.conn.queueWrite(proto.Response.serializeOk(1, "", &ok_buf) catch unreachable);
    const held = try testRequest(.kv_put, 2, "k", "v");
    defer std.testing.allocator.free(held);
    _ = t.client.conn.read_buf.write(held);
    // Three more in the kernel's buffer, then the start of a fourth.
    for ([_]u64{ 3, 4, 5 }) |id| {
        const req = try testRequest(.kv_put, id, "k", "v");
        defer std.testing.allocator.free(req);
        try t.send(req);
    }
    const partial = try testRequest(.kv_put, 6, "k", "v");
    defer std.testing.allocator.free(partial);
    try t.send(partial[0 .. partial.len - 3]);

    var out: [4096]u8 = undefined;
    var answers: [8]proto.Response = undefined;
    const n = try t.stop(&out, &answers);
    try std.testing.expectEqual(@as(usize, 5), n);
    try std.testing.expectEqual(@as(u64, 1), answers[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), answers[0].header.status);
    for (answers[1..5], [_]u64{ 2, 3, 4, 5 }) |r, id| try expectNotRun(r, id);
}

test "Shard: a stopping shard answers no request past one that doesn't decode" {
    var t: StopTest = undefined;
    try t.init();
    defer t.deinit();
    const good = try testRequest(.kv_put, 7, "k", "v");
    defer std.testing.allocator.free(good);
    try t.send(good);
    // The same frame with one payload byte flipped: its checksum fails.
    const bad = try testRequest(.kv_put, 8, "k", "v");
    defer std.testing.allocator.free(bad);
    bad[bad.len - 1] ^= 0xff;
    try t.send(bad);
    const after = try testRequest(.kv_put, 9, "k", "v");
    defer std.testing.allocator.free(after);
    try t.send(after);

    var out: [2048]u8 = undefined;
    var answers: [4]proto.Response = undefined;
    const n = try t.stop(&out, &answers);
    try std.testing.expectEqual(@as(usize, 1), n);
    try expectNotRun(answers[0], 7);
}

test "Shard: a stopping shard reads no binary requests out of an HTTP connection" {
    var t: StopTest = undefined;
    try t.init();
    defer t.deinit();
    // Known to be HTTP from its first bytes, already consumed: what follows
    // is never framed as a binary request, even one that would decode.
    t.client.conn.protocol = .http;
    const req = try testRequest(.kv_put, 10, "k", "v");
    defer std.testing.allocator.free(req);
    try t.send(req);
    var out: [1024]u8 = undefined;
    var answers: [4]proto.Response = undefined;
    try std.testing.expectEqual(@as(usize, 0), try t.stop(&out, &answers));
}

test "Shard: a stopping shard stops answering unread requests before its write buffer would overflow" {
    var t: StopTest = undefined;
    try t.init();
    defer t.deinit();
    const conn = t.client.conn;
    const filler = try std.testing.allocator.alloc(u8, Connection.MAX_WRITE_BUFFER - 512);
    defer std.testing.allocator.free(filler);
    @memset(filler, 0);
    try std.testing.expectEqual(filler.len, conn.queueWrite(filler));
    const req = try testRequest(.kv_put, 11, "k", "v");
    defer std.testing.allocator.free(req);
    try t.send(req);
    t.shard.refuseUnread(conn.fd, conn);
    // Nothing queued, nothing overflowed, and the request is left as it was.
    try std.testing.expectEqual(filler.len, conn.write_buf.readable());
    try std.testing.expect(!conn.write_overflow);
    try std.testing.expectEqual(req.len, conn.read_buf.readable());
}

test "an entry repeating an index the partition holds is counted as a duplicate, not as silent loss" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    var sm = ShardMetrics{ .shard_id = 0 };
    shard.shard_metrics = &sm;
    defer shard.shard_metrics = null;

    var e = entry_mod.buildEntry(.raft_noop, entry_mod.Flags.NONE, 1, 1, 0, "");
    e.header.crc32c = e.computeCrc();
    var out = persistence_mod.Result.start(&e);
    const first = applyEntryCore(shard.defaultPartition(), &shard.replay_registry, &e, &out);
    try std.testing.expect(first == .applied);
    const again = applyEntryCore(shard.defaultPartition(), &shard.replay_registry, &e, &out);
    try std.testing.expect(again == .partition_reject);
    try std.testing.expect(verdictOf(&shard.losses, shard.id, Shard.nowMs(), &e, again) == .duplicate);

    try std.testing.expectEqual(@as(u64, 0), shard.losses.total(.partition_reject));
    try std.testing.expectEqual(@as(u64, 1), shard.losses.duplicate_index);
    shard.publishHealth();
    const snap = sm.snapshot();
    try std.testing.expectEqual(@as(u64, 1), snap.duplicate_index);
    for (snap.silent_loss) |n| try std.testing.expectEqual(@as(u64, 0), n);
}

test "Shard: action.status for a run on another shard goes there, by the run id's partition bits" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    // A run minted for a partition shard 1 owns, as an invoke there would.
    const partition: u32 = for (0..a.router.partition_count) |p| {
        if (a.router.partitionToShard(@intCast(p)) == 1) break @intCast(p);
    } else return error.TestUnexpectedResult;
    // One whose text, hashed as a key, lands on shard 0: the old routing
    // sent status there, where the run isn't.
    var gen: run_id_mod.Generator = .{ .shard = 1 };
    var id_buf: [run_id_mod.MAX_ID_LEN]u8 = undefined;
    const run_id = for (0..256) |_| {
        const id = gen.next(.action, partition, &id_buf);
        if (a.router.partitionToShard(a.router.hashToPartition(node_router.routeNsKey(.default, id))) == 0) break id;
    } else return error.TestUnexpectedResult;
    _ = try applyActionEntry(&two.shards[1], .action_register, testRegister("echo"), 1, 1);
    _ = try applyActionEntry(&two.shards[1], .action_invoke, testInvoke("echo", run_id), 2, 1000 * std.time.ns_per_ms);

    // Asked on shard 0, it's sent to shard 1 before anything runs; before,
    // the id was hashed as a key and could land on a shard without the run.
    const req: proto.Request = .{ .header = proto.RequestHeader.init(.action_status, 1), .namespace = "", .key = run_id, .value = "" };
    switch (a.resolveTarget(@backingInt(proto.OpCode.action_status), req)) {
        .local => return error.TestUnexpectedResult,
        .shard => |t| try std.testing.expectEqual(@as(u16, 1), t.shard_id),
    }
    // There, it answers the run.
    const c = try TestClient.open(&two.shards[1]);
    defer _ = std.c.close(c.pair[1]);
    two.shards[1].runRequest(c.conn, req, .client);
    var out: [4096]u8 = undefined;
    const resp = try nextAnswer(c, &two.shards[1], &out);
    try std.testing.expectEqual(@as(u8, @backingInt(proto.StatusCode.ok)), resp.header.status);
    var diag: schema.Diagnostic = .{};
    const s = try table_run.op("action.status").response.decodeAll(resp.data, &diag);
    try std.testing.expectEqual(@import("../protocol/action_ops.zig").RunStatus.pending, s.status);
}

/// For tests: "k" in "default", as state and a single-key entry keep it.
const TEST_KV_K = ns_table.DEFAULT.bytes() ++ "k";

/// For tests: `raw` in "default", as state and a single-key entry keep it.
fn testKvKey(buf: *[limits.MAX_KV_KEY]u8, raw: []const u8) []const u8 {
    return kv_state.Key.init(buf, .default, raw).stored;
}

const HandlerOutcome = handler_mod.NamespaceHandler.CreateOutcome;

test "Shard: a follower and the leader publish the same live key count for the same KV entries, down to 0" {
    var t: FollowerTest = undefined;
    try t.init();
    defer t.deinit();
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var leader = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer leader.deinit();
    leader.wireHandlerShardPtrs();
    try std.testing.expect(leader.applyCommitted());

    var follower_metrics = MetricsRegistry.init(std.testing.allocator);
    defer follower_metrics.deinit();
    var leader_metrics = MetricsRegistry.init(std.testing.allocator);
    defer leader_metrics.deinit();
    t.shard.setMetricsRegistry(&follower_metrics);
    leader.setMetricsRegistry(&leader_metrics);

    // Each shard knows "orders", as its log would make it known, by the
    // same id: the metrics name a namespace from the id its keys carry.
    try std.testing.expectEqual(HandlerOutcome.created, t.shard.namespace_handler.applyCreate("orders"));
    try std.testing.expectEqual(HandlerOutcome.created, leader.namespace_handler.applyCreate("orders"));
    const orders = t.shard.namespace_handler.idOf("orders").?;
    try std.testing.expectEqual(orders, leader.namespace_handler.idOf("orders").?);
    const txn = @import("../kv/txn.zig");
    const batch = try txn.encodeBatch(std.testing.allocator, orders, &.{
        .{ .kind = .put, .key = @constCast("c"), .value = @constCast("v"), .ttl_ms = 0 },
        .{ .kind = .delete, .key = @constCast("a"), .value = @constCast(""), .ttl_ms = 0 },
    });
    defer std.testing.allocator.free(batch);
    const Op = union(enum) { put: []const u8, delete: []const u8, batch };
    // Each run of entries, then the count published after it.
    const runs = [_]struct { ops: []const Op, keys: u64 }{
        // Put a, put b, delete a missing key, delete a, put a again.
        .{ .ops = &.{ .{ .put = "a" }, .{ .put = "b" }, .{ .delete = "missing" }, .{ .delete = "a" }, .{ .put = "a" } }, .keys = 2 },
        // A batch: put c, delete a.
        .{ .ops = &.{.batch}, .keys = 2 },
        // Every key gone: the published count goes to 0, not left where it was.
        .{ .ops = &.{ .{ .delete = "b" }, .{ .delete = "c" } }, .keys = 0 },
    };
    var indices = [2]u64{ t.shard.raft_node.last_applied, leader.raft_node.last_applied };
    for (runs) |run| {
        for ([_]*Shard{ &t.shard, &leader }, &indices) |shard, *index| {
            for (run.ops) |op| {
                index.* += 1;
                var buf: [64]u8 = undefined;
                var kb: [limits.MAX_KV_KEY]u8 = undefined;
                const term = shard.raft_node.current_term;
                const e = switch (op) {
                    .put => |key| entry_mod.buildEntry(.kv_put, 0, term, index.*, 1, try kv_entries.Put.encodeInto(&buf, .{ .key = kv_state.Key.init(&kb, orders, key).stored, .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null })),
                    .delete => |key| entry_mod.buildEntry(.kv_delete, 0, term, index.*, 1, try kv_entries.Delete.encodeInto(&buf, .{ .key = kv_state.Key.init(&kb, orders, key).stored, .cas_version = null })),
                    .batch => entry_mod.buildEntry(.kv_batch, 0, term, index.*, 1, batch),
                };
                var out = persistence_mod.Result.start(&e);
                try std.testing.expect(shard.applyEntry(&e, &out));
            }
            shard.publishHealth();
        }
        try std.testing.expectEqual(run.keys, follower_metrics.kvLiveKeys("orders"));
        try std.testing.expectEqual(run.keys, leader_metrics.kvLiveKeys("orders"));
    }
}

test "Shard: a diverged member applies nothing more, and its reads say they are stale" {
    var t: AdminTest = undefined;
    try t.init(1, .bootstrap);
    defer t.deinit();
    const raft = t.shard.raft_node;
    try std.testing.expect(t.shard.applyCommitted());
    try ParkTest.joinPeer(&t.shard);
    var pbuf: [64]u8 = undefined;
    _ = try raft.propose(.kv_put, entry_mod.Flags.NONE, try kv_entries.Put.encodeInto(&pbuf, .{ .key = TEST_KV_K, .value = "v1", .ttl_ms = null, .condition = .always, .cas_version = null }));
    try ParkTest.ack(&t.shard);
    const frozen = raft.last_applied;
    var buf: [512]u8 = undefined;
    try std.testing.expectEqual(@as(u8, 0), (try t.ask(.cluster_status, "", &buf)).header.flags & proto.RESPONSE_STALE);

    // Diverged, then entries keep committing: none applies.
    _ = try raft.propose(.kv_put, entry_mod.Flags.NONE, try kv_entries.Put.encodeInto(&pbuf, .{ .key = TEST_KV_K, .value = "v2", .ttl_ms = null, .condition = .always, .cas_version = null }));
    t.shard.replica.markDiverged(2, raft.current_term);
    const last = raft.log.lastIndex();
    raft.commit_index = last;
    try std.testing.expect(t.shard.applyCommitted());
    try std.testing.expectEqual(frozen, raft.last_applied);
    try std.testing.expect(raft.commit_index > raft.last_applied);
    // Its reads are served, from that state, marked stale.
    try std.testing.expectEqual(proto.RESPONSE_STALE, (try t.ask(.cluster_status, "", &buf)).header.flags & proto.RESPONSE_STALE);
}

test "Shard: a cluster repair never skips a namespace create, even one the group halted at" {
    var t: AdminTest = undefined;
    try t.init(1, .bootstrap);
    defer t.deinit();
    const raft = t.shard.raft_node;
    try std.testing.expect(t.shard.applyCommitted());
    try ParkTest.joinPeer(&t.shard);
    var buf: [1024]u8 = undefined;
    // A create of an id already taken: the leader halts at it once it commits.
    const P = @import("../protocol/namespace_entries.zig").Create;
    var pbuf: [P.max_size]u8 = undefined;
    const h = (try raft.propose(.namespace_create, entry_mod.Flags.NONE, try P.encodeInto(&pbuf, .{ .name = "late", .id = ns_table.DEFAULT.int() }))).index;
    raft.peers[0].sent_up_to = h;
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = h, .from = 2 });
    try std.testing.expect(!t.shard.applyCommitted());
    try std.testing.expectEqual(h, raft.halt_at.?.index);
    try expectAnswer((try t.repairSkip(.admin, h, true, &buf)).?, .bad_request, "never skipped");
    try std.testing.expectEqual(h, raft.log.lastIndex());
}

test "Shard: a repair skip runs only from the admin socket, on a leader halted at the entry with a majority halted there; its dry run changes nothing" {
    var t: AdminTest = undefined;
    try t.init(1, .bootstrap);
    defer t.deinit();
    const raft = t.shard.raft_node;
    try std.testing.expect(t.shard.applyCommitted());
    try ParkTest.joinPeer(&t.shard);
    var buf: [1024]u8 = undefined;
    var ids: [8]u32 = undefined;

    var pbuf: [64]u8 = undefined;
    const applied = (try raft.propose(.kv_put, entry_mod.Flags.NONE, try kv_entries.Put.encodeInto(&pbuf, .{ .key = TEST_KV_K, .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null }))).index;
    try ParkTest.ack(&t.shard);
    // An entry every replica fails: the leader halts at it once it commits.
    const h = (try raft.propose(.cg_create, entry_mod.Flags.NONE, "")).index;
    raft.peers[0].sent_up_to = h;
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = h, .from = 2 });
    try std.testing.expect(!t.shard.applyCommitted());
    const halt = raft.halt_at.?;
    try std.testing.expectEqual(h, halt.index);

    // Not from a client's socket, or another shard.
    var r = (try t.repairSkip(.client, h, false, &buf)).?;
    try std.testing.expectEqual(proto.Reason.admin_only, (try r.refused()).reason);
    // Never a config or a term's no-op.
    try expectAnswer((try t.repairSkip(.admin, 1, false, &buf)).?, .bad_request, "never skipped");
    // Only where the leader is halted.
    var want: [64]u8 = undefined;
    try expectAnswer((try t.repairSkip(.admin, applied, false, &buf)).?, .bad_request, try std.fmt.bufPrint(&want, "not {d}:", .{applied}));
    // The peer hasn't said it halted there: one of two voters is no majority.
    try expectAnswer((try t.repairSkip(.admin, h, true, &buf)).?, .unavailable, "of 2 voters");
    try std.testing.expectEqual(h, raft.log.lastIndex());

    // Once it says so: the dry run names the entry and who halted there.
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = h, .from = 2, .halt = halt });
    r = (try t.repairSkip(.admin, h, false, &buf)).?;
    try std.testing.expectEqual(proto.StatusCode.ok, r.getStatus());
    const would = try cluster_wire.RepairSkipAnswer.decode(r.data, &ids);
    try std.testing.expect(!would.skipped);
    try std.testing.expectEqual(halt.crc, would.entry.crc);
    try std.testing.expectEqual(@backingInt(entry_mod.EntryType.cg_create), would.entry_type);
    try std.testing.expectEqualSlices(u32, &.{ 1, 2 }, would.halted);
    try std.testing.expectEqual(@as(u8, 2), would.voters);
    try std.testing.expectEqual(h, raft.log.lastIndex());

    // With yes, from a peer that forwarded it: proposed, answered at commit.
    try std.testing.expect((try t.repairSkip(.peer, h, true, &buf)) == null);
    const s = raft.log.lastIndex();
    var ebuf: [512]u8 = undefined;
    const skip_entry = raft.log.getEntryCopy(s, &ebuf).?;
    try std.testing.expect(repair.Skip.decode(&skip_entry).?.names(&(raft.log.getEntryCopy(h, &buf).?)));
    raft.peers[0].sent_up_to = s;
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = s, .from = 2, .halt = halt });
    try std.testing.expect(t.shard.applyCommitted());
    try std.testing.expect(t.shard.halted == null);
    var into: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &into);
    const done = try cluster_wire.RepairSkipAnswer.decode(into[0].data, &ids);
    try std.testing.expect(done.skipped);
    try std.testing.expectEqual(s, done.skip_index);

    // Asked again, it is skipped already, not a build split.
    t.conn.response_deferred = false;
    try expectAnswer((try t.repairSkip(.admin, h, false, &buf)).?, .bad_request, "skipped already");
}

test "Shard: a halted sync leader flushes its own repair skip, which commits only once its copy is on disk" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    var t: AdminTest = undefined;
    try t.initWith(1, .bootstrap, data_dir, .sync);
    defer t.deinit();
    const raft = t.shard.raft_node;
    try std.testing.expect(t.shard.applyCommitted());
    try ParkTest.joinPeer(&t.shard);
    var buf: [1024]u8 = undefined;
    // An entry every replica fails, committed by the peer and this
    // leader's own flushed copy: it halts there.
    const h = (try raft.propose(.cg_create, entry_mod.Flags.NONE, "")).index;
    _ = t.shard.applyCommitted();
    raft.peers[0].sent_up_to = h;
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = h, .from = 2 });
    try std.testing.expect(!t.shard.applyCommitted());
    const halt = raft.halt_at.?;
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = h, .from = 2, .halt = halt });
    // Its skip, acked by the peer: one of two voters until this leader's
    // copy is on disk, which only its apply pass flushes, halted or not.
    try std.testing.expect((try t.repairSkip(.peer, h, true, &buf)) == null);
    const s = raft.log.lastIndex();
    raft.peers[0].sent_up_to = s;
    raft.handleAppendResponse(.{ .term = raft.current_term, .success = true, .match_index = s, .from = 2, .halt = halt });
    try std.testing.expect(raft.commit_index < s);
    _ = t.shard.applyCommitted();
    try std.testing.expect(raft.durable_index >= s);
    try std.testing.expect(raft.commit_index >= s);
    _ = t.shard.applyCommitted();
    try std.testing.expect(t.shard.halted == null);
}

