test "checkAppliers: a type a contract machine owns may have no other applier, and needs none" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const Toy = struct {
        fn keys(_: *const entry_mod.Entry, _: *@import("../contract/view.zig").KeySet) error{OutOfMemory}!void {}
        fn apply(_: *@import("../contract/view.zig").View, _: *const entry_mod.Entry, _: *persistence_mod.Result) persistence_mod.ApplyError!void {}
        fn owning(comptime t: entry_mod.EntryType) contract_machine.Machine {
            return .{ .name = "toy", .entry_types = &.{t}, .families = &.{}, .keys = keys, .apply = apply };
        }
    };
    const listed_now = contract_machines.list;
    try checkAppliersWith(&listed_now, 0, &shard.replay_registry);
    // A type nothing else applies: the machine is its applier.
    try checkAppliersWith(&(listed_now ++ .{Toy.owning(.raft_snapshot)}), 0, &shard.replay_registry);
    // Routed to a projection, or registered by a handler, too: refused.
    try std.testing.expectError(error.EntryTypeHasTwoAppliers, checkAppliersWith(&(listed_now ++ .{Toy.owning(.ts_write)}), 0, &shard.replay_registry));
    try std.testing.expectError(error.EntryTypeHasTwoAppliers, checkAppliersWith(&(listed_now ++ .{Toy.owning(.stream_append)}), 0, &shard.replay_registry));
    // KV's types are its machine's: without it, they have no applier.
    try std.testing.expectError(error.EntryTypeHasNoApplier, checkAppliersWith(&.{}, 0, &shard.replay_registry));
}

test "applyEntryCore: a machine reads the streams every entry below its own left" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    const view_mod = @import("../contract/view.zig");
    const Reader = struct {
        var hash: stream_mod.StreamKey = @splat(0);
        var seen: [8]StreamID = undefined;
        var n: usize = 0;
        fn keys(_: *const entry_mod.Entry, _: *view_mod.KeySet) error{OutOfMemory}!void {}
        fn apply(view: *view_mod.View, _: *const entry_mod.Entry, _: *persistence_mod.Result) persistence_mod.ApplyError!void {
            n = (try view.streams()).idsAfter(hash, StreamID.MIN, &seen);
        }
        const machine: contract_machine.Machine = .{ .name = "reader", .entry_types = &.{.cg_create}, .families = &.{}, .keys = keys, .apply = apply };
    };
    Reader.hash = stream_mod.streamKey(.default, "s");

    const v = try stream_mod.encodeAppendValue(std.testing.allocator, 0, "a");
    defer std.testing.allocator.free(v);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    try std.testing.expect(shard.applyCommitted());

    // The next index, as the shard's own apply would reach it.
    const raft = shard.raft_node;
    const e = entry_mod.buildEntry(.cg_create, entry_mod.Flags.NONE, raft.current_term, raft.last_applied + 1, raft.applied_stamp + 1, "");
    var out: persistence_mod.Result = .{};
    out.reset(&e);
    const machines = contract_machines.list ++ .{Reader.machine};
    try std.testing.expect(applyEntryCoreWith(&machines, shard.defaultPartition(), &shard.replay_registry, &e, &out) == .applied);
    try std.testing.expectEqual(@as(usize, 2), Reader.n);
    try std.testing.expect(Reader.seen[0].eql(shard.stream_handler.stream.streamFirstId(Reader.hash)));
    try std.testing.expect(Reader.seen[1].eql(shard.stream_handler.stream.streamLastId(Reader.hash)));

    // Applied without the streams, the read halts the entry.
    var bare: persistence_mod.Result = .{};
    bare.reset(&e);
    try std.testing.expectError(error.Halt, contract_machine.applyEntry(&Reader.machine, &shard.defaultPartition().store, &shard.defaultPartition().apply_scratch, &e, &bare));
}

test "applyEntryCore: a stream's delete reaches its groups after it applies, and not when it is refused" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const v = try stream_mod.encodeAppendValue(std.testing.allocator, 0, "a");
    defer std.testing.allocator.free(v);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    try std.testing.expect(shard.applyCommitted());

    const gm = @import("../stream/group_machine.zig");
    const p = shard.defaultPartition();
    var index = shard.raft_node.last_applied;
    var cb: [ge_mod.Create.max_size]u8 = undefined;
    const create = entry_mod.buildEntry(.group_create, entry_mod.Flags.NONE, shard.raft_node.current_term, index + 1, 1, try ge_mod.Create.encodeInto(&cb, .{ .ns = 1, .stream = "s", .group = "g", .lease_ms = 30_000, .max_attempts = 3 }));
    index += 1;
    var out: persistence_mod.Result = .{};
    out.reset(&create);
    try std.testing.expect(applyEntryCore(p, &shard.replay_registry, &create, &out) == .applied);

    const hash = stream_mod.streamKey(.default, "s");
    const genOf = struct {
        fn f(part: *Partition, h: stream_mod.StreamKey) u64 {
            var b: [13]u8 = undefined;
            const got = (@import("../contract/view.zig").ReadView{ .store = &part.store }).get(gm.Streams_, gm.recKey(&b, h)) catch unreachable;
            return got.?.v.gen;
        }
    }.f;
    try std.testing.expectEqual(@as(u64, 0), genOf(p, hash));
    // Not empty, not forced: refused, and the group never hears of it.
    // Forced: applied, and the group's stream moves on a generation.
    for ([_]u16{ entry_mod.Flags.NONE, entry_mod.Flags.FORCE }, [_]u64{ 0, 1 }) |flags, gen| {
        var buf: [64]u8 = undefined;
        const cmd: entry_mod.CommandPayload = .{ .namespace_id = .default, .key_length = 1, .value_length = 0, .key = "s", .value = "" };
        index += 1;
        const del = entry_mod.buildEntry(.stream_delete, flags, shard.raft_node.current_term, index, 2, buf[0..cmd.serialize(&buf).?]);
        out.reset(&del);
        try std.testing.expect(applyEntryCore(p, &shard.replay_registry, &del, &out) == .applied);
        try std.testing.expectEqual(flags == entry_mod.Flags.NONE, out.refused() != null);
        try std.testing.expectEqual(gen, genOf(p, hash));
    }
}

test "applyEntryCore: a KV entry delivered twice applies once" {
    var part = try Partition.init(std.testing.allocator, 0, 8192, 0);
    defer part.deinit();
    part.wireProjections();
    var registry: ReplayRegistry = .{};
