test "Shard: a read the leader answers, on a node that does not lead, waits for a leader and is refused, never answered from here" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 8, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    // This node's own copy holds a message: a peek answered here would show it.
    try queue_handler_mod.enqueueHere(&shard, "q", "here");

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    const Peek = table_run.op("queue.peek");
    var body_buf: [Peek.request.max_size]u8 = undefined;
    const body = try Peek.request.encodeInto(&body_buf, .{ .limit = 5 });
    shard.runRequest(conn, .{ .header = proto.RequestHeader.init(.queue_peek, 6), .namespace = "default", .key = "q", .value = body }, .client);
    try std.testing.expectEqual(@as(u32, 1), shard.forward_count);
    try std.testing.expectEqual(@as(usize, 0), conn.write_buf.readable());
    // So are the hand-coded reads of leader memory: a group's info and
    // pending entries, and the dead letters only the leasing leader makes.
    for ([_]proto.OpCode{ .stream_group_info, .stream_group_pending, .queue_dlq_list }, 0..) |op, i| {
        shard.runRequest(conn, .{ .header = proto.RequestHeader.init(op, 80 + i), .namespace = "default", .key = "q", .value = "" }, .client);
        try std.testing.expectEqual(@as(u32, @intCast(2 + i)), shard.forward_count);
    }
    try std.testing.expectEqual(@as(usize, 0), conn.write_buf.readable());
    for (shard.forwards) |*f| {
        if (f.active and f.request_id >= 80) shard.dropForward(f);
    }

    shard.sweepForwards(Shard.nowMs() + FORWARD_TIMEOUT_MS + 1);
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);
    var out: [256]u8 = undefined;
    const n = std.c.read(pair[1], &out, out.len);
    try std.testing.expect(n > 0);
    const resp = try proto.Response.parse(out[0..@intCast(n)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), resp.header.status);
    const r = try resp.refused();
    try std.testing.expectEqual(proto.Reason.leader_unknown, r.reason);
    try std.testing.expectEqual(proto.Ran.no, r.ran);
}

test "a halted leader answers a read only it can, marked stale: a halt clears none of its memory" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    try queue_handler_mod.enqueueHere(&shard, "q", "kept");
    haltForTest(&shard, shard.raft_node.log.lastIndex() + 1);

    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    const Peek = table_run.op("queue.peek");
    var body_buf: [Peek.request.max_size]u8 = undefined;
    var out: [1024]u8 = undefined;
    shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.queue_peek, 7), .namespace = "default", .key = "q", .value = try Peek.request.encodeInto(&body_buf, .{ .limit = 5 }) }, .client);
    const resp = try proto.Response.parse(out[0..c.conn.write_buf.read(&out)]);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(resp.header.flags & proto.RESPONSE_STALE != 0);
    var diag: schema.Diagnostic = .{};
    const v = try Peek.response.decodeAll(resp.data, &diag);
    var it = v.messages.iterator();
    try std.testing.expectEqualStrings("kept", (try it.next()).?.payload);
}

test "Shard: a read the leader answers, unanswered by the shard it went to, is told it didn't run, as any read is" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    const Peek = table_run.op("queue.peek");
    var body_buf: [Peek.request.max_size]u8 = undefined;
    const peek = try Shard.serializeRequest(std.testing.allocator, .{ .header = proto.RequestHeader.init(.queue_peek, 61), .namespace = "default", .key = "q", .value = try Peek.request.encodeInto(&body_buf, .{ .limit = 5 }) });
    defer std.testing.allocator.free(peek);
    try forwardForTest(a, 1, c.conn, peek);
    // Its slot is a read's.
    for (a.reply_pool.slots) |*s| {
        if (s.active) {
            try std.testing.expect(!s.writes);
            s.taken_ms = 0;
            s.answer_due_ms = 0;
        }
    }
    a.reply_sweep_ms = 0;
    _ = try a.tick(0);
    var out: [256]u8 = undefined;
    var got: usize = 0;
    var tries: usize = 0;
    while (got < @sizeOf(proto.ResponseHeader) and tries < 1000) : (tries += 1) {
        const n = std.c.read(c.pair[1], out[got..].ptr, out.len - got);
        if (n > 0) got += @intCast(n);
    }
    const told = try proto.Response.parse(out[0..got]);
    try std.testing.expectEqual(@as(u64, 61), told.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), told.header.status);
    try std.testing.expectEqual(proto.Ran.no, (try told.refused()).ran);
}

test "Shard: a forward lost after it went to the leader tells a read it didn't run, and a write it may still apply" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 8, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    const Peek = table_run.op("queue.peek");
    var body_buf: [Peek.request.max_size]u8 = undefined;
    shard.runRequest(conn, .{ .header = proto.RequestHeader.init(.queue_peek, 71), .namespace = "default", .key = "q", .value = try Peek.request.encodeInto(&body_buf, .{ .limit = 5 }) }, .client);
    shard.runRequest(conn, testReq(.kv_put, 72, "", "k", "v", ""), .client);
    try std.testing.expectEqual(@as(u32, 2), shard.forward_count);
    // Both went to a leader, in a term that has since passed.
    for (shard.forwards) |*f| {
        if (!f.active) continue;
        f.sent_to = 2;
        f.sent_term = shard.raft_node.current_term + 1;
    }
    shard.sweepForwards(Shard.nowMs());
    try std.testing.expectEqual(@as(u32, 0), shard.forward_count);

    var out: [512]u8 = undefined;
    var got: usize = 0;
    var tries: usize = 0;
    while (got < 2 * @sizeOf(proto.ResponseHeader) + 40 and tries < 1000) : (tries += 1) {
        const n = std.c.read(pair[1], out[got..].ptr, out.len - got);
        if (n > 0) got += @intCast(n);
    }
    var at: usize = 0;
    for (0..2) |_| {
        const r = try proto.Response.parse(out[at..got]);
        at += @sizeOf(proto.ResponseHeader) + r.header.data_len;
        try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), r.header.status);
        const why = try r.refused();
        if (r.header.request_id == 71) {
            try std.testing.expectEqual(proto.Ran.no, why.ran);
            try std.testing.expectEqual(proto.Reason.leader_unknown, why.reason);
            try std.testing.expect(std.mem.indexOf(u8, why.message, "lost the leader before it answered") != null);
        } else {
            try std.testing.expectEqual(@as(u64, 72), r.header.request_id);
            try std.testing.expect(std.mem.indexOf(u8, why.message, "write may still apply") != null);
        }
    }
}

/// Shard 0's log written by hand: creates with any name and id, which no
/// ready leader would propose, and puts stamped with an id.
const CreateLog = struct {
    fn create(shard: *Shard, name: []const u8, id: u32) !u64 {
        var buf: [@import("../protocol/namespace_entries.zig").Create.max_size]u8 = undefined;
        const bytes = try @import("../protocol/namespace_entries.zig").Create.encodeInto(&buf, .{ .name = name, .id = id });
        return (try shard.raft_node.propose(.namespace_create, entry_mod.Flags.NONE, bytes)).index;
    }

    fn put(shard: *Shard, id: ns_table.Id, value: []const u8) !u64 {
        const key: [5]u8 = id.bytes() ++ [_]u8{'k'};
        var buf: [64]u8 = undefined;
        const bytes = try kv_entries.Put.encodeInto(&buf, .{ .key = &key, .value = value, .ttl_ms = null, .condition = .always, .cas_version = null });
        return (try shard.raft_node.propose(.kv_put, entry_mod.Flags.NONE, bytes)).index;
    }

    /// The put's value under `id`, on any of the shard's partitions.
    fn held(shard: *Shard, id: ns_table.Id) ?[]const u8 {
        const key: [5]u8 = id.bytes() ++ [_]u8{'k'};
        for (shard.partitions) |p| if (p.kv.get(&key)) |cur| return cur.value;
        return null;
    }

    const Refusal = enum { full, stale, existed };

    /// What comes before the create its applier refuses, applied; then the
    /// create, and a put behind it stamped with its id. Returns the create's
    /// index and id.
    fn build(shard: *Shard, why: Refusal) !struct { u64, ns_table.Id } {
        const nh = shard.namespace_handler;
        const first = ns_table.FIRST_ALLOCATED.int();
        var name_buf: [16]u8 = undefined;
        switch (why) {
            // Every live namespace there can be, default among them.
            .full => while (nh.namespaces.count() < ns_table.MAX_LIVE) {
                _ = try create(shard, try std.fmt.bufPrint(&name_buf, "ns{d}", .{nh.next_id}), nh.next_id);
                try std.testing.expect(shard.applyCommitted());
            },
            .stale, .existed => {
                _ = try create(shard, "first", first);
                try std.testing.expect(shard.applyCommitted());
            },
        }
        const id: u32 = switch (why) {
            .full, .existed => nh.next_id,
            // One another create already took.
            .stale => first,
        };
        const index = try create(shard, if (why == .existed) "first" else "late", id);
        _ = try put(shard, .of(id), "behind the create");
        return .{ index, .of(id) };
    }

    /// Halted at the create, with nothing from it or the put behind it.
    fn expectHaltedAt(shard: *Shard, index: u64, id: ns_table.Id, why: Refusal) !void {
        const h = shard.halted orelse return error.NotHalted;
        try std.testing.expectEqual(index, h.index);
        try std.testing.expectEqual(index - 1, shard.raft_node.last_applied);
        try std.testing.expect(held(shard, id) == null);
        try std.testing.expect(!shard.namespace_handler.namespaces.contains("late"));
        if (why == .full) try std.testing.expectEqual(@as(usize, ns_table.MAX_LIVE), shard.namespace_handler.namespaces.count());
        if (why == .existed) try std.testing.expect(shard.namespace_handler.nameOf(id) == null);
    }
};

test "Shard: a write behind a create its applier refuses never applies: shard 0 halts at the create, live and on replay at boot, on 1 and 4 shards" {
    for ([_]u16{ 1, 4 }) |shards| {
        for (std.enums.values(CreateLog.Refusal)) |why| {
            var tmp = std.testing.tmpDir(.{});
            defer tmp.cleanup();
            const data_dir = try testDataDir(&tmp);
            defer std.testing.allocator.free(data_dir);
            const pipe_fds = try @import("stdx").io.pipe();
            defer _ = std.c.close(pipe_fds[0]);
            defer _ = std.c.close(pipe_fds[1]);
            var index: u64 = 0;
            var id: ns_table.Id = .invalid;
            {
                // Logged and on disk, never applied here.
                var shard = try Shard.init(std.testing.allocator, 0, shards, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
                defer shard.deinit();
                shard.wireHandlerShardPtrs();
                try std.testing.expect(shard.applyCommitted());
                index, id = try CreateLog.build(&shard, why);
                try shard.flushSegmentToDisk();
            }
            {
                // Replayed at boot.
                var shard = try Shard.init(std.testing.allocator, 0, shards, 4096, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
                defer shard.deinit();
                shard.wireHandlerShardPtrs();
                try std.testing.expect(!shard.applyCommitted());
                try CreateLog.expectHaltedAt(&shard, index, id, why);
            }
            {
                // Applied live.
                var shard = try Shard.init(std.testing.allocator, 0, shards, 4096, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
                defer shard.deinit();
                shard.wireHandlerShardPtrs();
                try std.testing.expect(shard.applyCommitted());
                index, id = try CreateLog.build(&shard, why);
                try std.testing.expect(!shard.applyCommitted());
                try CreateLog.expectHaltedAt(&shard, index, id, why);
            }
        }
    }
}

test "Shard: a create cut with the log's tail by a new leader takes its write with it, and its id then holds only the new leader's namespace" {
    // How much of the old leader's create and write the new leader kept.
    for ([_]u64{ 0, 1 }) |kept| {
        var t: RaceTest = undefined;
        try t.init();
        defer t.deinit();
        const r = t.shard.raft_node;
        const nh = t.shard.namespace_handler;
        const term = r.current_term;
        const before = r.log.lastIndex();
        const id: ns_table.Id = .of(nh.next_id);
        // A write to a namespace this leader doesn't know: the create, then
        // the write stamped with its id, neither committed.
        var set_buf: [64]u8 = undefined;
        const body = try table_run.op("kv.set").request.encodeInto(&set_buf, .{ .value = "orders'", .ttl_ms = null, .condition = .always, .cas_version = null, .txn = null });
        t.shard.runRequest(t.conn, testReq(.kv_put, 1, "orders", "k", body, ""), .client);
        try std.testing.expectEqual(before + 2, r.log.lastIndex());
        try std.testing.expectEqual(@as(?ns_table.Id, id), nh.idOf("orders"));

        // Node 2 leads term + 1. It keeps `kept` of those entries, and in
        // place of the rest creates "ledger", which takes the same id, and
        // writes in it; all of it commits.
        var entries: [2]entry_mod.Entry = undefined;
        var create_buf: [@import("../protocol/namespace_entries.zig").Create.max_size]u8 = undefined;
        var put_buf: [64]u8 = undefined;
        const key: [5]u8 = id.bytes() ++ [_]u8{'k'};
        var stamp = r.log.last_stamp;
        const n: usize = if (kept == 0) 2 else 1;
        for (0..n) |i| {
            stamp += 1;
            const at = before + kept + 1 + i;
            entries[i] = if (kept == 0 and i == 0)
                entry_mod.buildEntry(.namespace_create, entry_mod.Flags.NONE, term + 1, at, stamp, try @import("../protocol/namespace_entries.zig").Create.encodeInto(&create_buf, .{ .name = "ledger", .id = id.int() }))
            else
                entry_mod.buildEntry(.kv_put, entry_mod.Flags.NONE, term + 1, at, stamp, try kv_entries.Put.encodeInto(&put_buf, .{ .key = &key, .value = "new leader's", .ttl_ms = null, .condition = .always, .cas_version = null }));
            entries[i].header.crc32c = entries[i].computeCrc();
        }
        const last = before + kept + n;
        _ = try r.handleAppendEntries(.{ .term = term + 1, .leader_id = 2, .prev_log_index = before + kept, .prev_log_term = term, .entries = entries[0..n], .leader_commit = last });
        t.shard.replica.leadershipLost("a leader with a newer term spoke");
        try std.testing.expect(t.shard.applyCommitted());
        try std.testing.expectEqual(last, r.last_applied);

        // The client's write never applied, and it was told it might not have.
        var buf: [1024]u8 = undefined;
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
        try std.testing.expect(nh.idOf("orders") == null or kept == 1);
        if (kept == 0) {
            // Both cut: the id is the new leader's namespace, with its data only.
            try std.testing.expect(!nh.namespaces.contains("orders"));
            try std.testing.expectEqualStrings("ledger", nh.nameOf(id).?);
            try std.testing.expectEqual(id, nh.namespaces.get("ledger").?.id);
        } else {
            // The create kept, its write cut: the namespace is made, empty
            // of the old leader's write.
            try std.testing.expectEqualStrings("orders", nh.nameOf(id).?);
            try std.testing.expect(!nh.namespaces.contains("ledger"));
        }
        try std.testing.expectEqualStrings("new leader's", CreateLog.held(&t.shard, id).?);
        // Nothing this node proposed is still taken for its own.
        try std.testing.expectEqual(@as(u32, 0), nh.pending_creates.count());
        try std.testing.expectEqual(@as(u32, 0), nh.next_alloc);
    }
}

test "Shard: a leader is ready only once its next id is past every create in its log, an earlier leader's committed and uncommitted ones too" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;
    const nh = t.shard.namespace_handler;
    const term = r.current_term;
    const before = r.log.lastIndex();
    const first = nh.next_id;
    // Node 2 leads term + 1 and creates two namespaces; this node, now
    // following, holds both, the first committed, neither applied.
    t.shard.replica.leadershipLost("a leader with a newer term spoke");
    var entries: [2]entry_mod.Entry = undefined;
    var bufs: [2][@import("../protocol/namespace_entries.zig").Create.max_size]u8 = undefined;
    for (&entries, 0..) |*e, i| {
        e.* = entry_mod.buildEntry(.namespace_create, entry_mod.Flags.NONE, term + 1, before + 1 + i, r.log.last_stamp + 1 + i, try @import("../protocol/namespace_entries.zig").Create.encodeInto(&bufs[i], .{ .name = if (i == 0) "a" else "b", .id = first + @as(u32, @intCast(i)) }));
        e.header.crc32c = e.computeCrc();
    }
    _ = try r.handleAppendEntries(.{ .term = term + 1, .leader_id = 2, .prev_log_index = before, .prev_log_term = term, .entries = &entries, .leader_commit = before + 1 });
    try std.testing.expectEqual(first, nh.next_id);

    // Elected at term + 2, as `becomeLeader` leaves it: nothing of the
    // earlier term applied yet.
    r.current_term = term + 2;
    r.role = .leader;
    r.leader_id = r.id;
    r.ready_index = r.log.lastIndex();
    try std.testing.expect(!r.leaderReady());
    switch (nh.proposeCreateOn(r, "fresh")) {
        .refused => |why| try std.testing.expectEqualStrings(NamespaceHandler.CATCHING_UP_MESSAGE, why.message),
        else => return error.TestUnexpectedResult,
    }
    // The committed create applies; the other waits for this term's entry.
    try std.testing.expect(t.shard.applyCommitted());
    try std.testing.expect(!r.leaderReady());
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    try ParkTest.ack(&t.shard);
    try std.testing.expect(r.leaderReady());
    try std.testing.expectEqual(first + 2, nh.next_id);
    try std.testing.expectEqualStrings("b", nh.nameOf(.of(first + 1)).?);
    // Its first create takes the id after them.
    const at = r.log.lastIndex() + 1;
    try std.testing.expect(nh.proposeCreateOn(r, "fresh") == .proposed);
    try std.testing.expectEqual(@as(?ns_table.Id, .of(first + 2)), nh.idOf("fresh"));
    try ParkTest.ack(&t.shard);
    try std.testing.expectEqual(at, nh.namespaces.get("fresh").?.created_index);
}

/// A below-the-ring source that can never be read right now, to stand in for
/// a host whose disk reads are blocked.
const BlockedCatchUp = struct {
    fn blocked(_: *anyopaque, _: u64, _: []entry_mod.Entry, _: []u8) raft_log_mod.CatchUpResult {
        return .{ .blocked = true };
    }
};

/// A blocked source that counts how often it is read and whose cause the test
/// can switch between a resource shortage and a failing disk.
const CountingBlock = struct {
    var calls: usize = 0;
    var disk_failing: bool = false;
    fn read(_: *anyopaque, _: u64, _: []entry_mod.Entry, _: []u8) raft_log_mod.CatchUpResult {
        calls += 1;
        return .{ .blocked = true, .disk_failing = disk_failing };
    }
};

/// A shard with 100 large entries, the first of them below the ring, so a
/// swapped-in catch-up source decides whether applying can proceed. Caller
/// owns `tmp` (cleanup) and the returned scratch slice (free).
fn blockedReadFixture(tmp: *std.testing.TmpDir, pipe_read: std.posix.fd_t) !struct { shard: Shard, real: raft_log_mod.CatchUpSource } {
    const data_dir = try testDataDir(tmp);
    defer std.testing.allocator.free(data_dir);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_read, data_dir, 8 * 1024 * 1024, 0, 0, .async_flush, 1, .single, .{}, .{});
    errdefer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const big = try std.testing.allocator.alloc(u8, 32 * 1024);
    defer std.testing.allocator.free(big);
    @memset(big, 0);
    const raft = shard.raft_node;
    const first = raft.log.lastIndex() + 1;
    for (0..100) |_| _ = try raft.propose(.raft_noop, entry_mod.Flags.NONE, big);
    try shard.flushSegmentToDisk();
    var scratch: [1024 * 1024]u8 = undefined;
    try std.testing.expect(raft.log.ual.readCopy(first, &scratch) == null);
    return .{ .shard = shard, .real = raft.log.catch_up.? };
}

test "shard: a blocked read is retried on a back-off, not probed on every apply" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const fix = try blockedReadFixture(&tmp, pipe_fds[0]);
    var shard = fix.shard;
    defer shard.deinit();
    const raft = shard.raft_node;

    CountingBlock.calls = 0;
    CountingBlock.disk_failing = false;
    raft.log.catch_up = .{ .ctx = fix.real.ctx, .read_range = CountingBlock.read };

    // The first apply probes the disk once and blocks.
    try std.testing.expect(!shard.applyCommitted());
    try std.testing.expectEqual(@as(usize, 1), CountingBlock.calls);
    // Further applies inside the back-off do not touch the disk.
    for (0..5) |_| try std.testing.expect(!shard.applyCommitted());
    try std.testing.expectEqual(@as(usize, 1), CountingBlock.calls);
    // Past the back-off, it probes again — once.
    shard.read_retry_at_ms = 0;
    try std.testing.expect(!shard.applyCommitted());
    try std.testing.expectEqual(@as(usize, 2), CountingBlock.calls);
}

test "shard: a disk-failing read damages only after the disk's own grace, restarting the clock at the class change, and clears the block" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const fix = try blockedReadFixture(&tmp, pipe_fds[0]);
    var shard = fix.shard;
    defer shard.deinit();
    const raft = shard.raft_node;

    CountingBlock.calls = 0;
    CountingBlock.disk_failing = false; // begins as a resource shortage
    raft.log.catch_up = .{ .ctx = fix.real.ctx, .read_range = CountingBlock.read };
    try std.testing.expect(!shard.applyCommitted());
    // A resource shortage sets no disk deadline, however long it lasts.
    try std.testing.expect(shard.read_blocked and !shard.read_block_disk_failing);
    try std.testing.expect(shard.read_block_disk_deadline_ms == null);

    // The cause now turns disk-class. The deadline is set here — a full grace
    // ahead of now — so the earlier resource wait does not count toward it, and
    // nothing is damaged yet. (An absolute deadline, so no uptime subtraction
    // that would underflow on a fresh host — the flo#302 trap.)
    CountingBlock.disk_failing = true;
    shard.read_retry_at_ms = 0;
    try std.testing.expect(!shard.applyCommitted());
    try std.testing.expect(shard.offline == null and !shard.replica.diverged);
    try std.testing.expect(shard.read_block_disk_failing);
    try std.testing.expect(shard.read_block_disk_deadline_ms.? > Shard.nowMs());
    try std.testing.expectEqual(@as(u64, 0), shard.losses.total(.unreadable_committed));

    // Bring the deadline into the past: the next disk-class read is damage.
    shard.read_block_disk_deadline_ms = 1;
    shard.read_retry_at_ms = 0;
    try std.testing.expect(!shard.applyCommitted());
    try std.testing.expect(shard.offline != null or shard.replica.diverged);
    try std.testing.expectEqual(@as(u64, 1), shard.losses.total(.unreadable_committed));
    // The block is cleared, so its gauge does not stick and `/status` shows the
    // damage, not a stale block.
    try std.testing.expect(!shard.read_blocked);
    try std.testing.expect(shard.healthState() != .read_blocked);
}

test "shard: a node still catching up that also blocks a read shows catching_up, not read_blocked" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const fix = try blockedReadFixture(&tmp, pipe_fds[0]);
    var shard = fix.shard;
    defer shard.deinit();

    // Still catching up (a cold async boot) and a committed read is blocked.
    shard.cold_gate = true;
    shard.read_blocked = true;
    // catching_up is checked first, so the node stays 503 rather than flipping
    // to read_blocked and answering 200 while it refuses reads.
    try std.testing.expectEqual(health_mod.ShardState.catching_up, shard.healthState());
    // Once caught up, the block is the state.
    shard.cold_gate = false;
    try std.testing.expectEqual(health_mod.ShardState.read_blocked, shard.healthState());
}

test "shard: a repair skip whose named entry can't be read holds its check, then damages on recovery, never dropping it" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], data_dir, 8 * 1024 * 1024, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const raft = shard.raft_node;

    // An entry this node applies, then pushed below the ring by larger ones
    // that also apply. A repair later skips it: this node holds what the group
    // dropped, so its check must damage — and must not be lost to a blocked read.
    const x = (try raft.propose(.raft_noop, entry_mod.Flags.NONE, "x")).index;
    const big = try std.testing.allocator.alloc(u8, 32 * 1024);
    defer std.testing.allocator.free(big);
    @memset(big, 0);
    for (0..100) |_| _ = try raft.propose(.raft_noop, entry_mod.Flags.NONE, big);
    try shard.flushSegmentToDisk();
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(raft.commit_index, raft.last_applied);
    var scratch: [1024 * 1024]u8 = undefined;
    try std.testing.expect(raft.log.ual.readCopy(x, &scratch) == null); // below the ring now
    const skip_idx = try proposeSkip(&shard, x);

    // Reads below the ring block: applying the skip reads the named entry and
    // can't decide. The check is held, not dropped — not damaged, not advanced.
    const real = raft.log.catch_up.?;
    raft.log.catch_up = .{ .ctx = real.ctx, .read_range = BlockedCatchUp.blocked };
    for (0..3) |_| {
        _ = shard.applyCommitted();
        shard.read_retry_at_ms = 0;
    }
    try std.testing.expectEqual(skip_idx, shard.skip_check_pending);
    try std.testing.expect(shard.read_blocked);
    try std.testing.expect(shard.offline == null and !shard.replica.diverged);
    try std.testing.expectEqual(@as(u64, 0), shard.losses.total(.applied_skipped));

    // The read recovers: the held check runs and finds this node applied what
    // the repair skips — damage, not silence.
    raft.log.catch_up = real;
    shard.read_retry_at_ms = 0;
    _ = shard.applyCommitted();
    try std.testing.expectEqual(@as(u64, 0), shard.skip_check_pending);
    try std.testing.expectEqual(@as(u64, 1), shard.losses.total(.applied_skipped));
    try std.testing.expect(shard.offline != null or shard.replica.diverged);
}

test "shard: publishHealth sets the read-blocked gauge while blocked, and clears it on recovery" {
    var registry = @import("../metrics/registry.zig").MetricsRegistry.init(std.testing.allocator);
    defer registry.deinit();
    try registry.initShards(1);
    const sm = registry.shardMetrics(0).?;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const fix = try blockedReadFixture(&tmp, pipe_fds[0]);
    var shard = fix.shard;
    defer shard.deinit();
    shard.shard_metrics = sm;
    const raft = shard.raft_node;

    CountingBlock.calls = 0;
    CountingBlock.disk_failing = false;
    raft.log.catch_up = .{ .ctx = fix.real.ctx, .read_range = CountingBlock.read };
    try std.testing.expect(!shard.applyCommitted());
    try std.testing.expect(shard.read_blocked);
    shard.publishHealth();
    try std.testing.expectEqual(@as(u8, 1), sm.read_blocked.load(.monotonic));

    // Recovers: the gauge drops back.
    raft.log.catch_up = fix.real;
    var rounds: usize = 0;
    while (raft.last_applied < raft.commit_index and rounds < 1000) : (rounds += 1) {
        shard.read_retry_at_ms = 0;
        _ = shard.applyCommitted();
    }
    try std.testing.expect(!shard.read_blocked);
    shard.publishHealth();
    try std.testing.expectEqual(@as(u8, 0), sm.read_blocked.load(.monotonic));
}

test "shard: a committed entry that cannot be read is held unapplied, applies on recovery, and a write for it parks" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, 4096, pipe_fds[0], data_dir, 8 * 1024 * 1024, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    // Enough large entries that the first falls below the ring.
    const big = try std.testing.allocator.alloc(u8, 32 * 1024);
    defer std.testing.allocator.free(big);
    @memset(big, 0);
    const raft = shard.raft_node;
    const first = raft.log.lastIndex() + 1;
    for (0..100) |_| _ = try raft.propose(.raft_noop, entry_mod.Flags.NONE, big);
    try shard.flushSegmentToDisk();
    const scratch = try std.testing.allocator.alloc(u8, 1024 * 1024);
    defer std.testing.allocator.free(scratch);
    try std.testing.expect(raft.log.ual.readCopy(first, scratch) == null);

    // Every below-ring read now blocks.
    const real = raft.log.catch_up.?;
    raft.log.catch_up = .{ .ctx = real.ctx, .read_range = BlockedCatchUp.blocked };
    const before = raft.last_applied;
    for (0..3) |_| try std.testing.expect(!shard.applyCommitted());
    // Held, not advanced, not damaged, not spinning, and visible.
    try std.testing.expectEqual(before, raft.last_applied);
    try std.testing.expect(shard.offline == null);
    try std.testing.expect(!shard.apply_behind);
    try std.testing.expect(shard.read_blocked);
    try std.testing.expectEqual(health_mod.ShardState.read_blocked, shard.healthState());
    try std.testing.expectEqual(@as(u64, 0), shard.losses.total(.unreadable_committed));

    // A write whose entry is held parks rather than being refused.
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    try ParkTest.send(&shard, conn, .kv_put, 7, "k", "v");
    var none: [0]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], scratch, &none);
    try std.testing.expect(conn.response_deferred);

    // The read recovers; everything applies in order and the parked write is
    // answered. (Clear the retry back-off so the test need not wait it out.)
    raft.log.catch_up = real;
    shard.read_retry_at_ms = 0;
    var rounds: usize = 0;
    while (raft.last_applied < raft.commit_index and rounds < 1000) : (rounds += 1) {
        shard.read_retry_at_ms = 0;
        _ = shard.applyCommitted();
    }
    try std.testing.expectEqual(raft.commit_index, raft.last_applied);
    try std.testing.expect(!shard.read_blocked);
    try std.testing.expect(shard.offline == null);
    try std.testing.expect(shard.halted == null);
    var one: [1]proto.Response = undefined;
    var rbuf: [1024]u8 = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &rbuf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
}

/// A lone node with no data dir, answering a client over a socket pair.
const AsyncAlone = struct {
    pipe_fds: [2]i32,
    pair: [2]std.posix.fd_t,
    shard: Shard,
    conn: *Connection,

    fn init(self: *AsyncAlone) !void {
        self.pipe_fds = try @import("stdx").io.pipe();
        self.shard = try Shard.init(std.testing.allocator, 0, 1, 4096, self.pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        self.shard.wireHandlerShardPtrs();
        try std.testing.expect(self.shard.applyCommitted());
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &self.pair));
        // Room for a thousand answers at once: on resume the shard writes
        // them all before the test reads, and a full socket would block it.
        const big: c_int = 1 << 20;
        for (self.pair) |fd| {
            _ = std.c.setsockopt(fd, std.posix.SOL.SOCKET, std.posix.SO.SNDBUF, @ptrCast(&big), @sizeOf(c_int));
            _ = std.c.setsockopt(fd, std.posix.SOL.SOCKET, std.posix.SO.RCVBUF, @ptrCast(&big), @sizeOf(c_int));
        }
        self.conn = try self.shard.addConnection(self.pair[0]);
    }

    fn deinit(self: *AsyncAlone) void {
        self.shard.deinit();
        _ = std.c.close(self.pair[1]);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
    }
};

/// Steps an open window until it closes; fails if it doesn't within a few.
fn stepWindowClosed(sh: *Shard) !void {
    var steps: u32 = 0;
    while (sh.snapshot_window != null) : (steps += 1) {
        try std.testing.expect(steps <= TEST_BAR_SLICES);
        sh.stepSnapshotWindow();
    }
}

test "Shard: alone, a write at a snapshot bar is answered and suspends apply; writes after it commit, park, read the state at the bar, and are answered on resume" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;

    t.shard.test_bar = r.log.lastIndex() + 1;
    try ParkTest.send(&t.shard, t.conn, .kv_put, 1, "a", "v");
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    const window = t.shard.snapshot_window.?;
    try std.testing.expectEqual(t.shard.test_bar, window.s);
    try std.testing.expectEqual(window.s, r.last_applied);

    // Committed at once on a lone node, but not applied: it waits.
    try ParkTest.send(&t.shard, t.conn, .kv_put, 2, "b", "v");
    try ParkTest.send(&t.shard, t.conn, .kv_put, 3, "c", "v");
    try std.testing.expect(r.commit_index >= window.s + 2);
    try std.testing.expectEqual(window.s, r.last_applied);
    try std.testing.expectEqual(@as(u32, 2), t.shard.pending_count);
    // A read sees the state at the bar.
    try ParkTest.send(&t.shard, t.conn, .kv_get, 4, "b", "");
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 4), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), one[0].header.status);

    try stepWindowClosed(&t.shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &two);
    for (two, [_]u64{ 2, 3 }) |a, id| {
        try std.testing.expectEqual(id, a.header.request_id);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), a.header.status);
    }
    try std.testing.expectEqual(@as(u32, 0), t.shard.pending_count);
    try std.testing.expectEqual(r.commit_index, r.last_applied);
}

test "Shard: alone and suspended, writes past the outstanding cap are refused before they're proposed, and the pending table never wraps" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;

    t.shard.test_bar = r.log.lastIndex() + 1;
    try ParkTest.send(&t.shard, t.conn, .kv_put, 1, "a", "v");
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    const s = t.shard.snapshot_window.?.s;

    var id: u64 = 2;
    while (r.log.lastIndex() - s < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        const before = r.log.lastIndex();
        try ParkTest.send(&t.shard, t.conn, .kv_put, id, "k", "v");
        if (r.log.lastIndex() == before) {
            // Refused before it was proposed: say why.
            try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
            std.debug.print("write {d} at {d} outstanding refused: {d} {s}\n", .{ id, before - s, one[0].header.status, (try one[0].refused()).message });
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expectEqual(@as(u32, @intCast(raft_node_mod.MAX_OUTSTANDING)), t.shard.pending_count);
    const last = r.log.lastIndex();
    try ParkTest.send(&t.shard, t.conn, .kv_put, id, "k", "v");
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(id, one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), one[0].header.status);
    try std.testing.expectEqual(proto.Ran.no, (try one[0].refused()).ran);
    try std.testing.expectEqual(last, r.log.lastIndex());

    // On resume every parked write is answered, none lost to a wrapped slot.
    try stepWindowClosed(&t.shard);
    var answered: u32 = 0;
    var rbuf: [1 << 20]u8 = undefined;
    var have: usize = 0;
    var rounds: u32 = 0;
    while (answered < raft_node_mod.MAX_OUTSTANDING and rounds < 1000) : (rounds += 1) {
        t.shard.flushToClient(t.conn.fd);
        const n = std.c.recv(t.pair[1], rbuf[have..].ptr, rbuf.len - have, std.c.MSG.DONTWAIT);
        if (n <= 0) {
            _ = try t.shard.tick(0);
            continue;
        }
        have += @intCast(n);
        // Whole answers only; a partial one waits for the rest.
        var off: usize = 0;
        while (proto.Response.parse(rbuf[off..have])) |a| {
            try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), a.header.status);
            off += @sizeOf(proto.ResponseHeader) + a.data.len;
            answered += 1;
        } else |_| {}
        std.mem.copyForwards(u8, rbuf[0 .. have - off], rbuf[off..have]);
        have -= off;
    }
    try std.testing.expectEqual(@as(u32, @intCast(raft_node_mod.MAX_OUTSTANDING)), answered);
}

test "Shard: alone with sync durability, a suspended leader still flushes and commits what it's sent" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var t: SyncAlone = undefined;
    try t.init(&tmp);
    defer t.deinit();
    const r = t.shard.raft_node;
    var buf: [4096]u8 = undefined;

    t.shard.test_bar = r.log.lastIndex() + 1;
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try t.put(1, "a", &buf)).header.status);
    const s = t.shard.snapshot_window.?.s;
    try ParkTest.send(&t.shard, t.conn, .kv_put, 2, "b", "v");
    // The tick's apply pass: flushed and committed, though not applied.
    _ = t.shard.applyCommitted();
    try std.testing.expect(r.durable_index >= s + 1);
    try std.testing.expect(r.commit_index >= s + 1);
    try std.testing.expectEqual(s, r.last_applied);
    try stepWindowClosed(&t.shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
}

test "Shard: in a cluster, a leader suspended at a bar keeps its term and commits what its follower acks; the writes are answered on resume" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;

    t.shard.test_bar = r.log.lastIndex() + 1;
    try ParkTest.send(&t.shard, t.conn, .kv_put, 1, "a", "v");
    try ParkTest.ack(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    const s = t.shard.snapshot_window.?.s;
    const term = r.current_term;

    try ParkTest.send(&t.shard, t.conn, .kv_put, 2, "b", "v");
    try ParkTest.ack(&t.shard);
    try std.testing.expect(r.commit_index > s);
    try std.testing.expectEqual(s, r.last_applied);
    try std.testing.expectEqual(@as(u32, 1), t.shard.pending_count);
    // Raft keeps running through ticks: heartbeats, no election.
    for (0..5) |_| _ = try t.shard.tick(0);
    try std.testing.expectEqual(raft_node_mod.Role.leader, r.role);
    try std.testing.expectEqual(term, r.current_term);

    try stepWindowClosed(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
}

test "Shard: a leader still applying earlier terms passes a bar without a snapshot and counts it; a follower at the bar takes its window" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;

    // Two writes proposed, then elected again before they commit: not ready
    // until it has applied them.
    try ParkTest.send(&t.shard, t.conn, .kv_put, 1, "a", "v");
    try ParkTest.send(&t.shard, t.conn, .kv_put, 2, "b", "v");
    const bar = r.log.lastIndex() - 1;
    t.shard.test_bar = bar;
    r.current_term += 1;
    r.ready_index = r.log.lastIndex();
    try std.testing.expect(t.shard.leaderApplying());
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    try ParkTest.ack(&t.shard);
    try std.testing.expect(r.last_applied > bar);
    try std.testing.expect(t.shard.snapshot_window == null);
    try std.testing.expectEqual(@as(u64, 1), t.shard.snapshot_skips_leader_not_ready);
    // Ready now, and past the bar: no snapshot is taken for it later.
    try std.testing.expect(!t.shard.leaderApplying());
    _ = try t.shard.tick(0);
    try std.testing.expect(t.shard.snapshot_window == null);
    // Counted where metrics and /status read it.
    var registry = MetricsRegistry.init(std.testing.allocator);
    defer registry.deinit();
    try registry.initShards(1);
    t.shard.setMetricsRegistry(&registry);
    t.shard.publishHealth();
    try std.testing.expectEqual(@as(u64, 1), t.shard.shard_metrics.?.snapshot().snapshot_skipped_leader_not_ready);
}

test "Shard: a follower reaching a bar suspends apply; one that stops applying drops its window" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;
    // Entries in the log, committed, applied as a follower would apply them.
    t.shard.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.role = .follower;
    try std.testing.expect(t.shard.applyCommitted());
    try std.testing.expectEqual(t.shard.test_bar, t.shard.snapshot_window.?.s);
    try std.testing.expectEqual(t.shard.test_bar, r.last_applied);
    try std.testing.expect(r.commit_index > r.last_applied);
    t.shard.replica.diverged = true;
    t.shard.stepSnapshotWindow();
    try std.testing.expect(t.shard.snapshot_window == null);
    t.shard.replica.diverged = false;
    r.role = .leader;
}

test "Shard: a processing sink whose shard is capped while apply is suspended holds its source, and writes every record once room comes back" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    const yaml =
        \\kind: Processing
        \\name: capped
        \\sources:
        \\  - name: src
        \\    stream: { name: in }
        \\sinks:
        \\  - name: out
        \\    stream: { name: out }
    ;
    sh.runRequest(t.conn, try ParkTest.request(.processing_submit, 1, proto.DEFAULT_NAMESPACE, "", yaml, ""), .client);
    _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(u32, 1), sh.processing_handler.jobs.count());

    // More source records than the cap.
    const records = 1500;
    for (0..records) |k| {
        var pbuf: [16]u8 = undefined;
        try sh.stream_handler.appendPayloadToStream("in", "default", try std.fmt.bufPrint(&pbuf, "rec-{d}", .{k}));
        if (k % 256 == 0) _ = sh.applyCommitted();
    }
    _ = sh.applyCommitted();
    try std.testing.expectEqual(r.commit_index, r.last_applied);

    // Apply suspends at the next entry; the pipeline then fills the cap.
    sh.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    _ = sh.applyCommitted();
    try std.testing.expect(sh.snapshot_window != null);
    const from = r.log.lastIndex() + 1;
    const Tick = struct {
        fn pipelines(s: *Shard) void {
            var it = s.processing_handler.pipelines.valueIterator();
            while (it.next()) |p| p.last_poll_ms = 0;
            _ = s.processing_handler.tickPipelines(s);
        }
    };
    for (0..40) |_| Tick.pipelines(sh);
    const suspended_writes = entriesOf(sh, .stream_append, from);
    try std.testing.expect(suspended_writes > 0);
    try std.testing.expect(r.log.lastIndex() - r.last_applied <= raft_node_mod.MAX_OUTSTANDING);
    try std.testing.expectEqual(@as(u64, 0), sh.processing_handler.sink_drops);

    // Resumed, every record reaches the sink exactly once, and none dropped.
    try stepWindowClosed(sh);
    for (0..200) |_| {
        Tick.pipelines(sh);
        _ = sh.applyCommitted();
        if (entriesOf(sh, .stream_append, from) >= records) break;
    }
    try std.testing.expectEqual(@as(usize, records), entriesOf(sh, .stream_append, from));
    try std.testing.expectEqual(@as(u64, 0), sh.processing_handler.sink_drops);
}

/// A lone node suspended at a fresh test bar; returns the bar.
fn suspendAtTestBar(sh: *Shard) !u64 {
    const r = sh.raft_node;
    sh.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    _ = sh.applyCommitted();
    return sh.snapshot_window.?.s;
}

test "Shard: a window is dropped when its shard halts, goes offline, has its applied entries cut below the bar, or wins an election" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;

    _ = try suspendAtTestBar(sh);
    sh.halted = .{ .index = r.last_applied + 1, .term = r.current_term, .crc = 0 };
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    sh.halted = null;

    _ = try suspendAtTestBar(sh);
    sh.offline = silent_loss.Damage.init(.segment_unreadable, "segment {d} is unreadable", .{7});
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    sh.offline = null;

    // An async-durability rewind below the bar.
    const s = try suspendAtTestBar(sh);
    r.last_applied = s - 1;
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    r.last_applied = s;

    // Opened as a follower, then elected: dropped, counted, and apply goes on.
    _ = try suspendAtTestBarAsFollower(sh);
    // Elected in a new term, with its no-op committed behind the window:
    // not ready until that applies.
    r.role = .leader;
    r.current_term += 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.ready_index = r.log.lastIndex();
    r.commit_index = r.log.lastIndex();
    const skips = sh.snapshot_skips_leader_not_ready;
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    try std.testing.expectEqual(skips + 1, sh.snapshot_skips_leader_not_ready);
    try std.testing.expectEqual(r.commit_index, r.last_applied);

    // Led when the window opened, then elected again in a later term: not
    // ready under the new term, so dropped too.
    _ = try suspendAtTestBar(sh);
    try std.testing.expect(r.leaderReady());
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window != null);
    r.current_term += 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.ready_index = r.log.lastIndex();
    r.commit_index = r.log.lastIndex();
    try std.testing.expect(!r.leaderReady());
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    try std.testing.expectEqual(skips + 2, sh.snapshot_skips_leader_not_ready);
    try std.testing.expectEqual(r.commit_index, r.last_applied);
}

/// `suspendAtTestBar` on a node acting as a follower: its entries are
/// proposed as leader, then applied as a follower applies them.
fn suspendAtTestBarAsFollower(sh: *Shard) !u64 {
    const r = sh.raft_node;
    r.role = .leader;
    sh.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.role = .follower;
    _ = sh.applyCommitted();
    return sh.snapshot_window.?.s;
}

test "Shard: alone with a committed entry it can't read, writes past the cap are refused before they're proposed, not left in a wrapped slot" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;
    // Reads blocked: committed entries wait unapplied, retried later.
    sh.read_blocked = true;
    sh.read_retry_at_ms = Shard.nowMs() + 60_000;
    var id: u64 = 1;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(sh, t.conn, .kv_put, id, "k", "v");
    }
    try std.testing.expectEqual(@as(u32, @intCast(raft_node_mod.MAX_OUTSTANDING)), sh.pending_count);
    const last = r.log.lastIndex();
    try ParkTest.send(sh, t.conn, .kv_put, id, "k", "v");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), one[0].header.status);
    try std.testing.expectEqual(proto.Ran.no, (try one[0].refused()).ran);
    try std.testing.expectEqual(last, r.log.lastIndex());
    sh.read_blocked = false;
    sh.read_retry_at_ms = 0;
    // Apply runs in budgeted passes.
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(u32, 0), sh.pending_count);
}

test "Shard: a duty with an entry in flight during a window isn't proposed again" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "flow", def);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 2, "flow", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expectEqual(@as(u32, 1), sh.workflow_handler.to_step.count());

    // Suspended: the first step's entry is proposed once, however many
    // passes the duty takes before it applies.
    _ = try suspendAtTestBar(sh);
    const from = sh.raft_node.log.lastIndex() + 1;
    for (0..5) |_| sh.workflow_handler.advanceStartedRuns(sh);
    try std.testing.expectEqual(@as(usize, 1), entriesOf(sh, .workflow_step_started, from));
    try stepWindowClosed(sh);
    for (0..5) |_| sh.workflow_handler.advanceStartedRuns(sh);
    try std.testing.expectEqual(@as(usize, 1), entriesOf(sh, .workflow_step_started, from));
}

test "Shard: a stream trigger whose shard is capped while apply is suspended keeps its cursor, and starts a run for every event once room comes back" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const triggered =
        \\{"kind":"Workflow","name":"on-events","version":"1.0.0","trigger":{"stream":"events"},
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "on-events", triggered);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);

    const events = 1500;
    for (0..events) |k| {
        var pbuf: [16]u8 = undefined;
        try sh.stream_handler.appendPayloadToStream("events", "default", try std.fmt.bufPrint(&pbuf, "ev-{d}", .{k}));
        if (k % 256 == 0) _ = sh.applyCommitted();
    }
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();

    _ = try suspendAtTestBar(sh);
    const Tick = struct {
        fn triggers(s: *Shard) void {
            s.workflow_handler.triggers_dirty = true;
            s.workflow_handler.tickStreamTriggers(s);
        }
    };
    // Ten events a tick: enough ticks to reach the cap while suspended.
    for (0..200) |_| Tick.triggers(sh);
    try std.testing.expectEqual(raft_node_mod.MAX_OUTSTANDING, r.log.lastIndex() - r.last_applied);

    try stepWindowClosed(sh);
    for (0..400) |_| {
        Tick.triggers(sh);
        passes = 0;
        while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
        if (sh.workflow_handler.runs.count() >= events) break;
    }
    try std.testing.expectEqual(@as(usize, events), sh.workflow_handler.runs.count());
}

/// A KV sink write as another shard sends it to the key's owner.
fn kvSinkMessage(sh: *Shard, key: []const u8, value: []const u8) InboxMessage {
    const bytes = (KVHandler.SinkPut{ .namespace = "default", .key = key, .value = value, .ttl_ms = null }).encode(sh.allocator).?;
    return .{ .tag = .kv_sink_put, .src_shard = 1, .payload_len = @intCast(bytes.len), .payload_ptr = bytes.ptr };
}

test "Shard: KV sink writes another shard sends while this one is full wait in order, are proposed once there's room, and past the list's bound are counted dropped" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    // Suspended, with its cap filled by parked writes.
    _ = try suspendAtTestBar(sh);
    var id: u64 = 1;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(sh, t.conn, .kv_put, id, "filler", "v");
    }
    const last = r.log.lastIndex();

    // Two writes to one key, then another: held, nothing proposed.
    sh.runKvSinkPut(kvSinkMessage(sh, "sink-key", "first"));
    sh.runKvSinkPut(kvSinkMessage(sh, "sink-key", "second"));
    sh.runKvSinkPut(kvSinkMessage(sh, "other", "x"));
    try std.testing.expectEqual(@as(usize, 3), sh.kv_sink_retries.items.len);
    try std.testing.expectEqual(last, r.log.lastIndex());
    try std.testing.expectEqual(@as(u64, 0), sh.processing_handler.sink_drops);

    // Full list: the next is dropped and counted.
    while (sh.kv_sink_retries.items.len < Shard.KV_SINK_RETRY_MAX) sh.runKvSinkPut(kvSinkMessage(sh, "more", "y"));
    sh.runKvSinkPut(kvSinkMessage(sh, "past", "z"));
    try std.testing.expectEqual(@as(u64, 1), sh.kv_sink_retry_overflow);
    try std.testing.expectEqual(@as(u64, 1), sh.processing_handler.sink_drops);

    // Room again: proposed oldest first, a key's last write winning.
    try stepWindowClosed(sh);
    var rounds: u32 = 0;
    while (sh.kv_sink_retries.items.len > 0 and rounds < 100) : (rounds += 1) {
        _ = try sh.tick(0);
        var passes: u32 = 0;
        while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    }
    try std.testing.expectEqual(@as(usize, 0), sh.kv_sink_retries.items.len);
    var buf: [4096]u8 = undefined;
    var rbuf: [1 << 20]u8 = undefined;
    // Drain the parked fillers' answers, then read the key back.
    sh.flushToClient(t.conn.fd);
    while (std.c.recv(t.pair[1], &rbuf, rbuf.len, std.c.MSG.DONTWAIT) > 0) sh.flushToClient(t.conn.fd);
    var one: [1]proto.Response = undefined;
    try ParkTest.send(sh, t.conn, .kv_get, 99_999, "sink-key", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expect(std.mem.indexOf(u8, one[0].data, "second") != null);
    try std.testing.expectEqual(@as(u64, 1), sh.processing_handler.sink_drops);
}

test "Shard: a KV sink write arriving while earlier ones wait goes behind them, though the log has room for it" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    try fillCapSuspended(&t);
    sh.runKvSinkPut(kvSinkMessage(sh, "k", "first"));
    try std.testing.expectEqual(@as(usize, 1), sh.kv_sink_retries.items.len);

    // Room again, before the list is retried: the next write still waits.
    try resumeAndApply(sh);
    try std.testing.expect(r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING);
    const last = r.log.lastIndex();
    sh.runKvSinkPut(kvSinkMessage(sh, "k", "second"));
    try std.testing.expectEqual(@as(usize, 2), sh.kv_sink_retries.items.len);
    try std.testing.expectEqual(last, r.log.lastIndex());

    // Retried in order: the key ends with the later write.
    _ = try sh.tick(0);
    try std.testing.expectEqual(@as(usize, 0), sh.kv_sink_retries.items.len);
    try std.testing.expectEqual(@as(usize, 0), sh.kv_sink_retry_bytes);
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    var buf: [4096]u8 = undefined;
    var rbuf: [1 << 20]u8 = undefined;
    sh.flushToClient(t.conn.fd);
    while (std.c.recv(t.pair[1], &rbuf, rbuf.len, std.c.MSG.DONTWAIT) > 0) sh.flushToClient(t.conn.fd);
    var one: [1]proto.Response = undefined;
    try ParkTest.send(sh, t.conn, .kv_get, 99_999, "k", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expect(std.mem.indexOf(u8, one[0].data, "second") != null);
}

test "Shard: KV sink writes waiting for room are bounded by bytes as well as by count" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    try fillCapSuspended(&t);
    const big: [60 * 1024]u8 = @splat('v');
    while (sh.kv_sink_retry_bytes + big.len + 64 <= Shard.KV_SINK_RETRY_MAX_BYTES) sh.runKvSinkPut(kvSinkMessage(sh, "big", &big));
    const held = sh.kv_sink_retries.items.len;
    try std.testing.expect(held < Shard.KV_SINK_RETRY_MAX);
    try std.testing.expectEqual(@as(u64, 0), sh.kv_sink_retry_overflow);
    sh.runKvSinkPut(kvSinkMessage(sh, "big", &big));
    try std.testing.expectEqual(held, sh.kv_sink_retries.items.len);
    try std.testing.expectEqual(@as(u64, 1), sh.kv_sink_retry_overflow);
    try std.testing.expect(sh.kv_sink_retry_bytes <= Shard.KV_SINK_RETRY_MAX_BYTES);
}

test "Shard: a workflow step whose action invoke the log is too full to take waits, says so once, and invokes once there's room" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    _ = try proposeAction(sh, .action_register, testRegister("act"));
    _ = sh.applyCommitted();
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"run":"@actions/act","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "flow", def);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 2, "flow", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    // Its first step logged and applied: queued to take.
    sh.workflow_handler.advanceStartedRuns(sh);
    _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(usize, 1), sh.workflow_handler.started_to_advance.items.len);

    // The log fills while apply is suspended.
    _ = try suspendAtTestBar(sh);
    var id: u64 = 10;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(sh, t.conn, .kv_put, id, "filler", "v");
    }
    sh.workflow_handler.advanceStartedRuns(sh);
    var runs = sh.workflow_handler.runs.valueIterator();
    const run = runs.next().?;
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);
    try std.testing.expect(run.pending_action_run_id_owned == null);
    try std.testing.expect(run.poll_next_at_ms > 0);
    var waits: usize = 0;
    for (run.history.items) |e| {
        if (std.mem.eql(u8, e.event_type_owned, "step_waiting_for_room")) waits += 1;
        try std.testing.expect(!std.mem.eql(u8, e.event_type_owned, "workflow_failed"));
    }
    try std.testing.expectEqual(@as(usize, 1), waits);

    // Room again: the poll timer runs the step, which now invokes.
    try stepWindowClosed(sh);
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    // Past the retry delay, as the run's armed timer reckons it.
    @import("stdx").time.sleep(@as(u64, @intCast(WorkflowHandler.STEP_ROOM_RETRY_MS + 50)) * std.time.ns_per_ms);
    sh.workflow_handler.checkPendingActions(sh);
    try std.testing.expect(run.pending_action_run_id_owned != null);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);
}

test "Shard: a plan step whose start is refused for room records its start and its wait once, however often it's retried" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    _ = try proposeAction(sh, .action_register, testRegister("act"));
    _ = sh.applyCommitted();
    const def =
        \\{"kind":"Workflow","name":"planned","version":"1.0.0",
        \\"plans":{"p":{"executors":[{"name":"only","run":"@actions/act"}]}},
        \\"start":{"run":"@plan/p","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "planned", def);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 2, "planned", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    sh.workflow_handler.advanceStartedRuns(sh);
    _ = sh.applyCommitted();

    try fillCapSuspended(&t);
    sh.workflow_handler.advanceStartedRuns(sh);
    var runs = sh.workflow_handler.runs.valueIterator();
    const run = runs.next().?;
    // Still full: retried on the poll timer, refused each time.
    var tries: u32 = 0;
    while (tries < 3) : (tries += 1) {
        @import("stdx").time.sleep(@as(u64, @intCast(WorkflowHandler.STEP_ROOM_RETRY_MS + 20)) * std.time.ns_per_ms);
        sh.workflow_handler.checkPendingActions(sh);
    }
    try std.testing.expect(run.pending_action_run_id_owned == null);
    try std.testing.expectEqual(@as(usize, 1), historyCount(run, "plan_executor_start"));
    try std.testing.expectEqual(@as(usize, 1), historyCount(run, "step_waiting_for_room"));

    try resumeAndApply(sh);
    @import("stdx").time.sleep(@as(u64, @intCast(WorkflowHandler.STEP_ROOM_RETRY_MS + 50)) * std.time.ns_per_ms);
    sh.workflow_handler.checkPendingActions(sh);
    try std.testing.expect(run.pending_action_run_id_owned != null);
    try std.testing.expect(!run.waiting_for_room);
    try std.testing.expectEqual(@as(usize, 1), historyCount(run, "plan_executor_start"));
}

fn historyCount(run: *const WorkflowHandler.RunRecord, event: []const u8) usize {
    var n: usize = 0;
    for (run.history.items) |e| {
        if (std.mem.eql(u8, e.event_type_owned, event)) n += 1;
    }
    return n;
}

/// Fills the log to its cap with parked client writes, apply suspended.
fn fillCapSuspended(t: *AsyncAlone) !void {
    const r = t.shard.raft_node;
    _ = try suspendAtTestBar(&t.shard);
    var id: u64 = 1_000_000;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(&t.shard, t.conn, .kv_put, id, "filler", "v");
    }
}

/// Resumes and applies everything committed.
fn resumeAndApply(sh: *Shard) !void {
    try stepWindowClosed(sh);
    const r = sh.raft_node;
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
}

